window.TF_FORMS=[{"form":1,"L":[{"p":1,"items":[{"pic":{"i":["student","book"],"bg":"school"},"opts":[{"zh":"他在吃飯。","py":"Tā zài chī fàn."},{"zh":"他在看書。","py":"Tā zài kàn shū."},{"zh":"他在睡覺。","py":"Tā zài shuì jiào."}],"a":1,"tr":{"id":"A: Dia sedang makan. B: Dia sedang membaca buku. C: Dia sedang tidur.","en":"A: He is eating. B: He is reading a book. C: He is sleeping.","tl":"A: Kumakain siya. B: Nagbabasa siya ng libro. C: Natutulog siya.","vi":"A: Cậu ấy đang ăn cơm. B: Cậu ấy đang đọc sách. C: Cậu ấy đang ngủ."},"exp":{"id":"Gambar menunjukkan siswa dengan buku, jadi dia sedang membaca.","en":"The picture shows a student with a book, so he is reading.","tl":"Makikita ang estudyanteng may libro, kaya nagbabasa siya.","vi":"Hình là học sinh cầm sách, nên cậu ấy đang đọc sách."}},{"pic":{"i":["clock"],"b":"07:30"},"opts":[{"zh":"現在七點半。","py":"Xiàn zài qī diǎn bàn."},{"zh":"現在八點半。","py":"Xiàn zài bā diǎn bàn."},{"zh":"現在七點十五分。","py":"Xiàn zài qī diǎn shí wǔ fēn."}],"a":0,"tr":{"id":"A: Sekarang jam setengah delapan (7.30). B: Sekarang jam 8.30. C: Sekarang jam 7.15.","en":"A: It is half past seven now. B: It is half past eight now. C: It is 7:15 now.","tl":"A: Alas-siyete y medya na ngayon. B: Alas-otso y medya na ngayon. C: 7:15 na ngayon.","vi":"A: Bây giờ là bảy giờ rưỡi. B: Bây giờ là tám giờ rưỡi. C: Bây giờ là bảy giờ mười lăm."},"exp":{"id":"Jam menunjukkan 07:30 = 七點半.","en":"The clock shows 07:30, which is 七點半.","tl":"Ang orasan ay 07:30, ibig sabihin 七點半.","vi":"Đồng hồ chỉ 07:30, tức là 七點半."}},{"pic":{"i":["rain","umbrella"],"bg":"street"},"opts":[{"zh":"今天天氣很好。","py":"Jīn tiān tiān qì hěn hǎo."},{"zh":"今天很熱。","py":"Jīn tiān hěn rè."},{"zh":"外面在下雨。","py":"Wài miàn zài xià yǔ."}],"a":2,"tr":{"id":"A: Cuaca hari ini sangat bagus. B: Hari ini sangat panas. C: Di luar sedang hujan.","en":"A: The weather is very nice today. B: It is very hot today. C: It is raining outside.","tl":"A: Napakaganda ng panahon ngayon. B: Napakainit ngayon. C: Umuulan sa labas.","vi":"A: Hôm nay thời tiết rất đẹp. B: Hôm nay rất nóng. C: Bên ngoài đang mưa."},"exp":{"id":"Gambar ada hujan dan payung, jadi sedang hujan.","en":"The picture shows rain and an umbrella, so it is raining.","tl":"May ulan at payong sa larawan, kaya umuulan.","vi":"Hình có mưa và ô, nên trời đang mưa."}},{"pic":{"i":["family","rice","table"],"bg":"home"},"opts":[{"zh":"他們在看電視。","py":"Tā men zài kàn diàn shì."},{"zh":"他們在家吃飯。","py":"Tā men zài jiā chī fàn."},{"zh":"他們在餐廳喝咖啡。","py":"Tā men zài cān tīng hē kā fēi."}],"a":1,"tr":{"id":"A: Mereka sedang menonton TV. B: Mereka sedang makan di rumah. C: Mereka sedang minum kopi di restoran.","en":"A: They are watching TV. B: They are eating at home. C: They are drinking coffee in a restaurant.","tl":"A: Nanonood sila ng TV. B: Kumakain sila sa bahay. C: Umiinom sila ng kape sa restawran.","vi":"A: Họ đang xem tivi. B: Họ đang ăn cơm ở nhà. C: Họ đang uống cà phê ở nhà hàng."},"exp":{"id":"Keluarga makan nasi di meja di rumah.","en":"A family is eating rice at a table at home.","tl":"Kumakain ng kanin ang pamilya sa mesa sa bahay.","vi":"Cả gia đình đang ăn cơm ở bàn trong nhà."}},{"pic":{"i":["calendar"],"b":"MAY 12"},"opts":[{"zh":"今天是十二月五號。","py":"Jīn tiān shì shí èr yuè wǔ hào."},{"zh":"今天是五月十二號。","py":"Jīn tiān shì wǔ yuè shí èr hào."},{"zh":"今天是五月二十號。","py":"Jīn tiān shì wǔ yuè èr shí hào."}],"a":1,"tr":{"id":"A: Hari ini tanggal 5 Desember. B: Hari ini tanggal 12 Mei. C: Hari ini tanggal 20 Mei.","en":"A: Today is December 5th. B: Today is May 12th. C: Today is May 20th.","tl":"A: Ngayon ay Disyembre 5. B: Ngayon ay Mayo 12. C: Ngayon ay Mayo 20.","vi":"A: Hôm nay là ngày 5 tháng 12. B: Hôm nay là ngày 12 tháng 5. C: Hôm nay là ngày 20 tháng 5."},"exp":{"id":"Kalender: 12 Mei = 五月十二號 (bulan dulu, lalu tanggal).","en":"The calendar shows May 12 = 五月十二號 (month first, then day).","tl":"Mayo 12 = 五月十二號 (buwan muna, saka araw).","vi":"Lịch ghi 12 tháng 5 = 五月十二號 (tháng trước, ngày sau)."}},{"pic":{"i":["teacher","student"],"bg":"school"},"opts":[{"zh":"老師在上課。","py":"Lǎo shī zài shàng kè."},{"zh":"醫生在看病。","py":"Yī shēng zài kàn bìng."},{"zh":"學生在打球。","py":"Xué shēng zài dǎ qiú."}],"a":0,"tr":{"id":"A: Guru sedang mengajar di kelas. B: Dokter sedang memeriksa pasien. C: Para siswa sedang bermain bola.","en":"A: The teacher is teaching a class. B: The doctor is seeing a patient. C: The students are playing ball.","tl":"A: Nagtuturo ang guro sa klase. B: Tumitingin ng pasyente ang doktor. C: Naglalaro ng bola ang mga estudyante.","vi":"A: Thầy giáo đang dạy học. B: Bác sĩ đang khám bệnh. C: Học sinh đang chơi bóng."},"exp":{"id":"Ada guru dan siswa di sekolah: sedang ada pelajaran.","en":"A teacher and a student at school: a class is going on.","tl":"May guro at estudyante sa paaralan: may klase.","vi":"Có thầy giáo và học sinh ở trường: đang lên lớp."}},{"pic":{"i":["noodles"],"b":"NT$80","bg":"shop"},"opts":[{"zh":"這碗飯八十塊。","py":"Zhè wǎn fàn bā shí kuài."},{"zh":"這碗麵十八塊。","py":"Zhè wǎn miàn shí bā kuài."},{"zh":"這碗麵八十塊。","py":"Zhè wǎn miàn bā shí kuài."}],"a":2,"tr":{"id":"A: Semangkuk nasi ini 80 dolar. B: Semangkuk mi ini 18 dolar. C: Semangkuk mi ini 80 dolar.","en":"A: This bowl of rice is 80 dollars. B: This bowl of noodles is 18 dollars. C: This bowl of noodles is 80 dollars.","tl":"A: 80 dolyar ang mangkok ng kaning ito. B: 18 dolyar ang mangkok ng nudels na ito. C: 80 dolyar ang mangkok ng nudels na ito.","vi":"A: Bát cơm này 80 đồng. B: Bát mì này 18 đồng. C: Bát mì này 80 đồng."},"exp":{"id":"Gambar mi dengan harga NT$80 = 八十塊, bukan 十八.","en":"Noodles priced NT$80 = 八十塊, not 十八.","tl":"Nudels na NT$80 = 八十塊, hindi 十八.","vi":"Mì giá NT$80 = 八十塊, không phải 十八."}},{"pic":{"i":["sun","hot"],"b":"35°C"},"opts":[{"zh":"今天很熱，三十五度。","py":"Jīn tiān hěn rè, sān shí wǔ dù."},{"zh":"今天很冷。","py":"Jīn tiān hěn lěng."},{"zh":"今天下雪了。","py":"Jīn tiān xià xuě le."}],"a":0,"tr":{"id":"A: Hari ini sangat panas, 35 derajat. B: Hari ini sangat dingin. C: Hari ini turun salju.","en":"A: It is very hot today, 35 degrees. B: It is very cold today. C: It snowed today.","tl":"A: Napakainit ngayon, 35 digri. B: Napakalamig ngayon. C: Nag-snow ngayon.","vi":"A: Hôm nay rất nóng, 35 độ. B: Hôm nay rất lạnh. C: Hôm nay có tuyết rơi."},"exp":{"id":"Matahari dan 35°C berarti panas.","en":"Sun and 35°C mean it is hot.","tl":"Araw at 35°C: mainit.","vi":"Mặt trời và 35°C nghĩa là trời nóng."}},{"pic":{"i":["old_woman","cook"],"bg":"home"},"opts":[{"zh":"爺爺在廚房做飯。","py":"Yé ye zài chú fáng zuò fàn."},{"zh":"奶奶在公園散步。","py":"Nǎi nai zài gōng yuán sàn bù."},{"zh":"奶奶在廚房做飯。","py":"Nǎi nai zài chú fáng zuò fàn."}],"a":2,"tr":{"id":"A: Kakek sedang memasak di dapur. B: Nenek sedang jalan-jalan di taman. C: Nenek sedang memasak di dapur.","en":"A: Grandpa is cooking in the kitchen. B: Grandma is taking a walk in the park. C: Grandma is cooking in the kitchen.","tl":"A: Nagluluto si Lolo sa kusina. B: Naglalakad si Lola sa parke. C: Nagluluto si Lola sa kusina.","vi":"A: Ông đang nấu cơm trong bếp. B: Bà đang đi dạo trong công viên. C: Bà đang nấu cơm trong bếp."},"exp":{"id":"Gambar nenek (bukan kakek) yang memasak di rumah.","en":"The picture shows grandma (not grandpa) cooking at home.","tl":"Si Lola (hindi si Lolo) ang nagluluto sa bahay.","vi":"Hình là bà (không phải ông) đang nấu ăn ở nhà."}},{"pic":{"i":["girl","bubble_tea"],"bg":"shop"},"opts":[{"zh":"她在買咖啡。","py":"Tā zài mǎi kā fēi."},{"zh":"她在買珍珠奶茶。","py":"Tā zài mǎi zhēn zhū nǎi chá."},{"zh":"她在喝果汁。","py":"Tā zài hē guǒ zhī."}],"a":1,"tr":{"id":"A: Dia sedang membeli kopi. B: Dia sedang membeli bubble tea. C: Dia sedang minum jus.","en":"A: She is buying coffee. B: She is buying bubble tea. C: She is drinking juice.","tl":"A: Bumibili siya ng kape. B: Bumibili siya ng bubble tea. C: Umiinom siya ng juice.","vi":"A: Cô ấy đang mua cà phê. B: Cô ấy đang mua trà sữa trân châu. C: Cô ấy đang uống nước ép."},"exp":{"id":"Gadis di toko dengan bubble tea (珍珠奶茶).","en":"A girl in a shop with bubble tea (珍珠奶茶).","tl":"Batang babae sa tindahan na may bubble tea (珍珠奶茶).","vi":"Cô gái ở cửa hàng với trà sữa trân châu (珍珠奶茶)."}}]},{"p":2,"items":[{"dlg":[{"sp":"M","zh":"你今天怎麼來學校？","py":"Nǐ jīn tiān zěn me lái xué xiào?"},{"sp":"F","zh":"我坐公車來的。","py":"Wǒ zuò gōng chē lái de."}],"q":{"zh":"女的今天怎麼來學校？","py":"Nǚ de jīn tiān zěn me lái xué xiào?"},"opts":[{"i":["bus"],"bg":"street"},{"i":["mrt"],"bg":"street"},{"i":["bicycle"],"bg":"street"}],"a":0,"tr":{"id":"M: Hari ini kamu datang ke sekolah naik apa? F: Saya naik bus. Q: Perempuan itu naik apa ke sekolah hari ini?","en":"M: How did you come to school today? F: I came by bus. Q: How did the woman come to school today?","tl":"M: Paano ka pumunta sa paaralan ngayon? F: Sumakay ako ng bus. Q: Paano pumunta sa paaralan ang babae ngayon?","vi":"M: Hôm nay bạn đến trường bằng gì? F: Mình đi xe buýt. Q: Hôm nay người nữ đến trường bằng gì?"},"exp":{"id":"Dia bilang 坐公車 = naik bus.","en":"She said 坐公車, by bus.","tl":"Sabi niya 坐公車, sakay ng bus.","vi":"Cô ấy nói 坐公車, đi xe buýt."}},{"dlg":[{"sp":"F","zh":"你明天幾點上課？","py":"Nǐ míng tiān jǐ diǎn shàng kè?"},{"sp":"M","zh":"九點，我九點有中文課。","py":"Jiǔ diǎn, wǒ jiǔ diǎn yǒu zhōng wén kè."}],"q":{"zh":"男的明天幾點上課？","py":"Nán de míng tiān jǐ diǎn shàng kè?"},"opts":[{"i":["clock"],"b":"08:00"},{"i":["clock"],"b":"10:00"},{"i":["clock"],"b":"09:00"}],"a":2,"tr":{"id":"F: Besok kamu masuk kelas jam berapa? M: Jam sembilan, jam sembilan saya ada kelas bahasa Mandarin. Q: Besok laki-laki itu masuk kelas jam berapa?","en":"F: What time is your class tomorrow? M: Nine. I have Chinese class at nine. Q: What time is the man's class tomorrow?","tl":"F: Anong oras ang klase mo bukas? M: Alas-nuwebe, may klase ako sa Chinese nang alas-nuwebe. Q: Anong oras ang klase ng lalaki bukas?","vi":"F: Ngày mai mấy giờ bạn vào học? M: Chín giờ, chín giờ mình có lớp tiếng Trung. Q: Ngày mai mấy giờ người nam vào học?"},"exp":{"id":"九點 = jam 09:00.","en":"九點 = 9:00.","tl":"九點 = 9:00.","vi":"九點 = 9 giờ."}},{"dlg":[{"sp":"M","zh":"你家有幾個人？","py":"Nǐ jiā yǒu jǐ ge rén?"},{"sp":"F","zh":"四個，爸爸、媽媽、哥哥和我。","py":"Sì ge, bà ba, mā ma, gē ge hé wǒ."}],"q":{"zh":"女的家有幾個人？","py":"Nǚ de jiā yǒu jǐ ge rén?"},"opts":[{"i":["family"],"b":"3","bg":"home"},{"i":["family"],"b":"4","bg":"home"},{"i":["family"],"b":"5","bg":"home"}],"a":1,"tr":{"id":"M: Keluargamu ada berapa orang? F: Empat: ayah, ibu, kakak laki-laki, dan saya. Q: Keluarga perempuan itu ada berapa orang?","en":"M: How many people are in your family? F: Four: dad, mom, my older brother and me. Q: How many people are in the woman's family?","tl":"M: Ilan kayo sa pamilya? F: Apat: tatay, nanay, kuya, at ako. Q: Ilan ang tao sa pamilya ng babae?","vi":"M: Nhà bạn có mấy người? F: Bốn người: bố, mẹ, anh trai và mình. Q: Nhà người nữ có mấy người?"},"exp":{"id":"Dia bilang 四個 (empat orang).","en":"She said 四個, four people.","tl":"Sabi niya 四個, apat na tao.","vi":"Cô ấy nói 四個, bốn người."}},{"dlg":[{"sp":"F","zh":"你晚上想吃什麼？","py":"Nǐ wǎn shàng xiǎng chī shén me?"},{"sp":"M","zh":"我想吃水餃。","py":"Wǒ xiǎng chī shuǐ jiǎo."}],"q":{"zh":"男的晚上想吃什麼？","py":"Nán de wǎn shàng xiǎng chī shén me?"},"opts":[{"i":["noodles"]},{"i":["dumplings"]},{"i":["rice"]}],"a":1,"tr":{"id":"F: Malam ini kamu mau makan apa? M: Saya mau makan pangsit rebus. Q: Laki-laki itu mau makan apa malam ini?","en":"F: What do you want to eat tonight? M: I want to eat dumplings. Q: What does the man want to eat tonight?","tl":"F: Ano ang gusto mong kainin mamayang gabi? M: Gusto kong kumain ng dumplings. Q: Ano ang gustong kainin ng lalaki mamayang gabi?","vi":"F: Tối nay bạn muốn ăn gì? M: Mình muốn ăn sủi cảo. Q: Tối nay người nam muốn ăn gì?"},"exp":{"id":"水餃 = pangsit (dumpling).","en":"水餃 means dumplings.","tl":"水餃 ay dumplings.","vi":"水餃 là sủi cảo."}},{"dlg":[{"sp":"M","zh":"明天天氣怎麼樣？","py":"Míng tiān tiān qì zěn me yàng?"},{"sp":"F","zh":"聽說明天會下雨，要帶傘。","py":"Tīng shuō míng tiān huì xià yǔ, yào dài sǎn."}],"q":{"zh":"明天天氣怎麼樣？","py":"Míng tiān tiān qì zěn me yàng?"},"opts":[{"i":["sun"]},{"i":["wind"]},{"i":["rain","umbrella"]}],"a":2,"tr":{"id":"M: Bagaimana cuaca besok? F: Katanya besok akan hujan, harus bawa payung. Q: Bagaimana cuaca besok?","en":"M: What will the weather be like tomorrow? F: I heard it will rain tomorrow; take an umbrella. Q: What will the weather be like tomorrow?","tl":"M: Ano ang panahon bukas? F: Uulan daw bukas, magdala ka ng payong. Q: Ano ang panahon bukas?","vi":"M: Thời tiết ngày mai thế nào? F: Nghe nói mai sẽ mưa, phải mang ô. Q: Thời tiết ngày mai thế nào?"},"exp":{"id":"會下雨 = akan hujan, perlu payung.","en":"會下雨: it will rain, so an umbrella.","tl":"會下雨: uulan, kaya payong.","vi":"會下雨: sẽ mưa, cần ô."}},{"dlg":[{"sp":"F","zh":"你的生日是幾月幾號？","py":"Nǐ de shēng rì shì jǐ yuè jǐ hào?"},{"sp":"M","zh":"十月八號，下個星期三。","py":"Shí yuè bā hào, xià ge xīng qí sān."}],"q":{"zh":"男的生日是幾月幾號？","py":"Nán de shēng rì shì jǐ yuè jǐ hào?"},"opts":[{"i":["calendar","birthday"],"b":"OCT 8"},{"i":["calendar","birthday"],"b":"AUG 10"},{"i":["calendar","birthday"],"b":"OCT 18"}],"a":0,"tr":{"id":"F: Ulang tahunmu tanggal berapa? M: 8 Oktober, Rabu depan. Q: Ulang tahun laki-laki itu tanggal berapa?","en":"F: When is your birthday? M: October 8th, next Wednesday. Q: When is the man's birthday?","tl":"F: Kailan ang kaarawan mo? M: Oktubre 8, sa susunod na Miyerkoles. Q: Kailan ang kaarawan ng lalaki?","vi":"F: Sinh nhật bạn là ngày mấy tháng mấy? M: Ngày 8 tháng 10, thứ Tư tuần sau. Q: Sinh nhật người nam là ngày nào?"},"exp":{"id":"十月八號 = 8 Oktober.","en":"十月八號 = October 8.","tl":"十月八號 = Oktubre 8.","vi":"十月八號 = ngày 8 tháng 10."}},{"dlg":[{"sp":"M","zh":"請問，圖書館在哪裡？","py":"Qǐng wèn, tú shū guǎn zài nǎ lǐ?"},{"sp":"F","zh":"你往左邊走，就到了。","py":"Nǐ wǎng zuǒ biān zǒu, jiù dào le."}],"q":{"zh":"圖書館在哪裡？","py":"Tú shū guǎn zài nǎ lǐ?"},"opts":[{"i":["library","left_arrow"]},{"i":["library","right_arrow"]},{"i":["library","straight_arrow"]}],"a":0,"tr":{"id":"M: Permisi, perpustakaan di mana? F: Jalan ke arah kiri, sudah sampai. Q: Perpustakaan di mana?","en":"M: Excuse me, where is the library? F: Walk to the left and you're there. Q: Where is the library?","tl":"M: Mawalang-galang po, nasaan ang aklatan? F: Lumakad ka pakaliwa, nandoon na. Q: Nasaan ang aklatan?","vi":"M: Xin hỏi, thư viện ở đâu? F: Bạn đi về bên trái là đến. Q: Thư viện ở đâu?"},"exp":{"id":"往左邊走 = ke kiri.","en":"往左邊走 means go left.","tl":"往左邊走 = pakaliwa.","vi":"往左邊走 = đi về bên trái."}},{"dlg":[{"sp":"F","zh":"你週末常常做什麼？","py":"Nǐ zhōu mò cháng cháng zuò shén me?"},{"sp":"M","zh":"我常常跟朋友去打籃球。","py":"Wǒ cháng cháng gēn péng yǒu qù dǎ lán qiú."}],"q":{"zh":"男的週末常常做什麼？","py":"Nán de zhōu mò cháng cháng zuò shén me?"},"opts":[{"i":["tennis"]},{"i":["swim"]},{"i":["basketball"]}],"a":2,"tr":{"id":"F: Akhir pekan kamu sering melakukan apa? M: Saya sering main basket dengan teman. Q: Laki-laki itu sering melakukan apa di akhir pekan?","en":"F: What do you often do on weekends? M: I often play basketball with friends. Q: What does the man often do on weekends?","tl":"F: Ano ang madalas mong ginagawa tuwing weekend? M: Madalas akong mag-basketball kasama ang mga kaibigan. Q: Ano ang madalas gawin ng lalaki tuwing weekend?","vi":"F: Cuối tuần bạn thường làm gì? M: Mình thường đi chơi bóng rổ với bạn. Q: Cuối tuần người nam thường làm gì?"},"exp":{"id":"打籃球 = main basket.","en":"打籃球 = play basketball.","tl":"打籃球 = mag-basketball.","vi":"打籃球 = chơi bóng rổ."}},{"dlg":[{"sp":"M","zh":"這件外套多少錢？","py":"Zhè jiàn wài tào duō shǎo qián?"},{"sp":"F","zh":"這件外套八百塊。","py":"Zhè jiàn wài tào bā bǎi kuài."}],"q":{"zh":"這件外套多少錢？","py":"Zhè jiàn wài tào duō shǎo qián?"},"opts":[{"i":["jacket"],"b":"NT$600","bg":"shop"},{"i":["jacket"],"b":"NT$800","bg":"shop"},{"i":["jacket"],"b":"NT$1800","bg":"shop"}],"a":1,"tr":{"id":"M: Jaket ini berapa harganya? F: Jaket ini 800 dolar. Q: Jaket ini berapa harganya?","en":"M: How much is this jacket? F: This jacket is 800 dollars. Q: How much is this jacket?","tl":"M: Magkano ang dyaket na ito? F: 800 dolyar ang dyaket na ito. Q: Magkano ang dyaket na ito?","vi":"M: Áo khoác này bao nhiêu tiền? F: Áo khoác này 800 đồng. Q: Áo khoác này bao nhiêu tiền?"},"exp":{"id":"八百塊 = NT$800.","en":"八百塊 = NT$800.","tl":"八百塊 = NT$800.","vi":"八百塊 = NT$800."}},{"dlg":[{"sp":"F","zh":"你哥哥在哪裡工作？","py":"Nǐ gē ge zài nǎ lǐ gōng zuò?"},{"sp":"M","zh":"他是醫生，在醫院工作。","py":"Tā shì yī shēng, zài yī yuàn gōng zuò."}],"q":{"zh":"男的哥哥在哪裡工作？","py":"Nán de gē ge zài nǎ lǐ gōng zuò?"},"opts":[{"i":["teacher","school"]},{"i":["doctor","hospital"]},{"i":["waiter","restaurant"]}],"a":1,"tr":{"id":"F: Kakak laki-lakimu bekerja di mana? M: Dia dokter, bekerja di rumah sakit. Q: Kakak laki-laki dari pria itu bekerja di mana?","en":"F: Where does your older brother work? M: He's a doctor; he works in a hospital. Q: Where does the man's older brother work?","tl":"F: Saan nagtatrabaho ang kuya mo? M: Doktor siya, sa ospital siya nagtatrabaho. Q: Saan nagtatrabaho ang kuya ng lalaki?","vi":"F: Anh trai bạn làm việc ở đâu? M: Anh ấy là bác sĩ, làm ở bệnh viện. Q: Anh trai người nam làm việc ở đâu?"},"exp":{"id":"醫生, 醫院 = dokter, rumah sakit.","en":"醫生 in a 醫院: doctor in a hospital.","tl":"醫生 sa 醫院: doktor sa ospital.","vi":"醫生, 醫院: bác sĩ ở bệnh viện."}},{"dlg":[{"sp":"M","zh":"你要喝什麼？","py":"Nǐ yào hē shén me?"},{"sp":"F","zh":"我要一杯熱茶，不要咖啡。","py":"Wǒ yào yì bēi rè chá, bú yào kā fēi."}],"q":{"zh":"女的要喝什麼？","py":"Nǚ de yào hē shén me?"},"opts":[{"i":["coffee"]},{"i":["juice"]},{"i":["tea"]}],"a":2,"tr":{"id":"M: Kamu mau minum apa? F: Saya mau secangkir teh panas, tidak mau kopi. Q: Perempuan itu mau minum apa?","en":"M: What would you like to drink? F: A cup of hot tea, not coffee. Q: What does the woman want to drink?","tl":"M: Ano ang gusto mong inumin? F: Isang tasang mainit na tsaa, ayaw ko ng kape. Q: Ano ang gustong inumin ng babae?","vi":"M: Bạn muốn uống gì? F: Mình muốn một cốc trà nóng, không uống cà phê. Q: Người nữ muốn uống gì?"},"exp":{"id":"Dia mau 熱茶 (teh), 不要咖啡.","en":"She wants 熱茶 (tea), 不要 coffee.","tl":"Gusto niya ng 熱茶 (tsaa), 不要 kape.","vi":"Cô ấy muốn 熱茶 (trà), 不要 cà phê."}},{"dlg":[{"sp":"F","zh":"你們學校的餐廳在幾樓？","py":"Nǐ men xué xiào de cān tīng zài jǐ lóu?"},{"sp":"M","zh":"在三樓，圖書館在五樓。","py":"Zài sān lóu, tú shū guǎn zài wǔ lóu."}],"q":{"zh":"餐廳在幾樓？","py":"Cān tīng zài jǐ lóu?"},"opts":[{"i":["restaurant"],"b":"3F"},{"i":["library"],"b":"5F"},{"i":["restaurant"],"b":"5F"}],"a":0,"tr":{"id":"F: Kantin sekolahmu di lantai berapa? M: Di lantai tiga, perpustakaan di lantai lima. Q: Kantin di lantai berapa?","en":"F: Which floor is your school's cafeteria on? M: The third floor; the library is on the fifth. Q: Which floor is the cafeteria on?","tl":"F: Nasa ilang palapag ang kantina ng paaralan ninyo? M: Nasa ikatlong palapag, ang aklatan ay nasa ikalima. Q: Nasa ilang palapag ang kantina?","vi":"F: Nhà ăn trường bạn ở tầng mấy? M: Ở tầng ba, thư viện ở tầng năm. Q: Nhà ăn ở tầng mấy?"},"exp":{"id":"餐廳在三樓 = kantin lantai 3.","en":"The cafeteria is on 3F; 5F is the library.","tl":"Ang kantina ay 3F; ang 5F ay aklatan.","vi":"Nhà ăn ở 3F; 5F là thư viện."}},{"dlg":[{"sp":"M","zh":"你昨天晚上幾點睡覺？","py":"Nǐ zuó tiān wǎn shàng jǐ diǎn shuì jiào?"},{"sp":"F","zh":"十一點半，今天好累。","py":"Shí yī diǎn bàn, jīn tiān hǎo lèi."}],"q":{"zh":"女的昨天晚上幾點睡覺？","py":"Nǚ de zuó tiān wǎn shàng jǐ diǎn shuì jiào?"},"opts":[{"i":["sleep","clock"],"b":"10:30","bg":"night"},{"i":["sleep","clock"],"b":"11:00","bg":"night"},{"i":["sleep","clock"],"b":"11:30","bg":"night"}],"a":2,"tr":{"id":"M: Tadi malam kamu tidur jam berapa? F: Jam setengah dua belas, hari ini capek sekali. Q: Tadi malam perempuan itu tidur jam berapa?","en":"M: What time did you go to bed last night? F: Half past eleven; I'm so tired today. Q: What time did the woman go to bed last night?","tl":"M: Anong oras ka natulog kagabi? F: Alas-onse y medya, pagod na pagod ako ngayon. Q: Anong oras natulog ang babae kagabi?","vi":"M: Tối qua mấy giờ bạn đi ngủ? F: Mười một giờ rưỡi, hôm nay mệt quá. Q: Tối qua người nữ ngủ lúc mấy giờ?"},"exp":{"id":"十一點半 = 11:30.","en":"十一點半 = 11:30.","tl":"十一點半 = 11:30.","vi":"十一點半 = 11:30."}},{"dlg":[{"sp":"F","zh":"你媽媽在做什麼？","py":"Nǐ mā ma zài zuò shén me?"},{"sp":"M","zh":"她在廚房做蛋糕。","py":"Tā zài chú fáng zuò dàn gāo."}],"q":{"zh":"男的媽媽在做什麼？","py":"Nán de mā ma zài zuò shén me?"},"opts":[{"i":["woman","cook","cake"],"bg":"home"},{"i":["woman","shop"],"bg":"shop"},{"i":["woman","watch_tv"],"bg":"home"}],"a":0,"tr":{"id":"F: Ibumu sedang apa? M: Dia sedang membuat kue di dapur. Q: Ibu laki-laki itu sedang apa?","en":"F: What is your mom doing? M: She's making a cake in the kitchen. Q: What is the man's mother doing?","tl":"F: Ano ang ginagawa ng nanay mo? M: Gumagawa siya ng cake sa kusina. Q: Ano ang ginagawa ng nanay ng lalaki?","vi":"F: Mẹ bạn đang làm gì? M: Mẹ đang làm bánh kem trong bếp. Q: Mẹ người nam đang làm gì?"},"exp":{"id":"做蛋糕 = membuat kue.","en":"做蛋糕 = making a cake.","tl":"做蛋糕 = gumagawa ng cake.","vi":"做蛋糕 = làm bánh kem."}},{"dlg":[{"sp":"M","zh":"今天好冷啊，現在幾度？","py":"Jīn tiān hǎo lěng a, xiàn zài jǐ dù?"},{"sp":"F","zh":"十二度，晚上會更冷。","py":"Shí èr dù, wǎn shàng huì gèng lěng."}],"q":{"zh":"現在幾度？","py":"Xiàn zài jǐ dù?"},"opts":[{"i":["cold"],"b":"20°C"},{"i":["cold"],"b":"12°C"},{"i":["cold"],"b":"2°C"}],"a":1,"tr":{"id":"M: Hari ini dingin sekali, sekarang berapa derajat? F: Dua belas derajat, malam nanti akan lebih dingin. Q: Sekarang berapa derajat?","en":"M: It's so cold today. What's the temperature now? F: Twelve degrees; it'll be colder tonight. Q: What is the temperature now?","tl":"M: Ang lamig ngayon, ilang digri na? F: Labindalawa, mas lalamig pa mamayang gabi. Q: Ilang digri ngayon?","vi":"M: Hôm nay lạnh quá, bây giờ bao nhiêu độ? F: Mười hai độ, tối sẽ lạnh hơn. Q: Bây giờ bao nhiêu độ?"},"exp":{"id":"十二度 = 12°C.","en":"十二度 = 12°C.","tl":"十二度 = 12°C.","vi":"十二度 = 12°C."}}]},{"p":3,"items":[{"dlg":[{"sp":"M","zh":"我們星期六去看電影，好不好？","py":"Wǒ men xīng qí liù qù kàn diàn yǐng, hǎo bù hǎo?"},{"sp":"F","zh":"星期六我要去奶奶家。","py":"Xīng qí liù wǒ yào qù nǎi nai jiā."},{"sp":"M","zh":"那星期天呢？","py":"Nà xīng qí tiān ne?"},{"sp":"F","zh":"星期天可以，下午兩點怎麼樣？","py":"Xīng qí tiān kě yǐ, xià wǔ liǎng diǎn zěn me yàng?"}],"q":{"zh":"他們什麼時候去看電影？","py":"Tā men shén me shí hòu qù kàn diàn yǐng?"},"opts":[{"i":["movie","calendar"],"b":"SAT 2PM"},{"i":["movie","calendar"],"b":"SUN 2PM"},{"i":["movie","calendar"],"b":"SUN 10AM"}],"a":1,"tr":{"id":"M: Sabtu kita nonton film, ya? F: Sabtu saya mau ke rumah nenek. M: Kalau Minggu? F: Minggu bisa, jam dua siang bagaimana? Q: Kapan mereka menonton film?","en":"M: Let's see a movie on Saturday, OK? F: On Saturday I'm going to grandma's. M: What about Sunday? F: Sunday is fine. How about 2 p.m.? Q: When will they see the movie?","tl":"M: Manood tayo ng sine sa Sabado, ayos ba? F: Pupunta ako kina Lola sa Sabado. M: E sa Linggo? F: Puwede sa Linggo, alas-dos ng hapon? Q: Kailan sila manonood ng sine?","vi":"M: Thứ Bảy mình đi xem phim nhé? F: Thứ Bảy mình phải đến nhà bà. M: Thế Chủ nhật thì sao? F: Chủ nhật được, hai giờ chiều nhé? Q: Khi nào họ đi xem phim?"},"exp":{"id":"Sabtu tidak bisa; jadi Minggu jam 2 siang.","en":"Saturday doesn't work, so Sunday at 2 p.m.","tl":"Hindi puwede sa Sabado, kaya Linggo nang 2 p.m.","vi":"Thứ Bảy không được, nên Chủ nhật lúc 2 giờ chiều."}},{"dlg":[{"sp":"F","zh":"你早上吃了什麼？","py":"Nǐ zǎo shàng chī le shén me?"},{"sp":"M","zh":"我本來想吃麵包，可是家裡沒有了。","py":"Wǒ běn lái xiǎng chī miàn bāo, kě shì jiā lǐ méi yǒu le."},{"sp":"F","zh":"那你吃了什麼？","py":"Nà nǐ chī le shén me?"},{"sp":"M","zh":"我吃了一個蛋，喝了一杯牛奶。","py":"Wǒ chī le yí ge dàn, hē le yì bēi niú nǎi."}],"q":{"zh":"男的早上吃了什麼？","py":"Nán de zǎo shàng chī le shén me?"},"opts":[{"i":["bread","milk"]},{"i":["egg","milk"]},{"i":["egg","coffee"]}],"a":1,"tr":{"id":"F: Tadi pagi kamu makan apa? M: Tadinya mau makan roti, tapi di rumah sudah habis. F: Jadi kamu makan apa? M: Saya makan sebutir telur dan minum segelas susu. Q: Tadi pagi laki-laki itu makan apa?","en":"F: What did you eat this morning? M: I wanted bread, but there was none left at home. F: So what did you eat? M: An egg and a glass of milk. Q: What did the man have this morning?","tl":"F: Ano ang kinain mo kaninang umaga? M: Gusto ko sanang tinapay, pero wala na sa bahay. F: E ano ang kinain mo? M: Isang itlog at isang basong gatas. Q: Ano ang kinain ng lalaki kaninang umaga?","vi":"F: Sáng nay bạn ăn gì? M: Mình định ăn bánh mì nhưng ở nhà hết rồi. F: Thế bạn ăn gì? M: Mình ăn một quả trứng, uống một cốc sữa. Q: Sáng nay người nam ăn gì?"},"exp":{"id":"Roti habis; dia makan telur dan minum susu.","en":"No bread left; he had an egg and milk.","tl":"Walang tinapay; itlog at gatas ang kinain niya.","vi":"Hết bánh mì; anh ấy ăn trứng và uống sữa."}},{"dlg":[{"sp":"M","zh":"你們班的中文課在幾號教室？","py":"Nǐ men bān de zhōng wén kè zài jǐ hào jiào shì?"},{"sp":"F","zh":"以前在三零五，這個星期換了。","py":"Yǐ qián zài sān líng wǔ, zhè ge xīng qí huàn le."},{"sp":"M","zh":"換到哪裡了？","py":"Huàn dào nǎ lǐ le?"},{"sp":"F","zh":"換到二零八，在二樓。","py":"Huàn dào èr líng bā, zài èr lóu."}],"q":{"zh":"這個星期中文課在幾號教室？","py":"Zhè ge xīng qí zhōng wén kè zài jǐ hào jiào shì?"},"opts":[{"i":["school","door"],"b":"305"},{"i":["school","door"],"b":"205"},{"i":["school","door"],"b":"208"}],"a":2,"tr":{"id":"M: Kelas Mandarin kelasmu di ruang nomor berapa? F: Dulu di 305, minggu ini pindah. M: Pindah ke mana? F: Ke 208, di lantai dua. Q: Minggu ini kelas Mandarin di ruang nomor berapa?","en":"M: Which classroom is your class's Chinese lesson in? F: It used to be 305, but it changed this week. M: Changed to where? F: To 208, on the second floor. Q: Which classroom is the Chinese class in this week?","tl":"M: Saang silid ang klase ninyo sa Chinese? F: Dati sa 305, pero lumipat ngayong linggo. M: Saan lumipat? F: Sa 208, sa ikalawang palapag. Q: Saang silid ang klase sa Chinese ngayong linggo?","vi":"M: Lớp tiếng Trung của lớp bạn học ở phòng số mấy? F: Trước đây ở 305, tuần này đổi rồi. M: Đổi sang đâu? F: Sang 208, ở tầng hai. Q: Tuần này lớp tiếng Trung ở phòng số mấy?"},"exp":{"id":"Dulu 305, sekarang pindah ke 208.","en":"It was 305 before; now it moved to 208.","tl":"Dati 305, ngayon 208 na.","vi":"Trước là 305, giờ đổi sang 208."}},{"dlg":[{"sp":"F","zh":"外面下雨了，你要怎麼回家？","py":"Wài miàn xià yǔ le, nǐ yào zěn me huí jiā?"},{"sp":"M","zh":"我本來想騎腳踏車。","py":"Wǒ běn lái xiǎng qí jiǎo tà chē."},{"sp":"F","zh":"下雨騎車太危險了。","py":"Xià yǔ qí chē tài wéi xiǎn le."},{"sp":"M","zh":"好吧，那我坐捷運回去。","py":"Hǎo ba, nà wǒ zuò jié yùn huí qù."}],"q":{"zh":"男的怎麼回家？","py":"Nán de zěn me huí jiā?"},"opts":[{"i":["bicycle"],"bg":"rain"},{"i":["mrt"]},{"i":["taxi"]}],"a":1,"tr":{"id":"F: Di luar hujan, kamu pulang naik apa? M: Tadinya saya mau naik sepeda. F: Naik sepeda waktu hujan terlalu berbahaya. M: Baiklah, saya naik MRT saja. Q: Laki-laki itu pulang naik apa?","en":"F: It's raining outside. How will you get home? M: I was going to ride my bike. F: Riding in the rain is too dangerous. M: OK, then I'll take the MRT. Q: How does the man go home?","tl":"F: Umuulan sa labas, paano ka uuwi? M: Balak ko sanang magbisikleta. F: Delikado ang magbisikleta habang umuulan. M: Sige, mag-MRT na lang ako. Q: Paano uuwi ang lalaki?","vi":"F: Ngoài trời mưa rồi, bạn về nhà bằng gì? M: Mình định đạp xe đạp. F: Trời mưa đạp xe nguy hiểm lắm. M: Thôi được, vậy mình đi tàu điện ngầm về. Q: Người nam về nhà bằng gì?"},"exp":{"id":"本來 sepeda, akhirnya 捷運 (MRT).","en":"He planned to bike (本來) but takes the MRT.","tl":"Bisikleta sana (本來), pero MRT na.","vi":"Định đạp xe (本來), cuối cùng đi 捷運."}},{"dlg":[{"sp":"M","zh":"媽，今天晚上吃什麼？","py":"Mā, jīn tiān wǎn shàng chī shén me?"},{"sp":"F","zh":"我想做牛肉麵。","py":"Wǒ xiǎng zuò niú ròu miàn."},{"sp":"M","zh":"我昨天吃過牛肉麵了，可以吃魚嗎？","py":"Wǒ zuó tiān chī guò niú ròu miàn le, kě yǐ chī yú ma?"},{"sp":"F","zh":"好，那我們吃魚和青菜。","py":"Hǎo, nà wǒ men chī yú hé qīng cài."}],"q":{"zh":"他們今天晚上吃什麼？","py":"Tā men jīn tiān wǎn shàng chī shén me?"},"opts":[{"i":["noodles","meat"]},{"i":["meat","vegetables"]},{"i":["fish_food","vegetables"]}],"a":2,"tr":{"id":"M: Bu, malam ini makan apa? F: Ibu mau masak mi daging sapi. M: Kemarin saya sudah makan mi daging sapi, boleh makan ikan? F: Baik, kita makan ikan dan sayur. Q: Malam ini mereka makan apa?","en":"M: Mom, what's for dinner tonight? F: I'm thinking of making beef noodles. M: I had beef noodles yesterday. Can we have fish? F: OK, then we'll have fish and vegetables. Q: What will they eat tonight?","tl":"M: Ma, ano ang hapunan mamaya? F: Gusto kong magluto ng beef noodles. M: Kumain na ako ng beef noodles kahapon, puwede bang isda? F: Sige, isda at gulay tayo. Q: Ano ang kakainin nila mamayang gabi?","vi":"M: Mẹ ơi, tối nay ăn gì ạ? F: Mẹ định nấu mì bò. M: Hôm qua con ăn mì bò rồi, ăn cá được không ạ? F: Được, vậy mình ăn cá và rau. Q: Tối nay họ ăn gì?"},"exp":{"id":"Rencana diganti: ikan dan sayur.","en":"The plan changed to fish and vegetables.","tl":"Napalitan ng isda at gulay.","vi":"Đổi sang ăn cá và rau."}},{"dlg":[{"sp":"F","zh":"你妹妹今年幾歲？","py":"Nǐ mèi mei jīn nián jǐ suì?"},{"sp":"M","zh":"她今年八歲。","py":"Tā jīn nián bā suì."},{"sp":"F","zh":"她上小學了嗎？","py":"Tā shàng xiǎo xué le ma?"},{"sp":"M","zh":"上了，下個月是她的生日，她就九歲了。","py":"Shàng le, xià ge yuè shì tā de shēng rì, tā jiù jiǔ suì le."}],"q":{"zh":"男的妹妹今年幾歲？","py":"Nán de mèi mei jīn nián jǐ suì?"},"opts":[{"i":["girl"],"b":"8"},{"i":["girl"],"b":"9"},{"i":["girl"],"b":"6"}],"a":0,"tr":{"id":"F: Adik perempuanmu tahun ini umur berapa? M: Tahun ini delapan tahun. F: Dia sudah SD? M: Sudah, bulan depan ulang tahunnya, dia jadi sembilan tahun. Q: Adik perempuan laki-laki itu sekarang umur berapa?","en":"F: How old is your little sister this year? M: She's eight. F: Is she in elementary school? M: Yes. Next month is her birthday; she'll be nine. Q: How old is the man's younger sister now?","tl":"F: Ilang taon na ang bunso mong kapatid na babae? M: Walong taon siya. F: Nag-aaral na ba siya sa elementarya? M: Oo, sa susunod na buwan ang kaarawan niya, magsisiyam na siya. Q: Ilang taon ngayon ang kapatid na babae ng lalaki?","vi":"F: Em gái bạn năm nay mấy tuổi? M: Năm nay tám tuổi. F: Em ấy đi học tiểu học chưa? M: Rồi, tháng sau là sinh nhật em, em sẽ chín tuổi. Q: Năm nay em gái người nam mấy tuổi?"},"exp":{"id":"Sekarang 8 tahun; 9 tahun baru bulan depan.","en":"She is 8 now; she turns 9 next month.","tl":"8 taon ngayon; 9 sa susunod na buwan.","vi":"Bây giờ 8 tuổi; tháng sau mới 9."}},{"dlg":[{"sp":"M","zh":"今天天氣怎麼樣？我們去爬山吧。","py":"Jīn tiān tiān qì zěn me yàng? Wǒ men qù pá shān ba."},{"sp":"F","zh":"早上出太陽，可是下午會下大雨。","py":"Zǎo shàng chū tài yáng, kě shì xià wǔ huì xià dà yǔ."},{"sp":"M","zh":"那我們早上去，中午就回來。","py":"Nà wǒ men zǎo shàng qù, zhōng wǔ jiù huí lái."},{"sp":"F","zh":"好，七點出發。","py":"Hǎo, qī diǎn chū fā."}],"q":{"zh":"今天下午天氣怎麼樣？","py":"Jīn tiān xià wǔ tiān qì zěn me yàng?"},"opts":[{"i":["sun"]},{"i":["cloud"]},{"i":["rain"]}],"a":2,"tr":{"id":"M: Cuaca hari ini bagaimana? Ayo kita naik gunung. F: Pagi cerah, tapi sore akan hujan deras. M: Kalau begitu kita pergi pagi, siang sudah pulang. F: Oke, berangkat jam tujuh. Q: Bagaimana cuaca sore ini?","en":"M: How's the weather today? Let's go hiking. F: It's sunny in the morning, but it'll rain hard in the afternoon. M: Then let's go in the morning and be back by noon. F: OK, we leave at seven. Q: What will the weather be like this afternoon?","tl":"M: Kumusta ang panahon ngayon? Umakyat tayo ng bundok. F: Maaraw sa umaga, pero uulan nang malakas sa hapon. M: Kung gayon umaga tayo pumunta, bumalik sa tanghali. F: Sige, alis tayo nang alas-siyete. Q: Ano ang panahon ngayong hapon?","vi":"M: Hôm nay thời tiết thế nào? Mình đi leo núi đi. F: Sáng có nắng, nhưng chiều sẽ mưa to. M: Vậy mình đi buổi sáng, trưa về. F: Ừ, bảy giờ xuất phát. Q: Chiều nay thời tiết thế nào?"},"exp":{"id":"Sore 下大雨 = hujan deras; cerah hanya pagi.","en":"Afternoon: 下大雨, heavy rain; sun is only in the morning.","tl":"Hapon: 下大雨, malakas na ulan.","vi":"Buổi chiều: 下大雨, mưa to; nắng chỉ buổi sáng."}},{"dlg":[{"sp":"F","zh":"你吃過晚飯了嗎？","py":"Nǐ chī guò wǎn fàn le ma?"},{"sp":"M","zh":"還沒，我想去夜市。","py":"Hái méi, wǒ xiǎng qù yè shì."},{"sp":"F","zh":"夜市今天人很多，去學校旁邊的餐廳吧。","py":"Yè shì jīn tiān rén hěn duō, qù xué xiào páng biān de cān tīng ba."},{"sp":"M","zh":"好啊，就去那裡。","py":"Hǎo a, jiù qù nà lǐ."}],"q":{"zh":"他們要去哪裡吃晚飯？","py":"Tā men yào qù nǎ lǐ chī wǎn fàn?"},"opts":[{"i":["night_market"],"bg":"night"},{"i":["restaurant"]},{"i":["house"],"bg":"home"}],"a":1,"tr":{"id":"F: Kamu sudah makan malam? M: Belum, saya mau ke pasar malam. F: Pasar malam hari ini ramai sekali, ke restoran di samping sekolah saja. M: Oke, ke sana saja. Q: Mereka akan makan malam di mana?","en":"F: Have you had dinner? M: Not yet. I want to go to the night market. F: The night market is crowded today; let's go to the restaurant next to school. M: OK, let's go there. Q: Where will they have dinner?","tl":"F: Naghapunan ka na ba? M: Hindi pa, gusto kong pumunta sa night market. F: Maraming tao sa night market ngayon, sa restawran na lang sa tabi ng paaralan. M: Sige, doon na lang. Q: Saan sila maghahapunan?","vi":"F: Bạn ăn tối chưa? M: Chưa, mình muốn đi chợ đêm. F: Hôm nay chợ đêm đông lắm, đi nhà hàng cạnh trường đi. M: Được, đi đó. Q: Họ sẽ ăn tối ở đâu?"},"exp":{"id":"Pasar malam ramai; mereka ke restoran.","en":"The night market is crowded, so they go to the restaurant.","tl":"Matao sa night market, kaya sa restawran sila.","vi":"Chợ đêm đông nên họ đi nhà hàng."}},{"dlg":[{"sp":"M","zh":"喂，你在哪裡？電影七點開始。","py":"Wéi, nǐ zài nǎ lǐ? Diàn yǐng qī diǎn kāi shǐ."},{"sp":"F","zh":"對不起，我在公車上，路上車很多。","py":"Duì bù qǐ, wǒ zài gōng chē shàng, lù shàng chē hěn duō."},{"sp":"M","zh":"你幾點會到？","py":"Nǐ jǐ diǎn huì dào?"},{"sp":"F","zh":"大概七點二十分。","py":"Dà gài qī diǎn èr shí fēn."}],"q":{"zh":"女的大概幾點會到？","py":"Nǚ de dà gài jǐ diǎn huì dào?"},"opts":[{"i":["clock"],"b":"07:20"},{"i":["clock"],"b":"07:00"},{"i":["clock"],"b":"07:10"}],"a":0,"tr":{"id":"M: Halo, kamu di mana? Filmnya mulai jam tujuh. F: Maaf, saya di bus, jalannya macet. M: Jam berapa kamu sampai? F: Kira-kira jam tujuh lewat dua puluh. Q: Kira-kira jam berapa perempuan itu sampai?","en":"M: Hello, where are you? The movie starts at seven. F: Sorry, I'm on the bus; there's a lot of traffic. M: What time will you get here? F: About 7:20. Q: About what time will the woman arrive?","tl":"M: Hello, nasaan ka? Alas-siyete magsisimula ang sine. F: Pasensya, nasa bus ako, maraming sasakyan. M: Anong oras ka darating? F: Mga 7:20. Q: Mga anong oras darating ang babae?","vi":"M: Alô, bạn đang ở đâu? Phim bắt đầu lúc bảy giờ. F: Xin lỗi, mình đang trên xe buýt, đường đông xe. M: Mấy giờ bạn đến? F: Khoảng bảy giờ hai mươi. Q: Người nữ khoảng mấy giờ đến?"},"exp":{"id":"7:00 film mulai; dia tiba sekitar 7:20.","en":"7:00 is the movie; she arrives about 7:20.","tl":"7:00 ang sine; darating siya mga 7:20.","vi":"7:00 là giờ phim; cô ấy đến khoảng 7:20."}},{"dlg":[{"sp":"F","zh":"你什麼時候去日本？","py":"Nǐ shén me shí hòu qù Rì běn?"},{"sp":"M","zh":"本來是七月，可是我七月要上課。","py":"Běn lái shì qī yuè, kě shì wǒ qī yuè yào shàng kè."},{"sp":"F","zh":"那改到什麼時候？","py":"Nà gǎi dào shén me shí hòu?"},{"sp":"M","zh":"改到八月了。","py":"Gǎi dào bā yuè le."}],"q":{"zh":"男的幾月去日本？","py":"Nán de jǐ yuè qù Rì běn?"},"opts":[{"i":["airplane","calendar"],"b":"AUG"},{"i":["airplane","calendar"],"b":"JUL"},{"i":["airplane","calendar"],"b":"SEP"}],"a":0,"tr":{"id":"F: Kapan kamu pergi ke Jepang? M: Tadinya bulan Juli, tapi Juli saya ada kuliah. F: Jadi diganti ke kapan? M: Diganti ke bulan Agustus. Q: Laki-laki itu pergi ke Jepang bulan apa?","en":"F: When are you going to Japan? M: It was going to be July, but I have classes in July. F: So when did you change it to? M: To August. Q: In which month will the man go to Japan?","tl":"F: Kailan ka pupunta sa Japan? M: Hulyo sana, pero may klase ako sa Hulyo. F: Kailan na lang? M: Inilipat ko sa Agosto. Q: Anong buwan pupunta sa Japan ang lalaki?","vi":"F: Khi nào bạn đi Nhật? M: Lúc đầu là tháng Bảy, nhưng tháng Bảy mình phải đi học. F: Vậy đổi sang khi nào? M: Đổi sang tháng Tám rồi. Q: Người nam đi Nhật vào tháng mấy?"},"exp":{"id":"本來 Juli, 改到 Agustus.","en":"Originally July, changed to August.","tl":"Hulyo sana, inilipat sa Agosto.","vi":"Ban đầu tháng 7, đổi sang tháng 8."}},{"dlg":[{"sp":"M","zh":"老師，明天的考試在早上嗎？","py":"Lǎo shī, míng tiān de kǎo shì zài zǎo shàng ma?"},{"sp":"F","zh":"不是早上，是下午。","py":"Bú shì zǎo shàng, shì xià wǔ."},{"sp":"M","zh":"下午幾點？","py":"Xià wǔ jǐ diǎn?"},{"sp":"F","zh":"兩點，不要遲到。","py":"Liǎng diǎn, bú yào chí dào."}],"q":{"zh":"明天的考試幾點開始？","py":"Míng tiān de kǎo shì jǐ diǎn kāi shǐ?"},"opts":[{"i":["clock","notebook"],"b":"14:00"},{"i":["clock","notebook"],"b":"10:00"},{"i":["clock","notebook"],"b":"12:00"}],"a":0,"tr":{"id":"M: Bu guru, ujian besok pagi? F: Bukan pagi, tapi siang. M: Siang jam berapa? F: Jam dua, jangan terlambat. Q: Ujian besok mulai jam berapa?","en":"M: Teacher, is tomorrow's exam in the morning? F: Not in the morning, in the afternoon. M: What time in the afternoon? F: Two o'clock. Don't be late. Q: What time does tomorrow's exam start?","tl":"M: Titser, sa umaga po ba ang pagsusulit bukas? F: Hindi sa umaga, sa hapon. M: Anong oras po sa hapon? F: Alas-dos, huwag kang mahuhuli. Q: Anong oras magsisimula ang pagsusulit bukas?","vi":"M: Cô ơi, bài thi ngày mai vào buổi sáng ạ? F: Không phải buổi sáng, là buổi chiều. M: Chiều mấy giờ ạ? F: Hai giờ, đừng đến muộn. Q: Bài thi ngày mai bắt đầu lúc mấy giờ?"},"exp":{"id":"下午兩點 = 14:00.","en":"下午兩點 = 2 p.m. = 14:00.","tl":"下午兩點 = 2 p.m. = 14:00.","vi":"下午兩點 = 14:00."}},{"dlg":[{"sp":"F","zh":"你在找什麼？","py":"Nǐ zài zhǎo shén me?"},{"sp":"M","zh":"我的手機，我以為在桌子上。","py":"Wǒ de shǒu jī, wǒ yǐ wéi zài zhuō zi shàng."},{"sp":"F","zh":"不在桌子上，在沙發上，你看。","py":"Bú zài zhuō zi shàng, zài shā fā shàng, nǐ kàn."},{"sp":"M","zh":"啊，找到了，謝謝。","py":"A, zhǎo dào le, xiè xie."}],"q":{"zh":"手機在哪裡？","py":"Shǒu jī zài nǎ lǐ?"},"opts":[{"i":["phone","table"],"bg":"home"},{"i":["phone","sofa"],"bg":"home"},{"i":["phone","bed"],"bg":"home"}],"a":1,"tr":{"id":"F: Kamu cari apa? M: HP saya, saya kira di atas meja. F: Bukan di meja, di sofa, lihat. M: Ah, ketemu, terima kasih. Q: HP-nya di mana?","en":"F: What are you looking for? M: My phone. I thought it was on the table. F: It's not on the table, it's on the sofa, look. M: Ah, found it, thanks. Q: Where is the phone?","tl":"F: Ano ang hinahanap mo? M: Ang cellphone ko, akala ko nasa mesa. F: Wala sa mesa, nasa sofa, tingnan mo. M: Ay, nakita ko na, salamat. Q: Nasaan ang cellphone?","vi":"F: Bạn đang tìm gì? M: Điện thoại của mình, mình tưởng ở trên bàn. F: Không ở trên bàn, ở trên sofa kìa. M: À, thấy rồi, cảm ơn. Q: Điện thoại ở đâu?"},"exp":{"id":"不在桌子上，在沙發上 = di sofa.","en":"Not on the table but on the sofa.","tl":"Wala sa mesa, nasa sofa.","vi":"Không ở trên bàn mà ở trên sofa."}},{"dlg":[{"sp":"M","zh":"你姊姊結婚了嗎？","py":"Nǐ jiě jie jié hūn le ma?"},{"sp":"F","zh":"還沒有，她明年結婚。","py":"Hái méi yǒu, tā míng nián jié hūn."},{"sp":"M","zh":"她現在做什麼工作？","py":"Tā xiàn zài zuò shén me gōng zuò?"},{"sp":"F","zh":"她以前是老師，現在在銀行工作。","py":"Tā yǐ qián shì lǎo shī, xiàn zài zài yín háng gōng zuò."}],"q":{"zh":"女的姊姊現在在哪裡工作？","py":"Nǚ de jiě jie xiàn zài zài nǎ lǐ gōng zuò?"},"opts":[{"i":["bank","woman"]},{"i":["school","teacher"]},{"i":["post_office","woman"]}],"a":0,"tr":{"id":"M: Kakak perempuanmu sudah menikah? F: Belum, dia menikah tahun depan. M: Sekarang dia kerja apa? F: Dulu dia guru, sekarang kerja di bank. Q: Kakak perempuan dari perempuan itu sekarang bekerja di mana?","en":"M: Is your older sister married? F: Not yet; she's getting married next year. M: What does she do now? F: She used to be a teacher; now she works at a bank. Q: Where does the woman's older sister work now?","tl":"M: May asawa na ba ang ate mo? F: Wala pa, ikakasal siya sa susunod na taon. M: Ano ang trabaho niya ngayon? F: Guro siya dati, ngayon sa bangko na siya nagtatrabaho. Q: Saan nagtatrabaho ngayon ang ate ng babae?","vi":"M: Chị gái bạn kết hôn chưa? F: Chưa, sang năm chị ấy cưới. M: Bây giờ chị ấy làm nghề gì? F: Trước kia là giáo viên, giờ làm ở ngân hàng. Q: Chị gái người nữ hiện làm ở đâu?"},"exp":{"id":"以前 guru; 現在 di bank.","en":"Before: teacher; now (現在): bank.","tl":"Dati guro; ngayon (現在) sa bangko.","vi":"Trước là giáo viên; giờ (現在) ở ngân hàng."}},{"dlg":[{"sp":"F","zh":"這家店的珍珠奶茶很好喝，你要不要？","py":"Zhè jiā diàn de zhēn zhū nǎi chá hěn hǎo hē, nǐ yào bú yào?"},{"sp":"M","zh":"我不喝甜的。","py":"Wǒ bù hē tián de."},{"sp":"F","zh":"那喝綠茶吧，不加糖。","py":"Nà hē lǜ chá ba, bù jiā táng."},{"sp":"M","zh":"好，我要一杯綠茶。","py":"Hǎo, wǒ yào yì bēi lǜ chá."}],"q":{"zh":"男的要喝什麼？","py":"Nán de yào hē shén me?"},"opts":[{"i":["bubble_tea"]},{"i":["juice"]},{"i":["tea"]}],"a":2,"tr":{"id":"F: Bubble tea di toko ini enak, kamu mau? M: Saya tidak minum yang manis. F: Kalau begitu minum teh hijau saja, tanpa gula. M: Oke, saya mau secangkir teh hijau. Q: Laki-laki itu mau minum apa?","en":"F: This shop's bubble tea is really good. Do you want some? M: I don't drink sweet things. F: Then have green tea, no sugar. M: OK, one green tea, please. Q: What does the man want to drink?","tl":"F: Masarap ang bubble tea dito, gusto mo? M: Hindi ako umiinom ng matamis. F: E di green tea na lang, walang asukal. M: Sige, isang green tea. Q: Ano ang gustong inumin ng lalaki?","vi":"F: Trà sữa trân châu quán này ngon lắm, bạn uống không? M: Mình không uống đồ ngọt. F: Vậy uống trà xanh đi, không đường. M: Được, cho mình một cốc trà xanh. Q: Người nam muốn uống gì?"},"exp":{"id":"Tidak suka manis; dia pilih 綠茶 (teh hijau).","en":"He doesn't drink sweet drinks; he chooses green tea.","tl":"Ayaw niya ng matamis; green tea ang pinili niya.","vi":"Không uống ngọt; anh ấy chọn trà xanh."}},{"dlg":[{"sp":"M","zh":"我們幾點在學校門口見面？","py":"Wǒ men jǐ diǎn zài xué xiào mén kǒu jiàn miàn?"},{"sp":"F","zh":"八點半，好嗎？","py":"Bā diǎn bàn, hǎo ma?"},{"sp":"M","zh":"太早了，九點吧。","py":"Tài zǎo le, jiǔ diǎn ba."},{"sp":"F","zh":"好，那就九點，不要晚了。","py":"Hǎo, nà jiù jiǔ diǎn, bú yào wǎn le."}],"q":{"zh":"他們幾點見面？","py":"Tā men jǐ diǎn jiàn miàn?"},"opts":[{"i":["school","clock"],"b":"08:30"},{"i":["school","clock"],"b":"09:30"},{"i":["school","clock"],"b":"09:00"}],"a":2,"tr":{"id":"M: Kita ketemu di depan gerbang sekolah jam berapa? F: Jam setengah sembilan, bagaimana? M: Terlalu pagi, jam sembilan saja. F: Oke, jam sembilan, jangan telat. Q: Mereka bertemu jam berapa?","en":"M: What time shall we meet at the school gate? F: 8:30, OK? M: Too early. Let's say nine. F: OK, nine then. Don't be late. Q: What time will they meet?","tl":"M: Anong oras tayo magkikita sa gate ng paaralan? F: 8:30, ayos ba? M: Masyadong maaga, alas-nuwebe na lang. F: Sige, alas-nuwebe, huwag kang mahuhuli. Q: Anong oras sila magkikita?","vi":"M: Mấy giờ mình gặp nhau ở cổng trường? F: Tám giờ rưỡi nhé? M: Sớm quá, chín giờ đi. F: Được, vậy chín giờ, đừng đến muộn. Q: Họ gặp nhau lúc mấy giờ?"},"exp":{"id":"8:30 terlalu pagi; disepakati jam 9:00.","en":"8:30 was too early; they agreed on 9:00.","tl":"Masyadong maaga ang 8:30; 9:00 ang napagkasunduan.","vi":"8:30 sớm quá; họ thống nhất 9:00."}}]},{"p":4,"items":[{"dlg":[{"sp":"F","zh":"你為什麼今天沒來上課？","py":"Nǐ wèi shén me jīn tiān méi lái shàng kè?"},{"sp":"M","zh":"我昨天晚上發燒了，今天去看醫生。","py":"Wǒ zuó tiān wǎn shàng fā shāo le, jīn tiān qù kàn yī shēng."},{"sp":"F","zh":"現在好一點了嗎？","py":"Xiàn zài hǎo yì diǎn le ma?"},{"sp":"M","zh":"好多了，明天就可以去學校了。","py":"Hǎo duō le, míng tiān jiù kě yǐ qù xué xiào le."}],"q":{"zh":"男的今天為什麼沒去上課？","py":"Nán de jīn tiān wèi shén me méi qù shàng kè?"},"opts":[{"zh":"他生病了","py":"Tā shēng bìng le"},{"zh":"他要去旅行","py":"Tā yào qù lǚ xíng"},{"zh":"他起床太晚了","py":"Tā qǐ chuáng tài wǎn le"},{"zh":"他忘了上課的時間","py":"Tā wàng le shàng kè de shí jiān"}],"a":0,"tr":{"id":"F: Kenapa hari ini kamu tidak masuk kelas? M: Tadi malam saya demam, hari ini ke dokter. F: Sekarang sudah lebih baik? M: Jauh lebih baik, besok sudah bisa ke sekolah. Q: Kenapa laki-laki itu hari ini tidak masuk kelas?","en":"F: Why didn't you come to class today? M: I had a fever last night, so I went to the doctor today. F: Are you better now? M: Much better. I can go to school tomorrow. Q: Why didn't the man go to class today?","tl":"F: Bakit hindi ka pumasok sa klase ngayon? M: Nilagnat ako kagabi, nagpatingin ako sa doktor ngayon. F: Medyo okay ka na ba? M: Mas mabuti na, makakapasok na ako bukas. Q: Bakit hindi pumasok sa klase ang lalaki ngayon?","vi":"F: Sao hôm nay bạn không đến lớp? M: Tối qua mình bị sốt, hôm nay đi khám bác sĩ. F: Giờ đỡ hơn chưa? M: Đỡ nhiều rồi, mai đi học được. Q: Vì sao hôm nay người nam không đi học?"},"exp":{"id":"發燒, 看醫生 = dia sakit.","en":"He had a fever and saw a doctor: he was sick.","tl":"Nilagnat at nagpadoktor: may sakit siya.","vi":"Bị sốt, đi khám bác sĩ: anh ấy bị ốm."}},{"dlg":[{"sp":"M","zh":"這家餐廳的菜怎麼樣？","py":"Zhè jiā cān tīng de cài zěn me yàng?"},{"sp":"F","zh":"很好吃，可是有一點貴。","py":"Hěn hǎo chī, kě shì yǒu yì diǎn guì."},{"sp":"M","zh":"兩個人大概多少錢？","py":"Liǎng ge rén dà gài duō shǎo qián?"},{"sp":"F","zh":"大概一千塊。","py":"Dà gài yì qiān kuài."}],"q":{"zh":"女的覺得這家餐廳怎麼樣？","py":"Nǚ de jué de zhè jiā cān tīng zěn me yàng?"},"opts":[{"zh":"好吃，也很便宜","py":"Hǎo chī, yě hěn pián yí"},{"zh":"不好吃，可是很便宜","py":"Bù hǎo chī, kě shì hěn pián yí"},{"zh":"好吃，可是有點貴","py":"Hǎo chī, kě shì yǒu diǎn guì"},{"zh":"不好吃，也很貴","py":"Bù hǎo chī, yě hěn guì"}],"a":2,"tr":{"id":"M: Bagaimana masakan di restoran ini? F: Enak sekali, tapi agak mahal. M: Dua orang kira-kira berapa? F: Kira-kira seribu dolar. Q: Menurut perempuan itu, restoran ini bagaimana?","en":"M: How's the food at this restaurant? F: Very tasty, but a bit expensive. M: About how much for two people? F: About a thousand dollars. Q: What does the woman think of this restaurant?","tl":"M: Kumusta ang pagkain sa restawran na ito? F: Masarap, pero medyo mahal. M: Mga magkano para sa dalawa? F: Mga isang libong dolyar. Q: Ano ang palagay ng babae sa restawran?","vi":"M: Món ăn ở nhà hàng này thế nào? F: Rất ngon, nhưng hơi đắt. M: Hai người khoảng bao nhiêu tiền? F: Khoảng một nghìn đồng. Q: Người nữ thấy nhà hàng này thế nào?"},"exp":{"id":"很好吃，可是有一點貴 = enak tapi agak mahal.","en":"很好吃，可是有一點貴: tasty but a bit pricey.","tl":"Masarap pero medyo mahal.","vi":"Ngon nhưng hơi đắt."}},{"dlg":[{"sp":"F","zh":"你週末要做什麼？","py":"Nǐ zhōu mò yào zuò shén me?"},{"sp":"M","zh":"星期六要去打工，星期天要在家寫功課。","py":"Xīng qí liù yào qù dǎ gōng, xīng qí tiān yào zài jiā xiě gōng kè."},{"sp":"F","zh":"星期天晚上要不要一起去吃火鍋？","py":"Xīng qí tiān wǎn shàng yào bú yào yì qǐ qù chī huǒ guō?"},{"sp":"M","zh":"好啊，寫完功課我就去。","py":"Hǎo a, xiě wán gōng kè wǒ jiù qù."}],"q":{"zh":"男的星期天晚上要做什麼？","py":"Nán de xīng qí tiān wǎn shàng yào zuò shén me?"},"opts":[{"zh":"去打工","py":"Qù dǎ gōng"},{"zh":"在家寫功課","py":"Zài jiā xiě gōng kè"},{"zh":"去吃火鍋","py":"Qù chī huǒ guō"},{"zh":"去看電影","py":"Qù kàn diàn yǐng"}],"a":2,"tr":{"id":"F: Akhir pekan kamu mau apa? M: Sabtu kerja paruh waktu, Minggu mengerjakan PR di rumah. F: Minggu malam mau makan hot pot bersama? M: Boleh, setelah PR selesai saya datang. Q: Minggu malam laki-laki itu mau apa?","en":"F: What are you doing this weekend? M: Part-time job on Saturday, homework at home on Sunday. F: Want to have hot pot together Sunday evening? M: Sure, I'll come after I finish my homework. Q: What will the man do on Sunday evening?","tl":"F: Ano ang gagawin mo ngayong weekend? M: Sa Sabado may part-time ako, sa Linggo gagawa ako ng takdang-aralin sa bahay. F: Gusto mo bang mag-hot pot tayo sa Linggo ng gabi? M: Sige, pagkatapos ng takdang-aralin pupunta ako. Q: Ano ang gagawin ng lalaki sa Linggo ng gabi?","vi":"F: Cuối tuần bạn làm gì? M: Thứ Bảy đi làm thêm, Chủ nhật ở nhà làm bài tập. F: Tối Chủ nhật đi ăn lẩu cùng nhau không? M: Được, làm xong bài tập mình đi. Q: Tối Chủ nhật người nam làm gì?"},"exp":{"id":"Minggu malam, setelah PR, dia makan hot pot.","en":"Sunday evening, after homework, he goes for hot pot.","tl":"Linggo ng gabi, pagkatapos ng aralin, hot pot.","vi":"Tối Chủ nhật, làm bài xong, anh ấy đi ăn lẩu."}},{"dlg":[{"sp":"M","zh":"你們家誰最會做菜？","py":"Nǐ men jiā shéi zuì huì zuò cài?"},{"sp":"F","zh":"以前是媽媽，現在是爸爸。","py":"Yǐ qián shì mā ma, xiàn zài shì bà ba."},{"sp":"M","zh":"真的嗎？你爸爸會做什麼菜？","py":"Zhēn de ma? Nǐ bà ba huì zuò shén me cài?"},{"sp":"F","zh":"他最會做魚，每個星期都做。","py":"Tā zuì huì zuò yú, měi ge xīng qí dōu zuò."}],"q":{"zh":"現在女的家誰最會做菜？","py":"Xiàn zài nǚ de jiā shéi zuì huì zuò cài?"},"opts":[{"zh":"媽媽","py":"Mā ma"},{"zh":"爸爸","py":"Bà ba"},{"zh":"奶奶","py":"Nǎi nai"},{"zh":"哥哥","py":"Gē ge"}],"a":1,"tr":{"id":"M: Di keluargamu siapa yang paling pintar masak? F: Dulu ibu, sekarang ayah. M: Benarkah? Ayahmu bisa masak apa? F: Dia paling pintar masak ikan, setiap minggu masak. Q: Sekarang siapa yang paling pintar masak di keluarga perempuan itu?","en":"M: Who's the best cook in your family? F: It used to be mom; now it's dad. M: Really? What can your dad cook? F: He's best at fish; he makes it every week. Q: Who is the best cook in the woman's family now?","tl":"M: Sino ang pinakamagaling magluto sa pamilya ninyo? F: Dati si Nanay, ngayon si Tatay. M: Talaga? Ano ang kayang lutuin ng tatay mo? F: Pinakamagaling siya sa isda, linggo-linggo niyang niluluto. Q: Sino ngayon ang pinakamagaling magluto sa pamilya ng babae?","vi":"M: Nhà bạn ai nấu ăn giỏi nhất? F: Trước là mẹ, bây giờ là bố. M: Thật à? Bố bạn nấu được món gì? F: Bố nấu cá giỏi nhất, tuần nào cũng nấu. Q: Bây giờ ai nấu ăn giỏi nhất nhà người nữ?"},"exp":{"id":"以前 ibu, 現在 ayah.","en":"Before (以前) mom, now (現在) dad.","tl":"Dati si Nanay, ngayon si Tatay.","vi":"Trước là mẹ, bây giờ là bố."}},{"dlg":[{"sp":"F","zh":"明天是幾月幾號？","py":"Míng tiān shì jǐ yuè jǐ hào?"},{"sp":"M","zh":"明天是三月二十號。","py":"Míng tiān shì sān yuè èr shí hào."},{"sp":"F","zh":"糟糕，明天是我媽媽的生日，我還沒買禮物。","py":"Zāo gāo, míng tiān shì wǒ mā ma de shēng rì, wǒ hái méi mǎi lǐ wù."},{"sp":"M","zh":"我陪你去買吧。","py":"Wǒ péi nǐ qù mǎi ba."}],"q":{"zh":"女的媽媽的生日是什麼時候？","py":"Nǚ de mā ma de shēng rì shì shén me shí hòu?"},"opts":[{"zh":"三月十號","py":"Sān yuè shí hào"},{"zh":"三月二十號","py":"Sān yuè èr shí hào"},{"zh":"二月十三號","py":"Èr yuè shí sān hào"},{"zh":"四月二十號","py":"Sì yuè èr shí hào"}],"a":1,"tr":{"id":"F: Besok tanggal berapa? M: Besok 20 Maret. F: Gawat, besok ulang tahun ibu saya, saya belum beli hadiah. M: Saya temani kamu beli. Q: Kapan ulang tahun ibu perempuan itu?","en":"F: What's the date tomorrow? M: Tomorrow is March 20th. F: Oh no, tomorrow is my mom's birthday and I haven't bought a present. M: I'll go shopping with you. Q: When is the woman's mother's birthday?","tl":"F: Anong petsa bukas? M: Marso 20 bukas. F: Naku, kaarawan ng nanay ko bukas, wala pa akong regalo. M: Sasamahan kitang bumili. Q: Kailan ang kaarawan ng nanay ng babae?","vi":"F: Ngày mai là ngày mấy tháng mấy? M: Mai là ngày 20 tháng 3. F: Chết rồi, mai là sinh nhật mẹ mình, mình chưa mua quà. M: Mình đi mua với bạn. Q: Sinh nhật mẹ người nữ là khi nào?"},"exp":{"id":"Besok = 20 Maret = ulang tahun ibunya.","en":"Tomorrow, March 20, is her mom's birthday.","tl":"Bukas, Marso 20, ang kaarawan ng nanay niya.","vi":"Ngày mai, 20 tháng 3, là sinh nhật mẹ cô ấy."}},{"dlg":[{"sp":"M","zh":"你每天怎麼去上班？","py":"Nǐ měi tiān zěn me qù shàng bān?"},{"sp":"F","zh":"以前坐公車，可是常常塞車。","py":"Yǐ qián zuò gōng chē, kě shì cháng cháng sāi chē."},{"sp":"M","zh":"那現在呢？","py":"Nà xiàn zài ne?"},{"sp":"F","zh":"現在騎機車，二十分鐘就到了。","py":"Xiàn zài qí jī chē, èr shí fēn zhōng jiù dào le."}],"q":{"zh":"女的現在怎麼去上班？","py":"Nǚ de xiàn zài zěn me qù shàng bān?"},"opts":[{"zh":"坐公車","py":"Zuò gōng chē"},{"zh":"坐捷運","py":"Zuò jié yùn"},{"zh":"騎腳踏車","py":"Qí jiǎo tà chē"},{"zh":"騎機車","py":"Qí jī chē"}],"a":3,"tr":{"id":"M: Setiap hari kamu ke kantor naik apa? F: Dulu naik bus, tapi sering macet. M: Kalau sekarang? F: Sekarang naik motor, dua puluh menit sudah sampai. Q: Sekarang perempuan itu ke kantor naik apa?","en":"M: How do you get to work every day? F: I used to take the bus, but there were often traffic jams. M: And now? F: Now I ride a scooter; I get there in twenty minutes. Q: How does the woman get to work now?","tl":"M: Paano ka pumapasok sa trabaho araw-araw? F: Dati nagba-bus ako, pero laging trapik. M: E ngayon? F: Ngayon nagmo-motor ako, dalawampung minuto lang. Q: Paano pumapasok sa trabaho ang babae ngayon?","vi":"M: Hằng ngày bạn đi làm bằng gì? F: Trước đi xe buýt, nhưng hay bị tắc đường. M: Còn bây giờ? F: Bây giờ đi xe máy, hai mươi phút là đến. Q: Bây giờ người nữ đi làm bằng gì?"},"exp":{"id":"Dulu bus; 現在騎機車 = sekarang naik motor.","en":"Bus before; now she rides a scooter (機車).","tl":"Bus dati; ngayon motor (機車).","vi":"Trước đi xe buýt; giờ đi xe máy (機車)."}},{"dlg":[{"sp":"F","zh":"今天好熱，我們去吃冰吧。","py":"Jīn tiān hǎo rè, wǒ men qù chī bīng ba."},{"sp":"M","zh":"好啊，可是我感冒了，不能吃冰的。","py":"Hǎo a, kě shì wǒ gǎn mào le, bù néng chī bīng de."},{"sp":"F","zh":"那你喝熱茶，我吃冰。","py":"Nà nǐ hē rè chá, wǒ chī bīng."},{"sp":"M","zh":"好，就這樣。","py":"Hǎo, jiù zhè yàng."}],"q":{"zh":"男的為什麼不吃冰？","py":"Nán de wèi shén me bù chī bīng?"},"opts":[{"zh":"他不喜歡吃冰","py":"Tā bù xǐ huān chī bīng"},{"zh":"他感冒了","py":"Tā gǎn mào le"},{"zh":"天氣太冷了","py":"Tiān qì tài lěng le"},{"zh":"他吃過了","py":"Tā chī guò le"}],"a":1,"tr":{"id":"F: Hari ini panas sekali, ayo makan es serut. M: Boleh, tapi saya lagi pilek, tidak boleh makan yang dingin. F: Kalau begitu kamu minum teh panas, saya makan es. M: Oke, begitu saja. Q: Kenapa laki-laki itu tidak makan es?","en":"F: It's so hot today. Let's go eat shaved ice. M: Sure, but I have a cold, so I can't eat cold things. F: Then you have hot tea and I'll have shaved ice. M: OK, deal. Q: Why doesn't the man eat shaved ice?","tl":"F: Ang init ngayon, kain tayo ng shaved ice. M: Sige, pero may sipon ako, bawal ang malamig. F: E di ikaw mainit na tsaa, ako ang shaved ice. M: Sige, ganoon na lang. Q: Bakit hindi kakain ng shaved ice ang lalaki?","vi":"F: Hôm nay nóng quá, mình đi ăn đá bào đi. M: Được, nhưng mình bị cảm, không ăn đồ lạnh được. F: Vậy bạn uống trà nóng, mình ăn đá bào. M: Ừ, vậy nhé. Q: Vì sao người nam không ăn đá bào?"},"exp":{"id":"Dia bilang 我感冒了 (pilek).","en":"He said 我感冒了: he has a cold.","tl":"Sabi niya 我感冒了: may sipon siya.","vi":"Anh ấy nói 我感冒了: bị cảm."}},{"dlg":[{"sp":"M","zh":"你的中文說得真好，學了多久了？","py":"Nǐ de zhōng wén shuō de zhēn hǎo, xué le duō jiǔ le?"},{"sp":"F","zh":"學了兩年了。","py":"Xué le liǎng nián le."},{"sp":"M","zh":"你在哪裡學的？","py":"Nǐ zài nǎ lǐ xué de?"},{"sp":"F","zh":"先在印尼學了一年，後來到臺灣又學了一年。","py":"Xiān zài Yìn ní xué le yì nián, hòu lái dào Tái wān yòu xué le yì nián."}],"q":{"zh":"女的在臺灣學了多久中文？","py":"Nǚ de zài Tái wān xué le duō jiǔ zhōng wén?"},"opts":[{"zh":"半年","py":"Bàn nián"},{"zh":"兩年","py":"Liǎng nián"},{"zh":"三年","py":"Sān nián"},{"zh":"一年","py":"Yì nián"}],"a":3,"tr":{"id":"M: Bahasa Mandarinmu bagus sekali, sudah belajar berapa lama? F: Sudah dua tahun. M: Belajar di mana? F: Mula-mula setahun di Indonesia, lalu setahun lagi di Taiwan. Q: Berapa lama perempuan itu belajar Mandarin di Taiwan?","en":"M: Your Chinese is really good. How long have you studied? F: Two years. M: Where did you study? F: First one year in Indonesia, then another year in Taiwan. Q: How long did the woman study Chinese in Taiwan?","tl":"M: Ang galing mong mag-Chinese, gaano ka na katagal nag-aaral? F: Dalawang taon na. M: Saan ka nag-aral? F: Isang taon muna sa Indonesia, tapos isa pang taon sa Taiwan. Q: Gaano katagal nag-aral ng Chinese ang babae sa Taiwan?","vi":"M: Tiếng Trung của bạn giỏi quá, học bao lâu rồi? F: Học hai năm rồi. M: Bạn học ở đâu? F: Đầu tiên học một năm ở Indonesia, sau đó sang Đài Loan học thêm một năm. Q: Người nữ học tiếng Trung ở Đài Loan bao lâu?"},"exp":{"id":"Total 2 tahun, tapi di Taiwan hanya 一年.","en":"Two years in total, but only one (一年) in Taiwan.","tl":"Dalawang taon lahat, pero isa (一年) lang sa Taiwan.","vi":"Tổng hai năm, nhưng ở Đài Loan chỉ 一年."}},{"dlg":[{"sp":"F","zh":"你家離學校遠不遠？","py":"Nǐ jiā lí xué xiào yuǎn bù yuǎn?"},{"sp":"M","zh":"不太遠，走路十五分鐘。","py":"Bú tài yuǎn, zǒu lù shí wǔ fēn zhōng."},{"sp":"F","zh":"下雨的時候呢？","py":"Xià yǔ de shí hòu ne?"},{"sp":"M","zh":"下雨的時候，我爸爸開車送我，五分鐘就到了。","py":"Xià yǔ de shí hòu, wǒ bà ba kāi chē sòng wǒ, wǔ fēn zhōng jiù dào le."}],"q":{"zh":"下雨的時候，男的怎麼去學校？","py":"Xià yǔ de shí hòu, nán de zěn me qù xué xiào?"},"opts":[{"zh":"爸爸開車送他","py":"Bà ba kāi chē sòng tā"},{"zh":"走路去","py":"Zǒu lù qù"},{"zh":"坐公車去","py":"Zuò gōng chē qù"},{"zh":"騎腳踏車去","py":"Qí jiǎo tà chē qù"}],"a":0,"tr":{"id":"F: Rumahmu jauh dari sekolah? M: Tidak terlalu jauh, jalan kaki lima belas menit. F: Kalau hujan? M: Kalau hujan, ayah saya mengantar naik mobil, lima menit sampai. Q: Kalau hujan, laki-laki itu ke sekolah bagaimana?","en":"F: Is your home far from school? M: Not very. Fifteen minutes on foot. F: What about when it rains? M: When it rains, my dad drives me; it takes five minutes. Q: How does the man go to school when it rains?","tl":"F: Malayo ba ang bahay mo sa paaralan? M: Hindi masyado, labinlimang minutong lakad. F: E kapag umuulan? M: Kapag umuulan, hinahatid ako ni Tatay sakay ng kotse, limang minuto lang. Q: Paano pumapasok ang lalaki kapag umuulan?","vi":"F: Nhà bạn có xa trường không? M: Không xa lắm, đi bộ mười lăm phút. F: Còn khi trời mưa? M: Khi mưa, bố mình lái xe đưa mình, năm phút là đến. Q: Khi trời mưa, người nam đến trường bằng cách nào?"},"exp":{"id":"Hujan: 爸爸開車送我.","en":"When it rains, his dad drives him.","tl":"Kapag umuulan, hinahatid siya ng tatay.","vi":"Khi mưa, bố lái xe đưa anh ấy."}},{"dlg":[{"sp":"M","zh":"服務生，我們點的牛肉飯還沒來。","py":"Fú wù shēng, wǒ men diǎn de niú ròu fàn hái méi lái."},{"sp":"F","zh":"對不起，牛肉飯賣完了，換雞肉飯好嗎？","py":"Duì bù qǐ, niú ròu fàn mài wán le, huàn jī ròu fàn hǎo ma?"},{"sp":"M","zh":"好吧，再給我們一碗湯。","py":"Hǎo ba, zài gěi wǒ men yì wǎn tāng."},{"sp":"F","zh":"好的，馬上來。","py":"Hǎo de, mǎ shàng lái."}],"q":{"zh":"男的最後點了什麼？","py":"Nán de zuì hòu diǎn le shén me?"},"opts":[{"zh":"牛肉飯和湯","py":"Niú ròu fàn hé tāng"},{"zh":"牛肉麵和湯","py":"Niú ròu miàn hé tāng"},{"zh":"只有雞肉飯","py":"Zhǐ yǒu jī ròu fàn"},{"zh":"雞肉飯和湯","py":"Jī ròu fàn hé tāng"}],"a":3,"tr":{"id":"M: Pelayan, nasi daging sapi yang kami pesan belum datang. F: Maaf, nasi daging sapi sudah habis, ganti nasi ayam boleh? M: Baiklah, tambah semangkuk sup. F: Baik, segera datang. Q: Akhirnya laki-laki itu memesan apa?","en":"M: Waiter, the beef rice we ordered hasn't come. F: Sorry, the beef rice is sold out. Would chicken rice be OK? M: Fine, and give us a bowl of soup too. F: Sure, right away. Q: What did the man finally order?","tl":"M: Waiter, hindi pa dumarating ang beef rice na inorder namin. F: Pasensya, ubos na ang beef rice, chicken rice na lang po? M: Sige, dagdagan mo ng isang mangkok ng sabaw. F: Opo, sandali lang. Q: Ano ang huling inorder ng lalaki?","vi":"M: Phục vụ ơi, cơm bò chúng tôi gọi vẫn chưa có. F: Xin lỗi, cơm bò hết rồi, đổi sang cơm gà được không ạ? M: Thôi được, cho thêm một bát canh. F: Vâng, có ngay. Q: Cuối cùng người nam gọi gì?"},"exp":{"id":"Daging sapi habis → nasi ayam + sup.","en":"Beef was sold out, so chicken rice plus soup.","tl":"Ubos ang beef, kaya chicken rice at sabaw.","vi":"Hết bò nên đổi cơm gà, thêm canh."}}]}],"R":[{"p":1,"items":[{"zh":"我每天早上七點半去學校。","py":"Wǒ měi tiān zǎo shang qī diǎn bàn qù xué xiào.","opts":[{"i":["student","school"],"b":"07:30"},{"i":["student","school"],"b":"08:30"},{"i":["student","bed"],"b":"07:30","bg":"home"}],"a":0,"tr":{"id":"Setiap pagi saya pergi ke sekolah jam setengah delapan.","en":"I go to school at 7:30 every morning.","tl":"Pumupunta ako sa paaralan tuwing umaga nang alas-siyete y medya.","vi":"Mỗi sáng tôi đi học lúc bảy giờ rưỡi."},"exp":{"id":"七點半 = 07:30, dan ia pergi ke sekolah, bukan tidur.","en":"七點半 is 7:30 and the person goes to school, not to bed.","tl":"Ang 七點半 ay 7:30 at papunta siya sa paaralan.","vi":"七點半 là 7:30 và người đó đi đến trường."}},{"zh":"今天下雨，媽媽帶了一把雨傘。","py":"Jīn tiān xià yǔ, mā ma dài le yì bǎ yǔ sǎn.","opts":[{"i":["woman","sun"],"bg":"street"},{"i":["woman","umbrella","rain"],"bg":"rain"},{"i":["woman","hat"],"bg":"rain"}],"a":1,"tr":{"id":"Hari ini hujan, ibu membawa sebuah payung.","en":"It is raining today; Mom took an umbrella.","tl":"Umuulan ngayon; nagdala si Nanay ng payong.","vi":"Hôm nay trời mưa, mẹ mang theo một cái ô."},"exp":{"id":"Hujan (下雨) dan ibu membawa payung (雨傘).","en":"It is raining (下雨) and Mom has an umbrella (雨傘).","tl":"Umuulan (下雨) at may payong (雨傘) si Nanay.","vi":"Trời mưa (下雨) và mẹ cầm ô (雨傘)."}},{"zh":"哥哥在餐廳吃牛肉麵。","py":"Gē ge zài cān tīng chī niú ròu miàn.","opts":[{"i":["man","rice","restaurant"]},{"i":["man","noodles","house"],"bg":"home"},{"i":["man","noodles","restaurant"]}],"a":2,"tr":{"id":"Kakak laki-laki makan mi daging sapi di restoran.","en":"My older brother is eating beef noodles at a restaurant.","tl":"Kumakain ng beef noodles ang kuya ko sa restawran.","vi":"Anh trai đang ăn mì bò ở nhà hàng."},"exp":{"id":"Mi (麵) di restoran (餐廳), bukan nasi dan bukan di rumah.","en":"Noodles (麵) at a restaurant (餐廳), not rice and not at home.","tl":"Noodles (麵) sa restawran (餐廳), hindi kanin at hindi sa bahay.","vi":"Mì (麵) ở nhà hàng (餐廳), không phải cơm hay ở nhà."}},{"zh":"我們班有二十五個學生。","py":"Wǒ men bān yǒu èr shí wǔ ge xué shēng.","opts":[{"i":["student","school"],"b":"52"},{"i":["student","school"],"b":"25"},{"i":["teacher","school"],"b":"25"}],"a":1,"tr":{"id":"Kelas kami punya dua puluh lima murid.","en":"Our class has twenty-five students.","tl":"May dalawampu't limang estudyante ang klase namin.","vi":"Lớp chúng tôi có hai mươi lăm học sinh."},"exp":{"id":"二十五 = 25 dan yang dihitung adalah murid (學生).","en":"二十五 is 25, and they are students (學生), not teachers.","tl":"Ang 二十五 ay 25, at mga estudyante (學生) sila.","vi":"二十五 là 25, và đó là học sinh (學生)."}},{"zh":"爸爸今天不太舒服，他發燒了。","py":"Bà ba jīn tiān bú tài shū fu, tā fā shāo le.","opts":[{"i":["man","fever"],"bg":"home"},{"i":["man","run"],"bg":"park"},{"i":["man","tv"],"bg":"home"}],"a":0,"tr":{"id":"Ayah hari ini kurang enak badan, dia demam.","en":"Dad doesn't feel well today; he has a fever.","tl":"Masama ang pakiramdam ni Tatay ngayon; nilalagnat siya.","vi":"Hôm nay bố không khỏe lắm, bố bị sốt."},"exp":{"id":"發燒 = demam; hanya gambar A menunjukkan ayah yang demam.","en":"發燒 means fever; only picture A shows Dad with a fever.","tl":"Ang 發燒 ay lagnat; larawan A lang ang may lagnat.","vi":"發燒 là sốt; chỉ hình A cho thấy bố bị sốt."}},{"zh":"外面很冷，你要穿外套。","py":"Wài miàn hěn lěng, nǐ yào chuān wài tào.","opts":[{"i":["boy","shirt","hot"]},{"i":["boy","swim","hot"],"bg":"sea"},{"i":["boy","jacket","cold"]}],"a":2,"tr":{"id":"Di luar sangat dingin, kamu harus memakai jaket.","en":"It's very cold outside; you should wear a jacket.","tl":"Napakalamig sa labas; magsuot ka ng dyaket.","vi":"Bên ngoài rất lạnh, bạn phải mặc áo khoác."},"exp":{"id":"Dingin (冷) dan memakai jaket (外套).","en":"Cold (冷) and wearing a jacket (外套).","tl":"Malamig (冷) at naka-dyaket (外套).","vi":"Lạnh (冷) và mặc áo khoác (外套)."}},{"zh":"姐姐的生日是五月十號。","py":"Jiě jie de shēng rì shì wǔ yuè shí hào.","opts":[{"i":["calendar","birthday"],"b":"MAY 10"},{"i":["calendar","birthday"],"b":"APR 10"},{"i":["calendar","birthday"],"b":"MAY 12"}],"a":0,"tr":{"id":"Ulang tahun kakak perempuan tanggal sepuluh Mei.","en":"My older sister's birthday is May 10th.","tl":"Ang kaarawan ng ate ko ay ika-10 ng Mayo.","vi":"Sinh nhật chị gái là ngày mười tháng năm."},"exp":{"id":"五月十號 = 10 Mei (MAY 10).","en":"五月十號 is May 10 (MAY 10).","tl":"Ang 五月十號 ay Mayo 10 (MAY 10).","vi":"五月十號 là ngày 10 tháng 5 (MAY 10)."}},{"zh":"弟弟在圖書館看書。","py":"Dì di zài tú shū guǎn kàn shū.","opts":[{"i":["boy","read","house"],"bg":"home"},{"i":["boy","play_ball"],"bg":"park"},{"i":["boy","read","library"]}],"a":2,"tr":{"id":"Adik laki-laki membaca buku di perpustakaan.","en":"My younger brother is reading in the library.","tl":"Nagbabasa ng libro ang nakababatang kapatid kong lalaki sa aklatan.","vi":"Em trai đang đọc sách ở thư viện."},"exp":{"id":"Membaca (看書) di perpustakaan (圖書館), bukan di rumah.","en":"Reading (看書) in the library (圖書館), not at home.","tl":"Nagbabasa (看書) sa aklatan (圖書館), hindi sa bahay.","vi":"Đọc sách (看書) ở thư viện (圖書館), không phải ở nhà."}},{"zh":"這杯咖啡六十塊錢。","py":"Zhè bēi kā fēi liù shí kuài qián.","opts":[{"i":["tea"],"b":"NT$60"},{"i":["coffee"],"b":"NT$60"},{"i":["coffee"],"b":"NT$16"}],"a":1,"tr":{"id":"Kopi segelas ini enam puluh dolar.","en":"This cup of coffee costs sixty dollars.","tl":"Animnapung dolyar ang tasang ito ng kape.","vi":"Ly cà phê này sáu mươi đồng."},"exp":{"id":"Kopi (咖啡) seharga 60 (六十), bukan teh dan bukan 16.","en":"Coffee (咖啡) for 60 (六十), not tea and not 16.","tl":"Kape (咖啡) na 60 (六十), hindi tsaa at hindi 16.","vi":"Cà phê (咖啡) giá 60 (六十), không phải trà hay 16."}},{"zh":"我們一家人星期天常常去山上走走。","py":"Wǒ men yì jiā rén xīng qí tiān cháng cháng qù shān shàng zǒu zou.","opts":[{"i":["family","beach"],"bg":"sea"},{"i":["family","mountain","walk"]},{"i":["family","cinema"],"bg":"night"}],"a":1,"tr":{"id":"Keluarga kami sering jalan-jalan ke gunung pada hari Minggu.","en":"Our family often goes for walks in the mountains on Sundays.","tl":"Madalas maglakad-lakad sa bundok ang pamilya namin tuwing Linggo.","vi":"Gia đình chúng tôi chủ nhật thường lên núi đi dạo."},"exp":{"id":"山上走走 = jalan-jalan di gunung, bukan pantai atau bioskop.","en":"山上走走 means walking in the mountains, not the beach or cinema.","tl":"Ang 山上走走 ay paglalakad sa bundok.","vi":"山上走走 là đi dạo trên núi, không phải biển hay rạp phim."}}]},{"p":2,"items":[{"pic":{"i":["girl","bubble_tea"],"bg":"shop"},"zh":"妹妹在喝＿＿＿。","py":"Mèi mei zài hē zhēn zhū nǎi chá.","opts":["珍珠奶茶","咖啡","果汁","牛奶"],"a":0,"tr":{"id":"Adik perempuan sedang minum bubble tea.","en":"My younger sister is drinking bubble tea.","tl":"Umiinom ng bubble tea ang nakababatang kapatid kong babae.","vi":"Em gái đang uống trà sữa trân châu."},"exp":{"id":"Gambar menunjukkan bubble tea = 珍珠奶茶.","en":"The picture shows bubble tea, 珍珠奶茶.","tl":"Bubble tea ang nasa larawan, 珍珠奶茶.","vi":"Hình là trà sữa trân châu, 珍珠奶茶."}},{"pic":{"i":["clock"],"b":"09:30"},"zh":"現在九點＿＿＿。","py":"Xiàn zài jiǔ diǎn bàn.","opts":["一刻","十五分","半","三十五分"],"a":2,"tr":{"id":"Sekarang jam setengah sepuluh.","en":"It is now half past nine.","tl":"Alas-nuwebe y medya na ngayon.","vi":"Bây giờ là chín giờ rưỡi."},"exp":{"id":"09:30 = 九點半 (半 = tiga puluh menit).","en":"09:30 is 九點半; 半 means thirty minutes.","tl":"Ang 09:30 ay 九點半; ang 半 ay tatlumpung minuto.","vi":"09:30 là 九點半; 半 là ba mươi phút."}},{"pic":{"i":["rain","umbrella"],"bg":"rain"},"zh":"今天＿＿＿，出門要帶傘。","py":"Jīn tiān xià yǔ, chū mén yào dài sǎn.","opts":["出太陽","下雨","下雪","颳風"],"a":1,"tr":{"id":"Hari ini hujan, keluar rumah harus membawa payung.","en":"It's raining today; take an umbrella when you go out.","tl":"Umuulan ngayon; magdala ng payong paglabas.","vi":"Hôm nay trời mưa, ra ngoài phải mang ô."},"exp":{"id":"Gambar menunjukkan hujan dan payung, jadi 下雨.","en":"The picture shows rain and an umbrella, so 下雨.","tl":"Ulan at payong ang nasa larawan, kaya 下雨.","vi":"Hình có mưa và ô, nên là 下雨."}},{"pic":{"i":["teacher","book"],"bg":"school"},"zh":"這是我們的中文＿＿＿。","py":"Zhè shì wǒ men de zhōng wén lǎo shī.","opts":["醫生","學生","老師","司機"],"a":2,"tr":{"id":"Ini guru bahasa Mandarin kami.","en":"This is our Chinese teacher.","tl":"Ito ang guro namin sa Chinese.","vi":"Đây là thầy giáo tiếng Trung của chúng tôi."},"exp":{"id":"Gambar menunjukkan guru di sekolah = 老師.","en":"The picture shows a teacher at school, 老師.","tl":"Guro sa paaralan ang nasa larawan, 老師.","vi":"Hình là giáo viên ở trường, 老師."}},{"pic":{"i":["family","house"],"b":"4","bg":"home"},"zh":"我家有＿＿＿人。","py":"Wǒ jiā yǒu sì ge rén.","opts":["三個","四個","五個","六個"],"a":1,"tr":{"id":"Keluarga saya ada empat orang.","en":"There are four people in my family.","tl":"Apat na tao ang pamilya ko.","vi":"Nhà tôi có bốn người."},"exp":{"id":"Angka di gambar adalah 4 = 四個.","en":"The number in the picture is 4, 四個.","tl":"Ang numero sa larawan ay 4, 四個.","vi":"Số trong hình là 4, 四個."}},{"pic":{"i":["man","cook"],"bg":"home"},"zh":"爸爸在廚房＿＿＿。","py":"Bà ba zài chú fáng zuò fàn.","opts":["做飯","睡覺","看電視","洗澡"],"a":0,"tr":{"id":"Ayah sedang memasak di dapur.","en":"Dad is cooking in the kitchen.","tl":"Nagluluto si Tatay sa kusina.","vi":"Bố đang nấu cơm trong bếp."},"exp":{"id":"Gambar menunjukkan ayah memasak = 做飯.","en":"The picture shows Dad cooking, 做飯.","tl":"Nagluluto si Tatay sa larawan, 做飯.","vi":"Hình là bố đang nấu ăn, 做飯."}},{"pic":{"i":["sun","hot"],"b":"35°C"},"zh":"今天三十五度，天氣很＿＿＿。","py":"Jīn tiān sān shí wǔ dù, tiān qì hěn rè.","opts":["冷","熱","涼快","暖和"],"a":1,"tr":{"id":"Hari ini 35 derajat, cuacanya sangat panas.","en":"It's 35 degrees today; the weather is very hot.","tl":"35 digri ngayon; napakainit ng panahon.","vi":"Hôm nay ba mươi lăm độ, trời rất nóng."},"exp":{"id":"35°C dan matahari terik = 熱 (panas).","en":"35°C with strong sun is 熱, hot.","tl":"Ang 35°C na may araw ay 熱, mainit.","vi":"35°C và nắng to là 熱, nóng."}},{"pic":{"i":["student","write","notebook"],"bg":"school"},"zh":"學生在教室裡＿＿＿功課。","py":"Xué shēng zài jiào shì lǐ xiě gōng kè.","opts":["吃","唱","買","寫"],"a":3,"tr":{"id":"Murid sedang mengerjakan PR di kelas.","en":"The student is doing homework in the classroom.","tl":"Gumagawa ng takdang-aralin ang estudyante sa silid-aralan.","vi":"Học sinh đang làm bài tập trong lớp."},"exp":{"id":"Gambar menunjukkan menulis; 寫功課 = mengerjakan PR.","en":"The picture shows writing; 寫功課 means do homework.","tl":"Pagsusulat ang nasa larawan; 寫功課 ay gumawa ng takdang-aralin.","vi":"Hình là đang viết; 寫功課 là làm bài tập."}},{"pic":{"i":["dumplings"],"b":"x10","bg":"shop"},"zh":"我點了十個＿＿＿。","py":"Wǒ diǎn le shí ge shuǐ jiǎo.","opts":["麵包","水餃","蛋糕","西瓜"],"a":1,"tr":{"id":"Saya memesan sepuluh pangsit rebus.","en":"I ordered ten dumplings.","tl":"Umorder ako ng sampung dumpling.","vi":"Tôi đã gọi mười cái sủi cảo."},"exp":{"id":"Gambar menunjukkan pangsit = 水餃.","en":"The picture shows dumplings, 水餃.","tl":"Dumpling ang nasa larawan, 水餃.","vi":"Hình là sủi cảo, 水餃."}},{"pic":{"i":["calendar"],"b":"SAT"},"zh":"今天是星期＿＿＿。","py":"Jīn tiān shì xīng qí liù.","opts":["一","三","五","六"],"a":3,"tr":{"id":"Hari ini hari Sabtu.","en":"Today is Saturday.","tl":"Sabado ngayon.","vi":"Hôm nay là thứ bảy."},"exp":{"id":"SAT = Sabtu = 星期六.","en":"SAT is Saturday, 星期六.","tl":"Ang SAT ay Sabado, 星期六.","vi":"SAT là thứ bảy, 星期六."}}]},{"p":3,"items":[{"zh":"我家有三＿＿＿狗。","py":"Wǒ jiā yǒu sān zhī gǒu.","opts":["隻","個","本","張"],"a":0,"tr":{"id":"Di rumah saya ada tiga ekor anjing.","en":"There are three dogs at my house.","tl":"May tatlong aso sa bahay namin.","vi":"Nhà tôi có ba con chó."},"exp":{"id":"Kata penggolong untuk hewan seperti anjing adalah 隻.","en":"The measure word for animals like dogs is 隻.","tl":"Ang measure word para sa hayop gaya ng aso ay 隻.","vi":"Lượng từ cho động vật như chó là 隻."}},{"zh":"你要喝咖啡＿＿＿喝茶？","py":"Nǐ yào hē kā fēi hái shì hē chá?","opts":["或是","還是","和","跟"],"a":1,"tr":{"id":"Kamu mau minum kopi atau teh?","en":"Do you want coffee or tea?","tl":"Gusto mo ba ng kape o tsaa?","vi":"Bạn muốn uống cà phê hay uống trà?"},"exp":{"id":"Dalam kalimat tanya pilihan dipakai 還是, bukan 或是.","en":"In choice questions use 還是, not 或是.","tl":"Sa tanong na may pagpipilian, 還是 ang gamit, hindi 或是.","vi":"Câu hỏi lựa chọn dùng 還是, không dùng 或是."}},{"zh":"哥哥＿＿＿我高。","py":"Gē ge bǐ wǒ gāo.","opts":["很","跟","比","對"],"a":2,"tr":{"id":"Kakak laki-laki lebih tinggi daripada saya.","en":"My older brother is taller than me.","tl":"Mas matangkad ang kuya ko kaysa sa akin.","vi":"Anh trai cao hơn tôi."},"exp":{"id":"Pola perbandingan: A 比 B + sifat.","en":"Comparison pattern: A 比 B + adjective.","tl":"Pattern ng paghahambing: A 比 B + pang-uri.","vi":"Cấu trúc so sánh: A 比 B + tính từ."}},{"zh":"A：你吃過臭豆腐嗎？\nB：我沒吃＿＿＿。","py":"Nǐ chī guò chòu dòu fu ma? Wǒ méi chī guò.","opts":["了","著","在","過"],"a":3,"tr":{"id":"A: Kamu pernah makan tahu busuk? B: Saya belum pernah makan.","en":"A: Have you ever eaten stinky tofu? B: I've never eaten it.","tl":"A: Nakakain ka na ba ng stinky tofu? B: Hindi pa ako nakakakain.","vi":"A: Bạn ăn đậu phụ thối bao giờ chưa? B: Tôi chưa ăn bao giờ."},"exp":{"id":"Pengalaman: 吃過 / 沒吃過.","en":"Experience is expressed with 過: 吃過 / 沒吃過.","tl":"Karanasan ay 過: 吃過 / 沒吃過.","vi":"Kinh nghiệm dùng 過: 吃過 / 沒吃過."}},{"zh":"我昨天晚上十二點＿＿＿睡覺，所以今天很累。","py":"Wǒ zuó tiān wǎn shang shí èr diǎn cái shuì jiào, suǒ yǐ jīn tiān hěn lèi.","opts":["就","才","再","還"],"a":1,"tr":{"id":"Tadi malam saya baru tidur jam dua belas, jadi hari ini sangat capek.","en":"I didn't go to bed until twelve last night, so I'm very tired today.","tl":"Alas-dose na ako natulog kagabi, kaya pagod na pagod ako ngayon.","vi":"Tối qua mười hai giờ tôi mới đi ngủ, nên hôm nay rất mệt."},"exp":{"id":"才 = baru (terlambat); cocok dengan 'sangat capek'.","en":"才 means 'not until' (late), matching 'very tired'.","tl":"Ang 才 ay 'saka lang' (huli), tugma sa 'pagod'.","vi":"才 nghĩa là 'mới' (muộn), hợp với 'rất mệt'."}},{"zh":"媽媽做菜做＿＿＿很好吃。","py":"Mā ma zuò cài zuò de hěn hǎo chī.","opts":["的","地","得","了"],"a":2,"tr":{"id":"Masakan ibu sangat enak.","en":"Mom cooks very deliciously.","tl":"Napakasarap magluto ni Nanay.","vi":"Mẹ nấu ăn rất ngon."},"exp":{"id":"Kata kerja + 得 + keterangan hasil: 做得很好吃.","en":"Verb + 得 + complement: 做得很好吃.","tl":"Pandiwa + 得 + komplemento: 做得很好吃.","vi":"Động từ + 得 + bổ ngữ: 做得很好吃."}},{"zh":"請你＿＿＿窗戶打開，好嗎？","py":"Qǐng nǐ bǎ chuāng hù dǎ kāi, hǎo ma?","opts":["被","讓","給","把"],"a":3,"tr":{"id":"Tolong buka jendelanya, ya?","en":"Could you please open the window?","tl":"Pakibuksan mo naman ang bintana?","vi":"Bạn mở cửa sổ ra giúp tôi được không?"},"exp":{"id":"Pola 把 + objek + kata kerja: 把窗戶打開.","en":"把 + object + verb pattern: 把窗戶打開.","tl":"Pattern na 把 + layon + pandiwa: 把窗戶打開.","vi":"Cấu trúc 把 + tân ngữ + động từ: 把窗戶打開."}},{"zh":"我每天＿＿＿捷運去上學。","py":"Wǒ měi tiān zuò jié yùn qù shàng xué.","opts":["坐","開","騎","走"],"a":0,"tr":{"id":"Setiap hari saya naik MRT ke sekolah.","en":"I take the MRT to school every day.","tl":"Sumasakay ako ng MRT papuntang paaralan araw-araw.","vi":"Mỗi ngày tôi đi tàu điện ngầm đến trường."},"exp":{"id":"Naik kendaraan umum seperti MRT memakai 坐.","en":"Riding public transport like the MRT uses 坐.","tl":"坐 ang gamit sa pagsakay sa MRT.","vi":"Đi phương tiện công cộng như MRT dùng 坐."}},{"zh":"我昨天＿＿＿上課，因為我生病了。","py":"Wǒ zuó tiān méi shàng kè, yīn wèi wǒ shēng bìng le.","opts":["沒","不","別","還"],"a":0,"tr":{"id":"Kemarin saya tidak masuk kelas karena saya sakit.","en":"I didn't go to class yesterday because I was sick.","tl":"Hindi ako pumasok sa klase kahapon dahil may sakit ako.","vi":"Hôm qua tôi không đi học vì tôi bị ốm."},"exp":{"id":"Untuk kejadian lampau (昨天) negasinya 沒.","en":"Past events (昨天) are negated with 沒.","tl":"Sa nakaraan (昨天), 沒 ang pangnegatibo.","vi":"Sự việc quá khứ (昨天) phủ định bằng 沒."}},{"zh":"現在是冬天，天氣越來越＿＿＿了。","py":"Xiàn zài shì dōng tiān, tiān qì yuè lái yuè lěng le.","opts":["熱","高","慢","冷"],"a":3,"tr":{"id":"Sekarang musim dingin, cuacanya makin lama makin dingin.","en":"It's winter now; the weather is getting colder and colder.","tl":"Taglamig na ngayon; lalong lumalamig ang panahon.","vi":"Bây giờ là mùa đông, thời tiết càng ngày càng lạnh."},"exp":{"id":"Musim dingin (冬天) → cuaca makin dingin (冷).","en":"Winter (冬天) means it gets colder (冷).","tl":"Taglamig (冬天), kaya lumalamig (冷).","vi":"Mùa đông (冬天) nên trời lạnh dần (冷)."}}]},{"p":4,"items":[{"zh":"我叫小美，是大學一年級的學生。我每天早上八點（1）課，下午四點下課。下課以後，我常常（2）同學去學校附近的小吃店吃東西。那家店的牛肉麵又便宜（3）好吃。晚上我回家跟爸爸媽媽一起吃飯。媽媽做的菜比外面的好吃（4）了。吃完飯，我（5）在房間寫功課，有時候也會看一點電視。","py":"Wǒ jiào Xiǎo Měi, shì dà xué yī nián jí de xué shēng. Wǒ měi tiān zǎo shang bā diǎn shàng kè, xià wǔ sì diǎn xià kè. Xià kè yǐ hòu, wǒ cháng cháng gēn tóng xué qù xué xiào fù jìn de xiǎo chī diàn chī dōng xi. Nà jiā diàn de niú ròu miàn yòu pián yi yòu hǎo chī. Wǎn shang wǒ huí jiā gēn bà ba mā ma yì qǐ chī fàn. Mā ma zuò de cài bǐ wài miàn de hǎo chī duō le. Chī wán fàn, wǒ jiù zài fáng jiān xiě gōng kè, yǒu shí hou yě huì kàn yì diǎn diàn shì.","bank":["跟","從","多","上","就","又"],"ans":[3,0,5,2,4],"tr":{"id":"Nama saya Xiaomei, mahasiswi tahun pertama. Setiap hari saya mulai kuliah jam delapan pagi dan selesai jam empat sore. Sesudah kuliah, saya sering pergi dengan teman sekelas makan di warung dekat kampus. Mi daging sapi di sana murah dan enak. Malamnya saya pulang dan makan bersama ayah dan ibu. Masakan ibu jauh lebih enak daripada di luar. Selesai makan, saya mengerjakan PR di kamar, kadang juga menonton sedikit TV.","en":"My name is Xiaomei, a first-year university student. Every day class starts at eight in the morning and ends at four in the afternoon. After class I often go with classmates to a snack shop near school. Their beef noodles are cheap and tasty. In the evening I go home and eat with my parents. Mom's cooking is much better than eating out. After dinner I do homework in my room, and sometimes watch a little TV.","tl":"Ako si Xiaomei, estudyante sa unang taon ng unibersidad. Araw-araw, alas-otso ng umaga ang simula ng klase ko at alas-kuwatro ng hapon ang tapos. Pagkatapos ng klase, madalas akong pumunta kasama ng mga kaklase sa kainan malapit sa paaralan. Mura at masarap ang beef noodles doon. Sa gabi, umuuwi ako at kumakain kasama sina Tatay at Nanay. Mas masarap ang luto ni Nanay kaysa sa labas. Pagkakain, gumagawa ako ng takdang-aralin sa kuwarto, at minsan nanonood ng kaunting TV.","vi":"Tôi tên là Tiểu Mỹ, sinh viên năm nhất. Mỗi ngày tôi vào học lúc tám giờ sáng, bốn giờ chiều tan học. Tan học xong, tôi thường cùng bạn học đến quán ăn vặt gần trường. Mì bò ở quán đó vừa rẻ vừa ngon. Buổi tối tôi về nhà ăn cơm cùng bố mẹ. Món mẹ nấu ngon hơn bên ngoài nhiều. Ăn xong, tôi liền vào phòng làm bài tập, đôi khi cũng xem một chút tivi."},"exp":{"id":"上課 = mulai kelas; 跟同學 = bersama teman; 又…又…; 好吃多了 = jauh lebih enak; 就 = langsung. 從 tidak dipakai.","en":"上課 start class; 跟同學 with classmates; 又…又…; 好吃多了 much tastier; 就 right then. 從 is unused.","tl":"上課 simula ng klase; 跟同學 kasama ang kaklase; 又…又…; 好吃多了 mas masarap; 就 agad. Hindi ginamit ang 從.","vi":"上課 vào học; 跟同學 cùng bạn; 又…又…; 好吃多了 ngon hơn nhiều; 就 liền. 從 không dùng."}}]},{"p":5,"items":[{"kind":"notice","title":"圖書館通知","zh":"同學們好：\n下星期一到星期五，學校圖書館開放時間是早上8:00到晚上9:00。星期六只開到中午12:00，星期天不開。借書一次最多可以借5本，要在兩個星期以內還。在圖書館裡不可以吃東西，也不可以講電話。","py":"Tóng xué men hǎo:\nXià xīng qí yī dào xīng qí wǔ, xué xiào tú shū guǎn kāi fàng shí jiān shì zǎo shang 8:00 dào wǎn shang 9:00. Xīng qí liù zhǐ kāi dào zhōng wǔ 12:00, xīng qí tiān bù kāi. Jiè shū yí cì zuì duō kě yǐ jiè 5 běn, yào zài liǎng ge xīng qí yǐ nèi huán. Zài tú shū guǎn lǐ bù kě yǐ chī dōng xi, yě bù kě yǐ jiǎng diàn huà.","qs":[{"zh":"星期六圖書館幾點關門？","py":"Xīng qí liù tú shū guǎn jǐ diǎn guān mén?","opts":["晚上九點","中午十二點","早上八點","星期六不開"],"a":1,"exp":{"id":"Hari Sabtu hanya buka sampai jam 12 siang.","en":"On Saturday it is only open until 12 noon.","tl":"Tuwing Sabado, bukas lang hanggang alas-dose ng tanghali.","vi":"Thứ bảy chỉ mở đến 12 giờ trưa."}},{"zh":"一次最多可以借幾本書？","py":"Yí cì zuì duō kě yǐ jiè jǐ běn shū?","opts":["兩本","四本","五本","十本"],"a":2,"exp":{"id":"Sekali pinjam paling banyak 5 buku.","en":"You can borrow at most 5 books at a time.","tl":"Hanggang 5 libro lang bawat hiram.","vi":"Mỗi lần mượn tối đa 5 quyển."}},{"zh":"在圖書館裡不可以做什麼？","py":"Zài tú shū guǎn lǐ bù kě yǐ zuò shén me?","opts":["看書","借書","講電話","寫功課"],"a":2,"exp":{"id":"Di perpustakaan tidak boleh makan dan menelepon (講電話).","en":"No eating and no phone calls (講電話) in the library.","tl":"Bawal kumain at tumawag (講電話) sa aklatan.","vi":"Trong thư viện không được ăn và gọi điện (講電話)."}}],"tr":{"id":"Halo semuanya: Senin sampai Jumat depan, perpustakaan sekolah buka jam 8:00 pagi sampai 9:00 malam. Sabtu hanya buka sampai 12:00 siang, Minggu tutup. Sekali pinjam paling banyak 5 buku, harus dikembalikan dalam dua minggu. Di perpustakaan tidak boleh makan dan tidak boleh menelepon.","en":"Hello students: Next Monday to Friday the school library is open from 8:00 a.m. to 9:00 p.m. On Saturday it is open only until 12:00 noon; it is closed on Sunday. You may borrow at most 5 books at a time and must return them within two weeks. No eating and no phone calls in the library.","tl":"Kumusta, mga estudyante: Mula Lunes hanggang Biyernes sa susunod na linggo, bukas ang aklatan mula 8:00 ng umaga hanggang 9:00 ng gabi. Sa Sabado, hanggang 12:00 ng tanghali lang; sarado sa Linggo. Hanggang 5 libro bawat hiram at dapat ibalik sa loob ng dalawang linggo. Bawal kumain at tumawag sa aklatan.","vi":"Chào các bạn: Từ thứ hai đến thứ sáu tuần sau, thư viện trường mở cửa từ 8:00 sáng đến 9:00 tối. Thứ bảy chỉ mở đến 12:00 trưa, chủ nhật đóng cửa. Mỗi lần mượn tối đa 5 quyển, phải trả trong vòng hai tuần. Trong thư viện không được ăn uống và không được gọi điện thoại."}},{"kind":"menu","title":"小王麵店","zh":"小王麵店\n營業時間：11:00～20:00（星期一休息）\n牛肉麵　120元\n雞肉飯　60元\n水餃（10個）　70元\n燙青菜　40元\n紅茶　25元\n※ 買兩碗牛肉麵，送一杯紅茶。","py":"Xiǎo Wáng miàn diàn\nYíng yè shí jiān: 11:00～20:00 (xīng qí yī xiū xí)\nNiú ròu miàn 120 yuán\nJī ròu fàn 60 yuán\nShuǐ jiǎo (10 ge) 70 yuán\nTàng qīng cài 40 yuán\nHóng chá 25 yuán\n※ Mǎi liǎng wǎn niú ròu miàn, sòng yì bēi hóng chá.","qs":[{"zh":"一碗牛肉麵和一盤燙青菜一共多少錢？","py":"Yì wǎn niú ròu miàn hé yì pán tàng qīng cài yí gòng duō shǎo qián?","opts":["一百二十元","一百六十元","一百八十元","一百四十五元"],"a":1,"exp":{"id":"120 + 40 = 160 元.","en":"120 + 40 = 160 dollars.","tl":"120 + 40 = 160 dolyar.","vi":"120 + 40 = 160 đồng."}},{"zh":"哪一天不能來這家店吃飯？","py":"Nǎ yì tiān bù néng lái zhè jiā diàn chī fàn?","opts":["星期一","星期三","星期六","星期天"],"a":0,"exp":{"id":"Menu menulis 星期一休息 (Senin tutup).","en":"The menu says 星期一休息, closed on Monday.","tl":"Nakasulat na 星期一休息, sarado tuwing Lunes.","vi":"Thực đơn ghi 星期一休息, thứ hai nghỉ."}},{"zh":"買兩碗牛肉麵會怎麼樣？","py":"Mǎi liǎng wǎn niú ròu miàn huì zěn me yàng?","opts":["送一盤青菜","便宜二十元","送十個水餃","送一杯紅茶"],"a":3,"exp":{"id":"Beli dua mangkuk mi sapi, gratis segelas teh hitam.","en":"Buy two bowls of beef noodles and get a free black tea.","tl":"Bumili ng dalawang beef noodles, libre ang isang black tea.","vi":"Mua hai bát mì bò được tặng một ly hồng trà."}}],"tr":{"id":"Warung Mi Xiao Wang. Jam buka 11:00–20:00 (Senin tutup). Mi daging sapi 120; Nasi ayam 60; Pangsit (10 buah) 70; Sayur rebus 40; Teh hitam 25. Beli dua mangkuk mi sapi, gratis segelas teh hitam.","en":"Xiao Wang Noodle Shop. Hours 11:00–20:00 (closed Mondays). Beef noodles 120; Chicken rice 60; Dumplings (10) 70; Blanched greens 40; Black tea 25. Buy two bowls of beef noodles, get a free black tea.","tl":"Xiao Wang Noodle Shop. Oras 11:00–20:00 (sarado tuwing Lunes). Beef noodles 120; Chicken rice 60; Dumpling (10 piraso) 70; Nilagang gulay 40; Black tea 25. Bumili ng dalawang beef noodles, libreng black tea.","vi":"Quán mì Tiểu Vương. Giờ mở cửa 11:00–20:00 (nghỉ thứ hai). Mì bò 120; Cơm gà 60; Sủi cảo (10 cái) 70; Rau luộc 40; Hồng trà 25. Mua hai bát mì bò tặng một ly hồng trà."}},{"kind":"message","title":"大明和小華的訊息","zh":"大明：小華，明天我們幾點在捷運站見面？\n小華：早上9:30好不好？\n大明：好。氣象說明天下午會下大雨，我們上午去動物園，下午去看電影吧。\n小華：好主意！我會帶雨傘。我姐姐也想去，可以嗎？\n大明：當然可以！","py":"Dà Míng: Xiǎo Huá, míng tiān wǒ men jǐ diǎn zài jié yùn zhàn jiàn miàn?\nXiǎo Huá: Zǎo shang 9:30 hǎo bù hǎo?\nDà Míng: Hǎo. Qì xiàng shuō míng tiān xià wǔ huì xià dà yǔ, wǒ men shàng wǔ qù dòng wù yuán, xià wǔ qù kàn diàn yǐng ba.\nXiǎo Huá: Hǎo zhǔ yì! Wǒ huì dài yǔ sǎn. Wǒ jiě jie yě xiǎng qù, kě yǐ ma?\nDà Míng: Dāng rán kě yǐ!","qs":[{"zh":"他們明天在哪裡見面？","py":"Tā men míng tiān zài nǎ lǐ jiàn miàn?","opts":["動物園","電影院","捷運站","小華家"],"a":2,"exp":{"id":"Mereka bertemu di stasiun MRT (捷運站).","en":"They meet at the MRT station (捷運站).","tl":"Magkikita sila sa MRT station (捷運站).","vi":"Họ gặp nhau ở ga tàu điện ngầm (捷運站)."}},{"zh":"明天下午他們要做什麼？","py":"Míng tiān xià wǔ tā men yào zuò shén me?","opts":["去動物園","看電影","回家","去買雨傘"],"a":1,"exp":{"id":"Sore hari akan hujan, jadi mereka menonton film.","en":"It will rain in the afternoon, so they will see a movie.","tl":"Uulan sa hapon, kaya manonood sila ng sine.","vi":"Chiều mưa nên họ đi xem phim."}},{"zh":"明天一共有幾個人要去？","py":"Míng tiān yí gòng yǒu jǐ ge rén yào qù?","opts":["一個","兩個","三個","四個"],"a":2,"exp":{"id":"Daming, Xiaohua, dan kakak Xiaohua = tiga orang.","en":"Daming, Xiaohua and Xiaohua's sister: three people.","tl":"Sina Daming, Xiaohua at ate ni Xiaohua: tatlo.","vi":"Đại Minh, Tiểu Hoa và chị của Tiểu Hoa: ba người."}}],"tr":{"id":"Daming: Xiaohua, besok kita bertemu jam berapa di stasiun MRT? Xiaohua: Jam 9:30 pagi bagaimana? Daming: Oke. Ramalan cuaca bilang besok sore akan hujan deras; pagi kita ke kebun binatang, sore kita nonton film saja. Xiaohua: Ide bagus! Aku akan bawa payung. Kakakku juga mau ikut, boleh? Daming: Tentu boleh!","en":"Daming: Xiaohua, what time shall we meet at the MRT station tomorrow? Xiaohua: How about 9:30 a.m.? Daming: OK. The forecast says heavy rain tomorrow afternoon, so let's go to the zoo in the morning and see a movie in the afternoon. Xiaohua: Good idea! I'll bring an umbrella. My older sister wants to come too, is that OK? Daming: Of course!","tl":"Daming: Xiaohua, anong oras tayo magkikita sa MRT station bukas? Xiaohua: 9:30 ng umaga, ayos ba? Daming: Sige. Sabi ng weather forecast, uulan nang malakas bukas ng hapon, kaya sa umaga tayo sa zoo, at sa hapon manood ng sine. Xiaohua: Magandang ideya! Magdadala ako ng payong. Gusto ring sumama ng ate ko, puwede ba? Daming: Siyempre!","vi":"Đại Minh: Tiểu Hoa, mai mấy giờ mình gặp nhau ở ga tàu điện ngầm? Tiểu Hoa: 9:30 sáng được không? Đại Minh: Được. Dự báo nói chiều mai mưa to, buổi sáng mình đi sở thú, buổi chiều đi xem phim nhé. Tiểu Hoa: Ý hay! Mình sẽ mang ô. Chị mình cũng muốn đi, được không? Đại Minh: Tất nhiên được!"}},{"kind":"schedule","title":"林老師的中文班","zh":"中文班上課時間\n星期一　9:00～11:00　聽力\n星期二　9:00～11:00　會話\n星期三　14:00～16:00　寫字\n星期四　9:00～11:00　會話\n星期五　14:00～16:00　閱讀\n※ 十月十日放假，不上課。","py":"Zhōng wén bān shàng kè shí jiān\nXīng qí yī 9:00～11:00 tīng lì\nXīng qí èr 9:00～11:00 huì huà\nXīng qí sān 14:00～16:00 xiě zì\nXīng qí sì 9:00～11:00 huì huà\nXīng qí wǔ 14:00～16:00 yuè dú\n※ Shí yuè shí rì fàng jià, bú shàng kè.","qs":[{"zh":"會話課一個星期上幾次？","py":"Huì huà kè yí ge xīng qí shàng jǐ cì?","opts":["一次","兩次","三次","四次"],"a":1,"exp":{"id":"Kelas percakapan ada hari Selasa dan Kamis: dua kali.","en":"Conversation class is on Tuesday and Thursday: twice.","tl":"Martes at Huwebes ang conversation class: dalawang beses.","vi":"Lớp hội thoại vào thứ ba và thứ năm: hai lần."}},{"zh":"星期三的課是幾點開始？","py":"Xīng qí sān de kè shì jǐ diǎn kāi shǐ?","opts":["早上九點","早上十一點","下午兩點","下午四點"],"a":2,"exp":{"id":"Rabu 14:00 = jam dua siang.","en":"Wednesday starts at 14:00, 2 p.m.","tl":"Miyerkoles, 14:00, alas-dos ng hapon.","vi":"Thứ tư bắt đầu 14:00, hai giờ chiều."}},{"zh":"下面哪一個是對的？","py":"Xià miàn nǎ yí ge shì duì de?","opts":["星期五上寫字課","星期一上午有聽力課","每天都是上午上課","十月十日要上課"],"a":1,"exp":{"id":"Senin 9:00–11:00 kelas mendengar, yaitu pagi hari.","en":"Monday 9:00–11:00 is listening class, in the morning.","tl":"Lunes 9:00–11:00 ay listening class, sa umaga.","vi":"Thứ hai 9:00–11:00 là lớp nghe, buổi sáng."}}],"tr":{"id":"Jadwal kelas Mandarin. Senin 9:00–11:00 mendengar; Selasa 9:00–11:00 percakapan; Rabu 14:00–16:00 menulis; Kamis 9:00–11:00 percakapan; Jumat 14:00–16:00 membaca. Tanggal 10 Oktober libur, tidak ada kelas.","en":"Chinese class schedule. Mon 9:00–11:00 Listening; Tue 9:00–11:00 Conversation; Wed 14:00–16:00 Writing; Thu 9:00–11:00 Conversation; Fri 14:00–16:00 Reading. No class on October 10 (holiday).","tl":"Iskedyul ng klase sa Chinese. Lunes 9:00–11:00 Listening; Martes 9:00–11:00 Conversation; Miyerkoles 14:00–16:00 Pagsulat; Huwebes 9:00–11:00 Conversation; Biyernes 14:00–16:00 Pagbasa. Walang klase sa Oktubre 10 (holiday).","vi":"Lịch học lớp tiếng Trung. Thứ hai 9:00–11:00 Nghe; Thứ ba 9:00–11:00 Hội thoại; Thứ tư 14:00–16:00 Viết chữ; Thứ năm 9:00–11:00 Hội thoại; Thứ sáu 14:00–16:00 Đọc. Ngày 10 tháng 10 nghỉ, không học."}},{"kind":"diary","title":"我的日記","zh":"十月五日　星期天　天氣很好\n今天是奶奶的生日，我們全家都回奶奶家。爸爸買了一個大蛋糕，媽媽和姑姑在廚房做了很多菜。我最喜歡吃奶奶做的魚，可是今天奶奶不用做菜，她只要休息。吃完飯，我們一起唱生日快樂歌。奶奶說她今年八十歲了，可是身體還很好。","py":"Shí yuè wǔ rì xīng qí tiān tiān qì hěn hǎo\nJīn tiān shì nǎi nai de shēng rì, wǒ men quán jiā dōu huí nǎi nai jiā. Bà ba mǎi le yí ge dà dàn gāo, mā ma hé gū gu zài chú fáng zuò le hěn duō cài. Wǒ zuì xǐ huān chī nǎi nai zuò de yú, kě shì jīn tiān nǎi nai bú yòng zuò cài, tā zhǐ yào xiū xí. Chī wán fàn, wǒ men yì qǐ chàng shēng rì kuài lè gē. Nǎi nai shuō tā jīn nián bā shí suì le, kě shì shēn tǐ hái hěn hǎo.","qs":[{"zh":"今天是誰的生日？","py":"Jīn tiān shì shéi de shēng rì?","opts":["奶奶","媽媽","姑姑","爸爸"],"a":0,"exp":{"id":"Kalimat kedua: 今天是奶奶的生日.","en":"The second sentence says 今天是奶奶的生日.","tl":"Sabi sa ikalawang pangungusap: 今天是奶奶的生日.","vi":"Câu thứ hai: 今天是奶奶的生日."}},{"zh":"今天的菜是誰做的？","py":"Jīn tiān de cài shì shéi zuò de?","opts":["奶奶","爸爸","媽媽和姑姑","奶奶和媽媽"],"a":2,"exp":{"id":"Ibu dan bibi memasak; nenek hari ini tidak perlu memasak.","en":"Mom and aunt cooked; Grandma didn't need to cook today.","tl":"Sina Nanay at tita ang nagluto; hindi nagluto si Lola.","vi":"Mẹ và cô nấu; hôm nay bà không phải nấu."}},{"zh":"下面哪一個是對的？","py":"Xià miàn nǎ yí ge shì duì de?","opts":["爸爸做了一個蛋糕","奶奶今年八十歲","今天下雨","我們在餐廳吃飯"],"a":1,"exp":{"id":"Nenek bilang tahun ini dia 80 tahun; ayah membeli (bukan membuat) kue.","en":"Grandma says she is 80; Dad bought, not made, the cake.","tl":"80 na si Lola; binili ni Tatay ang cake, hindi ginawa.","vi":"Bà nói năm nay 80 tuổi; bố mua bánh chứ không làm."}}],"tr":{"id":"5 Oktober, Minggu, cuaca cerah. Hari ini ulang tahun nenek, seluruh keluarga pulang ke rumah nenek. Ayah membeli kue besar, ibu dan bibi memasak banyak makanan di dapur. Saya paling suka ikan masakan nenek, tetapi hari ini nenek tidak perlu memasak, dia cukup beristirahat. Setelah makan, kami bersama menyanyikan lagu selamat ulang tahun. Nenek bilang tahun ini dia delapan puluh tahun, tetapi masih sangat sehat.","en":"October 5, Sunday, nice weather. Today is Grandma's birthday, and our whole family went back to her house. Dad bought a big cake, and Mom and my aunt cooked lots of dishes in the kitchen. I love Grandma's fish most, but today Grandma didn't have to cook; she just rested. After the meal we sang Happy Birthday together. Grandma said she is eighty this year, but she is still very healthy.","tl":"Oktubre 5, Linggo, maganda ang panahon. Kaarawan ni Lola ngayon, at umuwi ang buong pamilya sa bahay niya. Bumili si Tatay ng malaking cake, at nagluto sina Nanay at tita ng maraming ulam sa kusina. Pinakagusto ko ang isda na luto ni Lola, pero hindi na siya kailangang magluto ngayon; magpapahinga lang siya. Pagkakain, sabay-sabay naming kinanta ang Happy Birthday. Sabi ni Lola, otsenta na siya ngayong taon, pero malakas pa rin ang katawan niya.","vi":"Ngày 5 tháng 10, chủ nhật, trời đẹp. Hôm nay là sinh nhật bà nội, cả nhà về nhà bà. Bố mua một cái bánh kem to, mẹ và cô nấu rất nhiều món trong bếp. Tôi thích nhất món cá bà nấu, nhưng hôm nay bà không phải nấu, bà chỉ cần nghỉ ngơi. Ăn xong, cả nhà cùng hát bài chúc mừng sinh nhật. Bà nói năm nay bà tám mươi tuổi rồi, nhưng sức khỏe vẫn rất tốt."}}]}]},{"form":2,"L":[{"p":1,"items":[{"pic":{"i":["woman","scooter"],"bg":"street"},"opts":[{"zh":"她在騎腳踏車。","py":"Tā zài qí jiǎo tà chē."},{"zh":"她在騎機車。","py":"Tā zài qí jī chē."},{"zh":"她在坐公車。","py":"Tā zài zuò gōng chē."}],"a":1,"tr":{"id":"A: Dia sedang naik sepeda. B: Dia sedang naik motor. C: Dia sedang naik bus.","en":"A: She is riding a bicycle. B: She is riding a scooter. C: She is taking the bus.","tl":"A: Nagbibisikleta siya. B: Nagmamaneho siya ng scooter. C: Sumasakay siya ng bus.","vi":"A: Cô ấy đang đi xe đạp. B: Cô ấy đang chạy xe máy. C: Cô ấy đang đi xe buýt."},"exp":{"id":"Gambar menunjukkan perempuan naik motor (機車).","en":"The picture shows a woman on a scooter (機車).","tl":"Ipinapakita ng larawan ang babae na nakasakay sa scooter (機車).","vi":"Hình cho thấy người phụ nữ đi xe máy (機車)."}},{"pic":{"i":["shirt"],"b":"NT$350","bg":"shop"},"opts":[{"zh":"這件衣服三百五十塊。","py":"Zhè jiàn yī fú sān bǎi wǔ shí kuài."},{"zh":"這件裙子三百五十塊。","py":"Zhè jiàn qún zi sān bǎi wǔ shí kuài."},{"zh":"這件衣服五百三十塊。","py":"Zhè jiàn yī fú wǔ bǎi sān shí kuài."}],"a":0,"tr":{"id":"A: Baju ini 350 dolar. B: Rok ini 350 dolar. C: Baju ini 530 dolar.","en":"A: This top is 350 dollars. B: This skirt is 350 dollars. C: This top is 530 dollars.","tl":"A: Ang damit na ito ay 350 dolyar. B: Ang paldang ito ay 350 dolyar. C: Ang damit na ito ay 530 dolyar.","vi":"A: Cái áo này 350 đồng. B: Cái váy này 350 đồng. C: Cái áo này 530 đồng."},"exp":{"id":"Gambar: baju (衣服) dengan harga NT$350, bukan rok dan bukan 530.","en":"The picture shows a top (衣服) priced NT$350, not a skirt and not 530.","tl":"Damit (衣服) na NT$350 ang nasa larawan, hindi palda at hindi 530.","vi":"Hình là cái áo (衣服) giá NT$350, không phải váy, không phải 530."}},{"pic":{"i":["mrt","clock"],"b":"08:30"},"opts":[{"zh":"公車八點半到。","py":"Gōng chē bā diǎn bàn dào."},{"zh":"捷運九點半到。","py":"Jié yùn jiǔ diǎn bàn dào."},{"zh":"捷運八點半到。","py":"Jié yùn bā diǎn bàn dào."}],"a":2,"tr":{"id":"A: Bus datang jam setengah sembilan. B: MRT datang jam setengah sepuluh. C: MRT datang jam setengah sembilan.","en":"A: The bus arrives at 8:30. B: The MRT arrives at 9:30. C: The MRT arrives at 8:30.","tl":"A: Darating ang bus nang 8:30. B: Darating ang MRT nang 9:30. C: Darating ang MRT nang 8:30.","vi":"A: Xe buýt đến lúc tám giờ rưỡi. B: Tàu điện ngầm đến lúc chín giờ rưỡi. C: Tàu điện ngầm đến lúc tám giờ rưỡi."},"exp":{"id":"Gambar menunjukkan MRT dan jam 08:30.","en":"The picture shows the MRT and the time 08:30.","tl":"MRT at 08:30 ang nasa larawan.","vi":"Hình có tàu điện ngầm và giờ 08:30."}},{"pic":{"i":["friends","night_market"],"bg":"night"},"opts":[{"zh":"他們在看電影。","py":"Tā men zài kàn diàn yǐng."},{"zh":"他們在公園跑步。","py":"Tā men zài gōng yuán pǎo bù."},{"zh":"他們在逛夜市。","py":"Tā men zài guàng yè shì."}],"a":2,"tr":{"id":"A: Mereka sedang menonton film. B: Mereka sedang lari di taman. C: Mereka sedang jalan-jalan di pasar malam.","en":"A: They are watching a movie. B: They are running in the park. C: They are strolling around the night market.","tl":"A: Nanonood sila ng sine. B: Tumatakbo sila sa parke. C: Namamasyal sila sa night market.","vi":"A: Họ đang xem phim. B: Họ đang chạy bộ trong công viên. C: Họ đang dạo chợ đêm."},"exp":{"id":"Gambar: teman-teman di pasar malam pada malam hari.","en":"The picture shows friends at a night market in the evening.","tl":"Magkakaibigan sa night market sa gabi ang nasa larawan.","vi":"Hình là nhóm bạn ở chợ đêm vào buổi tối."}},{"pic":{"i":["man","taxi","rain"],"bg":"rain"},"opts":[{"zh":"下雨了，他要坐計程車。","py":"Xià yǔ le, tā yào zuò jì chéng chē."},{"zh":"下雨了，他在等公車。","py":"Xià yǔ le, tā zài děng gōng chē."},{"zh":"天氣很好，他要坐計程車。","py":"Tiān qì hěn hǎo, tā yào zuò jì chéng chē."}],"a":0,"tr":{"id":"A: Hujan, dia mau naik taksi. B: Hujan, dia sedang menunggu bus. C: Cuacanya bagus, dia mau naik taksi.","en":"A: It's raining; he is going to take a taxi. B: It's raining; he is waiting for the bus. C: The weather is nice; he is going to take a taxi.","tl":"A: Umuulan, sasakay siya ng taxi. B: Umuulan, naghihintay siya ng bus. C: Maganda ang panahon, sasakay siya ng taxi.","vi":"A: Trời mưa rồi, anh ấy sẽ đi taxi. B: Trời mưa rồi, anh ấy đang đợi xe buýt. C: Trời đẹp, anh ấy sẽ đi taxi."},"exp":{"id":"Gambar: hujan dan taksi. Cuaca tidak bagus, dan bukan bus.","en":"The picture shows rain and a taxi — not nice weather, not a bus.","tl":"Ulan at taxi ang nasa larawan — hindi magandang panahon, hindi bus.","vi":"Hình có mưa và taxi — trời không đẹp, không phải xe buýt."}},{"pic":{"i":["shoes"],"b":"x2","bg":"shop"},"opts":[{"zh":"這裡有兩頂帽子。","py":"Zhè lǐ yǒu liǎng dǐng mào zi."},{"zh":"這裡有兩雙鞋子。","py":"Zhè lǐ yǒu liǎng shuāng xié zi."},{"zh":"這裡有一雙鞋子。","py":"Zhè lǐ yǒu yì shuāng xié zi."}],"a":1,"tr":{"id":"A: Di sini ada dua topi. B: Di sini ada dua pasang sepatu. C: Di sini ada sepasang sepatu.","en":"A: There are two hats here. B: There are two pairs of shoes here. C: There is one pair of shoes here.","tl":"A: May dalawang sumbrero dito. B: May dalawang pares ng sapatos dito. C: May isang pares ng sapatos dito.","vi":"A: Ở đây có hai cái mũ. B: Ở đây có hai đôi giày. C: Ở đây có một đôi giày."},"exp":{"id":"Gambar: sepatu dengan tanda x2, jadi dua pasang (雙) sepatu.","en":"The picture shows shoes marked x2: two pairs (雙) of shoes.","tl":"Sapatos na may x2: dalawang pares (雙) ng sapatos.","vi":"Hình là giày có ký hiệu x2: hai đôi (雙) giày."}},{"pic":{"i":["bank","right_arrow"],"bg":"street"},"opts":[{"zh":"銀行在左邊。","py":"Yín háng zài zuǒ biān."},{"zh":"郵局在右邊。","py":"Yóu jú zài yòu biān."},{"zh":"銀行在右邊。","py":"Yín háng zài yòu biān."}],"a":2,"tr":{"id":"A: Bank ada di sebelah kiri. B: Kantor pos ada di sebelah kanan. C: Bank ada di sebelah kanan.","en":"A: The bank is on the left. B: The post office is on the right. C: The bank is on the right.","tl":"A: Nasa kaliwa ang bangko. B: Nasa kanan ang post office. C: Nasa kanan ang bangko.","vi":"A: Ngân hàng ở bên trái. B: Bưu điện ở bên phải. C: Ngân hàng ở bên phải."},"exp":{"id":"Gambar: bank dengan panah ke kanan (右邊).","en":"The picture shows a bank with an arrow pointing right (右邊).","tl":"Bangko na may arrow pakanan (右邊).","vi":"Hình là ngân hàng với mũi tên chỉ sang phải (右邊)."}},{"pic":{"i":["woman","call"],"bg":"home"},"opts":[{"zh":"她在家看電視。","py":"Tā zài jiā kàn diàn shì."},{"zh":"她在家打電話。","py":"Tā zài jiā dǎ diàn huà."},{"zh":"她在學校打電話。","py":"Tā zài xué xiào dǎ diàn huà."}],"a":1,"tr":{"id":"A: Dia sedang menonton TV di rumah. B: Dia sedang menelepon di rumah. C: Dia sedang menelepon di sekolah.","en":"A: She is watching TV at home. B: She is making a phone call at home. C: She is making a phone call at school.","tl":"A: Nanonood siya ng TV sa bahay. B: Tumatawag siya sa telepono sa bahay. C: Tumatawag siya sa paaralan.","vi":"A: Cô ấy đang xem tivi ở nhà. B: Cô ấy đang gọi điện thoại ở nhà. C: Cô ấy đang gọi điện thoại ở trường."},"exp":{"id":"Gambar: perempuan menelepon di rumah, bukan di sekolah.","en":"The picture shows a woman on the phone at home, not at school.","tl":"Babaeng tumatawag sa bahay, hindi sa paaralan.","vi":"Hình là người phụ nữ gọi điện ở nhà, không phải ở trường."}},{"pic":{"i":["ticket","train"],"b":"NT$500"},"opts":[{"zh":"火車票五百塊。","py":"Huǒ chē piào wǔ bǎi kuài."},{"zh":"電影票五百塊。","py":"Diàn yǐng piào wǔ bǎi kuài."},{"zh":"火車票五十塊。","py":"Huǒ chē piào wǔ shí kuài."}],"a":0,"tr":{"id":"A: Tiket kereta 500 dolar. B: Tiket film 500 dolar. C: Tiket kereta 50 dolar.","en":"A: The train ticket is 500 dollars. B: The movie ticket is 500 dollars. C: The train ticket is 50 dollars.","tl":"A: Ang tiket ng tren ay 500 dolyar. B: Ang tiket ng sine ay 500 dolyar. C: Ang tiket ng tren ay 50 dolyar.","vi":"A: Vé tàu hỏa 500 đồng. B: Vé xem phim 500 đồng. C: Vé tàu hỏa 50 đồng."},"exp":{"id":"Gambar: tiket dan kereta, harganya NT$500 (五百), bukan 50.","en":"The picture shows a train ticket for NT$500 (五百), not 50.","tl":"Tiket ng tren na NT$500 (五百), hindi 50.","vi":"Hình là vé tàu hỏa giá NT$500 (五百), không phải 50."}},{"pic":{"i":["man","jacket","cold"]},"opts":[{"zh":"天氣很熱，他穿了外套。","py":"Tiān qì hěn rè, tā chuān le wài tào."},{"zh":"天氣很冷，他穿了外套。","py":"Tiān qì hěn lěng, tā chuān le wài tào."},{"zh":"天氣很冷，他買了帽子。","py":"Tiān qì hěn lěng, tā mǎi le mào zi."}],"a":1,"tr":{"id":"A: Cuacanya panas, dia memakai jaket. B: Cuacanya dingin, dia memakai jaket. C: Cuacanya dingin, dia membeli topi.","en":"A: It's hot; he put on a jacket. B: It's cold; he put on a jacket. C: It's cold; he bought a hat.","tl":"A: Mainit ang panahon, nagsuot siya ng jacket. B: Malamig ang panahon, nagsuot siya ng jacket. C: Malamig ang panahon, bumili siya ng sumbrero.","vi":"A: Trời nóng, anh ấy mặc áo khoác. B: Trời lạnh, anh ấy mặc áo khoác. C: Trời lạnh, anh ấy mua mũ."},"exp":{"id":"Gambar: cuaca dingin dan pria memakai jaket (外套).","en":"The picture shows cold weather and a man in a jacket (外套).","tl":"Malamig at lalaking naka-jacket (外套) ang nasa larawan.","vi":"Hình cho thấy trời lạnh và người đàn ông mặc áo khoác (外套)."}}]},{"p":2,"items":[{"dlg":[{"sp":"M","zh":"請問去台北車站要坐幾號公車？","py":"Qǐng wèn qù Tái běi chē zhàn yào zuò jǐ hào gōng chē?"},{"sp":"F","zh":"坐兩百六十二號就可以了。","py":"Zuò liǎng bǎi liù shí èr hào jiù kě yǐ le."}],"q":{"zh":"男的要坐幾號公車？","py":"Nán de yào zuò jǐ hào gōng chē?"},"opts":[{"i":["bus"],"b":"226","bg":"street"},{"i":["bus"],"b":"62","bg":"street"},{"i":["bus"],"b":"262","bg":"street"}],"a":2,"tr":{"id":"Pria: Permisi, ke Stasiun Taipei naik bus nomor berapa?\nWanita: Naik nomor 262 saja.\nPertanyaan: Pria itu harus naik bus nomor berapa?","en":"Man: Excuse me, which bus number goes to Taipei Main Station?\nWoman: Just take number 262.\nQuestion: Which bus number should the man take?","tl":"Lalaki: Paumanhin, anong numero ng bus papuntang Taipei Station?\nBabae: Sumakay ka lang ng numero 262.\nTanong: Anong numero ng bus ang sasakyan ng lalaki?","vi":"Nam: Xin hỏi, đi ga Đài Bắc phải đi xe buýt số mấy?\nNữ: Đi số 262 là được.\nCâu hỏi: Người đàn ông phải đi xe buýt số mấy?"},"exp":{"id":"Perempuan bilang naik nomor 262 (兩百六十二).","en":"The woman says to take number 262 (兩百六十二).","tl":"Sinabi ng babae na sumakay sa numero 262 (兩百六十二).","vi":"Người phụ nữ nói đi số 262 (兩百六十二)."}},{"dlg":[{"sp":"F","zh":"這件外套多少錢？","py":"Zhè jiàn wài tào duō shǎo qián?"},{"sp":"M","zh":"這件六百八十塊。","py":"Zhè jiàn liù bǎi bā shí kuài."}],"q":{"zh":"外套多少錢？","py":"Wài tào duō shǎo qián?"},"opts":[{"i":["jacket"],"b":"NT$680","bg":"shop"},{"i":["jacket"],"b":"NT$860","bg":"shop"},{"i":["shirt"],"b":"NT$680","bg":"shop"}],"a":0,"tr":{"id":"Wanita: Jaket ini berapa harganya?\nPria: Yang ini 680 dolar.\nPertanyaan: Jaketnya berapa?","en":"Woman: How much is this jacket?\nMan: This one is 680 dollars.\nQuestion: How much is the jacket?","tl":"Babae: Magkano ang jacket na ito?\nLalaki: Ito ay 680 dolyar.\nTanong: Magkano ang jacket?","vi":"Nữ: Cái áo khoác này bao nhiêu tiền?\nNam: Cái này 680 đồng.\nCâu hỏi: Áo khoác bao nhiêu tiền?"},"exp":{"id":"Harga jaket 680 (六百八十), bukan 860; dan itu jaket, bukan kemeja.","en":"The jacket costs 680 (六百八十), not 860, and it is a jacket, not a shirt.","tl":"Ang jacket ay 680 (六百八十), hindi 860, at jacket ito, hindi polo.","vi":"Áo khoác giá 680 (六百八十), không phải 860, và là áo khoác chứ không phải sơ mi."}},{"dlg":[{"sp":"M","zh":"你每天怎麼去上班？","py":"Nǐ měi tiān zěn me qù shàng bān?"},{"sp":"F","zh":"我以前坐公車，現在都騎機車。","py":"Wǒ yǐ qián zuò gōng chē, xiàn zài dōu qí jī chē."}],"q":{"zh":"女的現在怎麼去上班？","py":"Nǚ de xiàn zài zěn me qù shàng bān?"},"opts":[{"i":["woman","bus"],"bg":"street"},{"i":["woman","scooter"],"bg":"street"},{"i":["woman","bicycle"],"bg":"street"}],"a":1,"tr":{"id":"Pria: Setiap hari kamu pergi kerja naik apa?\nWanita: Dulu aku naik bus, sekarang selalu naik motor.\nPertanyaan: Sekarang perempuan itu pergi kerja naik apa?","en":"Man: How do you get to work every day?\nWoman: I used to take the bus; now I always ride a scooter.\nQuestion: How does the woman get to work now?","tl":"Lalaki: Paano ka pumapasok sa trabaho araw-araw?\nBabae: Dati nagbu-bus ako, ngayon lagi akong naka-scooter.\nTanong: Paano pumapasok sa trabaho ang babae ngayon?","vi":"Nam: Mỗi ngày bạn đi làm bằng gì?\nNữ: Trước đây tôi đi xe buýt, bây giờ toàn đi xe máy.\nCâu hỏi: Bây giờ người phụ nữ đi làm bằng gì?"},"exp":{"id":"Bus itu dulu (以前); sekarang (現在) dia naik motor.","en":"The bus was before (以前); now (現在) she rides a scooter.","tl":"Bus ay dati (以前); ngayon (現在) scooter na siya.","vi":"Xe buýt là trước đây (以前); bây giờ (現在) cô ấy đi xe máy."}},{"dlg":[{"sp":"F","zh":"請問，洗手間在哪裡？","py":"Qǐng wèn, xǐ shǒu jiān zài nǎ lǐ?"},{"sp":"M","zh":"在二樓，電梯旁邊。","py":"Zài èr lóu, diàn tī páng biān."}],"q":{"zh":"洗手間在哪裡？","py":"Xǐ shǒu jiān zài nǎ lǐ?"},"opts":[{"i":["toilet","elevator"],"b":"3F"},{"i":["toilet","stairs"],"b":"2F"},{"i":["toilet","elevator"],"b":"2F"}],"a":2,"tr":{"id":"Wanita: Permisi, toiletnya di mana?\nPria: Di lantai dua, di samping lift.\nPertanyaan: Toiletnya di mana?","en":"Woman: Excuse me, where is the restroom?\nMan: On the second floor, next to the elevator.\nQuestion: Where is the restroom?","tl":"Babae: Paumanhin, nasaan ang banyo?\nLalaki: Nasa ikalawang palapag, katabi ng elevator.\nTanong: Nasaan ang banyo?","vi":"Nữ: Xin hỏi, nhà vệ sinh ở đâu?\nNam: Ở tầng hai, bên cạnh thang máy.\nCâu hỏi: Nhà vệ sinh ở đâu?"},"exp":{"id":"Toilet ada di lantai 2 (二樓), di samping lift (電梯).","en":"The restroom is on 2F (二樓), next to the elevator (電梯).","tl":"Ang banyo ay nasa 2F (二樓), katabi ng elevator (電梯).","vi":"Nhà vệ sinh ở tầng 2 (二樓), cạnh thang máy (電梯)."}},{"dlg":[{"sp":"M","zh":"你明天要去哪裡玩？","py":"Nǐ míng tiān yào qù nǎ lǐ wán?"},{"sp":"F","zh":"我想去墾丁，去海邊游泳。","py":"Wǒ xiǎng qù Kěn dīng, qù hǎi biān yóu yǒng."}],"q":{"zh":"女的明天要做什麼？","py":"Nǚ de míng tiān yào zuò shén me?"},"opts":[{"i":["mountain","walk"]},{"i":["beach","swim"],"bg":"sea"},{"i":["night_market"],"bg":"night"}],"a":1,"tr":{"id":"Pria: Besok kamu mau main ke mana?\nWanita: Aku mau ke Kenting, berenang di pantai.\nPertanyaan: Besok perempuan itu mau melakukan apa?","en":"Man: Where are you going for fun tomorrow?\nWoman: I want to go to Kenting and swim at the beach.\nQuestion: What is the woman going to do tomorrow?","tl":"Lalaki: Saan ka mamamasyal bukas?\nBabae: Gusto kong pumunta sa Kenting at lumangoy sa dagat.\nTanong: Ano ang gagawin ng babae bukas?","vi":"Nam: Ngày mai bạn định đi chơi ở đâu?\nNữ: Tôi muốn đi Khẩn Đinh, đi bơi ở biển.\nCâu hỏi: Ngày mai người phụ nữ sẽ làm gì?"},"exp":{"id":"Dia mau berenang (游泳) di pantai (海邊) di Kenting.","en":"She wants to swim (游泳) at the beach (海邊) in Kenting.","tl":"Gusto niyang lumangoy (游泳) sa dagat (海邊) sa Kenting.","vi":"Cô ấy muốn bơi (游泳) ở biển (海邊) tại Khẩn Đinh."}},{"dlg":[{"sp":"F","zh":"喂，你現在在哪裡？","py":"Wéi, nǐ xiàn zài zài nǎ lǐ?"},{"sp":"M","zh":"我在捷運站，十分鐘就到。","py":"Wǒ zài jié yùn zhàn, shí fēn zhōng jiù dào."}],"q":{"zh":"男的現在在哪裡？","py":"Nán de xiàn zài zài nǎ lǐ?"},"opts":[{"i":["man","mrt"]},{"i":["man","bus"],"bg":"street"},{"i":["man","house"],"bg":"home"}],"a":0,"tr":{"id":"Wanita: Halo, kamu sekarang di mana?\nPria: Aku di stasiun MRT, sepuluh menit lagi sampai.\nPertanyaan: Pria itu sekarang di mana?","en":"Woman: Hello, where are you now?\nMan: I'm at the MRT station; I'll be there in ten minutes.\nQuestion: Where is the man now?","tl":"Babae: Hello, nasaan ka ngayon?\nLalaki: Nasa MRT station ako, darating ako sa loob ng sampung minuto.\nTanong: Nasaan ang lalaki ngayon?","vi":"Nữ: A lô, bây giờ bạn đang ở đâu?\nNam: Tôi đang ở ga tàu điện ngầm, mười phút nữa là tới.\nCâu hỏi: Người đàn ông bây giờ đang ở đâu?"},"exp":{"id":"Pria itu bilang dia di stasiun MRT (捷運站).","en":"The man says he is at the MRT station (捷運站).","tl":"Sinabi ng lalaki na nasa MRT station (捷運站) siya.","vi":"Người đàn ông nói anh ấy đang ở ga tàu điện ngầm (捷運站)."}},{"dlg":[{"sp":"M","zh":"你去夜市常常買什麼？","py":"Nǐ qù yè shì cháng cháng mǎi shén me?"},{"sp":"F","zh":"我常常買珍珠奶茶，很便宜。","py":"Wǒ cháng cháng mǎi zhēn zhū nǎi chá, hěn pián yí."}],"q":{"zh":"女的在夜市常常買什麼？","py":"Nǚ de zài yè shì cháng cháng mǎi shén me?"},"opts":[{"i":["coffee"],"bg":"night"},{"i":["bubble_tea"],"bg":"night"},{"i":["ice_cream"],"bg":"night"}],"a":1,"tr":{"id":"Pria: Kalau ke pasar malam, kamu sering beli apa?\nWanita: Aku sering beli bubble tea, murah sekali.\nPertanyaan: Perempuan itu sering beli apa di pasar malam?","en":"Man: What do you often buy at the night market?\nWoman: I often buy bubble tea; it's cheap.\nQuestion: What does the woman often buy at the night market?","tl":"Lalaki: Ano ang madalas mong binibili sa night market?\nBabae: Madalas akong bumili ng bubble tea, mura kasi.\nTanong: Ano ang madalas bilhin ng babae sa night market?","vi":"Nam: Khi đi chợ đêm bạn thường mua gì?\nNữ: Tôi thường mua trà sữa trân châu, rất rẻ.\nCâu hỏi: Người phụ nữ thường mua gì ở chợ đêm?"},"exp":{"id":"Dia sering membeli bubble tea (珍珠奶茶).","en":"She often buys bubble tea (珍珠奶茶).","tl":"Madalas siyang bumili ng bubble tea (珍珠奶茶).","vi":"Cô ấy thường mua trà sữa trân châu (珍珠奶茶)."}},{"dlg":[{"sp":"F","zh":"這雙鞋子你要買嗎？","py":"Zhè shuāng xié zi nǐ yào mǎi ma?"},{"sp":"M","zh":"不要，太小了，我要買那頂帽子。","py":"Bú yào, tài xiǎo le, wǒ yào mǎi nà dǐng mào zi."}],"q":{"zh":"男的要買什麼？","py":"Nán de yào mǎi shén me?"},"opts":[{"i":["hat"],"bg":"shop"},{"i":["shoes"],"bg":"shop"},{"i":["socks"],"bg":"shop"}],"a":0,"tr":{"id":"Wanita: Sepatu ini mau kamu beli?\nPria: Tidak, terlalu kecil. Aku mau beli topi itu.\nPertanyaan: Pria itu mau membeli apa?","en":"Woman: Are you going to buy these shoes?\nMan: No, they're too small. I want to buy that hat.\nQuestion: What does the man want to buy?","tl":"Babae: Bibilhin mo ba ang sapatos na ito?\nLalaki: Hindi, masyadong maliit. Bibilhin ko ang sumbrerong iyon.\nTanong: Ano ang gustong bilhin ng lalaki?","vi":"Nữ: Đôi giày này bạn có mua không?\nNam: Không, nhỏ quá. Tôi muốn mua cái mũ kia.\nCâu hỏi: Người đàn ông muốn mua gì?"},"exp":{"id":"Sepatunya terlalu kecil; dia mau beli topi (帽子).","en":"The shoes are too small; he wants the hat (帽子).","tl":"Masyadong maliit ang sapatos; sumbrero (帽子) ang gusto niya.","vi":"Giày nhỏ quá; anh ấy muốn mua mũ (帽子)."}},{"dlg":[{"sp":"M","zh":"去機場坐什麼比較快？","py":"Qù jī chǎng zuò shén me bǐ jiào kuài?"},{"sp":"F","zh":"坐捷運比坐計程車快。","py":"Zuò jié yùn bǐ zuò jì chéng chē kuài."}],"q":{"zh":"女的說坐什麼比較快？","py":"Nǚ de shuō zuò shén me bǐ jiào kuài?"},"opts":[{"i":["taxi","airplane"]},{"i":["bus","airplane"]},{"i":["mrt","airplane"]}],"a":2,"tr":{"id":"Pria: Ke bandara naik apa yang lebih cepat?\nWanita: Naik MRT lebih cepat daripada naik taksi.\nPertanyaan: Menurut perempuan itu, naik apa yang lebih cepat?","en":"Man: What's faster for getting to the airport?\nWoman: The MRT is faster than a taxi.\nQuestion: According to the woman, what is faster?","tl":"Lalaki: Ano ang mas mabilis papuntang airport?\nBabae: Mas mabilis ang MRT kaysa sa taxi.\nTanong: Ayon sa babae, ano ang mas mabilis?","vi":"Nam: Đi sân bay bằng gì thì nhanh hơn?\nNữ: Đi tàu điện ngầm nhanh hơn đi taxi.\nCâu hỏi: Người phụ nữ nói đi bằng gì nhanh hơn?"},"exp":{"id":"捷運比計程車快: MRT lebih cepat dari taksi.","en":"捷運比計程車快 means the MRT is faster than a taxi.","tl":"捷運比計程車快: mas mabilis ang MRT kaysa taxi.","vi":"捷運比計程車快: tàu điện ngầm nhanh hơn taxi."}},{"dlg":[{"sp":"F","zh":"火車幾點開？","py":"Huǒ chē jǐ diǎn kāi?"},{"sp":"M","zh":"十點四十五分，我們還有二十分鐘。","py":"Shí diǎn sì shí wǔ fēn, wǒ men hái yǒu èr shí fēn zhōng."}],"q":{"zh":"火車幾點開？","py":"Huǒ chē jǐ diǎn kāi?"},"opts":[{"i":["train"],"b":"10:25"},{"i":["train"],"b":"10:45"},{"i":["train"],"b":"10:20"}],"a":1,"tr":{"id":"Wanita: Keretanya berangkat jam berapa?\nPria: Jam 10.45, kita masih punya dua puluh menit.\nPertanyaan: Keretanya berangkat jam berapa?","en":"Woman: What time does the train leave?\nMan: At 10:45. We still have twenty minutes.\nQuestion: What time does the train leave?","tl":"Babae: Anong oras aalis ang tren?\nLalaki: Alas-10:45. May dalawampung minuto pa tayo.\nTanong: Anong oras aalis ang tren?","vi":"Nữ: Tàu hỏa mấy giờ chạy?\nNam: Mười giờ bốn mươi lăm, chúng ta còn hai mươi phút.\nCâu hỏi: Tàu hỏa mấy giờ chạy?"},"exp":{"id":"Kereta berangkat jam 10.45; \"dua puluh menit\" adalah sisa waktu.","en":"The train leaves at 10:45; \"twenty minutes\" is the time left.","tl":"Aalis ang tren nang 10:45; ang \"dalawampung minuto\" ay natitirang oras.","vi":"Tàu chạy lúc 10:45; \"hai mươi phút\" là thời gian còn lại."}},{"dlg":[{"sp":"M","zh":"請問，郵局怎麼走？","py":"Qǐng wèn, yóu jú zěn me zǒu?"},{"sp":"F","zh":"一直往前走，到了路口往左轉。","py":"Yì zhí wǎng qián zǒu, dào le lù kǒu wǎng zuǒ zhuǎn."}],"q":{"zh":"到了路口要往哪裡走？","py":"Dào le lù kǒu yào wǎng nǎ lǐ zǒu?"},"opts":[{"i":["post_office","right_arrow"],"bg":"street"},{"i":["post_office","straight_arrow"],"bg":"street"},{"i":["post_office","left_arrow"],"bg":"street"}],"a":2,"tr":{"id":"Pria: Permisi, ke kantor pos lewat mana?\nWanita: Jalan lurus terus, sampai di persimpangan belok kiri.\nPertanyaan: Sampai di persimpangan harus ke arah mana?","en":"Man: Excuse me, how do I get to the post office?\nWoman: Go straight, then turn left at the intersection.\nQuestion: Which way should he go at the intersection?","tl":"Lalaki: Paumanhin, paano pumunta sa post office?\nBabae: Diretso lang, pagdating sa kanto kumaliwa ka.\nTanong: Saan siya dapat pumunta pagdating sa kanto?","vi":"Nam: Xin hỏi, bưu điện đi thế nào?\nNữ: Cứ đi thẳng, tới ngã tư thì rẽ trái.\nCâu hỏi: Tới ngã tư thì phải đi hướng nào?"},"exp":{"id":"Lurus dulu, lalu di persimpangan belok kiri (往左轉).","en":"First straight, then at the intersection turn left (往左轉).","tl":"Diretso muna, saka kumaliwa (往左轉) sa kanto.","vi":"Đi thẳng trước, tới ngã tư thì rẽ trái (往左轉)."}},{"dlg":[{"sp":"F","zh":"你買了幾張電影票？","py":"Nǐ mǎi le jǐ zhāng diàn yǐng piào?"},{"sp":"M","zh":"我買了三張，我、你和小美。","py":"Wǒ mǎi le sān zhāng, wǒ, nǐ hé Xiǎo Měi."}],"q":{"zh":"男的買了幾張票？","py":"Nán de mǎi le jǐ zhāng piào?"},"opts":[{"i":["ticket","movie"],"b":"x3"},{"i":["ticket","movie"],"b":"x2"},{"i":["ticket","movie"],"b":"x4"}],"a":0,"tr":{"id":"Wanita: Kamu beli berapa tiket film?\nPria: Aku beli tiga: aku, kamu, dan Xiaomei.\nPertanyaan: Pria itu membeli berapa tiket?","en":"Woman: How many movie tickets did you buy?\nMan: I bought three: me, you and Xiaomei.\nQuestion: How many tickets did the man buy?","tl":"Babae: Ilang tiket ng sine ang binili mo?\nLalaki: Tatlo ang binili ko: ako, ikaw at si Xiaomei.\nTanong: Ilang tiket ang binili ng lalaki?","vi":"Nữ: Bạn đã mua mấy vé xem phim?\nNam: Tôi mua ba vé: tôi, bạn và Tiểu Mỹ.\nCâu hỏi: Người đàn ông đã mua mấy vé?"},"exp":{"id":"Dia membeli tiga (三張) tiket untuk tiga orang.","en":"He bought three (三張) tickets for three people.","tl":"Tatlong (三張) tiket ang binili niya para sa tatlong tao.","vi":"Anh ấy mua ba (三張) vé cho ba người."}},{"dlg":[{"sp":"M","zh":"這個西瓜怎麼賣？","py":"Zhè ge xī guā zěn me mài?"},{"sp":"F","zh":"一個一百二十塊，兩個兩百塊。","py":"Yí ge yì bǎi èr shí kuài, liǎng ge liǎng bǎi kuài."}],"q":{"zh":"一個西瓜多少錢？","py":"Yí ge xī guā duō shǎo qián?"},"opts":[{"i":["watermelon"],"b":"NT$200"},{"i":["watermelon"],"b":"NT$120"},{"i":["watermelon"],"b":"NT$100"}],"a":1,"tr":{"id":"Pria: Semangka ini dijual berapa?\nWanita: Satu 120 dolar, dua 200 dolar.\nPertanyaan: Satu semangka berapa harganya?","en":"Man: How much is this watermelon?\nWoman: 120 dollars for one, 200 for two.\nQuestion: How much is one watermelon?","tl":"Lalaki: Magkano ang pakwan na ito?\nBabae: Isa ay 120 dolyar, dalawa ay 200.\nTanong: Magkano ang isang pakwan?","vi":"Nam: Quả dưa hấu này bán thế nào?\nNữ: Một quả 120 đồng, hai quả 200 đồng.\nCâu hỏi: Một quả dưa hấu bao nhiêu tiền?"},"exp":{"id":"Satu semangka 120 dolar; 200 adalah harga untuk dua.","en":"One watermelon is 120; 200 is the price for two.","tl":"Ang isa ay 120; ang 200 ay para sa dalawa.","vi":"Một quả 120 đồng; 200 là giá hai quả."}},{"dlg":[{"sp":"F","zh":"你週末要做什麼？","py":"Nǐ zhōu mò yào zuò shén me?"},{"sp":"M","zh":"我要跟朋友去淡水騎腳踏車。","py":"Wǒ yào gēn péng yǒu qù Dàn shuǐ qí jiǎo tà chē."}],"q":{"zh":"男的週末要做什麼？","py":"Nán de zhōu mò yào zuò shén me?"},"opts":[{"i":["friends","bicycle"],"bg":"park"},{"i":["friends","scooter"],"bg":"street"},{"i":["friends","train"]}],"a":0,"tr":{"id":"Wanita: Akhir pekan kamu mau apa?\nPria: Aku mau bersepeda di Tamsui dengan teman.\nPertanyaan: Pria itu mau apa akhir pekan ini?","en":"Woman: What are you doing this weekend?\nMan: I'm going cycling in Tamsui with friends.\nQuestion: What will the man do this weekend?","tl":"Babae: Ano ang gagawin mo sa weekend?\nLalaki: Magbibisikleta kami ng mga kaibigan ko sa Tamsui.\nTanong: Ano ang gagawin ng lalaki sa weekend?","vi":"Nữ: Cuối tuần bạn định làm gì?\nNam: Tôi sẽ đi đạp xe ở Đạm Thủy với bạn bè.\nCâu hỏi: Cuối tuần người đàn ông sẽ làm gì?"},"exp":{"id":"Dia akan bersepeda (騎腳踏車) dengan teman.","en":"He will ride bicycles (騎腳踏車) with friends.","tl":"Magbibisikleta (騎腳踏車) siya kasama ang mga kaibigan.","vi":"Anh ấy sẽ đạp xe (騎腳踏車) cùng bạn bè."}},{"dlg":[{"sp":"M","zh":"你的手機呢？","py":"Nǐ de shǒu jī ne?"},{"sp":"F","zh":"在我的包包裡，你要打電話嗎？","py":"Zài wǒ de bāo bāo lǐ, nǐ yào dǎ diàn huà ma?"}],"q":{"zh":"女的手機在哪裡？","py":"Nǚ de shǒu jī zài nǎ lǐ?"},"opts":[{"i":["phone","table"]},{"i":["phone","bed"]},{"i":["phone","handbag"]}],"a":2,"tr":{"id":"Pria: Ponselmu mana?\nWanita: Di dalam tasku. Kamu mau menelepon?\nPertanyaan: Ponsel perempuan itu di mana?","en":"Man: Where's your phone?\nWoman: In my bag. Do you want to make a call?\nQuestion: Where is the woman's phone?","tl":"Lalaki: Nasaan ang cellphone mo?\nBabae: Nasa bag ko. Tatawag ka ba?\nTanong: Nasaan ang cellphone ng babae?","vi":"Nam: Điện thoại của bạn đâu?\nNữ: Trong túi xách của tôi. Bạn muốn gọi điện à?\nCâu hỏi: Điện thoại của người phụ nữ ở đâu?"},"exp":{"id":"Ponselnya ada di dalam tas (包包裡).","en":"Her phone is in her bag (包包裡).","tl":"Nasa loob ng bag (包包裡) ang cellphone niya.","vi":"Điện thoại ở trong túi xách (包包裡)."}}]},{"p":3,"items":[{"dlg":[{"sp":"F","zh":"我們明天開車去台中，好不好？","py":"Wǒ men míng tiān kāi chē qù Tái zhōng, hǎo bù hǎo?"},{"sp":"M","zh":"開車太累了，坐火車吧。","py":"Kāi chē tài lèi le, zuò huǒ chē ba."},{"sp":"F","zh":"可是火車票比較貴。","py":"Kě shì huǒ chē piào bǐ jiào guì."},{"sp":"M","zh":"沒關係，我請你。","py":"Méi guān xi, wǒ qǐng nǐ."}],"q":{"zh":"他們明天怎麼去台中？","py":"Tā men míng tiān zěn me qù Tái zhōng?"},"opts":[{"i":["car"]},{"i":["train"]},{"i":["bus"]}],"a":1,"tr":{"id":"Wanita: Besok kita naik mobil ke Taichung, ya?\nPria: Menyetir terlalu capek, naik kereta saja.\nWanita: Tapi tiket kereta lebih mahal.\nPria: Tidak apa-apa, aku yang traktir.\nPertanyaan: Besok mereka ke Taichung naik apa?","en":"Woman: Shall we drive to Taichung tomorrow?\nMan: Driving is too tiring. Let's take the train.\nWoman: But train tickets are more expensive.\nMan: No problem, it's my treat.\nQuestion: How will they go to Taichung tomorrow?","tl":"Babae: Magmaneho tayo papuntang Taichung bukas, ha?\nLalaki: Nakakapagod magmaneho, mag-tren na lang tayo.\nBabae: Pero mas mahal ang tiket ng tren.\nLalaki: Okay lang, libre ko.\nTanong: Paano sila pupunta sa Taichung bukas?","vi":"Nữ: Ngày mai mình lái xe đi Đài Trung nhé?\nNam: Lái xe mệt quá, đi tàu hỏa đi.\nNữ: Nhưng vé tàu đắt hơn.\nNam: Không sao, tôi mời bạn.\nCâu hỏi: Ngày mai họ đi Đài Trung bằng gì?"},"exp":{"id":"Pria menolak menyetir dan akan membayar tiket; mereka naik kereta.","en":"The man rejects driving and will pay the tickets, so they take the train.","tl":"Ayaw magmaneho ng lalaki at siya ang magbabayad; magte-tren sila.","vi":"Người đàn ông không muốn lái xe và sẽ trả tiền vé, nên họ đi tàu hỏa."}},{"dlg":[{"sp":"M","zh":"你覺得這件紅色的裙子怎麼樣？","py":"Nǐ jué de zhè jiàn hóng sè de qún zi zěn me yàng?"},{"sp":"F","zh":"很好看，可是有一點短。","py":"Hěn hǎo kàn, kě shì yǒu yì diǎn duǎn."},{"sp":"M","zh":"那這件長的洋裝呢？","py":"Nà zhè jiàn cháng de yáng zhuāng ne?"},{"sp":"F","zh":"這件不錯，我就買這件吧。","py":"Zhè jiàn bú cuò, wǒ jiù mǎi zhè jiàn ba."}],"q":{"zh":"女的要買什麼？","py":"Nǚ de yào mǎi shén me?"},"opts":[{"i":["dress"],"bg":"shop"},{"i":["skirt"],"bg":"shop"},{"i":["pants"],"bg":"shop"}],"a":0,"tr":{"id":"Pria: Menurutmu rok merah ini bagaimana?\nWanita: Bagus, tapi agak pendek.\nPria: Kalau gaun panjang ini?\nWanita: Yang ini bagus, aku beli yang ini saja.\nPertanyaan: Perempuan itu mau membeli apa?","en":"Man: What do you think of this red skirt?\nWoman: It looks nice, but it's a bit short.\nMan: Then what about this long dress?\nWoman: This one's nice. I'll buy this one.\nQuestion: What is the woman going to buy?","tl":"Lalaki: Ano sa tingin mo sa pulang palda na ito?\nBabae: Maganda, pero medyo maikli.\nLalaki: E itong mahabang bestida?\nBabae: Maganda ito, ito na ang bibilhin ko.\nTanong: Ano ang bibilhin ng babae?","vi":"Nam: Bạn thấy cái váy đỏ này thế nào?\nNữ: Đẹp lắm, nhưng hơi ngắn.\nNam: Thế còn cái đầm dài này?\nNữ: Cái này được đấy, tôi mua cái này.\nCâu hỏi: Người phụ nữ sẽ mua gì?"},"exp":{"id":"Roknya terlalu pendek; dia membeli gaun panjang (洋裝).","en":"The skirt is too short; she buys the long dress (洋裝).","tl":"Maikli ang palda; ang mahabang bestida (洋裝) ang bibilhin niya.","vi":"Váy ngắn quá; cô ấy mua cái đầm dài (洋裝)."}},{"dlg":[{"sp":"F","zh":"我們六點在捷運站見面吧。","py":"Wǒ men liù diǎn zài jié yùn zhàn jiàn miàn ba."},{"sp":"M","zh":"捷運站人太多了，在便利商店門口好不好？","py":"Jié yùn zhàn rén tài duō le, zài biàn lì shāng diàn mén kǒu hǎo bù hǎo?"},{"sp":"F","zh":"好啊，那時間呢？","py":"Hǎo a, nà shí jiān ne?"},{"sp":"M","zh":"時間不變，還是六點。","py":"Shí jiān bú biàn, hái shì liù diǎn."}],"q":{"zh":"他們六點在哪裡見面？","py":"Tā men liù diǎn zài nǎ lǐ jiàn miàn?"},"opts":[{"i":["mrt"],"bg":"street"},{"i":["store"],"bg":"street"},{"i":["park"],"bg":"park"}],"a":1,"tr":{"id":"Wanita: Kita bertemu jam enam di stasiun MRT, ya.\nPria: Stasiun MRT terlalu ramai, di depan minimarket saja?\nWanita: Boleh, lalu jamnya?\nPria: Jamnya tidak berubah, tetap jam enam.\nPertanyaan: Jam enam mereka bertemu di mana?","en":"Woman: Let's meet at the MRT station at six.\nMan: The MRT station is too crowded. How about outside the convenience store?\nWoman: Sure. And the time?\nMan: The time stays the same, still six.\nQuestion: Where will they meet at six?","tl":"Babae: Magkita tayo nang alas-sais sa MRT station.\nLalaki: Masyadong maraming tao sa MRT station. Sa harap ng convenience store kaya?\nBabae: Sige, e ang oras?\nLalaki: Hindi magbabago ang oras, alas-sais pa rin.\nTanong: Saan sila magkikita nang alas-sais?","vi":"Nữ: Sáu giờ mình gặp nhau ở ga tàu điện ngầm nhé.\nNam: Ga tàu đông người quá, ở trước cửa cửa hàng tiện lợi được không?\nNữ: Được, thế còn giờ?\nNam: Giờ không đổi, vẫn là sáu giờ.\nCâu hỏi: Sáu giờ họ gặp nhau ở đâu?"},"exp":{"id":"Tempatnya diganti dari stasiun MRT ke depan minimarket (便利商店).","en":"The place changed from the MRT station to the convenience store (便利商店).","tl":"Pinalitan ang lugar mula MRT station papuntang convenience store (便利商店).","vi":"Địa điểm đổi từ ga tàu sang trước cửa hàng tiện lợi (便利商店)."}},{"dlg":[{"sp":"M","zh":"請問，到夜市大概多少錢？","py":"Qǐng wèn, dào yè shì dà gài duō shǎo qián?"},{"sp":"F","zh":"大概一百五十塊。","py":"Dà gài yì bǎi wǔ shí kuài."},{"sp":"M","zh":"好，可以刷卡嗎？","py":"Hǎo, kě yǐ shuā kǎ ma?"},{"sp":"F","zh":"對不起，只能付現金。","py":"Duì bù qǐ, zhǐ néng fù xiàn jīn."}],"q":{"zh":"男的要怎麼付錢？","py":"Nán de yào zěn me fù qián?"},"opts":[{"i":["money","taxi"]},{"i":["card","taxi"]},{"i":["phone","taxi"]}],"a":0,"tr":{"id":"Pria: Permisi, ke pasar malam kira-kira berapa?\nWanita: Kira-kira 150 dolar.\nPria: Baik, bisa bayar pakai kartu?\nWanita: Maaf, hanya bisa bayar tunai.\nPertanyaan: Pria itu harus bayar dengan cara apa?","en":"Man: Excuse me, about how much is it to the night market?\nWoman: About 150 dollars.\nMan: OK. Can I pay by card?\nWoman: Sorry, cash only.\nQuestion: How will the man have to pay?","tl":"Lalaki: Excuse po, mga magkano papuntang night market?\nBabae: Mga 150 dolyar.\nLalaki: Sige, puwede bang magbayad gamit ang card?\nBabae: Pasensya na, cash lang.\nTanong: Paano magbabayad ang lalaki?","vi":"Nam: Xin hỏi, đến chợ đêm khoảng bao nhiêu tiền?\nNữ: Khoảng 150 đồng.\nNam: Được, có quẹt thẻ được không?\nNữ: Xin lỗi, chỉ trả tiền mặt thôi.\nCâu hỏi: Người đàn ông phải trả tiền bằng cách nào?"},"exp":{"id":"Tidak bisa pakai kartu; hanya tunai (現金).","en":"Cards aren't accepted; only cash (現金).","tl":"Hindi puwede ang card; cash (現金) lang.","vi":"Không quẹt thẻ được; chỉ tiền mặt (現金)."}},{"dlg":[{"sp":"F","zh":"你出門要帶雨傘嗎？","py":"Nǐ chū mén yào dài yǔ sǎn ma?"},{"sp":"M","zh":"現在是晴天，不用帶吧。","py":"Xiàn zài shì qíng tiān, bú yòng dài ba."},{"sp":"F","zh":"可是新聞說下午會下大雨。","py":"Kě shì xīn wén shuō xià wǔ huì xià dà yǔ."},{"sp":"M","zh":"好吧，那我帶一把。","py":"Hǎo ba, nà wǒ dài yì bǎ."}],"q":{"zh":"下午天氣怎麼樣？","py":"Xià wǔ tiān qì zěn me yàng?"},"opts":[{"i":["sun"]},{"i":["cloud","wind"]},{"i":["rain","umbrella"],"bg":"rain"}],"a":2,"tr":{"id":"Wanita: Kamu bawa payung kalau keluar?\nPria: Sekarang cerah, tidak usah bawa.\nWanita: Tapi berita bilang sore nanti akan hujan deras.\nPria: Baiklah, aku bawa satu.\nPertanyaan: Bagaimana cuaca sore nanti?","en":"Woman: Are you taking an umbrella when you go out?\nMan: It's sunny now, no need.\nWoman: But the news says it will rain hard this afternoon.\nMan: All right, I'll take one.\nQuestion: What will the weather be like in the afternoon?","tl":"Babae: Magdadala ka ba ng payong paglabas mo?\nLalaki: Maaraw ngayon, hindi na kailangan.\nBabae: Pero sabi sa balita, uulan nang malakas mamayang hapon.\nLalaki: Sige, magdadala ako ng isa.\nTanong: Ano ang panahon mamayang hapon?","vi":"Nữ: Bạn ra ngoài có mang ô không?\nNam: Bây giờ trời nắng, không cần mang đâu.\nNữ: Nhưng tin tức nói chiều nay sẽ mưa to.\nNam: Thôi được, vậy tôi mang một cái.\nCâu hỏi: Buổi chiều thời tiết thế nào?"},"exp":{"id":"Sekarang cerah, tapi sore akan hujan deras (下大雨).","en":"It's sunny now, but it will rain hard (下大雨) in the afternoon.","tl":"Maaraw ngayon, pero uulan nang malakas (下大雨) sa hapon.","vi":"Bây giờ nắng, nhưng chiều sẽ mưa to (下大雨)."}},{"dlg":[{"sp":"M","zh":"我們去夜市吃什麼？牛肉麵好嗎？","py":"Wǒ men qù yè shì chī shén me? Niú ròu miàn hǎo ma?"},{"sp":"F","zh":"我昨天吃過了。吃水餃怎麼樣？","py":"Wǒ zuó tiān chī guò le. Chī shuǐ jiǎo zěn me yàng?"},{"sp":"M","zh":"好啊，吃完再去買冰淇淋。","py":"Hǎo a, chī wán zài qù mǎi bīng qí lín."},{"sp":"F","zh":"太好了！","py":"Tài hǎo le!"}],"q":{"zh":"他們要先吃什麼？","py":"Tā men yào xiān chī shén me?"},"opts":[{"i":["noodles"],"bg":"night"},{"i":["dumplings"],"bg":"night"},{"i":["ice_cream"],"bg":"night"}],"a":1,"tr":{"id":"Pria: Kita makan apa di pasar malam? Mi daging sapi, mau?\nWanita: Aku sudah makan kemarin. Bagaimana kalau pangsit?\nPria: Boleh, habis makan kita beli es krim.\nWanita: Bagus sekali!\nPertanyaan: Mereka mau makan apa dulu?","en":"Man: What shall we eat at the night market? Beef noodles?\nWoman: I had that yesterday. How about dumplings?\nMan: Sure, and after that we'll buy ice cream.\nWoman: Great!\nQuestion: What will they eat first?","tl":"Lalaki: Ano ang kakainin natin sa night market? Beef noodles kaya?\nBabae: Kumain na ako niyan kahapon. Dumplings kaya?\nLalaki: Sige, pagkatapos bumili tayo ng ice cream.\nBabae: Ayos!\nTanong: Ano ang uunahin nilang kainin?","vi":"Nam: Mình đi chợ đêm ăn gì? Mì bò được không?\nNữ: Hôm qua tôi ăn rồi. Ăn sủi cảo thì sao?\nNam: Được, ăn xong rồi đi mua kem.\nNữ: Tuyệt quá!\nCâu hỏi: Họ sẽ ăn gì trước?"},"exp":{"id":"Mi sudah dimakan kemarin; mereka makan pangsit dulu, es krim sesudahnya.","en":"She had noodles yesterday; they eat dumplings first, ice cream afterwards.","tl":"Kumain na siya ng noodles kahapon; dumplings muna, ice cream pagkatapos.","vi":"Mì đã ăn hôm qua; họ ăn sủi cảo trước, kem sau."}},{"dlg":[{"sp":"F","zh":"請問，捷運站離這裡遠不遠？","py":"Qǐng wèn, jié yùn zhàn lí zhè lǐ yuǎn bù yuǎn?"},{"sp":"M","zh":"不遠，走路五分鐘就到了。","py":"Bù yuǎn, zǒu lù wǔ fēn zhōng jiù dào le."},{"sp":"F","zh":"要怎麼走？","py":"Yào zěn me zǒu?"},{"sp":"M","zh":"你過了銀行以後右轉，就看到了。","py":"Nǐ guò le yín háng yǐ hòu yòu zhuǎn, jiù kàn dào le."}],"q":{"zh":"過了銀行以後要往哪裡走？","py":"Guò le yín háng yǐ hòu yào wǎng nǎ lǐ zǒu?"},"opts":[{"i":["bank","left_arrow"],"bg":"street"},{"i":["bank","straight_arrow"],"bg":"street"},{"i":["bank","right_arrow"],"bg":"street"}],"a":2,"tr":{"id":"Wanita: Permisi, stasiun MRT jauh dari sini?\nPria: Tidak jauh, jalan kaki lima menit sampai.\nWanita: Lewat mana?\nPria: Setelah lewat bank, belok kanan, langsung kelihatan.\nPertanyaan: Setelah lewat bank harus ke arah mana?","en":"Woman: Excuse me, is the MRT station far from here?\nMan: Not far, five minutes on foot.\nWoman: How do I get there?\nMan: After you pass the bank, turn right and you'll see it.\nQuestion: Which way after passing the bank?","tl":"Babae: Paumanhin, malayo ba ang MRT station dito?\nLalaki: Hindi malayo, limang minutong lakad.\nBabae: Paano pumunta roon?\nLalaki: Paglampas mo sa bangko, kumanan ka at makikita mo na.\nTanong: Saan pupunta paglampas sa bangko?","vi":"Nữ: Xin hỏi, ga tàu điện ngầm có xa đây không?\nNam: Không xa, đi bộ năm phút là tới.\nNữ: Đi thế nào?\nNam: Đi qua ngân hàng rồi rẽ phải là thấy.\nCâu hỏi: Qua ngân hàng rồi đi hướng nào?"},"exp":{"id":"Setelah lewat bank, belok kanan (右轉).","en":"After the bank, turn right (右轉).","tl":"Paglampas sa bangko, kumanan (右轉).","vi":"Qua ngân hàng thì rẽ phải (右轉)."}},{"dlg":[{"sp":"M","zh":"喂，媽，我在超市，你要我買什麼？","py":"Wéi, mā, wǒ zài chāo shì, nǐ yào wǒ mǎi shén me?"},{"sp":"F","zh":"買一瓶牛奶和一些水果。","py":"Mǎi yì píng niú nǎi hé yì xiē shuǐ guǒ."},{"sp":"M","zh":"雞蛋要不要？","py":"Jī dàn yào bú yào?"},{"sp":"F","zh":"雞蛋家裡還有，不用買。","py":"Jī dàn jiā lǐ hái yǒu, bú yòng mǎi."}],"q":{"zh":"男的不用買什麼？","py":"Nán de bú yòng mǎi shén me?"},"opts":[{"i":["egg"],"bg":"shop"},{"i":["milk"],"bg":"shop"},{"i":["fruit"],"bg":"shop"}],"a":0,"tr":{"id":"Pria: Halo, Bu, aku di supermarket. Mau aku belikan apa?\nWanita: Beli sebotol susu dan sedikit buah.\nPria: Telurnya perlu tidak?\nWanita: Di rumah masih ada telur, tidak usah beli.\nPertanyaan: Apa yang tidak perlu dibeli pria itu?","en":"Man: Hi Mom, I'm at the supermarket. What do you want me to buy?\nWoman: Buy a bottle of milk and some fruit.\nMan: Do you need eggs?\nWoman: We still have eggs at home, no need.\nQuestion: What doesn't the man need to buy?","tl":"Lalaki: Hello, Ma, nasa supermarket ako. Ano ang ipabibili mo?\nBabae: Bumili ka ng isang bote ng gatas at ilang prutas.\nLalaki: Kailangan ba ng itlog?\nBabae: May itlog pa sa bahay, huwag nang bumili.\nTanong: Ano ang hindi na kailangang bilhin ng lalaki?","vi":"Nam: A lô, mẹ ơi, con đang ở siêu thị, mẹ muốn con mua gì?\nNữ: Mua một chai sữa và ít trái cây.\nNam: Có cần trứng không?\nNữ: Ở nhà vẫn còn trứng, không cần mua.\nCâu hỏi: Người đàn ông không cần mua gì?"},"exp":{"id":"Telur masih ada di rumah, jadi tidak perlu dibeli.","en":"There are still eggs at home, so he doesn't need to buy them.","tl":"May itlog pa sa bahay, kaya hindi na kailangang bilhin.","vi":"Ở nhà còn trứng nên không cần mua."}},{"dlg":[{"sp":"F","zh":"喂，我們的電影是七點的嗎？","py":"Wéi, wǒ men de diàn yǐng shì qī diǎn de ma?"},{"sp":"M","zh":"不是，七點的票賣完了，我買了九點的。","py":"Bú shì, qī diǎn de piào mài wán le, wǒ mǎi le jiǔ diǎn de."},{"sp":"F","zh":"那我們先去吃晚飯吧。","py":"Nà wǒ men xiān qù chī wǎn fàn ba."},{"sp":"M","zh":"好，八點在餐廳見。","py":"Hǎo, bā diǎn zài cān tīng jiàn."}],"q":{"zh":"電影幾點開始？","py":"Diàn yǐng jǐ diǎn kāi shǐ?"},"opts":[{"i":["movie","clock"],"b":"19:00"},{"i":["movie","clock"],"b":"21:00"},{"i":["movie","clock"],"b":"20:00"}],"a":1,"tr":{"id":"Wanita: Halo, film kita jam tujuh ya?\nPria: Bukan, tiket jam tujuh habis, aku beli yang jam sembilan.\nWanita: Kalau begitu kita makan malam dulu.\nPria: Oke, sampai jumpa jam delapan di restoran.\nPertanyaan: Filmnya mulai jam berapa?","en":"Woman: Hello, is our movie the seven o'clock one?\nMan: No, the seven o'clock tickets sold out, so I bought the nine o'clock.\nWoman: Then let's have dinner first.\nMan: OK, see you at the restaurant at eight.\nQuestion: What time does the movie start?","tl":"Babae: Hello, alas-siyete ba ang sine natin?\nLalaki: Hindi, ubos na ang tiket ng alas-siyete, alas-nuwebe ang binili ko.\nBabae: Kung gayon, kumain muna tayo ng hapunan.\nLalaki: Sige, kita tayo sa restawran nang alas-otso.\nTanong: Anong oras magsisimula ang sine?","vi":"Nữ: A lô, phim của mình là suất bảy giờ à?\nNam: Không, vé bảy giờ bán hết rồi, tôi mua suất chín giờ.\nNữ: Vậy mình đi ăn tối trước đi.\nNam: Được, tám giờ gặp ở nhà hàng.\nCâu hỏi: Phim mấy giờ bắt đầu?"},"exp":{"id":"Tiket jam tujuh habis, jadi filmnya jam sembilan; jam delapan untuk makan.","en":"Seven o'clock was sold out, so the movie is at nine; eight is dinner.","tl":"Ubos ang alas-siyete kaya alas-nuwebe ang sine; alas-otso ang hapunan.","vi":"Suất bảy giờ hết vé nên phim lúc chín giờ; tám giờ là ăn tối."}},{"dlg":[{"sp":"M","zh":"你今天怎麼沒騎機車來？","py":"Nǐ jīn tiān zěn me méi qí jī chē lái?"},{"sp":"F","zh":"早上下大雨，所以我坐公車來。","py":"Zǎo shàng xià dà yǔ, suǒ yǐ wǒ zuò gōng chē lái."},{"sp":"M","zh":"那下班我開車送你回家吧。","py":"Nà xià bān wǒ kāi chē sòng nǐ huí jiā ba."},{"sp":"F","zh":"太好了，謝謝你！","py":"Tài hǎo le, xiè xie nǐ!"}],"q":{"zh":"女的今天早上怎麼來的？","py":"Nǚ de jīn tiān zǎo shàng zěn me lái de?"},"opts":[{"i":["woman","bus"],"bg":"rain"},{"i":["woman","scooter"],"bg":"rain"},{"i":["woman","car"],"bg":"rain"}],"a":0,"tr":{"id":"Pria: Kenapa hari ini kamu tidak naik motor?\nWanita: Tadi pagi hujan deras, jadi aku naik bus.\nPria: Nanti pulang kerja aku antar kamu pakai mobil.\nWanita: Bagus, terima kasih!\nPertanyaan: Pagi ini perempuan itu datang naik apa?","en":"Man: Why didn't you come by scooter today?\nWoman: It rained hard this morning, so I came by bus.\nMan: Then after work I'll drive you home.\nWoman: Great, thank you!\nQuestion: How did the woman come this morning?","tl":"Lalaki: Bakit hindi ka nag-scooter ngayon?\nBabae: Malakas ang ulan kaninang umaga, kaya nag-bus ako.\nLalaki: Kung gayon, ihahatid kita pauwi sakay ng kotse pagkatapos ng trabaho.\nBabae: Ayos, salamat!\nTanong: Paano pumunta ang babae kaninang umaga?","vi":"Nam: Sao hôm nay bạn không đi xe máy đến?\nNữ: Sáng nay mưa to nên tôi đi xe buýt đến.\nNam: Vậy tan làm tôi lái xe đưa bạn về nhé.\nNữ: Tốt quá, cảm ơn bạn!\nCâu hỏi: Sáng nay người phụ nữ đến bằng gì?"},"exp":{"id":"Karena hujan, dia naik bus (坐公車); mobil itu untuk pulang nanti.","en":"Because of rain she took the bus (坐公車); the car is for going home later.","tl":"Dahil sa ulan, nag-bus (坐公車) siya; ang kotse ay para mamaya pauwi.","vi":"Vì mưa nên cô ấy đi xe buýt (坐公車); ô tô là để về nhà sau."}},{"dlg":[{"sp":"F","zh":"老闆，這種襪子一雙多少錢？","py":"Lǎo bǎn, zhè zhǒng wà zi yì shuāng duō shǎo qián?"},{"sp":"M","zh":"一雙五十塊，三雙一百塊。","py":"Yì shuāng wǔ shí kuài, sān shuāng yì bǎi kuài."},{"sp":"F","zh":"那我買三雙。","py":"Nà wǒ mǎi sān shuāng."},{"sp":"M","zh":"好，一共一百塊。","py":"Hǎo, yí gòng yì bǎi kuài."}],"q":{"zh":"女的要付多少錢？","py":"Nǚ de yào fù duō shǎo qián?"},"opts":[{"i":["socks"],"b":"NT$50"},{"i":["socks"],"b":"NT$150"},{"i":["socks"],"b":"NT$100"}],"a":2,"tr":{"id":"Wanita: Pak, kaus kaki seperti ini sepasang berapa?\nPria: Sepasang 50 dolar, tiga pasang 100 dolar.\nWanita: Kalau begitu aku beli tiga pasang.\nPria: Baik, totalnya 100 dolar.\nPertanyaan: Perempuan itu harus membayar berapa?","en":"Woman: Boss, how much is a pair of these socks?\nMan: 50 for one pair, 100 for three pairs.\nWoman: Then I'll buy three pairs.\nMan: OK, 100 in total.\nQuestion: How much does the woman have to pay?","tl":"Babae: Boss, magkano ang isang pares ng medyas na ito?\nLalaki: Isang pares 50, tatlong pares 100.\nBabae: Kung gayon, tatlong pares ang bibilhin ko.\nLalaki: Sige, 100 lahat.\nTanong: Magkano ang babayaran ng babae?","vi":"Nữ: Ông chủ ơi, loại tất này một đôi bao nhiêu?\nNam: Một đôi 50 đồng, ba đôi 100 đồng.\nNữ: Vậy tôi mua ba đôi.\nNam: Được, tổng cộng 100 đồng.\nCâu hỏi: Người phụ nữ phải trả bao nhiêu tiền?"},"exp":{"id":"Tiga pasang harganya 100 dolar (一共一百塊).","en":"Three pairs cost 100 in total (一共一百塊).","tl":"Ang tatlong pares ay 100 lahat (一共一百塊).","vi":"Ba đôi tổng cộng 100 đồng (一共一百塊)."}},{"dlg":[{"sp":"M","zh":"放假的時候你要去日月潭嗎？","py":"Fàng jià de shí hòu nǐ yào qù Rì yuè tán ma?"},{"sp":"F","zh":"本來想去，可是太遠了。","py":"Běn lái xiǎng qù, kě shì tài yuǎn le."},{"sp":"M","zh":"那你要去哪裡？","py":"Nà nǐ yào qù nǎ lǐ?"},{"sp":"F","zh":"我要去陽明山看花。","py":"Wǒ yào qù Yáng míng shān kàn huā."}],"q":{"zh":"女的放假要去做什麼？","py":"Nǚ de fàng jià yào qù zuò shén me?"},"opts":[{"i":["beach"],"bg":"sea"},{"i":["temple"]},{"i":["mountain","flower"]}],"a":2,"tr":{"id":"Pria: Waktu libur kamu mau ke Danau Matahari Bulan?\nWanita: Tadinya mau, tapi terlalu jauh.\nPria: Lalu kamu mau ke mana?\nWanita: Aku mau ke Gunung Yangming melihat bunga.\nPertanyaan: Waktu libur perempuan itu mau melakukan apa?","en":"Man: Are you going to Sun Moon Lake during the holiday?\nWoman: I wanted to at first, but it's too far.\nMan: So where are you going?\nWoman: I'm going to Yangmingshan to see the flowers.\nQuestion: What will the woman do during the holiday?","tl":"Lalaki: Pupunta ka ba sa Sun Moon Lake sa bakasyon?\nBabae: Gusto ko sana, pero masyadong malayo.\nLalaki: E saan ka pupunta?\nBabae: Pupunta ako sa Yangmingshan para tumingin ng bulaklak.\nTanong: Ano ang gagawin ng babae sa bakasyon?","vi":"Nam: Kỳ nghỉ bạn có đi Nhật Nguyệt Đàm không?\nNữ: Lúc đầu định đi, nhưng xa quá.\nNam: Vậy bạn sẽ đi đâu?\nNữ: Tôi sẽ lên núi Dương Minh ngắm hoa.\nCâu hỏi: Kỳ nghỉ người phụ nữ sẽ đi làm gì?"},"exp":{"id":"Danau terlalu jauh; dia pergi ke gunung (陽明山) melihat bunga.","en":"The lake is too far; she'll go to the mountain (陽明山) to see flowers.","tl":"Malayo ang lawa; pupunta siya sa bundok (陽明山) para tumingin ng bulaklak.","vi":"Hồ xa quá; cô ấy lên núi (陽明山) ngắm hoa."}},{"dlg":[{"sp":"F","zh":"喂，請問王先生在嗎？","py":"Wéi, qǐng wèn Wáng xiān shēng zài ma?"},{"sp":"M","zh":"他不在，他去銀行了。","py":"Tā bú zài, tā qù yín háng le."},{"sp":"F","zh":"他什麼時候回來？","py":"Tā shén me shí hòu huí lái?"},{"sp":"M","zh":"大概三點。我請他回電話給你，好嗎？","py":"Dà gài sān diǎn. Wǒ qǐng tā huí diàn huà gěi nǐ, hǎo ma?"},{"sp":"F","zh":"好，謝謝。","py":"Hǎo, xiè xie."}],"q":{"zh":"王先生現在在哪裡？","py":"Wáng xiān shēng xiàn zài zài nǎ lǐ?"},"opts":[{"i":["bank"]},{"i":["post_office"]},{"i":["hospital"]}],"a":0,"tr":{"id":"Wanita: Halo, apakah Pak Wang ada?\nPria: Dia tidak ada, dia pergi ke bank.\nWanita: Kapan dia kembali?\nPria: Kira-kira jam tiga. Nanti saya minta dia menelepon balik, ya?\nWanita: Baik, terima kasih.\nPertanyaan: Pak Wang sekarang di mana?","en":"Woman: Hello, is Mr. Wang there?\nMan: He's not in; he went to the bank.\nWoman: When will he be back?\nMan: Around three. I'll ask him to call you back, OK?\nWoman: OK, thanks.\nQuestion: Where is Mr. Wang now?","tl":"Babae: Hello, nandiyan ba si G. Wang?\nLalaki: Wala siya, pumunta siya sa bangko.\nBabae: Kailan siya babalik?\nLalaki: Mga alas-tres. Sasabihan ko siyang tawagan ka, ha?\nBabae: Sige, salamat.\nTanong: Nasaan si G. Wang ngayon?","vi":"Nữ: A lô, xin hỏi anh Vương có ở đó không?\nNam: Anh ấy không có ở đây, anh ấy đi ngân hàng rồi.\nNữ: Khi nào anh ấy về?\nNam: Khoảng ba giờ. Tôi sẽ bảo anh ấy gọi lại cho chị nhé?\nNữ: Vâng, cảm ơn.\nCâu hỏi: Anh Vương bây giờ đang ở đâu?"},"exp":{"id":"Pak Wang pergi ke bank (去銀行了).","en":"Mr. Wang has gone to the bank (去銀行了).","tl":"Pumunta si G. Wang sa bangko (去銀行了).","vi":"Anh Vương đã đi ngân hàng (去銀行了)."}},{"dlg":[{"sp":"M","zh":"請問，男生的衣服在幾樓？","py":"Qǐng wèn, nán shēng de yī fú zài jǐ lóu?"},{"sp":"F","zh":"男裝在五樓，女裝在四樓。","py":"Nán zhuāng zài wǔ lóu, nǚ zhuāng zài sì lóu."},{"sp":"M","zh":"鞋子呢？","py":"Xié zi ne?"},{"sp":"F","zh":"鞋子在三樓。","py":"Xié zi zài sān lóu."},{"sp":"M","zh":"好，我先去買鞋子。","py":"Hǎo, wǒ xiān qù mǎi xié zi."}],"q":{"zh":"男的先去幾樓？","py":"Nán de xiān qù jǐ lóu?"},"opts":[{"i":["shirt"],"b":"5F"},{"i":["shoes"],"b":"3F"},{"i":["dress"],"b":"4F"}],"a":1,"tr":{"id":"Pria: Permisi, pakaian pria di lantai berapa?\nWanita: Pakaian pria di lantai lima, wanita di lantai empat.\nPria: Kalau sepatu?\nWanita: Sepatu di lantai tiga.\nPria: Oke, aku beli sepatu dulu.\nPertanyaan: Pria itu pergi ke lantai berapa dulu?","en":"Man: Excuse me, which floor is men's clothing on?\nWoman: Menswear is on 5F, womenswear on 4F.\nMan: And shoes?\nWoman: Shoes are on 3F.\nMan: OK, I'll go buy shoes first.\nQuestion: Which floor does the man go to first?","tl":"Lalaki: Paumanhin, anong palapag ang damit panlalaki?\nBabae: Panlalaki sa 5F, pambabae sa 4F.\nLalaki: E ang sapatos?\nBabae: Nasa 3F ang sapatos.\nLalaki: Sige, sapatos muna ang bibilhin ko.\nTanong: Anong palapag muna pupunta ang lalaki?","vi":"Nam: Xin hỏi, quần áo nam ở tầng mấy?\nNữ: Đồ nam ở tầng năm, đồ nữ ở tầng bốn.\nNam: Còn giày?\nNữ: Giày ở tầng ba.\nNam: Được, tôi đi mua giày trước.\nCâu hỏi: Người đàn ông đi tầng mấy trước?"},"exp":{"id":"Dia membeli sepatu dulu, dan sepatu ada di lantai tiga.","en":"He buys shoes first, and shoes are on 3F.","tl":"Sapatos muna ang bibilhin niya, at nasa 3F ito.","vi":"Anh ấy mua giày trước, giày ở tầng ba."}},{"dlg":[{"sp":"F","zh":"我們騎腳踏車去河邊好不好？","py":"Wǒ men qí jiǎo tà chē qù hé biān hǎo bù hǎo?"},{"sp":"M","zh":"好啊，可是我的腳踏車壞了。","py":"Hǎo a, kě shì wǒ de jiǎo tà chē huài le."},{"sp":"F","zh":"沒關係，可以在捷運站旁邊租。","py":"Méi guān xi, kě yǐ zài jié yùn zhàn páng biān zū."},{"sp":"M","zh":"好，那我們先坐捷運去那裡，再騎車。","py":"Hǎo, nà wǒ men xiān zuò jié yùn qù nà lǐ, zài qí chē."}],"q":{"zh":"他們先坐什麼？","py":"Tā men xiān zuò shén me?"},"opts":[{"i":["bicycle"],"bg":"park"},{"i":["bus"],"bg":"street"},{"i":["mrt"]}],"a":2,"tr":{"id":"Wanita: Kita bersepeda ke tepi sungai, yuk?\nPria: Boleh, tapi sepedaku rusak.\nWanita: Tidak apa-apa, bisa sewa di samping stasiun MRT.\nPria: Oke, kita naik MRT ke sana dulu, baru bersepeda.\nPertanyaan: Mereka naik apa dulu?","en":"Woman: Shall we cycle to the riverside?\nMan: Sure, but my bike is broken.\nWoman: No problem, you can rent one next to the MRT station.\nMan: OK, so we'll take the MRT there first, then ride.\nQuestion: What will they take first?","tl":"Babae: Magbisikleta tayo papunta sa ilog, gusto mo?\nLalaki: Sige, pero sira ang bisikleta ko.\nBabae: Okay lang, puwedeng umupa sa tabi ng MRT station.\nLalaki: Sige, mag-MRT muna tayo papunta roon, saka magbisikleta.\nTanong: Ano ang sasakyan nila muna?","vi":"Nữ: Mình đạp xe ra bờ sông được không?\nNam: Được, nhưng xe đạp của tôi hỏng rồi.\nNữ: Không sao, có thể thuê ở cạnh ga tàu điện ngầm.\nNam: Được, vậy mình đi tàu điện ngầm đến đó trước rồi đạp xe.\nCâu hỏi: Họ đi bằng gì trước?"},"exp":{"id":"Mereka naik MRT dulu (先坐捷運), baru bersepeda.","en":"They take the MRT first (先坐捷運), then ride bikes.","tl":"MRT muna (先坐捷運), saka bisikleta.","vi":"Họ đi tàu điện ngầm trước (先坐捷運), rồi mới đạp xe."}}]},{"p":4,"items":[{"dlg":[{"sp":"M","zh":"這杯珍珠奶茶多少錢？","py":"Zhè bēi zhēn zhū nǎi chá duō shǎo qián?"},{"sp":"F","zh":"大杯六十，小杯四十五。","py":"Dà bēi liù shí, xiǎo bēi sì shí wǔ."},{"sp":"M","zh":"我要兩杯小杯的。","py":"Wǒ yào liǎng bēi xiǎo bēi de."},{"sp":"F","zh":"好，一共九十塊。","py":"Hǎo, yí gòng jiǔ shí kuài."}],"q":{"zh":"男的要付多少錢？","py":"Nán de yào fù duō shǎo qián?"},"opts":[{"zh":"六十塊","py":"Liù shí kuài"},{"zh":"一百二十塊","py":"Yì bǎi èr shí kuài"},{"zh":"九十塊","py":"Jiǔ shí kuài"},{"zh":"四十五塊","py":"Sì shí wǔ kuài"}],"a":2,"tr":{"id":"Pria: Bubble tea ini berapa?\nWanita: Gelas besar 60, gelas kecil 45.\nPria: Saya mau dua gelas kecil.\nWanita: Baik, totalnya 90 dolar.\nPertanyaan: Pria itu harus membayar berapa?","en":"Man: How much is this bubble tea?\nWoman: Large is 60, small is 45.\nMan: I'll have two small ones.\nWoman: OK, 90 in total.\nQuestion: How much does the man have to pay?","tl":"Lalaki: Magkano ang bubble tea na ito?\nBabae: Malaki 60, maliit 45.\nLalaki: Dalawang maliit ang sa akin.\nBabae: Sige, 90 lahat.\nTanong: Magkano ang babayaran ng lalaki?","vi":"Nam: Ly trà sữa trân châu này bao nhiêu tiền?\nNữ: Ly lớn 60, ly nhỏ 45.\nNam: Tôi lấy hai ly nhỏ.\nNữ: Được, tổng cộng 90 đồng.\nCâu hỏi: Người đàn ông phải trả bao nhiêu?"},"exp":{"id":"Dua gelas kecil: 45 × 2 = 90 (一共九十塊).","en":"Two small cups: 45 × 2 = 90 (一共九十塊).","tl":"Dalawang maliit: 45 × 2 = 90 (一共九十塊).","vi":"Hai ly nhỏ: 45 × 2 = 90 (一共九十塊)."}},{"dlg":[{"sp":"F","zh":"你怎麼這麼晚才到？","py":"Nǐ zěn me zhè me wǎn cái dào?"},{"sp":"M","zh":"對不起，我坐錯公車了。","py":"Duì bù qǐ, wǒ zuò cuò gōng chē le."},{"sp":"F","zh":"你應該坐捷運，比較快。","py":"Nǐ yīng gāi zuò jié yùn, bǐ jiào kuài."},{"sp":"M","zh":"下次我會坐捷運。","py":"Xià cì wǒ huì zuò jié yùn."}],"q":{"zh":"男的為什麼晚到？","py":"Nán de wèi shén me wǎn dào?"},"opts":[{"zh":"他坐錯公車了","py":"Tā zuò cuò gōng chē le"},{"zh":"捷運壞了","py":"Jié yùn huài le"},{"zh":"他起床太晚了","py":"Tā qǐ chuáng tài wǎn le"},{"zh":"路上車太多","py":"Lù shàng chē tài duō"}],"a":0,"tr":{"id":"Wanita: Kenapa kamu baru datang selarut ini?\nPria: Maaf, aku salah naik bus.\nWanita: Kamu seharusnya naik MRT, lebih cepat.\nPria: Lain kali aku akan naik MRT.\nPertanyaan: Kenapa pria itu terlambat?","en":"Woman: Why are you so late?\nMan: Sorry, I took the wrong bus.\nWoman: You should take the MRT; it's faster.\nMan: Next time I'll take the MRT.\nQuestion: Why was the man late?","tl":"Babae: Bakit ngayon ka lang dumating?\nLalaki: Pasensya na, nagkamali ako ng bus.\nBabae: Dapat nag-MRT ka, mas mabilis.\nLalaki: Sa susunod, mag-MRT na ako.\nTanong: Bakit nahuli ang lalaki?","vi":"Nữ: Sao bạn đến muộn thế?\nNam: Xin lỗi, tôi đi nhầm xe buýt.\nNữ: Bạn nên đi tàu điện ngầm, nhanh hơn.\nNam: Lần sau tôi sẽ đi tàu điện ngầm.\nCâu hỏi: Tại sao người đàn ông đến muộn?"},"exp":{"id":"Dia bilang 坐錯公車了: salah naik bus.","en":"He says 坐錯公車了: he took the wrong bus.","tl":"Sabi niya 坐錯公車了: nagkamali siya ng bus.","vi":"Anh ấy nói 坐錯公車了: đi nhầm xe buýt."}},{"dlg":[{"sp":"F","zh":"先生，這件襯衫我昨天買的，可以換嗎？","py":"Xiān shēng, zhè jiàn chèn shān wǒ zuó tiān mǎi de, kě yǐ huàn ma?"},{"sp":"M","zh":"可以，有什麼問題嗎？","py":"Kě yǐ, yǒu shén me wèn tí ma?"},{"sp":"F","zh":"太大了，我要小一號的。","py":"Tài dà le, wǒ yào xiǎo yí hào de."},{"sp":"M","zh":"好，請等一下。","py":"Hǎo, qǐng děng yí xià."}],"q":{"zh":"女的為什麼要換襯衫？","py":"Nǚ de wèi shén me yào huàn chèn shān?"},"opts":[{"zh":"襯衫太小","py":"Chèn shān tài xiǎo"},{"zh":"顏色不好看","py":"Yán sè bù hǎo kàn"},{"zh":"襯衫太貴","py":"Chèn shān tài guì"},{"zh":"襯衫太大","py":"Chèn shān tài dà"}],"a":3,"tr":{"id":"Wanita: Pak, kemeja ini saya beli kemarin, bisa ditukar?\nPria: Bisa, ada masalah apa?\nWanita: Terlalu besar, saya mau satu ukuran lebih kecil.\nPria: Baik, tunggu sebentar.\nPertanyaan: Kenapa perempuan itu mau menukar kemeja?","en":"Woman: Sir, I bought this shirt yesterday. Can I exchange it?\nMan: Sure. Is there a problem?\nWoman: It's too big. I want one size smaller.\nMan: OK, one moment please.\nQuestion: Why does the woman want to exchange the shirt?","tl":"Babae: Sir, binili ko ang polong ito kahapon. Puwede bang palitan?\nLalaki: Puwede. May problema ba?\nBabae: Masyadong malaki, gusto ko ng isang size na mas maliit.\nLalaki: Sige, sandali lang.\nTanong: Bakit gustong papalitan ng babae ang polo?","vi":"Nữ: Anh ơi, cái áo sơ mi này hôm qua tôi mua, đổi được không?\nNam: Được, có vấn đề gì không?\nNữ: Rộng quá, tôi muốn cỡ nhỏ hơn một số.\nNam: Vâng, xin chờ một chút.\nCâu hỏi: Tại sao người phụ nữ muốn đổi áo sơ mi?"},"exp":{"id":"Dia bilang 太大了 (terlalu besar) dan mau ukuran lebih kecil.","en":"She says 太大了 (too big) and wants a smaller size.","tl":"Sabi niya 太大了 (masyadong malaki), gusto niya ng mas maliit.","vi":"Cô ấy nói 太大了 (rộng quá) và muốn cỡ nhỏ hơn."}},{"dlg":[{"sp":"M","zh":"請問，下一班到高雄的車幾點？","py":"Qǐng wèn, xià yì bān dào Gāo xióng de chē jǐ diǎn?"},{"sp":"F","zh":"兩點十分，還有十五分鐘。","py":"Liǎng diǎn shí fēn, hái yǒu shí wǔ fēn zhōng."},{"sp":"M","zh":"我要一張票，要靠窗的。","py":"Wǒ yào yì zhāng piào, yào kào chuāng de."},{"sp":"F","zh":"好，一共八百四十塊。","py":"Hǎo, yí gòng bā bǎi sì shí kuài."}],"q":{"zh":"他們可能在哪裡？","py":"Tā men kě néng zài nǎ lǐ?"},"opts":[{"zh":"機場","py":"Jī chǎng"},{"zh":"火車站","py":"Huǒ chē zhàn"},{"zh":"銀行","py":"Yín háng"},{"zh":"電影院","py":"Diàn yǐng yuàn"}],"a":1,"tr":{"id":"Pria: Permisi, kereta berikutnya ke Kaohsiung jam berapa?\nWanita: Jam 2.10, masih lima belas menit lagi.\nPria: Saya mau satu tiket, kursi di samping jendela.\nWanita: Baik, totalnya 840 dolar.\nPertanyaan: Mereka mungkin ada di mana?","en":"Man: Excuse me, what time is the next train to Kaohsiung?\nWoman: At 2:10, in fifteen minutes.\nMan: One ticket please, a window seat.\nWoman: OK, that's 840 in total.\nQuestion: Where are they probably?","tl":"Lalaki: Paumanhin, anong oras ang susunod na biyahe papuntang Kaohsiung?\nBabae: Alas-2:10, labinlimang minuto pa.\nLalaki: Isang tiket po, sa tabi ng bintana.\nBabae: Sige, 840 lahat.\nTanong: Saan sila malamang naroroon?","vi":"Nam: Xin hỏi, chuyến tiếp theo đi Cao Hùng mấy giờ?\nNữ: Hai giờ mười, còn mười lăm phút nữa.\nNam: Cho tôi một vé, ghế cạnh cửa sổ.\nNữ: Vâng, tổng cộng 840 đồng.\nCâu hỏi: Họ có thể đang ở đâu?"},"exp":{"id":"Membeli tiket ke Kaohsiung, jadwal \"kereta berikutnya\": di stasiun kereta.","en":"Buying a ticket for the next train to Kaohsiung: a train station.","tl":"Bumibili ng tiket sa susunod na biyahe papuntang Kaohsiung: istasyon ng tren.","vi":"Mua vé chuyến tiếp theo đi Cao Hùng: ở ga tàu hỏa."}},{"dlg":[{"sp":"F","zh":"喂，小林，我是安娜。你今天晚上有空嗎？","py":"Wéi, Xiǎo Lín, wǒ shì Ān nà. Nǐ jīn tiān wǎn shàng yǒu kòng ma?"},{"sp":"M","zh":"今天要加班，明天晚上可以。","py":"Jīn tiān yào jiā bān, míng tiān wǎn shàng kě yǐ."},{"sp":"F","zh":"好，那我們明天去饒河夜市吧。","py":"Hǎo, nà wǒ men míng tiān qù Ráo hé yè shì ba."},{"sp":"M","zh":"沒問題，七點在捷運站等你。","py":"Méi wèn tí, qī diǎn zài jié yùn zhàn děng nǐ."}],"q":{"zh":"小林今天晚上要做什麼？","py":"Xiǎo Lín jīn tiān wǎn shàng yào zuò shén me?"},"opts":[{"zh":"去夜市","py":"Qù yè shì"},{"zh":"加班","py":"Jiā bān"},{"zh":"去捷運站","py":"Qù jié yùn zhàn"},{"zh":"跟安娜吃飯","py":"Gēn Ān nà chī fàn"}],"a":1,"tr":{"id":"Wanita: Halo, Xiaolin, ini Anna. Malam ini kamu ada waktu?\nPria: Hari ini harus lembur, besok malam bisa.\nWanita: Oke, besok kita ke Pasar Malam Raohe.\nPria: Tidak masalah, jam tujuh aku tunggu di stasiun MRT.\nPertanyaan: Malam ini Xiaolin mau apa?","en":"Woman: Hi Xiaolin, it's Anna. Are you free tonight?\nMan: I have to work overtime today; tomorrow night is fine.\nWoman: OK, then let's go to Raohe Night Market tomorrow.\nMan: No problem, I'll wait for you at the MRT station at seven.\nQuestion: What will Xiaolin do tonight?","tl":"Babae: Hello, Xiaolin, si Anna ito. Libre ka ba mamayang gabi?\nLalaki: Mag-o-overtime ako ngayon, bukas ng gabi puwede.\nBabae: Sige, pumunta tayo sa Raohe Night Market bukas.\nLalaki: Walang problema, hihintayin kita sa MRT station nang alas-siyete.\nTanong: Ano ang gagawin ni Xiaolin mamayang gabi?","vi":"Nữ: A lô, Tiểu Lâm, mình là Anna. Tối nay bạn rảnh không?\nNam: Hôm nay phải tăng ca, tối mai thì được.\nNữ: Được, vậy mai mình đi chợ đêm Nhiêu Hà nhé.\nNam: Không vấn đề, bảy giờ tôi đợi bạn ở ga tàu điện ngầm.\nCâu hỏi: Tối nay Tiểu Lâm sẽ làm gì?"},"exp":{"id":"Malam ini dia lembur (加班); pasar malam itu besok.","en":"Tonight he works overtime (加班); the night market is tomorrow.","tl":"Mag-o-overtime (加班) siya ngayong gabi; bukas ang night market.","vi":"Tối nay anh ấy tăng ca (加班); chợ đêm là ngày mai."}},{"dlg":[{"sp":"M","zh":"老闆，這頂帽子可以便宜一點嗎？","py":"Lǎo bǎn, zhè dǐng mào zi kě yǐ pián yí yì diǎn ma?"},{"sp":"F","zh":"三百塊已經很便宜了。","py":"Sān bǎi kuài yǐ jīng hěn pián yí le."},{"sp":"M","zh":"我買兩頂，五百塊好不好？","py":"Wǒ mǎi liǎng dǐng, wǔ bǎi kuài hǎo bù hǎo?"},{"sp":"F","zh":"好吧，五百就五百。","py":"Hǎo ba, wǔ bǎi jiù wǔ bǎi."}],"q":{"zh":"兩頂帽子一共多少錢？","py":"Liǎng dǐng mào zi yí gòng duō shǎo qián?"},"opts":[{"zh":"三百塊","py":"Sān bǎi kuài"},{"zh":"六百塊","py":"Liù bǎi kuài"},{"zh":"兩百五十塊","py":"Liǎng bǎi wǔ shí kuài"},{"zh":"五百塊","py":"Wǔ bǎi kuài"}],"a":3,"tr":{"id":"Pria: Bu, topi ini bisa lebih murah?\nWanita: 300 dolar sudah sangat murah.\nPria: Saya beli dua, 500 dolar boleh?\nWanita: Baiklah, 500 ya 500.\nPertanyaan: Dua topi totalnya berapa?","en":"Man: Boss, can this hat be a bit cheaper?\nWoman: 300 is already very cheap.\nMan: If I buy two, how about 500?\nWoman: All right, 500 it is.\nQuestion: How much are the two hats in total?","tl":"Lalaki: Boss, puwede bang bawasan ang presyo ng sumbrerong ito?\nBabae: Mura na ang 300.\nLalaki: Kung dalawa ang bibilhin ko, 500 na lang?\nBabae: Sige na nga, 500.\nTanong: Magkano lahat ang dalawang sumbrero?","vi":"Nam: Bà chủ ơi, cái mũ này rẻ hơn chút được không?\nNữ: 300 đồng là rẻ lắm rồi.\nNam: Tôi mua hai cái, 500 đồng được không?\nNữ: Thôi được, 500 thì 500.\nCâu hỏi: Hai cái mũ tổng cộng bao nhiêu tiền?"},"exp":{"id":"Penjual setuju: dua topi 500 dolar (五百就五百).","en":"The seller agrees: two hats for 500 (五百就五百).","tl":"Pumayag ang tindera: dalawang sumbrero sa 500 (五百就五百).","vi":"Người bán đồng ý: hai mũ 500 đồng (五百就五百)."}},{"dlg":[{"sp":"F","zh":"你去台東玩了幾天？","py":"Nǐ qù Tái dōng wán le jǐ tiān?"},{"sp":"M","zh":"本來要去五天，可是颱風來了，所以只玩了三天。","py":"Běn lái yào qù wǔ tiān, kě shì tái fēng lái le, suǒ yǐ zhǐ wán le sān tiān."},{"sp":"F","zh":"真可惜！你是坐火車去的嗎？","py":"Zhēn kě xí! Nǐ shì zuò huǒ chē qù de ma?"},{"sp":"M","zh":"不是，我坐飛機去的。","py":"Bú shì, wǒ zuò fēi jī qù de."}],"q":{"zh":"男的在台東玩了幾天？","py":"Nán de zài Tái dōng wán le jǐ tiān?"},"opts":[{"zh":"三天","py":"Sān tiān"},{"zh":"五天","py":"Wǔ tiān"},{"zh":"兩天","py":"Liǎng tiān"},{"zh":"四天","py":"Sì tiān"}],"a":0,"tr":{"id":"Wanita: Kamu jalan-jalan di Taitung berapa hari?\nPria: Tadinya lima hari, tapi ada topan, jadi hanya tiga hari.\nWanita: Sayang sekali! Kamu ke sana naik kereta?\nPria: Bukan, aku naik pesawat.\nPertanyaan: Pria itu berlibur di Taitung berapa hari?","en":"Woman: How many days were you in Taitung?\nMan: I planned five days, but a typhoon came, so only three.\nWoman: What a pity! Did you go by train?\nMan: No, I flew.\nQuestion: How many days did the man spend in Taitung?","tl":"Babae: Ilang araw kang namasyal sa Taitung?\nLalaki: Limang araw sana, pero dumating ang bagyo, kaya tatlong araw lang.\nBabae: Sayang! Nag-tren ka ba papunta roon?\nLalaki: Hindi, nag-eroplano ako.\nTanong: Ilang araw namasyal ang lalaki sa Taitung?","vi":"Nữ: Bạn đi chơi Đài Đông mấy ngày?\nNam: Lúc đầu định đi năm ngày, nhưng có bão nên chỉ chơi ba ngày.\nNữ: Tiếc thật! Bạn đi bằng tàu hỏa à?\nNam: Không, tôi đi máy bay.\nCâu hỏi: Người đàn ông chơi ở Đài Đông mấy ngày?"},"exp":{"id":"Rencananya lima hari, tapi karena topan hanya tiga hari (只玩了三天).","en":"He planned five, but because of the typhoon stayed only three (只玩了三天).","tl":"Lima sana, pero dahil sa bagyo tatlo lang (只玩了三天).","vi":"Định năm ngày, nhưng vì bão chỉ chơi ba ngày (只玩了三天)."}},{"dlg":[{"sp":"M","zh":"小姐，你要去哪裡？","py":"Xiǎo jiě, nǐ yào qù nǎ lǐ?"},{"sp":"F","zh":"我要去台大醫院。","py":"Wǒ yào qù Tái dà yī yuàn."},{"sp":"M","zh":"你不舒服嗎？","py":"Nǐ bù shū fú ma?"},{"sp":"F","zh":"不是，我去看我的朋友，她生病了。","py":"Bú shì, wǒ qù kàn wǒ de péng yǒu, tā shēng bìng le."}],"q":{"zh":"女的去醫院做什麼？","py":"Nǚ de qù yī yuàn zuò shén me?"},"opts":[{"zh":"去看醫生","py":"Qù kàn yī shēng"},{"zh":"去工作","py":"Qù gōng zuò"},{"zh":"去看朋友","py":"Qù kàn péng yǒu"},{"zh":"去拿藥","py":"Qù ná yào"}],"a":2,"tr":{"id":"Pria: Nona, mau ke mana?\nWanita: Saya mau ke Rumah Sakit NTU.\nPria: Anda sedang tidak enak badan?\nWanita: Bukan, saya mau menjenguk teman, dia sakit.\nPertanyaan: Perempuan itu ke rumah sakit untuk apa?","en":"Man: Miss, where are you going?\nWoman: To National Taiwan University Hospital.\nMan: Are you not feeling well?\nWoman: No, I'm visiting my friend; she's sick.\nQuestion: Why is the woman going to the hospital?","tl":"Lalaki: Miss, saan po kayo pupunta?\nBabae: Sa NTU Hospital po.\nLalaki: Masama ba ang pakiramdam mo?\nBabae: Hindi, dadalawin ko ang kaibigan ko, may sakit siya.\nTanong: Ano ang gagawin ng babae sa ospital?","vi":"Nam: Cô ơi, cô muốn đi đâu?\nNữ: Tôi muốn đến Bệnh viện Đài Đại.\nNam: Cô không khỏe à?\nNữ: Không, tôi đi thăm bạn, cô ấy bị ốm.\nCâu hỏi: Người phụ nữ đến bệnh viện làm gì?"},"exp":{"id":"Dia tidak sakit; dia menjenguk temannya yang sakit.","en":"She isn't sick; she's visiting her sick friend.","tl":"Hindi siya may sakit; dadalawin niya ang kaibigang may sakit.","vi":"Cô ấy không ốm; cô ấy đi thăm người bạn bị ốm."}},{"dlg":[{"sp":"F","zh":"你要去哪裡？","py":"Nǐ yào qù nǎ lǐ?"},{"sp":"M","zh":"我要去便利商店買早餐，你要不要什麼？","py":"Wǒ yào qù biàn lì shāng diàn mǎi zǎo cān, nǐ yào bú yào shén me?"},{"sp":"F","zh":"幫我買一杯咖啡，不要加糖。","py":"Bāng wǒ mǎi yì bēi kā fēi, bú yào jiā táng."},{"sp":"M","zh":"好，熱的還是冰的？","py":"Hǎo, rè de hái shì bīng de?"},{"sp":"F","zh":"冰的，謝謝。","py":"Bīng de, xiè xie."}],"q":{"zh":"女的要什麼？","py":"Nǚ de yào shén me?"},"opts":[{"zh":"熱咖啡，不加糖","py":"Rè kā fēi, bù jiā táng"},{"zh":"冰咖啡，加糖","py":"Bīng kā fēi, jiā táng"},{"zh":"熱奶茶，不加糖","py":"Rè nǎi chá, bù jiā táng"},{"zh":"冰咖啡，不加糖","py":"Bīng kā fēi, bù jiā táng"}],"a":3,"tr":{"id":"Wanita: Kamu mau ke mana?\nPria: Aku mau beli sarapan di minimarket. Kamu mau sesuatu?\nWanita: Tolong belikan kopi segelas, tanpa gula.\nPria: Oke, panas atau dingin?\nWanita: Dingin, terima kasih.\nPertanyaan: Perempuan itu mau apa?","en":"Woman: Where are you going?\nMan: I'm going to the convenience store for breakfast. Want anything?\nWoman: Get me a coffee, no sugar.\nMan: OK, hot or iced?\nWoman: Iced, thanks.\nQuestion: What does the woman want?","tl":"Babae: Saan ka pupunta?\nLalaki: Bibili ako ng almusal sa convenience store. May gusto ka ba?\nBabae: Ibili mo ako ng kape, walang asukal.\nLalaki: Sige, mainit o malamig?\nBabae: Malamig, salamat.\nTanong: Ano ang gusto ng babae?","vi":"Nữ: Bạn đi đâu đấy?\nNam: Tôi đi cửa hàng tiện lợi mua bữa sáng, bạn có cần gì không?\nNữ: Mua giúp tôi một ly cà phê, không đường.\nNam: Được, nóng hay đá?\nNữ: Đá, cảm ơn.\nCâu hỏi: Người phụ nữ muốn gì?"},"exp":{"id":"Dia mau kopi dingin (冰的) tanpa gula (不要加糖).","en":"She wants iced (冰的) coffee with no sugar (不要加糖).","tl":"Gusto niya ng malamig (冰的) na kape na walang asukal (不要加糖).","vi":"Cô ấy muốn cà phê đá (冰的) không đường (不要加糖)."}},{"dlg":[{"sp":"M","zh":"糟糕，我的手機不見了！","py":"Zāo gāo, wǒ de shǒu jī bú jiàn le!"},{"sp":"F","zh":"你最後一次用是在哪裡？","py":"Nǐ zuì hòu yí cì yòng shì zài nǎ lǐ?"},{"sp":"M","zh":"在捷運上，我打了電話給我哥哥。","py":"Zài jié yùn shàng, wǒ dǎ le diàn huà gěi wǒ gē ge."},{"sp":"F","zh":"我們去捷運站的服務台問問吧。","py":"Wǒ men qù jié yùn zhàn de fú wù tái wèn wen ba."}],"q":{"zh":"男的最後在哪裡用了手機？","py":"Nán de zuì hòu zài nǎ lǐ yòng le shǒu jī?"},"opts":[{"zh":"在公車上","py":"Zài gōng chē shàng"},{"zh":"在捷運上","py":"Zài jié yùn shàng"},{"zh":"在哥哥家","py":"Zài gē ge jiā"},{"zh":"在服務台","py":"Zài fú wù tái"}],"a":1,"tr":{"id":"Pria: Gawat, ponselku hilang!\nWanita: Terakhir kali kamu pakai di mana?\nPria: Di MRT, aku menelepon kakakku.\nWanita: Ayo kita tanya di meja layanan stasiun MRT.\nPertanyaan: Terakhir pria itu memakai ponsel di mana?","en":"Man: Oh no, my phone is gone!\nWoman: Where did you last use it?\nMan: On the MRT; I called my older brother.\nWoman: Let's ask at the MRT station's service counter.\nQuestion: Where did the man last use his phone?","tl":"Lalaki: Naku, nawawala ang cellphone ko!\nBabae: Saan mo ito huling ginamit?\nLalaki: Sa MRT, tinawagan ko ang kuya ko.\nBabae: Magtanong tayo sa service counter ng MRT station.\nTanong: Saan huling ginamit ng lalaki ang cellphone?","vi":"Nam: Chết rồi, điện thoại của tôi mất rồi!\nNữ: Lần cuối bạn dùng là ở đâu?\nNam: Trên tàu điện ngầm, tôi gọi điện cho anh trai.\nNữ: Mình đến quầy dịch vụ của ga tàu hỏi thử đi.\nCâu hỏi: Lần cuối người đàn ông dùng điện thoại ở đâu?"},"exp":{"id":"Dia terakhir memakai ponsel di MRT (在捷運上) untuk menelepon kakaknya.","en":"He last used it on the MRT (在捷運上), calling his brother.","tl":"Huli niyang ginamit ito sa MRT (在捷運上) nang tawagan ang kuya.","vi":"Lần cuối anh ấy dùng trên tàu điện ngầm (在捷運上) để gọi anh trai."}}]}],"R":[{"p":1,"items":[{"zh":"我每天坐捷運去上班。","py":"Wǒ měi tiān zuò jié yùn qù shàng bān.","opts":[{"i":["man","bus"],"bg":"street"},{"i":["man","mrt"]},{"i":["man","scooter"],"bg":"street"}],"a":1,"tr":{"id":"Setiap hari saya naik MRT ke kantor.","en":"I take the MRT to work every day.","tl":"Araw-araw sumasakay ako ng MRT papunta sa trabaho.","vi":"Mỗi ngày tôi đi tàu điện ngầm (MRT) đi làm."},"exp":{"id":"捷運 = MRT, jadi gambar orang dengan MRT.","en":"捷運 means MRT, so the picture shows a man with the MRT.","tl":"Ang 捷運 ay MRT, kaya ang larawan ay lalaking may MRT.","vi":"捷運 là tàu điện ngầm MRT, nên chọn tranh người đàn ông với MRT."}},{"zh":"這件外套三百五十塊。","py":"Zhè jiàn wài tào sān bǎi wǔ shí kuài.","opts":[{"i":["jacket"],"b":"NT$350","bg":"shop"},{"i":["jacket"],"b":"NT$530","bg":"shop"},{"i":["shirt"],"b":"NT$350","bg":"shop"}],"a":0,"tr":{"id":"Jaket ini harganya 350 dolar.","en":"This jacket costs 350 dollars.","tl":"Ang jacket na ito ay 350 dolyar.","vi":"Cái áo khoác này giá 350 đồng (Đài tệ)."},"exp":{"id":"外套 = jaket, 三百五十 = 350.","en":"外套 is a jacket and 三百五十 is 350.","tl":"外套 ay jacket at 三百五十 ay 350.","vi":"外套 là áo khoác, 三百五十 là 350."}},{"zh":"晚上我們去夜市吃東西。","py":"Wǎn shàng wǒ men qù yè shì chī dōng xi.","opts":[{"i":["friends","park"],"bg":"park"},{"i":["friends","cinema"],"bg":"night"},{"i":["friends","night_market","eat"],"bg":"night"}],"a":2,"tr":{"id":"Malam hari kami pergi ke pasar malam untuk makan.","en":"In the evening we go to the night market to eat.","tl":"Sa gabi pumupunta kami sa night market para kumain.","vi":"Buổi tối chúng tôi đi chợ đêm ăn uống."},"exp":{"id":"夜市 = pasar malam, 吃東西 = makan.","en":"夜市 is a night market, and they go there to eat.","tl":"夜市 ay night market, at kumakain sila roon.","vi":"夜市 là chợ đêm, họ đến đó để ăn."}},{"zh":"下雨了，她坐計程車回家。","py":"Xià yǔ le, tā zuò jì chéng chē huí jiā.","opts":[{"i":["woman","umbrella","walk"],"bg":"rain"},{"i":["woman","bus"],"bg":"rain"},{"i":["woman","taxi"],"bg":"rain"}],"a":2,"tr":{"id":"Hujan turun, dia naik taksi pulang ke rumah.","en":"It's raining, so she takes a taxi home.","tl":"Umuulan, kaya sumakay siya ng taxi pauwi.","vi":"Trời mưa rồi, cô ấy đi taxi về nhà."},"exp":{"id":"計程車 = taksi, bukan bus atau jalan kaki.","en":"計程車 is a taxi, not a bus or walking.","tl":"計程車 ay taxi, hindi bus o paglalakad.","vi":"計程車 là taxi, không phải xe buýt hay đi bộ."}},{"zh":"從這裡往前走，到了路口再往右轉。","py":"Cóng zhè lǐ wǎng qián zǒu, dào le lù kǒu zài wǎng yòu zhuǎn.","opts":[{"i":["straight_arrow","left_arrow"],"bg":"street"},{"i":["straight_arrow","right_arrow"],"bg":"street"},{"i":["left_arrow"],"bg":"street"}],"a":1,"tr":{"id":"Dari sini jalan lurus, sampai di persimpangan lalu belok kanan.","en":"Go straight from here, then turn right at the intersection.","tl":"Mula rito dumiretso, pagdating sa kanto ay kumanan.","vi":"Từ đây đi thẳng, đến ngã tư thì rẽ phải."},"exp":{"id":"往前走 = lurus, 往右轉 = belok kanan.","en":"往前走 is straight ahead and 往右轉 is turn right.","tl":"往前走 ay diretso at 往右轉 ay kumanan.","vi":"往前走 là đi thẳng, 往右轉 là rẽ phải."}},{"zh":"哥哥正在用手機打電話。","py":"Gē ge zhèng zài yòng shǒu jī dǎ diàn huà.","opts":[{"i":["man","call"]},{"i":["man","listen_music"]},{"i":["man","photo"]}],"a":0,"tr":{"id":"Kakak laki-laki sedang menelepon dengan ponsel.","en":"My older brother is making a phone call on his cell phone.","tl":"Tumatawag ang kuya ko gamit ang cellphone.","vi":"Anh trai đang gọi điện bằng điện thoại di động."},"exp":{"id":"打電話 = menelepon.","en":"打電話 means making a phone call.","tl":"Ang 打電話 ay tumawag sa telepono.","vi":"打電話 nghĩa là gọi điện thoại."}},{"zh":"這雙鞋子太小了，我想買大一點的。","py":"Zhè shuāng xié zi tài xiǎo le, wǒ xiǎng mǎi dà yì diǎn de.","opts":[{"i":["woman","hat"],"bg":"shop"},{"i":["woman","shoes"],"bg":"shop"},{"i":["woman","socks"],"bg":"shop"}],"a":1,"tr":{"id":"Sepatu ini terlalu kecil, saya mau beli yang lebih besar.","en":"These shoes are too small; I want to buy a bigger pair.","tl":"Masyadong maliit ang sapatos na ito, gusto kong bumili ng mas malaki.","vi":"Đôi giày này nhỏ quá, tôi muốn mua đôi to hơn một chút."},"exp":{"id":"鞋子 = sepatu, jadi gambar di toko sepatu.","en":"鞋子 means shoes, so choose the shoe picture.","tl":"Ang 鞋子 ay sapatos, kaya piliin ang larawan ng sapatos.","vi":"鞋子 là giày, nên chọn tranh có giày."}},{"zh":"火車八點二十分開。","py":"Huǒ chē bā diǎn èr shí fēn kāi.","opts":[{"i":["train","clock"],"b":"08:12"},{"i":["bus","clock"],"b":"08:20"},{"i":["train","clock"],"b":"08:20"}],"a":2,"tr":{"id":"Kereta berangkat pukul 8:20.","en":"The train leaves at 8:20.","tl":"Aalis ang tren nang 8:20.","vi":"Tàu hỏa khởi hành lúc 8 giờ 20."},"exp":{"id":"火車 = kereta, 八點二十分 = 08:20.","en":"火車 is a train and the time is 08:20.","tl":"火車 ay tren at ang oras ay 08:20.","vi":"火車 là tàu hỏa, giờ là 08:20."}},{"zh":"我騎機車去郵局寄信。","py":"Wǒ qí jī chē qù yóu jú jì xìn.","opts":[{"i":["scooter","post_office","letter"]},{"i":["bicycle","post_office","letter"]},{"i":["scooter","bank","money"]}],"a":0,"tr":{"id":"Saya naik skuter ke kantor pos untuk mengirim surat.","en":"I ride my scooter to the post office to send a letter.","tl":"Sumakay ako ng scooter papunta sa post office para magpadala ng sulat.","vi":"Tôi đi xe máy đến bưu điện gửi thư."},"exp":{"id":"機車 = skuter, 郵局 = kantor pos, 信 = surat.","en":"機車 is a scooter, 郵局 a post office, 信 a letter.","tl":"機車 ay scooter, 郵局 ay post office, 信 ay sulat.","vi":"機車 là xe máy, 郵局 là bưu điện, 信 là thư."}},{"zh":"爸爸開車帶我們去海邊玩。","py":"Bà ba kāi chē dài wǒ men qù hǎi biān wán.","opts":[{"i":["family","train"],"bg":"sea"},{"i":["family","car"],"bg":"sea"},{"i":["family","car","mountain"]}],"a":1,"tr":{"id":"Ayah menyetir mobil membawa kami bermain ke pantai.","en":"Dad drives us to the beach to have fun.","tl":"Nagmaneho si Tatay para dalhin kami sa tabing-dagat.","vi":"Bố lái xe đưa chúng tôi ra biển chơi."},"exp":{"id":"開車 = menyetir mobil, 海邊 = pantai.","en":"開車 is driving a car and 海邊 is the seaside.","tl":"開車 ay pagmamaneho ng kotse at 海邊 ay tabing-dagat.","vi":"開車 là lái ô tô, 海邊 là bờ biển."}}]},{"p":2,"items":[{"pic":{"i":["woman","bus"],"bg":"street"},"zh":"她在等＿＿＿。","py":"Tā zài děng gōng chē.","opts":["捷運","火車","計程車","公車"],"a":3,"tr":{"id":"Dia sedang menunggu bus.","en":"She is waiting for the bus.","tl":"Naghihintay siya ng bus.","vi":"Cô ấy đang đợi xe buýt."},"exp":{"id":"Gambar menunjukkan bus, yaitu 公車.","en":"The picture shows a bus, which is 公車.","tl":"Bus ang nasa larawan, ibig sabihin 公車.","vi":"Tranh có xe buýt, tức là 公車."}},{"pic":{"i":["bubble_tea"],"b":"NT$60"},"zh":"這杯珍珠奶茶＿＿＿塊。","py":"Zhè bēi zhēn zhū nǎi chá liù shí kuài.","opts":["十六","六十","六百","一百六"],"a":1,"tr":{"id":"Bubble tea ini harganya 60 dolar.","en":"This bubble tea costs 60 dollars.","tl":"Ang bubble tea na ito ay 60 dolyar.","vi":"Ly trà sữa trân châu này giá 60 đồng."},"exp":{"id":"Harga di gambar NT$60 = 六十.","en":"The badge says NT$60, which is 六十.","tl":"NT$60 ang presyo, ibig sabihin 六十.","vi":"Giá trong tranh là NT$60, tức 六十."}},{"pic":{"i":["man","bicycle"],"bg":"park"},"zh":"他在公園＿＿＿腳踏車。","py":"Tā zài gōng yuán qí jiǎo tà chē.","opts":["騎","打","開","踢"],"a":0,"tr":{"id":"Dia sedang naik sepeda di taman.","en":"He is riding a bicycle in the park.","tl":"Nagbibisikleta siya sa parke.","vi":"Anh ấy đang đạp xe đạp trong công viên."},"exp":{"id":"Untuk sepeda dan skuter dipakai kata kerja 騎.","en":"Bicycles and scooters take the verb 騎 (ride).","tl":"Ginagamit ang 騎 para sa bisikleta at scooter.","vi":"Xe đạp, xe máy dùng động từ 騎 (cưỡi, đi)."}},{"pic":{"i":["shirt"],"b":"x3","bg":"shop"},"zh":"我買了三＿＿＿衣服。","py":"Wǒ mǎi le sān jiàn yī fú.","opts":["雙","條","件","張"],"a":2,"tr":{"id":"Saya membeli tiga potong baju.","en":"I bought three tops.","tl":"Bumili ako ng tatlong damit.","vi":"Tôi đã mua ba cái áo."},"exp":{"id":"Kata bantu bilangan untuk baju (衣服) adalah 件.","en":"The measure word for clothes/tops (衣服) is 件.","tl":"Ang measure word para sa damit (衣服) ay 件.","vi":"Lượng từ cho quần áo (衣服) là 件."}},{"pic":{"i":["book","elevator"],"b":"7F","bg":"shop"},"zh":"書店在＿＿＿樓。","py":"Shū diàn zài qī lóu.","opts":["一","七","十","四"],"a":1,"tr":{"id":"Toko buku ada di lantai 7.","en":"The bookstore is on the 7th floor.","tl":"Nasa ika-7 palapag ang bookstore.","vi":"Hiệu sách ở tầng 7."},"exp":{"id":"Gambar menunjukkan 7F, yaitu 七樓.","en":"The badge shows 7F, so it is 七樓.","tl":"7F ang nasa larawan, kaya 七樓.","vi":"Tranh ghi 7F, tức là 七樓."}},{"pic":{"i":["woman","umbrella"],"bg":"rain"},"zh":"外面在下雨，她帶了＿＿＿。","py":"Wài miàn zài xià yǔ, tā dài le yǔ sǎn.","opts":["帽子","手機","外套","雨傘"],"a":3,"tr":{"id":"Di luar sedang hujan, dia membawa payung.","en":"It's raining outside; she brought an umbrella.","tl":"Umuulan sa labas, nagdala siya ng payong.","vi":"Bên ngoài đang mưa, cô ấy mang theo ô."},"exp":{"id":"Gambar menunjukkan payung = 雨傘.","en":"The picture shows an umbrella, 雨傘.","tl":"Payong ang nasa larawan, 雨傘.","vi":"Tranh có cái ô, tức 雨傘."}},{"pic":{"i":["man","left_arrow"],"bg":"street"},"zh":"到了路口，請往＿＿＿轉。","py":"Dào le lù kǒu, qǐng wǎng zuǒ zhuǎn.","opts":["右","前","左","後"],"a":2,"tr":{"id":"Sampai di persimpangan, silakan belok kiri.","en":"At the intersection, please turn left.","tl":"Pagdating sa kanto, kumaliwa po kayo.","vi":"Đến ngã tư, xin rẽ trái."},"exp":{"id":"Panah menunjuk ke kiri = 左.","en":"The arrow points left, 左.","tl":"Pakaliwa ang arrow, 左.","vi":"Mũi tên chỉ sang trái, 左."}},{"pic":{"i":["airplane","family"],"bg":"none"},"zh":"我們坐＿＿＿去花蓮。","py":"Wǒ men zuò fēi jī qù Huā lián.","opts":["飛機","火車","公車","船"],"a":0,"tr":{"id":"Kami naik pesawat ke Hualien.","en":"We are taking a plane to Hualien.","tl":"Sasakay kami ng eroplano papuntang Hualien.","vi":"Chúng tôi đi máy bay đến Hoa Liên."},"exp":{"id":"Gambar menunjukkan pesawat = 飛機.","en":"The picture shows an airplane, 飛機.","tl":"Eroplano ang nasa larawan, 飛機.","vi":"Tranh có máy bay, 飛機."}},{"pic":{"i":["girl","skirt"],"bg":"shop"},"zh":"她在試穿一條＿＿＿。","py":"Tā zài shì chuān yì tiáo qún zi.","opts":["褲子","襪子","帽子","裙子"],"a":3,"tr":{"id":"Dia sedang mencoba sebuah rok.","en":"She is trying on a skirt.","tl":"Sinusukat niya ang isang palda.","vi":"Cô ấy đang mặc thử một chiếc váy."},"exp":{"id":"Gambar menunjukkan rok = 裙子.","en":"The picture shows a skirt, 裙子.","tl":"Palda ang nasa larawan, 裙子.","vi":"Tranh có chiếc váy, 裙子."}},{"pic":{"i":["woman","call"],"bg":"home"},"zh":"媽媽正在＿＿＿電話。","py":"Mā ma zhèng zài dǎ diàn huà.","opts":["看","打","寫","買"],"a":1,"tr":{"id":"Ibu sedang menelepon.","en":"Mom is making a phone call.","tl":"Tumatawag si Nanay sa telepono.","vi":"Mẹ đang gọi điện thoại."},"exp":{"id":"Menelepon = 打電話.","en":"Making a call is 打電話.","tl":"Ang tumawag ay 打電話.","vi":"Gọi điện là 打電話."}}]},{"p":3,"items":[{"zh":"這條褲子＿＿＿那條貴一百塊。","py":"Zhè tiáo kù zi bǐ nà tiáo guì yì bǎi kuài.","opts":["跟","和","比","對"],"a":2,"tr":{"id":"Celana ini 100 dolar lebih mahal daripada yang itu.","en":"These pants are 100 dollars more expensive than those.","tl":"Mas mahal nang 100 dolyar ang pantalong ito kaysa roon.","vi":"Cái quần này đắt hơn cái kia 100 đồng."},"exp":{"id":"Pola perbandingan: A 比 B + sifat.","en":"Comparison pattern: A 比 B + adjective.","tl":"Paghahambing: A 比 B + pang-uri.","vi":"Cấu trúc so sánh: A 比 B + tính từ."}},{"zh":"A：你要喝咖啡＿＿＿茶？\nB：茶，謝謝。","py":"Nǐ yào hē kā fēi hái shì chá? Chá, xiè xie.","opts":["還是","或是","也是","就是"],"a":0,"tr":{"id":"A: Kamu mau minum kopi atau teh? B: Teh, terima kasih.","en":"A: Do you want coffee or tea? B: Tea, thanks.","tl":"A: Kape ba o tsaa ang gusto mo? B: Tsaa, salamat.","vi":"A: Bạn muốn uống cà phê hay trà? B: Trà, cảm ơn."},"exp":{"id":"Dalam kalimat tanya pilihan dipakai 還是.","en":"In 'A or B' questions, use 還是.","tl":"Sa tanong na 'A o B', 還是 ang gamit.","vi":"Câu hỏi lựa chọn dùng 還是."}},{"zh":"我去過臺北兩＿＿＿。","py":"Wǒ qù guò Tái běi liǎng cì.","opts":["個","本","張","次"],"a":3,"tr":{"id":"Saya sudah pernah ke Taipei dua kali.","en":"I have been to Taipei twice.","tl":"Dalawang beses na akong nakapunta sa Taipei.","vi":"Tôi đã đến Đài Bắc hai lần."},"exp":{"id":"次 menghitung berapa kali suatu kegiatan.","en":"次 counts how many times an action happens.","tl":"Ang 次 ay pambilang ng ilang beses.","vi":"次 dùng để đếm số lần."}},{"zh":"公車站＿＿＿這裡不遠，走五分鐘就到了。","py":"Gōng chē zhàn lí zhè lǐ bù yuǎn, zǒu wǔ fēn zhōng jiù dào le.","opts":["從","離","在","往"],"a":1,"tr":{"id":"Halte bus tidak jauh dari sini, jalan lima menit sudah sampai.","en":"The bus stop isn't far from here; it's a five-minute walk.","tl":"Hindi malayo rito ang bus stop, limang minutong lakad lang.","vi":"Trạm xe buýt cách đây không xa, đi bộ năm phút là tới."},"exp":{"id":"Jarak dari suatu tempat memakai 離: A 離 B 遠/近.","en":"Distance uses 離: A 離 B 遠/近.","tl":"Para sa layo, gamitin ang 離: A 離 B 遠/近.","vi":"Nói khoảng cách dùng 離: A 離 B 遠/近."}},{"zh":"我昨天十二點＿＿＿睡覺，所以今天很累。","py":"Wǒ zuó tiān shí èr diǎn cái shuì jiào, suǒ yǐ jīn tiān hěn lèi.","opts":["就","再","才","又"],"a":2,"tr":{"id":"Kemarin saya baru tidur jam 12, jadi hari ini capek sekali.","en":"I didn't go to bed until 12 yesterday, so I'm tired today.","tl":"Alas-dose na ako natulog kahapon, kaya pagod ako ngayon.","vi":"Hôm qua 12 giờ tôi mới đi ngủ, nên hôm nay rất mệt."},"exp":{"id":"才 = baru (terlambat), cocok dengan 'capek'.","en":"才 shows 'not until / late', which fits being tired.","tl":"Ang 才 ay nagpapakitang huli na, kaya pagod.","vi":"才 diễn tả 'muộn mới', hợp với 'mệt'."}},{"zh":"A：這件衣服可以＿＿＿嗎？\nB：可以，試衣間在那邊。","py":"Zhè jiàn yī fú kě yǐ shì chuān ma? Kě yǐ, shì yī jiān zài nà biān.","opts":["洗","試穿","送","拿走"],"a":1,"tr":{"id":"A: Baju ini boleh dicoba? B: Boleh, kamar pas ada di sana.","en":"A: Can I try this on? B: Sure, the fitting room is over there.","tl":"A: Puwede ko bang isukat ito? B: Oo, nandoon ang fitting room.","vi":"A: Bộ đồ này mặc thử được không? B: Được, phòng thử đồ ở bên kia."},"exp":{"id":"Jawaban menyebut kamar pas, jadi 試穿 (mencoba).","en":"B mentions the fitting room, so the answer is 試穿 (try on).","tl":"Binanggit ang fitting room, kaya 試穿 (isukat).","vi":"B nhắc phòng thử đồ, nên chọn 試穿 (mặc thử)."}},{"zh":"看電影的時候，請＿＿＿手機關掉。","py":"Kàn diàn yǐng de shí hòu, qǐng bǎ shǒu jī guān diào.","opts":["把","被","給","讓"],"a":0,"tr":{"id":"Saat menonton film, tolong matikan ponsel.","en":"When watching a movie, please turn off your phone.","tl":"Habang nanonood ng pelikula, pakipatay ang cellphone.","vi":"Khi xem phim, xin hãy tắt điện thoại."},"exp":{"id":"Pola 把 + benda + kata kerja + hasil (關掉).","en":"Pattern: 把 + object + verb + result (關掉).","tl":"Pattern: 把 + bagay + pandiwa + resulta (關掉).","vi":"Cấu trúc 把 + tân ngữ + động từ + kết quả (關掉)."}},{"zh":"王先生說中文說＿＿＿很好。","py":"Wáng xiān shēng shuō Zhōng wén shuō de hěn hǎo.","opts":["的","了","地","得"],"a":3,"tr":{"id":"Pak Wang berbicara bahasa Mandarin dengan sangat baik.","en":"Mr. Wang speaks Chinese very well.","tl":"Magaling magsalita ng Chinese si G. Wang.","vi":"Ông Vương nói tiếng Trung rất giỏi."},"exp":{"id":"Kata kerja + 得 + penilaian (很好).","en":"Verb + 得 + comment on how well (很好).","tl":"Pandiwa + 得 + paglalarawan (很好).","vi":"Động từ + 得 + bổ ngữ mức độ (很好)."}},{"zh":"我還不＿＿＿騎機車，我正在學。","py":"Wǒ hái bú huì qí jī chē, wǒ zhèng zài xué.","opts":["要","想","會","愛"],"a":2,"tr":{"id":"Saya belum bisa naik skuter, saya sedang belajar.","en":"I can't ride a scooter yet; I'm learning.","tl":"Hindi pa ako marunong mag-scooter, nag-aaral pa ako.","vi":"Tôi vẫn chưa biết đi xe máy, tôi đang học."},"exp":{"id":"會 = bisa karena sudah belajar; cocok dengan 正在學.","en":"會 means a learned skill, matching 'I'm learning'.","tl":"Ang 會 ay kakayahang natutunan, tugma sa 'nag-aaral'.","vi":"會 là biết (kỹ năng học được), hợp với 'đang học'."}},{"zh":"我＿＿＿吃飯，等一下再打給你。","py":"Wǒ zài chī fàn, děng yí xià zài dǎ gěi nǐ.","opts":["在","了","過","著"],"a":0,"tr":{"id":"Saya sedang makan, nanti saya telepon kamu lagi.","en":"I'm eating right now; I'll call you back later.","tl":"Kumakain ako ngayon, tatawagan kita mamaya.","vi":"Tôi đang ăn cơm, lát nữa gọi lại cho bạn."},"exp":{"id":"在 + kata kerja = sedang melakukan.","en":"在 + verb shows an action in progress.","tl":"Ang 在 + pandiwa ay kasalukuyang ginagawa.","vi":"在 + động từ diễn tả đang làm."}}]},{"p":4,"items":[{"zh":"上個週末，我跟朋友去臺南玩。我們（1）高鐵去，一個多小時就到了。晚上我們去（2）吃東西，那裡的小吃又便宜又好吃。我還買了一（3）漂亮的衣服，要送給妹妹。第二天下雨了，不能騎腳踏車，（4）我們就去咖啡店喝咖啡、聊天。雖然天氣不好，（5）我們玩得很開心。","py":"Shàng ge zhōu mò, wǒ gēn péng yǒu qù Tái nán wán. Wǒ men zuò gāo tiě qù, yí ge duō xiǎo shí jiù dào le. Wǎn shàng wǒ men qù yè shì chī dōng xi, nà lǐ de xiǎo chī yòu pián yí yòu hǎo chī. Wǒ hái mǎi le yí jiàn piào liàng de yī fú, yào sòng gěi mèi mei. Dì èr tiān xià yǔ le, bù néng qí jiǎo tà chē, suǒ yǐ wǒ men jiù qù kā fēi diàn hē kā fēi, liáo tiān. Suī rán tiān qì bù hǎo, dàn shì wǒ men wán de hěn kāi xīn.","bank":["件","但是","坐","條","夜市","所以"],"ans":[2,4,0,5,1],"tr":{"id":"Akhir pekan lalu, saya dan teman pergi jalan-jalan ke Tainan. Kami naik kereta cepat (HSR), lebih dari satu jam sudah sampai. Malamnya kami pergi ke pasar malam untuk makan; jajanan di sana murah dan enak. Saya juga membeli sepotong baju yang cantik untuk adik perempuan saya. Hari kedua hujan, tidak bisa naik sepeda, jadi kami pergi ke kafe minum kopi dan mengobrol. Walaupun cuacanya tidak bagus, tetapi kami bersenang-senang.","en":"Last weekend my friend and I went to Tainan. We took the high-speed rail and got there in just over an hour. In the evening we went to the night market to eat; the snacks there were cheap and tasty. I also bought a pretty piece of clothing to give my younger sister. On the second day it rained and we couldn't ride bikes, so we went to a café to drink coffee and chat. Although the weather wasn't good, we had a great time.","tl":"Noong nakaraang weekend, pumunta kami ng kaibigan ko sa Tainan. Sumakay kami ng high-speed rail at mahigit isang oras lang ay nakarating na. Sa gabi pumunta kami sa night market para kumain; mura at masarap ang pagkain doon. Bumili rin ako ng magandang damit para sa nakababata kong kapatid na babae. Sa ikalawang araw umulan, hindi kami makapagbisikleta, kaya pumunta kami sa coffee shop para magkape at magkuwentuhan. Kahit hindi maganda ang panahon, nag-enjoy kami.","vi":"Cuối tuần trước, tôi và bạn đi chơi Đài Nam. Chúng tôi đi tàu cao tốc, hơn một tiếng là đến. Buổi tối chúng tôi đi chợ đêm ăn uống, đồ ăn vặt ở đó vừa rẻ vừa ngon. Tôi còn mua một bộ quần áo đẹp để tặng em gái. Ngày thứ hai trời mưa, không đạp xe được, nên chúng tôi đi quán cà phê uống cà phê, trò chuyện. Tuy thời tiết không đẹp nhưng chúng tôi chơi rất vui."},"exp":{"id":"坐 高鐵 (naik); 夜市 tempat jajanan; 件 untuk baju; 所以 karena hujan; 雖然…但是….","en":"坐 a train; 夜市 for snacks; 件 for clothes; 所以 for result; 雖然…但是… pattern. 條 is extra.","tl":"坐 para sa tren; 夜市 para sa pagkain; 件 sa damit; 所以 para sa resulta; 雖然…但是…. Sobra ang 條.","vi":"坐 tàu; 夜市 ăn vặt; 件 cho quần áo; 所以 chỉ kết quả; 雖然…但是…. 條 là từ thừa."}}]},{"p":5,"items":[{"kind":"notice","title":"捷運站公告","zh":"各位旅客您好：\n本站二號出口的電梯，從10月6日到10月12日要修理，不能使用。\n要坐電梯的旅客，請走到一號出口。\n帶大行李的旅客，可以到服務台找人幫忙。\n謝謝！","py":"Gè wèi lǚ kè nín hǎo: Běn zhàn èr hào chū kǒu de diàn tī, cóng 10 yuè 6 rì dào 10 yuè 12 rì yào xiū lǐ, bù néng shǐ yòng. Yào zuò diàn tī de lǚ kè, qǐng zǒu dào yī hào chū kǒu. Dài dà xíng lǐ de lǚ kè, kě yǐ dào fú wù tái zhǎo rén bāng máng. Xiè xie!","qs":[{"zh":"哪個出口的電梯不能用？","py":"Nǎ ge chū kǒu de diàn tī bù néng yòng?","opts":["一號出口","二號出口","三號出口","每個出口"],"a":1,"exp":{"id":"Pengumuman: lift di pintu keluar 2 diperbaiki.","en":"The notice says the elevator at Exit 2 is being repaired.","tl":"Sinasabi ng paunawa na inaayos ang elevator sa Exit 2.","vi":"Thông báo nói thang máy ở cửa ra số 2 đang sửa."}},{"zh":"電梯要修理幾天？","py":"Diàn tī yào xiū lǐ jǐ tiān?","opts":["五天","六天","七天","十二天"],"a":2,"exp":{"id":"Dari 6 sampai 12 Oktober = 7 hari.","en":"From October 6 to 12 is seven days.","tl":"Mula Oktubre 6 hanggang 12 ay pitong araw.","vi":"Từ ngày 6 đến 12 tháng 10 là bảy ngày."}},{"zh":"帶大行李的旅客可以怎麼做？","py":"Dài dà xíng lǐ de lǚ kè kě yǐ zěn me zuò?","opts":["去服務台找人幫忙","走樓梯上去","坐計程車","明天再來"],"a":0,"exp":{"id":"Mereka boleh minta bantuan di meja layanan (服務台).","en":"They can ask for help at the service desk (服務台).","tl":"Puwede silang humingi ng tulong sa service desk (服務台).","vi":"Họ có thể đến quầy phục vụ (服務台) nhờ giúp."}}],"tr":{"id":"Para penumpang yang terhormat: Lift di pintu keluar 2 stasiun ini akan diperbaiki dari 6 sampai 12 Oktober dan tidak bisa digunakan. Penumpang yang perlu lift, silakan ke pintu keluar 1. Penumpang yang membawa bagasi besar dapat meminta bantuan di meja layanan. Terima kasih!","en":"Dear passengers: The elevator at Exit 2 of this station will be under repair from October 6 to October 12 and cannot be used. Passengers who need an elevator, please go to Exit 1. Passengers with large luggage can ask for help at the service desk. Thank you!","tl":"Mahal na mga pasahero: Ang elevator sa Exit 2 ng istasyong ito ay aayusin mula Oktubre 6 hanggang 12 at hindi magagamit. Ang mga kailangang gumamit ng elevator ay pumunta sa Exit 1. Ang may malalaking bagahe ay maaaring humingi ng tulong sa service desk. Salamat!","vi":"Kính chào quý hành khách: Thang máy ở cửa ra số 2 của ga này sẽ sửa chữa từ ngày 6 đến 12 tháng 10, không sử dụng được. Hành khách cần đi thang máy xin đến cửa ra số 1. Hành khách mang hành lý lớn có thể đến quầy phục vụ nhờ giúp đỡ. Xin cảm ơn!"}},{"kind":"menu","title":"阿美小吃店","zh":"牛肉麵　大碗150元　小碗120元\n水餃　十個60元\n滷肉飯　35元\n青菜湯　30元\n珍珠奶茶　50元\n開店時間：11:00－21:00\n※買兩碗牛肉麵，送一杯珍珠奶茶。\n※星期一休息。","py":"Niú ròu miàn dà wǎn 150 yuán xiǎo wǎn 120 yuán. Shuǐ jiǎo shí ge 60 yuán. Lǔ ròu fàn 35 yuán. Qīng cài tāng 30 yuán. Zhēn zhū nǎi chá 50 yuán. Kāi diàn shí jiān: 11:00 - 21:00. Mǎi liǎng wǎn niú ròu miàn, sòng yì bēi zhēn zhū nǎi chá. Xīng qí yī xiū xí.","qs":[{"zh":"一碗小碗牛肉麵和一碗滷肉飯，一共多少錢？","py":"Yì wǎn xiǎo wǎn niú ròu miàn hé yì wǎn lǔ ròu fàn, yí gòng duō shǎo qián?","opts":["一百八十五元","一百五十五元","一百七十元","一百四十五元"],"a":1,"exp":{"id":"Mi sapi mangkuk kecil 120 + nasi babi cincang 35 = 155.","en":"Small beef noodles 120 + braised pork rice 35 = 155.","tl":"Maliit na beef noodles 120 + braised pork rice 35 = 155.","vi":"Mì bò bát nhỏ 120 + cơm thịt kho 35 = 155."}},{"zh":"哪一天不能去這家店吃飯？","py":"Nǎ yì tiān bù néng qù zhè jiā diàn chī fàn?","opts":["星期天","星期六","星期一","星期五"],"a":2,"exp":{"id":"Menu tertulis 星期一休息 (Senin tutup).","en":"The menu says 星期一休息: closed on Mondays.","tl":"Nakasulat na 星期一休息: sarado tuwing Lunes.","vi":"Thực đơn ghi 星期一休息: nghỉ thứ Hai."}},{"zh":"買兩碗牛肉麵，會送什麼？","py":"Mǎi liǎng wǎn niú ròu miàn, huì sòng shén me?","opts":["十個水餃","一碗滷肉飯","一碗青菜湯","一杯珍珠奶茶"],"a":3,"exp":{"id":"Beli dua mangkuk mi sapi, gratis satu bubble tea.","en":"Buy two beef noodles and get a free bubble tea.","tl":"Bumili ng dalawang beef noodles, libre ang isang bubble tea.","vi":"Mua hai bát mì bò được tặng một ly trà sữa trân châu."}}],"tr":{"id":"Warung Ah-Mei. Mi sapi: mangkuk besar 150, kecil 120. Pangsit: 10 buah 60. Nasi babi cincang: 35. Sup sayur: 30. Bubble tea: 50. Jam buka 11:00–21:00. Beli dua mangkuk mi sapi, gratis satu bubble tea. Senin tutup.","en":"Ah-Mei Snack Shop. Beef noodles: large 150, small 120. Dumplings: 10 for 60. Braised pork rice: 35. Vegetable soup: 30. Bubble tea: 50. Open 11:00–21:00. Buy two beef noodles, get a free bubble tea. Closed Mondays.","tl":"Ah-Mei Snack Shop. Beef noodles: malaki 150, maliit 120. Dumplings: 10 piraso 60. Braised pork rice: 35. Sabaw ng gulay: 30. Bubble tea: 50. Bukas 11:00–21:00. Bumili ng dalawang beef noodles, libre ang isang bubble tea. Sarado tuwing Lunes.","vi":"Quán ăn A Mỹ. Mì bò: bát lớn 150, bát nhỏ 120. Sủi cảo: 10 cái 60. Cơm thịt kho: 35. Canh rau: 30. Trà sữa trân châu: 50. Giờ mở cửa 11:00–21:00. Mua hai bát mì bò tặng một ly trà sữa trân châu. Nghỉ thứ Hai."}},{"kind":"message","title":"手機訊息","zh":"小美：你到了嗎？我已經在捷運站一號出口了。\n大明：對不起，我坐錯車了，現在在公車上。\n大明：大概還要二十分鐘才會到。\n小美：沒關係，那我先去旁邊的書店看看書。\n大明：好，我到了再打電話給你。","py":"Xiǎo Měi: Nǐ dào le ma? Wǒ yǐ jīng zài jié yùn zhàn yī hào chū kǒu le. Dà Míng: Duì bù qǐ, wǒ zuò cuò chē le, xiàn zài zài gōng chē shàng. Dà Míng: Dà gài hái yào èr shí fēn zhōng cái huì dào. Xiǎo Měi: Méi guān xi, nà wǒ xiān qù páng biān de shū diàn kàn kan shū. Dà Míng: Hǎo, wǒ dào le zài dǎ diàn huà gěi nǐ.","qs":[{"zh":"大明為什麼會晚到？","py":"Dà Míng wèi shén me huì wǎn dào?","opts":["他坐錯車了","他太晚起床","他的手機壞了","他在書店買書"],"a":0,"exp":{"id":"Daming bilang 我坐錯車了 (salah naik kendaraan).","en":"Daming says 我坐錯車了: he took the wrong vehicle.","tl":"Sabi ni Daming 我坐錯車了: mali ang nasakyan niya.","vi":"Đại Minh nói 我坐錯車了: anh ấy đi nhầm xe."}},{"zh":"小美等大明的時候，要去哪裡？","py":"Xiǎo Měi děng Dà Míng de shí hòu, yào qù nǎ lǐ?","opts":["咖啡店","公車站","書店","捷運站二號出口"],"a":2,"exp":{"id":"Xiaomei akan ke toko buku di sebelah.","en":"Xiaomei will go to the bookstore next door.","tl":"Pupunta si Xiaomei sa katabing bookstore.","vi":"Tiểu Mỹ sẽ sang hiệu sách bên cạnh."}},{"zh":"大明到了以後，會做什麼？","py":"Dà Míng dào le yǐ hòu, huì zuò shén me?","opts":["去書店找書","打電話給小美","坐捷運回家","買書給小美"],"a":1,"exp":{"id":"Daming: 我到了再打電話給你 (akan menelepon).","en":"Daming says he'll call her when he arrives.","tl":"Sabi ni Daming tatawag siya pagdating niya.","vi":"Đại Minh nói đến nơi sẽ gọi điện cho cô ấy."}}],"tr":{"id":"Xiaomei: Kamu sudah sampai? Saya sudah di pintu keluar 1 stasiun MRT. Daming: Maaf, saya salah naik, sekarang di bus. Daming: Kira-kira 20 menit lagi baru sampai. Xiaomei: Tidak apa-apa, kalau begitu saya ke toko buku di sebelah dulu. Daming: Oke, nanti kalau sudah sampai saya telepon kamu.","en":"Xiaomei: Are you here? I'm already at Exit 1 of the MRT station. Daming: Sorry, I took the wrong bus/train; I'm on a bus now. Daming: I'll need about 20 more minutes. Xiaomei: No problem, I'll go look at books in the bookstore next door. Daming: OK, I'll call you when I get there.","tl":"Xiaomei: Nandiyan ka na ba? Nasa Exit 1 na ako ng MRT station. Daming: Sorry, mali ang nasakyan ko, nasa bus ako ngayon. Daming: Mga 20 minuto pa bago ako makarating. Xiaomei: Okay lang, pupunta muna ako sa katabing bookstore. Daming: Sige, tatawagan kita pagdating ko.","vi":"Tiểu Mỹ: Bạn đến chưa? Mình đã ở cửa ra số 1 ga MRT rồi. Đại Minh: Xin lỗi, mình đi nhầm xe, giờ đang ở trên xe buýt. Đại Minh: Khoảng 20 phút nữa mới tới. Tiểu Mỹ: Không sao, vậy mình sang hiệu sách bên cạnh xem sách trước. Đại Minh: Được, tới nơi mình gọi cho bạn."}},{"kind":"schedule","title":"臺北到花蓮火車時刻表","zh":"臺北→花蓮\n快車　7:30開　9:40到　440元\n普通車　8:10開　11:20到　340元\n快車　10:00開　12:10到　440元\n※星期五、星期六、星期天的車票很快就賣完，請早一點買票。","py":"Tái běi → Huā lián. Kuài chē 7:30 kāi 9:40 dào 440 yuán. Pǔ tōng chē 8:10 kāi 11:20 dào 340 yuán. Kuài chē 10:00 kāi 12:10 dào 440 yuán. Xīng qí wǔ, xīng qí liù, xīng qí tiān de chē piào hěn kuài jiù mài wán, qǐng zǎo yì diǎn mǎi piào.","qs":[{"zh":"坐快車從臺北到花蓮要多久？","py":"Zuò kuài chē cóng Tái běi dào Huā lián yào duō jiǔ?","opts":["兩個小時","兩個小時十分鐘","三個小時十分鐘","一個小時四十分鐘"],"a":1,"exp":{"id":"7:30–9:40 dan 10:00–12:10 = 2 jam 10 menit.","en":"7:30–9:40 and 10:00–12:10 are both 2 hours 10 minutes.","tl":"7:30–9:40 at 10:00–12:10 ay parehong 2 oras at 10 minuto.","vi":"7:30–9:40 và 10:00–12:10 đều là 2 tiếng 10 phút."}},{"zh":"小王想十二點以前到花蓮，可是想晚一點出發。他應該坐幾點的車？","py":"Xiǎo Wáng xiǎng shí èr diǎn yǐ qián dào Huā lián, kě shì xiǎng wǎn yì diǎn chū fā. Tā yīng gāi zuò jǐ diǎn de chē?","opts":["八點十分","七點半","十點","九點四十分"],"a":0,"exp":{"id":"Kereta 8:10 tiba 11:20 (sebelum jam 12); kereta 10:00 tiba 12:10.","en":"The 8:10 train arrives at 11:20; the 10:00 train arrives after 12.","tl":"Ang 8:10 na tren ay darating nang 11:20; ang 10:00 ay lampas 12.","vi":"Chuyến 8:10 đến lúc 11:20; chuyến 10:00 đến sau 12 giờ."}},{"zh":"關於這張時刻表，哪一個是對的？","py":"Guān yú zhè zhāng shí kè biǎo, nǎ yí ge shì duì de?","opts":["普通車比快車貴","每天只有兩班車","快車十點到花蓮","星期六的車票很快就賣完"],"a":3,"exp":{"id":"Tiket Jumat–Minggu cepat habis, termasuk Sabtu.","en":"Friday to Sunday tickets sell out fast, including Saturday.","tl":"Mabilis maubos ang tiket mula Biyernes hanggang Linggo, kasama ang Sabado.","vi":"Vé thứ Sáu đến Chủ nhật bán hết nhanh, gồm cả thứ Bảy."}}],"tr":{"id":"Taipei → Hualien. Kereta cepat: berangkat 7:30, tiba 9:40, 440. Kereta biasa: berangkat 8:10, tiba 11:20, 340. Kereta cepat: berangkat 10:00, tiba 12:10, 440. Tiket hari Jumat, Sabtu, dan Minggu cepat habis, silakan beli lebih awal.","en":"Taipei → Hualien. Express: departs 7:30, arrives 9:40, NT$440. Local: departs 8:10, arrives 11:20, NT$340. Express: departs 10:00, arrives 12:10, NT$440. Tickets for Friday, Saturday and Sunday sell out quickly; please buy early.","tl":"Taipei → Hualien. Express: alis 7:30, dating 9:40, 440. Ordinaryo: alis 8:10, dating 11:20, 340. Express: alis 10:00, dating 12:10, 440. Mabilis maubos ang tiket ng Biyernes, Sabado at Linggo, kaya bumili nang maaga.","vi":"Đài Bắc → Hoa Liên. Tàu nhanh: đi 7:30, đến 9:40, 440 đồng. Tàu thường: đi 8:10, đến 11:20, 340 đồng. Tàu nhanh: đi 10:00, đến 12:10, 440 đồng. Vé thứ Sáu, thứ Bảy, Chủ nhật bán hết rất nhanh, xin mua sớm."}},{"kind":"diary","title":"小美的日記","zh":"10月5日　星期六　晴天\n今天我和媽媽去百貨公司買衣服。那裡的衣服很好看，可是太貴了，一件外套要三千多塊。後來我們去夜市，買了兩件襯衫和一雙鞋子，一共才八百塊。回家的時候，我們坐捷運，可是車上人太多了，我們一直站著。雖然很累，但是我很高興。","py":"10 yuè 5 rì xīng qí liù qíng tiān. Jīn tiān wǒ hé mā ma qù bǎi huò gōng sī mǎi yī fú. Nà lǐ de yī fú hěn hǎo kàn, kě shì tài guì le, yí jiàn wài tào yào sān qiān duō kuài. Hòu lái wǒ men qù yè shì, mǎi le liǎng jiàn chèn shān hé yì shuāng xié zi, yí gòng cái bā bǎi kuài. Huí jiā de shí hòu, wǒ men zuò jié yùn, kě shì chē shàng rén tài duō le, wǒ men yì zhí zhàn zhe. Suī rán hěn lèi, dàn shì wǒ hěn gāo xìng.","qs":[{"zh":"她們為什麼沒在百貨公司買衣服？","py":"Tā men wèi shén me méi zài bǎi huò gōng sī mǎi yī fú?","opts":["衣服太貴了","衣服不好看","百貨公司沒開","媽媽不喜歡"],"a":0,"exp":{"id":"Bajunya bagus tetapi terlalu mahal (太貴了).","en":"The clothes looked nice but were too expensive (太貴了).","tl":"Maganda ang damit pero masyadong mahal (太貴了).","vi":"Quần áo đẹp nhưng đắt quá (太貴了)."}},{"zh":"她在夜市買了什麼？","py":"Tā zài yè shì mǎi le shén me?","opts":["一件外套","兩雙鞋子","兩件襯衫和一雙鞋子","一件襯衫和兩雙鞋子"],"a":2,"exp":{"id":"Di pasar malam: dua kemeja dan sepasang sepatu.","en":"At the night market: two shirts and one pair of shoes.","tl":"Sa night market: dalawang kamiseta at isang pares ng sapatos.","vi":"Ở chợ đêm: hai áo sơ mi và một đôi giày."}},{"zh":"她們怎麼回家？","py":"Tā men zěn me huí jiā?","opts":["坐公車","坐捷運","騎機車","坐計程車"],"a":1,"exp":{"id":"Tertulis 我們坐捷運 (naik MRT).","en":"The diary says 我們坐捷運: they took the MRT.","tl":"Nakasulat na 我們坐捷運: nag-MRT sila.","vi":"Nhật ký ghi 我們坐捷運: họ đi MRT."}}],"tr":{"id":"5 Oktober, Sabtu, cerah. Hari ini saya dan ibu pergi ke mal membeli baju. Bajunya bagus, tetapi terlalu mahal; satu jaket lebih dari 3.000. Lalu kami pergi ke pasar malam, membeli dua kemeja dan sepasang sepatu, totalnya hanya 800. Waktu pulang kami naik MRT, tetapi penumpangnya terlalu banyak, kami berdiri terus. Walaupun capek, saya senang.","en":"October 5, Saturday, sunny. Today Mom and I went to the department store to buy clothes. The clothes were nice but too expensive; one jacket cost over 3,000. Later we went to the night market and bought two shirts and a pair of shoes for only 800 in total. We took the MRT home, but it was too crowded, so we stood the whole way. Although I was tired, I was happy.","tl":"Oktubre 5, Sabado, maaraw. Ngayon pumunta kami ni Nanay sa department store para bumili ng damit. Maganda ang mga damit pero masyadong mahal; ang isang jacket ay mahigit 3,000. Pagkatapos pumunta kami sa night market at bumili ng dalawang kamiseta at isang pares ng sapatos, 800 lang lahat. Pauwi, nag-MRT kami pero sobrang dami ng tao kaya nakatayo kami buong biyahe. Kahit pagod, masaya ako.","vi":"Ngày 5 tháng 10, thứ Bảy, trời nắng. Hôm nay tôi và mẹ đi trung tâm thương mại mua quần áo. Quần áo ở đó đẹp nhưng đắt quá, một chiếc áo khoác hơn 3.000 đồng. Sau đó chúng tôi đi chợ đêm, mua hai áo sơ mi và một đôi giày, tổng cộng chỉ 800 đồng. Lúc về nhà chúng tôi đi MRT, nhưng trên tàu đông người quá, chúng tôi phải đứng suốt. Tuy mệt nhưng tôi rất vui."}}]}]},{"form":3,"L":[{"p":1,"items":[{"pic":{"i":["doctor","boy"],"bg":"hospital"},"opts":[{"zh":"這個人在學校上課。","py":"Zhè ge rén zài xué xiào shàng kè."},{"zh":"小男孩在看醫生。","py":"Xiǎo nán hái zài kàn yī shēng."},{"zh":"醫生在吃飯。","py":"Yī shēng zài chī fàn."}],"a":1,"tr":{"id":"A: Orang ini sedang belajar di sekolah. B: Anak laki-laki kecil itu sedang periksa ke dokter. C: Dokter sedang makan.","en":"A: This person is having class at school. B: The little boy is seeing a doctor. C: The doctor is eating.","tl":"A: Nag-aaral ang taong ito sa paaralan. B: Nagpapatingin sa doktor ang batang lalaki. C: Kumakain ang doktor.","vi":"A: Người này đang học ở trường. B: Cậu bé đang đi khám bác sĩ. C: Bác sĩ đang ăn cơm."},"exp":{"id":"Gambar menunjukkan dokter dan anak laki-laki di rumah sakit.","en":"The picture shows a doctor with a boy at a hospital.","tl":"Makikita ang doktor at batang lalaki sa ospital.","vi":"Tranh có bác sĩ và cậu bé ở bệnh viện."}},{"pic":{"i":["woman","fever"],"bg":"home"},"opts":[{"zh":"她發燒了，在家休息。","py":"Tā fā shāo le, zài jiā xiū xí."},{"zh":"她在公園跑步。","py":"Tā zài gōng yuán pǎo bù."},{"zh":"她在廚房做飯。","py":"Tā zài chú fáng zuò fàn."}],"a":0,"tr":{"id":"A: Dia demam dan beristirahat di rumah. B: Dia sedang lari di taman. C: Dia sedang memasak di dapur.","en":"A: She has a fever and is resting at home. B: She is running in the park. C: She is cooking in the kitchen.","tl":"A: May lagnat siya at nagpapahinga sa bahay. B: Tumatakbo siya sa parke. C: Nagluluto siya sa kusina.","vi":"A: Cô ấy bị sốt, đang nghỉ ở nhà. B: Cô ấy đang chạy bộ trong công viên. C: Cô ấy đang nấu ăn trong bếp."},"exp":{"id":"Gambar: perempuan demam di rumah.","en":"The picture shows a woman with a fever at home.","tl":"Babaeng may lagnat sa bahay ang nasa larawan.","vi":"Tranh là người phụ nữ bị sốt ở nhà."}},{"pic":{"i":["boy","basketball"],"bg":"school"},"opts":[{"zh":"他在打網球。","py":"Tā zài dǎ wǎng qiú."},{"zh":"他在踢足球。","py":"Tā zài tī zú qiú."},{"zh":"他在打籃球。","py":"Tā zài dǎ lán qiú."}],"a":2,"tr":{"id":"A: Dia sedang main tenis. B: Dia sedang main sepak bola. C: Dia sedang main basket.","en":"A: He is playing tennis. B: He is playing soccer. C: He is playing basketball.","tl":"A: Naglalaro siya ng tennis. B: Naglalaro siya ng soccer. C: Naglalaro siya ng basketball.","vi":"A: Cậu ấy đang chơi quần vợt. B: Cậu ấy đang đá bóng. C: Cậu ấy đang chơi bóng rổ."},"exp":{"id":"Gambar menunjukkan bola basket, jadi 打籃球.","en":"The picture shows a basketball, so 打籃球.","tl":"Basketball ang nasa larawan, kaya 打籃球.","vi":"Tranh có quả bóng rổ nên là 打籃球."}},{"pic":{"i":["waiter","restaurant"],"bg":"shop"},"opts":[{"zh":"他是醫生，在醫院工作。","py":"Tā shì yī shēng, zài yī yuàn gōng zuò."},{"zh":"他在餐廳工作。","py":"Tā zài cān tīng gōng zuò."},{"zh":"他是司機，每天開公車。","py":"Tā shì sī jī, měi tiān kāi gōng chē."}],"a":1,"tr":{"id":"A: Dia dokter, bekerja di rumah sakit. B: Dia bekerja di restoran. C: Dia sopir, setiap hari menyetir bus.","en":"A: He is a doctor and works at a hospital. B: He works at a restaurant. C: He is a driver and drives a bus every day.","tl":"A: Doktor siya at nagtatrabaho sa ospital. B: Nagtatrabaho siya sa restawran. C: Drayber siya at nagmamaneho ng bus araw-araw.","vi":"A: Anh ấy là bác sĩ, làm ở bệnh viện. B: Anh ấy làm việc ở nhà hàng. C: Anh ấy là tài xế, ngày nào cũng lái xe buýt."},"exp":{"id":"Gambar: pelayan di restoran.","en":"The picture shows a waiter at a restaurant.","tl":"Weyter sa restawran ang nasa larawan.","vi":"Tranh là người phục vụ ở nhà hàng."}},{"pic":{"i":["man","cook"],"b":"18:30","bg":"home"},"opts":[{"zh":"他六點半在做晚飯。","py":"Tā liù diǎn bàn zài zuò wǎn fàn."},{"zh":"他八點半在洗衣服。","py":"Tā bā diǎn bàn zài xǐ yī fu."},{"zh":"他六點半在看電視。","py":"Tā liù diǎn bàn zài kàn diàn shì."}],"a":0,"tr":{"id":"A: Jam setengah tujuh (18.30) dia sedang memasak makan malam. B: Jam setengah sembilan dia sedang mencuci baju. C: Jam setengah tujuh dia sedang menonton TV.","en":"A: At 6:30 he is cooking dinner. B: At 8:30 he is washing clothes. C: At 6:30 he is watching TV.","tl":"A: Alas-sais y medya, nagluluto siya ng hapunan. B: Alas-otso y medya, naglalaba siya. C: Alas-sais y medya, nanonood siya ng TV.","vi":"A: Sáu giờ rưỡi anh ấy đang nấu cơm tối. B: Tám giờ rưỡi anh ấy đang giặt quần áo. C: Sáu giờ rưỡi anh ấy đang xem tivi."},"exp":{"id":"Jam 18:30 dan dia sedang memasak.","en":"It is 18:30 and he is cooking.","tl":"18:30 at nagluluto siya.","vi":"Lúc 18:30 và anh ấy đang nấu ăn."}},{"pic":{"i":["girl","cake","birthday"],"b":"8"},"opts":[{"zh":"她在麵包店買麵包。","py":"Tā zài miàn bāo diàn mǎi miàn bāo."},{"zh":"今天她十八歲生日。","py":"Jīn tiān tā shí bā suì shēng rì."},{"zh":"今天是她的生日，她八歲了。","py":"Jīn tiān shì tā de shēng rì, tā bā suì le."}],"a":2,"tr":{"id":"A: Dia membeli roti di toko roti. B: Hari ini ulang tahunnya yang ke-18. C: Hari ini ulang tahunnya, dia sudah 8 tahun.","en":"A: She is buying bread at a bakery. B: Today is her 18th birthday. C: Today is her birthday; she is eight.","tl":"A: Bumibili siya ng tinapay sa panaderya. B: Ika-18 kaarawan niya ngayon. C: Kaarawan niya ngayon; walong taon na siya.","vi":"A: Cô bé đang mua bánh mì ở tiệm bánh. B: Hôm nay là sinh nhật 18 tuổi của cô ấy. C: Hôm nay là sinh nhật cô bé, cô bé tám tuổi rồi."},"exp":{"id":"Ada kue ulang tahun dan angka 8, bukan 18.","en":"There is a birthday cake and the number 8, not 18.","tl":"May birthday cake at numerong 8, hindi 18.","vi":"Có bánh sinh nhật và số 8, không phải 18."}},{"pic":{"i":["couple","cinema"],"bg":"night"},"opts":[{"zh":"他們在餐廳吃晚飯。","py":"Tā men zài cān tīng chī wǎn fàn."},{"zh":"他們晚上去看電影。","py":"Tā men wǎn shàng qù kàn diàn yǐng."},{"zh":"他們在家看電視。","py":"Tā men zài jiā kàn diàn shì."}],"a":1,"tr":{"id":"A: Mereka makan malam di restoran. B: Malam hari mereka pergi menonton film. C: Mereka menonton TV di rumah.","en":"A: They are having dinner at a restaurant. B: They go to see a movie in the evening. C: They are watching TV at home.","tl":"A: Naghahapunan sila sa restawran. B: Nanonood sila ng sine sa gabi. C: Nanonood sila ng TV sa bahay.","vi":"A: Họ đang ăn tối ở nhà hàng. B: Buổi tối họ đi xem phim. C: Họ đang xem tivi ở nhà."},"exp":{"id":"Gambar: pasangan di bioskop pada malam hari.","en":"The picture shows a couple at a cinema at night.","tl":"Magkasintahan sa sinehan sa gabi ang nasa larawan.","vi":"Tranh là một cặp đôi ở rạp chiếu phim buổi tối."}},{"pic":{"i":["boy","listen_music"],"bg":"home"},"opts":[{"zh":"他在打電話。","py":"Tā zài dǎ diàn huà."},{"zh":"他在唱歌。","py":"Tā zài chàng gē."},{"zh":"他在聽音樂。","py":"Tā zài tīng yīn yuè."}],"a":2,"tr":{"id":"A: Dia sedang menelepon. B: Dia sedang bernyanyi. C: Dia sedang mendengarkan musik.","en":"A: He is making a phone call. B: He is singing. C: He is listening to music.","tl":"A: Tumatawag siya sa telepono. B: Kumakanta siya. C: Nakikinig siya ng musika.","vi":"A: Cậu ấy đang gọi điện thoại. B: Cậu ấy đang hát. C: Cậu ấy đang nghe nhạc."},"exp":{"id":"Gambar menunjukkan anak laki-laki mendengarkan musik.","en":"The picture shows a boy listening to music.","tl":"Batang lalaking nakikinig ng musika ang nasa larawan.","vi":"Tranh là cậu bé đang nghe nhạc."}},{"pic":{"i":["swim","swimming_pool"],"b":"32°C","bg":"park"},"opts":[{"zh":"天氣很冷，他在家睡覺。","py":"Tiān qì hěn lěng, tā zài jiā shuì jiào."},{"zh":"天氣很熱，他去游泳。","py":"Tiān qì hěn rè, tā qù yóu yǒng."},{"zh":"下雨了，他沒去游泳。","py":"Xià yǔ le, tā méi qù yóu yǒng."}],"a":1,"tr":{"id":"A: Cuacanya dingin, dia tidur di rumah. B: Cuacanya panas, dia pergi berenang. C: Hujan turun, dia tidak pergi berenang.","en":"A: It's cold, so he is sleeping at home. B: It's hot, so he goes swimming. C: It's raining, so he didn't go swimming.","tl":"A: Malamig, kaya natutulog siya sa bahay. B: Mainit, kaya lumangoy siya. C: Umuulan, kaya hindi siya lumangoy.","vi":"A: Trời lạnh, anh ấy ngủ ở nhà. B: Trời nóng, anh ấy đi bơi. C: Trời mưa, anh ấy không đi bơi."},"exp":{"id":"32°C berarti panas, dan ada orang berenang di kolam.","en":"32°C means hot, and someone is swimming in a pool.","tl":"Mainit ang 32°C at may lumalangoy sa pool.","vi":"32°C là trời nóng, và có người đang bơi ở hồ bơi."}},{"pic":{"i":["old_man","medicine"],"b":"x3"},"opts":[{"zh":"爺爺一天吃三次藥。","py":"Yé ye yì tiān chī sān cì yào."},{"zh":"爺爺一天吃兩次藥。","py":"Yé ye yì tiān chī liǎng cì yào."},{"zh":"奶奶一天吃三次藥。","py":"Nǎi nai yì tiān chī sān cì yào."}],"a":0,"tr":{"id":"A: Kakek minum obat tiga kali sehari. B: Kakek minum obat dua kali sehari. C: Nenek minum obat tiga kali sehari.","en":"A: Grandpa takes medicine three times a day. B: Grandpa takes medicine twice a day. C: Grandma takes medicine three times a day.","tl":"A: Umiinom ng gamot si Lolo nang tatlong beses sa isang araw. B: Umiinom ng gamot si Lolo nang dalawang beses sa isang araw. C: Umiinom ng gamot si Lola nang tatlong beses sa isang araw.","vi":"A: Ông uống thuốc ba lần một ngày. B: Ông uống thuốc hai lần một ngày. C: Bà uống thuốc ba lần một ngày."},"exp":{"id":"Gambar: kakek, obat, dan x3 (tiga kali).","en":"The picture shows an old man, medicine and x3 (three times).","tl":"Lolo, gamot at x3 (tatlong beses) ang nasa larawan.","vi":"Tranh có ông cụ, thuốc và x3 (ba lần)."}}]},{"p":2,"items":[{"dlg":[{"sp":"M","zh":"你哪裡不舒服？","py":"Nǐ nǎ lǐ bù shū fu?"},{"sp":"F","zh":"我頭很痛。","py":"Wǒ tóu hěn tòng."}],"q":{"zh":"女的怎麼了？","py":"Nǚ de zěn me le?"},"opts":[{"i":["woman","fever"]},{"i":["woman","headache"]},{"i":["woman","run"],"bg":"park"}],"a":1,"tr":{"id":"L: Bagian mana yang tidak enak? P: Kepala saya sakit sekali. Pertanyaan: Perempuan itu kenapa?","en":"M: Where do you feel unwell? W: My head really hurts. Q: What's wrong with the woman?","tl":"L: Saan masama ang pakiramdam mo? B: Masakit na masakit ang ulo ko. T: Ano ang nangyari sa babae?","vi":"Nam: Bạn khó chịu ở đâu? Nữ: Tôi đau đầu lắm. Hỏi: Người nữ bị sao?"},"exp":{"id":"Dia bilang 頭很痛, kepalanya sakit.","en":"She says 頭很痛 — she has a headache.","tl":"Sabi niya 頭很痛 — masakit ang ulo niya.","vi":"Cô ấy nói 頭很痛 — bị đau đầu."}},{"dlg":[{"sp":"F","zh":"你週末常做什麼運動？","py":"Nǐ zhōu mò cháng zuò shén me yùn dòng?"},{"sp":"M","zh":"我常去打棒球。","py":"Wǒ cháng qù dǎ bàng qiú."}],"q":{"zh":"男的週末常做什麼？","py":"Nán de zhōu mò cháng zuò shén me?"},"opts":[{"i":["man","basketball"]},{"i":["man","swim"]},{"i":["man","baseball"]}],"a":2,"tr":{"id":"P: Akhir pekan kamu sering olahraga apa? L: Saya sering main bisbol. Pertanyaan: Akhir pekan laki-laki itu sering melakukan apa?","en":"W: What sport do you often do on weekends? M: I often play baseball. Q: What does the man often do on weekends?","tl":"B: Anong isport ang madalas mong gawin tuwing weekend? L: Madalas akong maglaro ng baseball. T: Ano ang madalas gawin ng lalaki tuwing weekend?","vi":"Nữ: Cuối tuần bạn hay chơi môn thể thao gì? Nam: Tôi hay đi chơi bóng chày. Hỏi: Cuối tuần người nam hay làm gì?"},"exp":{"id":"打棒球 = main bisbol.","en":"打棒球 means playing baseball.","tl":"Ang 打棒球 ay paglalaro ng baseball.","vi":"打棒球 là chơi bóng chày."}},{"dlg":[{"sp":"M","zh":"你哥哥做什麼工作？","py":"Nǐ gē ge zuò shén me gōng zuò?"},{"sp":"F","zh":"他是老師，在小學教書。","py":"Tā shì lǎo shī, zài xiǎo xué jiāo shū."}],"q":{"zh":"女的哥哥做什麼工作？","py":"Nǚ de gē ge zuò shén me gōng zuò?"},"opts":[{"i":["teacher","school"]},{"i":["doctor","hospital"]},{"i":["driver","bus"]}],"a":0,"tr":{"id":"L: Kakak laki-lakimu kerja apa? P: Dia guru, mengajar di SD. Pertanyaan: Kakak laki-laki si perempuan bekerja sebagai apa?","en":"M: What does your older brother do? W: He's a teacher; he teaches at an elementary school. Q: What does the woman's older brother do?","tl":"L: Ano ang trabaho ng kuya mo? B: Guro siya, nagtuturo sa elementarya. T: Ano ang trabaho ng kuya ng babae?","vi":"Nam: Anh trai bạn làm nghề gì? Nữ: Anh ấy là giáo viên, dạy ở trường tiểu học. Hỏi: Anh trai của người nữ làm nghề gì?"},"exp":{"id":"Kakaknya 老師 (guru) di sekolah.","en":"Her brother is a 老師 (teacher) at a school.","tl":"Ang kuya niya ay 老師 (guro) sa paaralan.","vi":"Anh trai cô ấy là 老師 (giáo viên) ở trường."}},{"dlg":[{"sp":"F","zh":"我們明天幾點見面？","py":"Wǒ men míng tiān jǐ diǎn jiàn miàn?"},{"sp":"M","zh":"下午兩點，在捷運站。","py":"Xià wǔ liǎng diǎn, zài jié yùn zhàn."}],"q":{"zh":"他們在哪裡見面？","py":"Tā men zài nǎ lǐ jiàn miàn?"},"opts":[{"i":["mrt","station"],"b":"14:00"},{"i":["park"],"b":"14:00"},{"i":["cinema"],"b":"14:00"}],"a":0,"tr":{"id":"P: Besok kita ketemu jam berapa? L: Jam dua siang, di stasiun MRT. Pertanyaan: Mereka bertemu di mana?","en":"W: What time do we meet tomorrow? M: Two p.m., at the MRT station. Q: Where will they meet?","tl":"B: Anong oras tayo magkikita bukas? L: Alas-dos ng hapon, sa istasyon ng MRT. T: Saan sila magkikita?","vi":"Nữ: Ngày mai mấy giờ chúng ta gặp nhau? Nam: Hai giờ chiều, ở ga tàu điện ngầm. Hỏi: Họ gặp nhau ở đâu?"},"exp":{"id":"Mereka bertemu di 捷運站 (stasiun MRT).","en":"They meet at the 捷運站 (MRT station).","tl":"Magkikita sila sa 捷運站 (istasyon ng MRT).","vi":"Họ gặp nhau ở 捷運站 (ga tàu điện ngầm)."}},{"dlg":[{"sp":"M","zh":"電影幾點開始？","py":"Diàn yǐng jǐ diǎn kāi shǐ?"},{"sp":"F","zh":"晚上七點四十分。","py":"Wǎn shàng qī diǎn sì shí fēn."}],"q":{"zh":"電影幾點開始？","py":"Diàn yǐng jǐ diǎn kāi shǐ?"},"opts":[{"i":["movie","clock"],"b":"17:40"},{"i":["movie","clock"],"b":"19:40"},{"i":["movie","clock"],"b":"19:04"}],"a":1,"tr":{"id":"L: Filmnya mulai jam berapa? P: Jam tujuh lewat empat puluh malam. Pertanyaan: Film mulai jam berapa?","en":"M: What time does the movie start? W: 7:40 in the evening. Q: What time does the movie start?","tl":"L: Anong oras magsisimula ang sine? B: Alas-siyete kuwarenta ng gabi. T: Anong oras magsisimula ang sine?","vi":"Nam: Phim mấy giờ bắt đầu? Nữ: Bảy giờ bốn mươi tối. Hỏi: Phim mấy giờ bắt đầu?"},"exp":{"id":"晚上七點四十分 = 19:40, bukan 19:04.","en":"晚上七點四十分 is 19:40, not 19:04.","tl":"Ang 晚上七點四十分 ay 19:40, hindi 19:04.","vi":"晚上七點四十分 là 19:40, không phải 19:04."}},{"dlg":[{"sp":"F","zh":"你喜歡做什麼？","py":"Nǐ xǐ huān zuò shén me?"},{"sp":"M","zh":"我喜歡唱歌，也喜歡跳舞。","py":"Wǒ xǐ huān chàng gē, yě xǐ huān tiào wǔ."}],"q":{"zh":"男的喜歡做什麼？","py":"Nán de xǐ huān zuò shén me?"},"opts":[{"i":["man","read","dance"]},{"i":["man","sing","swim"]},{"i":["man","sing","dance"]}],"a":2,"tr":{"id":"P: Kamu suka melakukan apa? L: Saya suka bernyanyi, juga suka menari. Pertanyaan: Laki-laki itu suka melakukan apa?","en":"W: What do you like to do? M: I like singing, and I also like dancing. Q: What does the man like to do?","tl":"B: Ano ang gusto mong gawin? L: Gusto kong kumanta, at gusto ko ring sumayaw. T: Ano ang gustong gawin ng lalaki?","vi":"Nữ: Bạn thích làm gì? Nam: Tôi thích hát, cũng thích nhảy. Hỏi: Người nam thích làm gì?"},"exp":{"id":"Dia suka 唱歌 dan 跳舞.","en":"He likes both 唱歌 (singing) and 跳舞 (dancing).","tl":"Gusto niya ang 唱歌 at 跳舞.","vi":"Anh ấy thích cả 唱歌 (hát) và 跳舞 (nhảy)."}},{"dlg":[{"sp":"M","zh":"媽，我可以幫你做什麼？","py":"Mā, wǒ kě yǐ bāng nǐ zuò shén me?"},{"sp":"F","zh":"你幫我去便利商店買牛奶吧。","py":"Nǐ bāng wǒ qù biàn lì shāng diàn mǎi niú nǎi ba."}],"q":{"zh":"女的要男的買什麼？","py":"Nǚ de yào nán de mǎi shén me?"},"opts":[{"i":["store","milk"]},{"i":["store","egg"]},{"i":["store","bread"]}],"a":0,"tr":{"id":"L: Ma, aku bisa bantu apa? P: Tolong belikan susu di minimarket. Pertanyaan: Perempuan itu menyuruh laki-laki itu membeli apa?","en":"M: Mom, what can I help you with? W: Go to the convenience store and buy some milk for me. Q: What does the woman want the man to buy?","tl":"L: Ma, ano ang maitutulong ko? B: Bilhan mo ako ng gatas sa convenience store. T: Ano ang ipinabibili ng babae sa lalaki?","vi":"Nam: Mẹ ơi, con giúp mẹ được gì? Nữ: Con đi cửa hàng tiện lợi mua sữa giúp mẹ nhé. Hỏi: Người nữ bảo người nam mua gì?"},"exp":{"id":"Dia minta beli 牛奶 (susu).","en":"She asks him to buy 牛奶 (milk).","tl":"Ipinabili niya ang 牛奶 (gatas).","vi":"Bà ấy nhờ mua 牛奶 (sữa)."}},{"dlg":[{"sp":"F","zh":"你妹妹生日，你送她什麼？","py":"Nǐ mèi mei shēng rì, nǐ sòng tā shén me?"},{"sp":"M","zh":"我送她一本書。","py":"Wǒ sòng tā yì běn shū."}],"q":{"zh":"男的送妹妹什麼？","py":"Nán de sòng mèi mei shén me?"},"opts":[{"i":["gift","watch"]},{"i":["gift","book"]},{"i":["gift","handbag"]}],"a":1,"tr":{"id":"P: Adikmu ulang tahun, kamu kasih hadiah apa? L: Saya kasih dia sebuah buku. Pertanyaan: Laki-laki itu memberi adiknya apa?","en":"W: It's your younger sister's birthday; what are you giving her? M: I'm giving her a book. Q: What does the man give his sister?","tl":"B: Kaarawan ng nakababata mong kapatid; ano ang ireregalo mo? L: Bibigyan ko siya ng libro. T: Ano ang regalo ng lalaki sa kapatid niya?","vi":"Nữ: Sinh nhật em gái, bạn tặng em ấy gì? Nam: Tôi tặng em ấy một quyển sách. Hỏi: Người nam tặng em gái cái gì?"},"exp":{"id":"一本書 = sebuah buku.","en":"一本書 means a book.","tl":"Ang 一本書 ay isang libro.","vi":"一本書 là một quyển sách."}},{"dlg":[{"sp":"M","zh":"醫生說你要吃藥嗎？","py":"Yī shēng shuō nǐ yào chī yào ma?"},{"sp":"F","zh":"不用吃藥，多喝水、多休息就好了。","py":"Bú yòng chī yào, duō hē shuǐ, duō xiū xí jiù hǎo le."}],"q":{"zh":"醫生要女的做什麼？","py":"Yī shēng yào nǚ de zuò shén me?"},"opts":[{"i":["woman","medicine"]},{"i":["water","bed"]},{"i":["woman","run"],"bg":"park"}],"a":1,"tr":{"id":"L: Dokter bilang kamu harus minum obat? P: Tidak perlu obat, cukup banyak minum air dan banyak istirahat. Pertanyaan: Dokter menyuruh perempuan itu melakukan apa?","en":"M: Did the doctor say you need to take medicine? W: No medicine; just drink lots of water and rest a lot. Q: What does the doctor want the woman to do?","tl":"L: Sabi ba ng doktor kailangan mong uminom ng gamot? B: Hindi na kailangan; uminom lang ng maraming tubig at magpahinga nang husto. T: Ano ang ipinagagawa ng doktor sa babae?","vi":"Nam: Bác sĩ nói bạn phải uống thuốc à? Nữ: Không cần uống thuốc, uống nhiều nước, nghỉ ngơi nhiều là được. Hỏi: Bác sĩ bảo người nữ làm gì?"},"exp":{"id":"不用吃藥 — cukup minum air dan istirahat.","en":"不用吃藥 — just water and rest.","tl":"不用吃藥 — tubig at pahinga lang.","vi":"不用吃藥 — chỉ cần uống nước và nghỉ ngơi."}},{"dlg":[{"sp":"F","zh":"你每天怎麼去上班？","py":"Nǐ měi tiān zěn me qù shàng bān?"},{"sp":"M","zh":"我騎機車去公司。","py":"Wǒ qí jī chē qù gōng sī."}],"q":{"zh":"男的怎麼去上班？","py":"Nán de zěn me qù shàng bān?"},"opts":[{"i":["man","bicycle"]},{"i":["man","mrt"]},{"i":["man","scooter"]}],"a":2,"tr":{"id":"P: Setiap hari kamu berangkat kerja naik apa? L: Saya naik motor ke kantor. Pertanyaan: Laki-laki itu berangkat kerja naik apa?","en":"W: How do you get to work every day? M: I ride my scooter to the office. Q: How does the man get to work?","tl":"B: Paano ka pumapasok sa trabaho araw-araw? L: Nagmo-motorsiklo ako papunta sa opisina. T: Paano pumapasok sa trabaho ang lalaki?","vi":"Nữ: Mỗi ngày bạn đi làm bằng gì? Nam: Tôi đi xe máy đến công ty. Hỏi: Người nam đi làm bằng gì?"},"exp":{"id":"騎機車 = naik sepeda motor, bukan sepeda.","en":"騎機車 means riding a scooter, not a bicycle.","tl":"Ang 騎機車 ay pagsakay sa motorsiklo, hindi bisikleta.","vi":"騎機車 là đi xe máy, không phải xe đạp."}},{"dlg":[{"sp":"M","zh":"你常常去游泳嗎？","py":"Nǐ cháng cháng qù yóu yǒng ma?"},{"sp":"F","zh":"我一個星期去三次。","py":"Wǒ yí ge xīng qí qù sān cì."}],"q":{"zh":"女的一個星期去游泳幾次？","py":"Nǚ de yí ge xīng qí qù yóu yǒng jǐ cì?"},"opts":[{"i":["swimming_pool","calendar"],"b":"x2"},{"i":["swimming_pool","calendar"],"b":"x4"},{"i":["swimming_pool","calendar"],"b":"x3"}],"a":2,"tr":{"id":"L: Kamu sering berenang? P: Saya pergi tiga kali seminggu. Pertanyaan: Perempuan itu berenang berapa kali seminggu?","en":"M: Do you go swimming often? W: I go three times a week. Q: How many times a week does the woman go swimming?","tl":"L: Madalas ka bang lumangoy? B: Tatlong beses ako pumupunta sa isang linggo. T: Ilang beses lumalangoy ang babae sa isang linggo?","vi":"Nam: Bạn có hay đi bơi không? Nữ: Tôi đi một tuần ba lần. Hỏi: Người nữ đi bơi mấy lần một tuần?"},"exp":{"id":"三次 = tiga kali (x3).","en":"三次 means three times (x3).","tl":"Ang 三次 ay tatlong beses (x3).","vi":"三次 là ba lần (x3)."}},{"dlg":[{"sp":"F","zh":"你的興趣是什麼？","py":"Nǐ de xìng qù shì shén me?"},{"sp":"M","zh":"我喜歡照相。","py":"Wǒ xǐ huān zhào xiàng."}],"q":{"zh":"男的喜歡做什麼？","py":"Nán de xǐ huān zuò shén me?"},"opts":[{"i":["man","camera"]},{"i":["man","game"]},{"i":["man","book"]}],"a":0,"tr":{"id":"P: Hobimu apa? L: Saya suka memotret. Pertanyaan: Laki-laki itu suka melakukan apa?","en":"W: What are your hobbies? M: I like taking photos. Q: What does the man like to do?","tl":"B: Ano ang hilig mo? L: Gusto kong kumuha ng litrato. T: Ano ang gustong gawin ng lalaki?","vi":"Nữ: Sở thích của bạn là gì? Nam: Tôi thích chụp ảnh. Hỏi: Người nam thích làm gì?"},"exp":{"id":"照相 = memotret, pakai kamera.","en":"照相 means taking photos with a camera.","tl":"Ang 照相 ay pagkuha ng litrato gamit ang kamera.","vi":"照相 là chụp ảnh bằng máy ảnh."}},{"dlg":[{"sp":"M","zh":"中秋節你要做什麼？","py":"Zhōng qiū jié nǐ yào zuò shén me?"},{"sp":"F","zh":"我要回家跟家人一起烤肉。","py":"Wǒ yào huí jiā gēn jiā rén yì qǐ kǎo ròu."}],"q":{"zh":"女的中秋節要做什麼？","py":"Nǚ de zhōng qiū jié yào zuò shén me?"},"opts":[{"i":["friends","cinema"]},{"i":["family","dumplings"]},{"i":["family","meat"]}],"a":2,"tr":{"id":"L: Festival Kue Bulan kamu mau apa? P: Saya mau pulang dan barbekyu bersama keluarga. Pertanyaan: Apa yang akan dilakukan perempuan itu saat Festival Kue Bulan?","en":"M: What are you doing for the Mid-Autumn Festival? W: I'm going home to have a barbecue with my family. Q: What will the woman do at the Mid-Autumn Festival?","tl":"L: Ano ang gagawin mo sa Mid-Autumn Festival? B: Uuwi ako para mag-ihaw kasama ang pamilya ko. T: Ano ang gagawin ng babae sa Mid-Autumn Festival?","vi":"Nam: Tết Trung thu bạn định làm gì? Nữ: Tôi về nhà nướng thịt cùng gia đình. Hỏi: Tết Trung thu người nữ sẽ làm gì?"},"exp":{"id":"烤肉 bersama 家人 (keluarga).","en":"She'll barbecue (烤肉) with her family (家人).","tl":"Mag-iihaw (烤肉) siya kasama ang pamilya (家人).","vi":"Cô ấy nướng thịt (烤肉) với gia đình (家人)."}},{"dlg":[{"sp":"F","zh":"明天會下雨嗎？","py":"Míng tiān huì xià yǔ ma?"},{"sp":"M","zh":"不會，明天是晴天。","py":"Bú huì, míng tiān shì qíng tiān."}],"q":{"zh":"明天天氣怎麼樣？","py":"Míng tiān tiān qì zěn me yàng?"},"opts":[{"i":["rain"],"bg":"rain"},{"i":["sun"]},{"i":["cloud","wind"]}],"a":1,"tr":{"id":"P: Besok akan hujan? L: Tidak, besok cerah. Pertanyaan: Bagaimana cuaca besok?","en":"W: Will it rain tomorrow? M: No, tomorrow will be sunny. Q: What will the weather be like tomorrow?","tl":"B: Uulan ba bukas? L: Hindi, maaraw bukas. T: Ano ang magiging panahon bukas?","vi":"Nữ: Ngày mai có mưa không? Nam: Không, ngày mai trời nắng. Hỏi: Thời tiết ngày mai thế nào?"},"exp":{"id":"晴天 = cuaca cerah.","en":"晴天 means a sunny day.","tl":"Ang 晴天 ay maaraw na araw.","vi":"晴天 là trời nắng."}},{"dlg":[{"sp":"M","zh":"這雙球鞋多少錢？","py":"Zhè shuāng qiú xié duō shǎo qián?"},{"sp":"F","zh":"一千兩百塊。","py":"Yì qiān liǎng bǎi kuài."}],"q":{"zh":"這雙球鞋多少錢？","py":"Zhè shuāng qiú xié duō shǎo qián?"},"opts":[{"i":["shoes"],"b":"NT$1200","bg":"shop"},{"i":["shoes"],"b":"NT$1020","bg":"shop"},{"i":["shoes"],"b":"NT$2100","bg":"shop"}],"a":0,"tr":{"id":"L: Sepatu olahraga ini berapa? P: Seribu dua ratus. Pertanyaan: Berapa harga sepatu ini?","en":"M: How much are these sneakers? W: 1,200 dollars. Q: How much are the sneakers?","tl":"L: Magkano ang sapatos na ito? B: Isang libo't dalawandaan. T: Magkano ang sapatos?","vi":"Nam: Đôi giày thể thao này bao nhiêu tiền? Nữ: Một nghìn hai trăm. Hỏi: Đôi giày bao nhiêu tiền?"},"exp":{"id":"一千兩百 = 1200.","en":"一千兩百 is 1200.","tl":"Ang 一千兩百 ay 1200.","vi":"一千兩百 là 1200."}}]},{"p":3,"items":[{"dlg":[{"sp":"M","zh":"你今天怎麼沒來上課？","py":"Nǐ jīn tiān zěn me méi lái shàng kè?"},{"sp":"F","zh":"我頭痛，去看醫生了。","py":"Wǒ tóu tòng, qù kàn yī shēng le."},{"sp":"M","zh":"你感冒了嗎？要吃藥嗎？","py":"Nǐ gǎn mào le ma? Yào chī yào ma?"},{"sp":"F","zh":"不是感冒，醫生說我太累了，不用吃藥，多睡覺就好。","py":"Bú shì gǎn mào, yī shēng shuō wǒ tài lèi le, bú yòng chī yào, duō shuì jiào jiù hǎo."}],"q":{"zh":"醫生要女的做什麼？","py":"Yī shēng yào nǚ de zuò shén me?"},"opts":[{"i":["woman","medicine"]},{"i":["woman","sleep"],"bg":"home"},{"i":["woman","run"],"bg":"park"}],"a":1,"tr":{"id":"L: Kenapa hari ini kamu tidak masuk kelas? P: Kepalaku sakit, aku ke dokter. L: Kamu flu? Harus minum obat? P: Bukan flu. Dokter bilang aku terlalu capek, tidak perlu obat, cukup banyak tidur. Pertanyaan: Dokter menyuruh perempuan itu melakukan apa?","en":"M: Why didn't you come to class today? W: I had a headache, so I went to the doctor. M: Do you have a cold? Do you need medicine? W: It's not a cold. The doctor said I'm too tired; no medicine, I just need more sleep. Q: What does the doctor want the woman to do?","tl":"L: Bakit hindi ka pumasok sa klase ngayon? B: Masakit ang ulo ko, kaya nagpatingin ako sa doktor. L: Sipon ba? Kailangan mo bang uminom ng gamot? B: Hindi sipon. Sabi ng doktor pagod lang ako; hindi kailangan ng gamot, matulog lang nang mas marami. T: Ano ang ipinagagawa ng doktor sa babae?","vi":"Nam: Sao hôm nay bạn không đi học? Nữ: Tôi đau đầu nên đi khám bác sĩ. Nam: Bạn bị cảm à? Phải uống thuốc không? Nữ: Không phải cảm. Bác sĩ nói tôi mệt quá, không cần uống thuốc, ngủ nhiều là được. Hỏi: Bác sĩ bảo người nữ làm gì?"},"exp":{"id":"不用吃藥，多睡覺 — cukup banyak tidur.","en":"不用吃藥，多睡覺 — no medicine, just sleep more.","tl":"不用吃藥，多睡覺 — matulog lang nang marami.","vi":"不用吃藥，多睡覺 — không cần thuốc, chỉ cần ngủ nhiều."}},{"dlg":[{"sp":"F","zh":"星期六我們去打網球，好不好？","py":"Xīng qí liù wǒ men qù dǎ wǎng qiú, hǎo bù hǎo?"},{"sp":"M","zh":"好啊。幾點？","py":"Hǎo a. Jǐ diǎn?"},{"sp":"F","zh":"早上九點。","py":"Zǎo shàng jiǔ diǎn."},{"sp":"M","zh":"九點太早了，十點吧。","py":"Jiǔ diǎn tài zǎo le, shí diǎn ba."},{"sp":"F","zh":"好，那十點見。","py":"Hǎo, nà shí diǎn jiàn."}],"q":{"zh":"他們星期六幾點去打網球？","py":"Tā men xīng qí liù jǐ diǎn qù dǎ wǎng qiú?"},"opts":[{"i":["tennis","clock"],"b":"10:00"},{"i":["tennis","clock"],"b":"09:00"},{"i":["tennis","clock"],"b":"08:00"}],"a":0,"tr":{"id":"P: Sabtu kita main tenis, ya? L: Oke. Jam berapa? P: Jam sembilan pagi. L: Jam sembilan terlalu pagi, jam sepuluh saja. P: Baik, sampai jumpa jam sepuluh. Pertanyaan: Sabtu mereka main tenis jam berapa?","en":"W: Let's play tennis on Saturday, okay? M: Sure. What time? W: Nine in the morning. M: Nine is too early; let's do ten. W: Okay, see you at ten. Q: What time will they play tennis on Saturday?","tl":"B: Maglaro tayo ng tennis sa Sabado, ha? L: Sige. Anong oras? B: Alas-nuwebe ng umaga. L: Masyadong maaga ang alas-nuwebe; alas-diyes na lang. B: Sige, kita tayo nang alas-diyes. T: Anong oras sila maglalaro ng tennis sa Sabado?","vi":"Nữ: Thứ bảy chúng ta đi chơi quần vợt nhé? Nam: Được. Mấy giờ? Nữ: Chín giờ sáng. Nam: Chín giờ sớm quá, mười giờ đi. Nữ: Được, vậy mười giờ gặp. Hỏi: Thứ bảy mấy giờ họ đi chơi quần vợt?"},"exp":{"id":"Jam 9 diganti menjadi 十點 (jam 10).","en":"Nine was changed to 十點 (ten o'clock).","tl":"Pinalitan ang alas-nuwebe ng 十點 (alas-diyes).","vi":"Chín giờ được đổi thành 十點 (mười giờ)."}},{"dlg":[{"sp":"M","zh":"你找到工作了嗎？","py":"Nǐ zhǎo dào gōng zuò le ma?"},{"sp":"F","zh":"找到了。我下個月開始上班。","py":"Zhǎo dào le. Wǒ xià ge yuè kāi shǐ shàng bān."},{"sp":"M","zh":"在郵局嗎？你上次說想去郵局。","py":"Zài yóu jú ma? Nǐ shàng cì shuō xiǎng qù yóu jú."},{"sp":"F","zh":"不是，郵局太遠了。我在銀行工作。","py":"Bú shì, yóu jú tài yuǎn le. Wǒ zài yín háng gōng zuò."}],"q":{"zh":"女的在哪裡工作？","py":"Nǚ de zài nǎ lǐ gōng zuò?"},"opts":[{"i":["post_office","letter"]},{"i":["hospital"]},{"i":["bank","money"]}],"a":2,"tr":{"id":"L: Kamu sudah dapat kerja? P: Sudah. Bulan depan aku mulai kerja. L: Di kantor pos? Waktu itu kamu bilang mau ke kantor pos. P: Bukan, kantor posnya terlalu jauh. Aku kerja di bank. Pertanyaan: Perempuan itu bekerja di mana?","en":"M: Have you found a job? W: Yes. I start next month. M: At the post office? Last time you said you wanted to work there. W: No, the post office is too far. I'm working at a bank. Q: Where does the woman work?","tl":"L: Nakahanap ka na ba ng trabaho? B: Oo. Magsisimula ako sa susunod na buwan. L: Sa post office ba? Sabi mo dati gusto mo roon. B: Hindi, masyadong malayo ang post office. Sa bangko ako magtatrabaho. T: Saan nagtatrabaho ang babae?","vi":"Nam: Bạn tìm được việc chưa? Nữ: Tìm được rồi. Tháng sau tôi bắt đầu đi làm. Nam: Ở bưu điện à? Lần trước bạn nói muốn làm ở bưu điện. Nữ: Không, bưu điện xa quá. Tôi làm ở ngân hàng. Hỏi: Người nữ làm việc ở đâu?"},"exp":{"id":"Bukan kantor pos; dia bekerja di 銀行 (bank).","en":"Not the post office; she works at a 銀行 (bank).","tl":"Hindi sa post office; sa 銀行 (bangko) siya.","vi":"Không phải bưu điện; cô ấy làm ở 銀行 (ngân hàng)."}},{"dlg":[{"sp":"F","zh":"晚上一起吃飯吧？","py":"Wǎn shàng yì qǐ chī fàn ba?"},{"sp":"M","zh":"好啊，去夜市怎麼樣？","py":"Hǎo a, qù yè shì zěn me yàng?"},{"sp":"F","zh":"夜市人太多了，我們去那家日本餐廳吧。","py":"Yè shì rén tài duō le, wǒ men qù nà jiā Rì běn cān tīng ba."},{"sp":"M","zh":"好，就這樣。","py":"Hǎo, jiù zhè yàng."}],"q":{"zh":"他們晚上要去哪裡吃飯？","py":"Tā men wǎn shàng yào qù nǎ lǐ chī fàn?"},"opts":[{"i":["night_market"],"bg":"night"},{"i":["restaurant","fish_food"],"bg":"night"},{"i":["house","rice"],"bg":"home"}],"a":1,"tr":{"id":"P: Malam ini makan bareng, yuk? L: Oke, bagaimana kalau ke pasar malam? P: Pasar malam terlalu ramai, kita ke restoran Jepang itu saja. L: Oke, begitu saja. Pertanyaan: Malam ini mereka makan di mana?","en":"W: Shall we have dinner together tonight? M: Sure, how about the night market? W: The night market is too crowded; let's go to that Japanese restaurant. M: Okay, deal. Q: Where will they eat tonight?","tl":"B: Sabay tayong maghapunan mamaya? L: Sige, sa night market kaya? B: Masyadong maraming tao sa night market; doon na lang tayo sa Japanese restaurant. L: Sige, ganoon na lang. T: Saan sila kakain mamayang gabi?","vi":"Nữ: Tối nay đi ăn cùng nhau nhé? Nam: Được, đi chợ đêm thế nào? Nữ: Chợ đêm đông người quá, chúng ta đi nhà hàng Nhật kia đi. Nam: Được, vậy nhé. Hỏi: Tối nay họ đi ăn ở đâu?"},"exp":{"id":"Pasar malam ditolak; mereka ke 日本餐廳.","en":"The night market was rejected; they go to the 日本餐廳 (Japanese restaurant).","tl":"Hindi sa night market; sa 日本餐廳 sila pupunta.","vi":"Không đi chợ đêm; họ đi 日本餐廳 (nhà hàng Nhật)."}},{"dlg":[{"sp":"M","zh":"星期天要不要去看電影？","py":"Xīng qí tiān yào bú yào qù kàn diàn yǐng?"},{"sp":"F","zh":"好啊，可是電影票很貴。","py":"Hǎo a, kě shì diàn yǐng piào hěn guì."},{"sp":"M","zh":"那我們在我家看電視，我買飲料。","py":"Nà wǒ men zài wǒ jiā kàn diàn shì, wǒ mǎi yǐn liào."},{"sp":"F","zh":"好，就這麼辦。","py":"Hǎo, jiù zhè me bàn."}],"q":{"zh":"他們星期天要做什麼？","py":"Tā men xīng qí tiān yào zuò shén me?"},"opts":[{"i":["friends","tv"],"bg":"home"},{"i":["friends","cinema"]},{"i":["friends","sing"]}],"a":0,"tr":{"id":"L: Hari Minggu mau nonton film? P: Boleh, tapi tiket bioskop mahal. L: Kalau begitu kita nonton TV di rumahku, aku beli minuman. P: Oke, begitu saja. Pertanyaan: Hari Minggu mereka akan melakukan apa?","en":"M: Do you want to see a movie on Sunday? W: Sure, but movie tickets are expensive. M: Then let's watch TV at my place; I'll buy drinks. W: Okay, let's do that. Q: What will they do on Sunday?","tl":"L: Gusto mo bang manood ng sine sa Linggo? B: Sige, pero mahal ang tiket. L: Kung gayon, manood na lang tayo ng TV sa bahay ko; ako ang bibili ng inumin. B: Sige, ganoon na lang. T: Ano ang gagawin nila sa Linggo?","vi":"Nam: Chủ nhật có muốn đi xem phim không? Nữ: Được, nhưng vé xem phim đắt lắm. Nam: Vậy chúng ta xem tivi ở nhà tôi, tôi mua đồ uống. Nữ: Được, cứ thế đi. Hỏi: Chủ nhật họ sẽ làm gì?"},"exp":{"id":"Tiket mahal, jadi 在我家看電視.","en":"Tickets are expensive, so they'll 在我家看電視 (watch TV at his place).","tl":"Mahal ang tiket, kaya 在我家看電視 sila.","vi":"Vé đắt nên họ 在我家看電視 (xem tivi ở nhà)."}},{"dlg":[{"sp":"F","zh":"今天晚上誰做飯？","py":"Jīn tiān wǎn shàng shéi zuò fàn?"},{"sp":"M","zh":"我做飯吧。","py":"Wǒ zuò fàn ba."},{"sp":"F","zh":"不好，你上次做的菜不好吃。","py":"Bù hǎo, nǐ shàng cì zuò de cài bù hǎo chī."},{"sp":"M","zh":"好吧，那你做飯，我去買菜。","py":"Hǎo ba, nà nǐ zuò fàn, wǒ qù mǎi cài."}],"q":{"zh":"男的要做什麼？","py":"Nán de yào zuò shén me?"},"opts":[{"i":["man","cook"],"bg":"home"},{"i":["man","watch_tv"],"bg":"home"},{"i":["man","shop","vegetables"]}],"a":2,"tr":{"id":"P: Malam ini siapa yang masak? L: Aku saja. P: Jangan, masakanmu kemarin tidak enak. L: Baiklah, kamu yang masak, aku belanja sayur. Pertanyaan: Laki-laki itu akan melakukan apa?","en":"W: Who's cooking tonight? M: I'll cook. W: No, the food you made last time wasn't good. M: Fine, you cook and I'll go buy groceries. Q: What will the man do?","tl":"B: Sino ang magluluto mamayang gabi? L: Ako na. B: Huwag, hindi masarap ang niluto mo noong huli. L: Sige, ikaw ang magluto, ako ang mamamalengke. T: Ano ang gagawin ng lalaki?","vi":"Nữ: Tối nay ai nấu cơm? Nam: Để tôi nấu. Nữ: Không được, lần trước anh nấu không ngon. Nam: Thôi được, em nấu, anh đi mua thức ăn. Hỏi: Người nam sẽ làm gì?"},"exp":{"id":"Akhirnya dia 去買菜 (belanja), bukan memasak.","en":"In the end he will 去買菜 (buy groceries), not cook.","tl":"Sa huli, 去買菜 (mamamalengke) siya, hindi magluluto.","vi":"Cuối cùng anh ấy 去買菜 (đi mua thức ăn), không nấu."}},{"dlg":[{"sp":"M","zh":"你的生日會在哪裡？","py":"Nǐ de shēng rì huì zài nǎ lǐ?"},{"sp":"F","zh":"本來想在餐廳，後來決定在我家。","py":"Běn lái xiǎng zài cān tīng, hòu lái jué dìng zài wǒ jiā."},{"sp":"M","zh":"為什麼不在餐廳？","py":"Wèi shén me bú zài cān tīng?"},{"sp":"F","zh":"餐廳太貴了，在家比較方便。","py":"Cān tīng tài guì le, zài jiā bǐ jiào fāng biàn."}],"q":{"zh":"生日會在哪裡？","py":"Shēng rì huì zài nǎ lǐ?"},"opts":[{"i":["restaurant","cake"]},{"i":["park","cake"]},{"i":["house","cake"],"bg":"home"}],"a":2,"tr":{"id":"L: Pesta ulang tahunmu di mana? P: Awalnya mau di restoran, lalu kuputuskan di rumahku. L: Kenapa tidak di restoran? P: Restoran terlalu mahal, di rumah lebih praktis. Pertanyaan: Pesta ulang tahunnya di mana?","en":"M: Where is your birthday party? W: At first I wanted a restaurant, but then I decided on my home. M: Why not a restaurant? W: Restaurants are too expensive; home is more convenient. Q: Where is the birthday party?","tl":"L: Saan ang birthday party mo? B: Noong una gusto ko sa restawran, pero nagpasya akong sa bahay na lang. L: Bakit hindi sa restawran? B: Masyadong mahal; mas maginhawa sa bahay. T: Saan ang birthday party?","vi":"Nam: Tiệc sinh nhật của bạn ở đâu? Nữ: Lúc đầu định ở nhà hàng, sau quyết định ở nhà tôi. Nam: Sao không ở nhà hàng? Nữ: Nhà hàng đắt quá, ở nhà tiện hơn. Hỏi: Tiệc sinh nhật ở đâu?"},"exp":{"id":"本來 restoran, 後來 di rumah.","en":"本來 a restaurant, 後來 (later) her home.","tl":"本來 sa restawran, 後來 sa bahay.","vi":"本來 nhà hàng, 後來 (sau đó) ở nhà."}},{"dlg":[{"sp":"F","zh":"喂，我想看醫生，明天上午可以嗎？","py":"Wéi, wǒ xiǎng kàn yī shēng, míng tiān shàng wǔ kě yǐ ma?"},{"sp":"M","zh":"明天上午醫生不在，下午三點可以嗎？","py":"Míng tiān shàng wǔ yī shēng bú zài, xià wǔ sān diǎn kě yǐ ma?"},{"sp":"F","zh":"三點我要上課，四點呢？","py":"Sān diǎn wǒ yào shàng kè, sì diǎn ne?"},{"sp":"M","zh":"可以，四點見。","py":"Kě yǐ, sì diǎn jiàn."}],"q":{"zh":"女的明天幾點看醫生？","py":"Nǚ de míng tiān jǐ diǎn kàn yī shēng?"},"opts":[{"i":["doctor","clock"],"b":"16:00"},{"i":["doctor","clock"],"b":"15:00"},{"i":["doctor","clock"],"b":"10:00"}],"a":0,"tr":{"id":"P: Halo, saya mau periksa ke dokter, besok pagi bisa? L: Besok pagi dokter tidak ada, jam tiga sore bisa? P: Jam tiga saya ada kelas, jam empat bagaimana? L: Bisa, sampai jumpa jam empat. Pertanyaan: Besok jam berapa perempuan itu ke dokter?","en":"W: Hello, I'd like to see the doctor. Is tomorrow morning okay? M: The doctor isn't in tomorrow morning; is 3 p.m. okay? W: I have class at three; how about four? M: Sure, see you at four. Q: What time will the woman see the doctor tomorrow?","tl":"B: Hello, gusto kong magpatingin sa doktor; puwede ba bukas ng umaga? L: Wala ang doktor bukas ng umaga; puwede ba ang alas-tres ng hapon? B: May klase ako nang alas-tres; e alas-kuwatro? L: Puwede, kita tayo nang alas-kuwatro. T: Anong oras magpapatingin ang babae bukas?","vi":"Nữ: Alô, tôi muốn khám bác sĩ, sáng mai được không? Nam: Sáng mai bác sĩ không có, ba giờ chiều được không? Nữ: Ba giờ tôi phải đi học, bốn giờ thì sao? Nam: Được, bốn giờ gặp. Hỏi: Ngày mai mấy giờ người nữ đi khám?"},"exp":{"id":"Pagi dan jam tiga tidak bisa; akhirnya 四點 (16:00).","en":"Morning and three don't work; finally 四點 (16:00).","tl":"Hindi puwede ang umaga at alas-tres; 四點 (16:00) ang huli.","vi":"Sáng và ba giờ đều không được; cuối cùng là 四點 (16:00)."}},{"dlg":[{"sp":"F","zh":"你以前常踢足球，現在還踢嗎？","py":"Nǐ yǐ qián cháng tī zú qiú, xiàn zài hái tī ma?"},{"sp":"M","zh":"不踢了，我現在每天早上跑步。","py":"Bù tī le, wǒ xiàn zài měi tiān zǎo shàng pǎo bù."},{"sp":"F","zh":"跑多久？","py":"Pǎo duō jiǔ?"},{"sp":"M","zh":"半個小時。","py":"Bàn ge xiǎo shí."}],"q":{"zh":"男的現在做什麼運動？","py":"Nán de xiàn zài zuò shén me yùn dòng?"},"opts":[{"i":["man","soccer"]},{"i":["man","run"],"bg":"park"},{"i":["man","basketball"]}],"a":1,"tr":{"id":"P: Dulu kamu sering main sepak bola, sekarang masih? L: Tidak lagi, sekarang aku lari setiap pagi. P: Berapa lama? L: Setengah jam. Pertanyaan: Sekarang laki-laki itu olahraga apa?","en":"W: You used to play soccer a lot. Do you still play? M: Not anymore. Now I run every morning. W: For how long? M: Half an hour. Q: What sport does the man do now?","tl":"B: Madalas kang mag-soccer dati; naglalaro ka pa ba? L: Hindi na. Tumatakbo na ako tuwing umaga ngayon. B: Gaano katagal? L: Kalahating oras. T: Anong isport ang ginagawa ng lalaki ngayon?","vi":"Nữ: Trước đây bạn hay đá bóng, bây giờ còn đá không? Nam: Không đá nữa, bây giờ sáng nào tôi cũng chạy bộ. Nữ: Chạy bao lâu? Nam: Nửa tiếng. Hỏi: Bây giờ người nam chơi môn thể thao gì?"},"exp":{"id":"不踢了 — sekarang 跑步 (lari).","en":"不踢了 (no more soccer) — now he 跑步 (runs).","tl":"不踢了 — 跑步 (tumatakbo) na siya ngayon.","vi":"不踢了 — bây giờ anh ấy 跑步 (chạy bộ)."}},{"dlg":[{"sp":"F","zh":"下星期是爸爸的生日，我們送他什麼？","py":"Xià xīng qí shì bà ba de shēng rì, wǒ men sòng tā shén me?"},{"sp":"M","zh":"送他一支手錶怎麼樣？","py":"Sòng tā yì zhī shǒu biǎo zěn me yàng?"},{"sp":"F","zh":"他已經有很多手錶了，送他一件襯衫吧。","py":"Tā yǐ jīng yǒu hěn duō shǒu biǎo le, sòng tā yí jiàn chèn shān ba."},{"sp":"M","zh":"好，明天去買。","py":"Hǎo, míng tiān qù mǎi."}],"q":{"zh":"他們要送爸爸什麼？","py":"Tā men yào sòng bà ba shén me?"},"opts":[{"i":["gift","watch"]},{"i":["gift","hat"]},{"i":["gift","shirt"]}],"a":2,"tr":{"id":"P: Minggu depan ulang tahun Ayah, kita kasih apa? L: Bagaimana kalau jam tangan? P: Dia sudah punya banyak jam tangan, kasih kemeja saja. L: Oke, besok kita beli. Pertanyaan: Mereka akan memberi Ayah apa?","en":"W: Next week is Dad's birthday. What should we give him? M: How about a watch? W: He already has lots of watches; let's give him a shirt. M: Okay, we'll buy it tomorrow. Q: What will they give Dad?","tl":"B: Kaarawan ni Tatay sa susunod na linggo; ano ang ireregalo natin? L: Relo kaya? B: Marami na siyang relo; polo na lang. L: Sige, bilhin natin bukas. T: Ano ang ireregalo nila kay Tatay?","vi":"Nữ: Tuần sau là sinh nhật bố, chúng ta tặng bố gì? Nam: Tặng bố một chiếc đồng hồ thì sao? Nữ: Bố có nhiều đồng hồ rồi, tặng bố một chiếc áo sơ mi đi. Nam: Được, mai đi mua. Hỏi: Họ sẽ tặng bố cái gì?"},"exp":{"id":"Jam tangan ditolak; mereka beri 襯衫 (kemeja).","en":"The watch was rejected; they'll give a 襯衫 (shirt).","tl":"Hindi relo; 襯衫 (polo) ang ireregalo.","vi":"Không tặng đồng hồ; họ tặng 襯衫 (áo sơ mi)."}},{"dlg":[{"sp":"M","zh":"我們怎麼去音樂會？坐公車嗎？","py":"Wǒ men zěn me qù yīn yuè huì? Zuò gōng chē ma?"},{"sp":"F","zh":"公車太慢了，坐捷運吧。","py":"Gōng chē tài màn le, zuò jié yùn ba."},{"sp":"M","zh":"捷運站有點遠，我們坐計程車吧。","py":"Jié yùn zhàn yǒu diǎn yuǎn, wǒ men zuò jì chéng chē ba."},{"sp":"F","zh":"好啊，那我叫車。","py":"Hǎo a, nà wǒ jiào chē."}],"q":{"zh":"他們怎麼去音樂會？","py":"Tā men zěn me qù yīn yuè huì?"},"opts":[{"i":["taxi"],"bg":"street"},{"i":["bus"],"bg":"street"},{"i":["mrt","station"]}],"a":0,"tr":{"id":"L: Kita ke konser naik apa? Naik bus? P: Bus terlalu lambat, naik MRT saja. L: Stasiun MRT agak jauh, kita naik taksi saja. P: Oke, aku pesan taksi. Pertanyaan: Mereka ke konser naik apa?","en":"M: How do we get to the concert? By bus? W: The bus is too slow; let's take the MRT. M: The MRT station is a bit far; let's take a taxi. W: Okay, I'll call one. Q: How will they get to the concert?","tl":"L: Paano tayo pupunta sa konsiyerto? Magbu-bus ba? B: Masyadong mabagal ang bus; mag-MRT na lang tayo. L: Medyo malayo ang istasyon ng MRT; mag-taxi na lang tayo. B: Sige, tatawag ako ng taxi. T: Paano sila pupunta sa konsiyerto?","vi":"Nam: Chúng ta đi buổi hòa nhạc bằng gì? Xe buýt à? Nữ: Xe buýt chậm quá, đi tàu điện ngầm đi. Nam: Ga tàu điện ngầm hơi xa, chúng ta đi taxi đi. Nữ: Được, để tôi gọi xe. Hỏi: Họ đi buổi hòa nhạc bằng gì?"},"exp":{"id":"Bus dan MRT ditolak; akhirnya 計程車 (taksi).","en":"Bus and MRT were rejected; finally a 計程車 (taxi).","tl":"Hindi bus at MRT; 計程車 (taxi) ang huli.","vi":"Không đi xe buýt hay tàu điện; cuối cùng đi 計程車 (taxi)."}},{"dlg":[{"sp":"F","zh":"明天去爬山吧！","py":"Míng tiān qù pá shān ba!"},{"sp":"M","zh":"聽說明天會下雨。","py":"Tīng shuō míng tiān huì xià yǔ."},{"sp":"F","zh":"那我們去圖書館看書吧。","py":"Nà wǒ men qù tú shū guǎn kàn shū ba."},{"sp":"M","zh":"好主意。","py":"Hǎo zhǔ yì."}],"q":{"zh":"他們明天要去哪裡？","py":"Tā men míng tiān yào qù nǎ lǐ?"},"opts":[{"i":["mountain"],"bg":"park"},{"i":["library","book"]},{"i":["beach"],"bg":"sea"}],"a":1,"tr":{"id":"P: Besok kita naik gunung, yuk! L: Katanya besok akan hujan. P: Kalau begitu kita ke perpustakaan baca buku saja. L: Ide bagus. Pertanyaan: Besok mereka pergi ke mana?","en":"W: Let's go hiking tomorrow! M: I heard it's going to rain tomorrow. W: Then let's go read at the library. M: Good idea. Q: Where are they going tomorrow?","tl":"B: Umakyat tayo ng bundok bukas! L: Narinig kong uulan bukas. B: Kung gayon, sa library na lang tayo magbasa. L: Magandang ideya. T: Saan sila pupunta bukas?","vi":"Nữ: Mai đi leo núi đi! Nam: Nghe nói mai trời mưa. Nữ: Vậy chúng ta đi thư viện đọc sách đi. Nam: Ý hay đấy. Hỏi: Ngày mai họ đi đâu?"},"exp":{"id":"Karena hujan, mereka ke 圖書館 (perpustakaan).","en":"Because of rain, they go to the 圖書館 (library).","tl":"Dahil uulan, sa 圖書館 (library) sila pupunta.","vi":"Vì trời mưa nên họ đi 圖書館 (thư viện)."}},{"dlg":[{"sp":"M","zh":"你暑假要做什麼？","py":"Nǐ shǔ jià yào zuò shén me?"},{"sp":"F","zh":"我要去咖啡店打工。","py":"Wǒ yào qù kā fēi diàn dǎ gōng."},{"sp":"M","zh":"你不是說要去便利商店嗎？","py":"Nǐ bú shì shuō yào qù biàn lì shāng diàn ma?"},{"sp":"F","zh":"便利商店要晚上上班，我不喜歡。","py":"Biàn lì shāng diàn yào wǎn shàng shàng bān, wǒ bù xǐ huān."}],"q":{"zh":"女的暑假在哪裡打工？","py":"Nǚ de shǔ jià zài nǎ lǐ dǎ gōng?"},"opts":[{"i":["store"],"b":"24h","bg":"night"},{"i":["waiter","coffee"],"bg":"shop"},{"i":["waiter","bubble_tea"],"bg":"shop"}],"a":1,"tr":{"id":"L: Liburan musim panas kamu mau apa? P: Aku mau kerja paruh waktu di kafe. L: Bukannya kamu bilang mau di minimarket? P: Di minimarket harus kerja malam, aku tidak suka. Pertanyaan: Perempuan itu kerja paruh waktu di mana saat liburan?","en":"M: What are you doing over summer vacation? W: I'm going to work part-time at a coffee shop. M: Didn't you say a convenience store? W: The convenience store needs night shifts; I don't like that. Q: Where will the woman work part-time this summer?","tl":"L: Ano ang gagawin mo sa summer vacation? B: Magpa-part-time ako sa coffee shop. L: Hindi ba sabi mo sa convenience store? B: Panggabi ang trabaho sa convenience store; ayoko noon. T: Saan magpa-part-time ang babae ngayong bakasyon?","vi":"Nam: Nghỉ hè bạn định làm gì? Nữ: Tôi sẽ đi làm thêm ở quán cà phê. Nam: Không phải bạn nói làm ở cửa hàng tiện lợi sao? Nữ: Cửa hàng tiện lợi phải làm ca đêm, tôi không thích. Hỏi: Nghỉ hè người nữ làm thêm ở đâu?"},"exp":{"id":"Dia memilih 咖啡店 (kafe), bukan minimarket.","en":"She chose the 咖啡店 (coffee shop), not the convenience store.","tl":"咖啡店 (coffee shop) ang pinili niya, hindi convenience store.","vi":"Cô ấy chọn 咖啡店 (quán cà phê), không phải cửa hàng tiện lợi."}},{"dlg":[{"sp":"M","zh":"音樂會的票要買幾張？","py":"Yīn yuè huì de piào yào mǎi jǐ zhāng?"},{"sp":"F","zh":"你、我和小美，三張。","py":"Nǐ, wǒ hé Xiǎo Měi, sān zhāng."},{"sp":"M","zh":"小美說她那天要上班，不能去。","py":"Xiǎo Měi shuō tā nà tiān yào shàng bān, bù néng qù."},{"sp":"F","zh":"那買兩張就好了。","py":"Nà mǎi liǎng zhāng jiù hǎo le."}],"q":{"zh":"他們要買幾張票？","py":"Tā men yào mǎi jǐ zhāng piào?"},"opts":[{"i":["ticket","music"],"b":"x3"},{"i":["ticket","music"],"b":"x1"},{"i":["ticket","music"],"b":"x2"}],"a":2,"tr":{"id":"L: Tiket konser perlu beli berapa? P: Kamu, aku, dan Xiaomei, tiga lembar. L: Xiaomei bilang hari itu dia kerja, tidak bisa ikut. P: Kalau begitu beli dua saja. Pertanyaan: Mereka akan membeli berapa tiket?","en":"M: How many concert tickets should we buy? W: You, me and Xiaomei, so three. M: Xiaomei says she has to work that day and can't go. W: Then just buy two. Q: How many tickets will they buy?","tl":"L: Ilang tiket ng konsiyerto ang bibilhin natin? B: Ikaw, ako at si Xiaomei, tatlo. L: Sabi ni Xiaomei may trabaho siya noon, hindi siya makakapunta. B: Kung gayon, dalawa na lang. T: Ilang tiket ang bibilhin nila?","vi":"Nam: Vé hòa nhạc cần mua mấy vé? Nữ: Bạn, tôi và Tiểu Mỹ, ba vé. Nam: Tiểu Mỹ nói hôm đó cô ấy phải đi làm, không đi được. Nữ: Vậy mua hai vé là được. Hỏi: Họ mua mấy vé?"},"exp":{"id":"Xiaomei tidak ikut, jadi 兩張 (dua).","en":"Xiaomei can't go, so 兩張 (two).","tl":"Hindi makakasama si Xiaomei, kaya 兩張 (dalawa).","vi":"Tiểu Mỹ không đi nên mua 兩張 (hai vé)."}},{"dlg":[{"sp":"M","zh":"你怎麼買這麼多藥？你生病了嗎？","py":"Nǐ zěn me mǎi zhè me duō yào? Nǐ shēng bìng le ma?"},{"sp":"F","zh":"不是我，是我奶奶。","py":"Bú shì wǒ, shì wǒ nǎi nai."},{"sp":"M","zh":"她怎麼了？","py":"Tā zěn me le?"},{"sp":"F","zh":"她發燒了，爺爺在家照顧她。","py":"Tā fā shāo le, yé ye zài jiā zhào gù tā."}],"q":{"zh":"誰生病了？","py":"Shéi shēng bìng le?"},"opts":[{"i":["old_woman","fever"]},{"i":["woman","fever"]},{"i":["old_man","fever"]}],"a":0,"tr":{"id":"L: Kenapa kamu beli obat sebanyak ini? Kamu sakit? P: Bukan aku, nenekku. L: Dia kenapa? P: Dia demam, kakek merawatnya di rumah. Pertanyaan: Siapa yang sakit?","en":"M: Why did you buy so much medicine? Are you sick? W: Not me, my grandma. M: What's wrong with her? W: She has a fever; Grandpa is taking care of her at home. Q: Who is sick?","tl":"L: Bakit ang dami mong binili na gamot? May sakit ka ba? B: Hindi ako, ang lola ko. L: Ano ang nangyari sa kaniya? B: May lagnat siya; inaalagaan siya ni Lolo sa bahay. T: Sino ang may sakit?","vi":"Nam: Sao bạn mua nhiều thuốc thế? Bạn ốm à? Nữ: Không phải tôi, là bà tôi. Nam: Bà bị sao? Nữ: Bà bị sốt, ông đang chăm bà ở nhà. Hỏi: Ai bị ốm?"},"exp":{"id":"不是我，是我奶奶 — neneknya yang demam.","en":"不是我，是我奶奶 — her grandma has the fever.","tl":"不是我，是我奶奶 — ang lola niya ang may lagnat.","vi":"不是我，是我奶奶 — bà cô ấy bị sốt."}}]},{"p":4,"items":[{"dlg":[{"sp":"F","zh":"你的感冒好了嗎？","py":"Nǐ de gǎn mào hǎo le ma?"},{"sp":"M","zh":"好多了，可是還有一點咳嗽。","py":"Hǎo duō le, kě shì hái yǒu yì diǎn ké sòu."},{"sp":"F","zh":"你吃藥了沒？","py":"Nǐ chī yào le méi?"},{"sp":"M","zh":"吃了，醫生說再休息兩天就好了。","py":"Chī le, yī shēng shuō zài xiū xí liǎng tiān jiù hǎo le."}],"q":{"zh":"男的現在怎麼樣？","py":"Nán de xiàn zài zěn me yàng?"},"opts":[{"zh":"已經全好了","py":"Yǐ jīng quán hǎo le"},{"zh":"還有一點咳嗽","py":"Hái yǒu yì diǎn ké sòu"},{"zh":"發燒了","py":"Fā shāo le"},{"zh":"還沒吃藥","py":"Hái méi chī yào"}],"a":1,"tr":{"id":"P: Flumu sudah sembuh? L: Sudah jauh lebih baik, tapi masih sedikit batuk. P: Sudah minum obat? L: Sudah, dokter bilang istirahat dua hari lagi akan sembuh. Pertanyaan: Bagaimana keadaan laki-laki itu sekarang? A. Sudah sembuh total B. Masih sedikit batuk C. Demam D. Belum minum obat","en":"W: Is your cold better? M: Much better, but I still have a bit of a cough. W: Have you taken medicine? M: Yes, the doctor said two more days of rest and I'll be fine. Q: How is the man now? A. Completely better B. Still coughing a little C. Has a fever D. Hasn't taken medicine","tl":"B: Magaling na ba ang sipon mo? L: Mas mabuti na, pero may kaunting ubo pa. B: Uminom ka na ba ng gamot? L: Oo, sabi ng doktor magpahinga pa ng dalawang araw at gagaling na. T: Kumusta ang lalaki ngayon? A. Lubos nang magaling B. May kaunting ubo pa C. May lagnat D. Hindi pa umiinom ng gamot","vi":"Nữ: Bạn khỏi cảm chưa? Nam: Đỡ nhiều rồi, nhưng vẫn còn ho một chút. Nữ: Bạn uống thuốc chưa? Nam: Uống rồi, bác sĩ nói nghỉ thêm hai ngày là khỏi. Hỏi: Người nam bây giờ thế nào? A. Khỏi hẳn rồi B. Vẫn còn ho một chút C. Bị sốt D. Chưa uống thuốc"},"exp":{"id":"Dia bilang 還有一點咳嗽.","en":"He says 還有一點咳嗽 (still a little cough).","tl":"Sabi niya 還有一點咳嗽 (may kaunting ubo pa).","vi":"Anh ấy nói 還有一點咳嗽 (vẫn còn ho một chút)."}},{"dlg":[{"sp":"M","zh":"你每天幾點下班？","py":"Nǐ měi tiān jǐ diǎn xià bān?"},{"sp":"F","zh":"平常六點，可是這個星期很忙，要到八點。","py":"Píng cháng liù diǎn, kě shì zhè ge xīng qí hěn máng, yào dào bā diǎn."},{"sp":"M","zh":"那週末呢？","py":"Nà zhōu mò ne?"},{"sp":"F","zh":"週末不用上班。","py":"Zhōu mò bú yòng shàng bān."}],"q":{"zh":"女的這個星期幾點下班？","py":"Nǚ de zhè ge xīng qí jǐ diǎn xià bān?"},"opts":[{"zh":"六點","py":"Liù diǎn"},{"zh":"七點","py":"Qī diǎn"},{"zh":"八點","py":"Bā diǎn"},{"zh":"十點","py":"Shí diǎn"}],"a":2,"tr":{"id":"L: Setiap hari kamu pulang kerja jam berapa? P: Biasanya jam enam, tapi minggu ini sibuk, sampai jam delapan. L: Kalau akhir pekan? P: Akhir pekan tidak kerja. Pertanyaan: Minggu ini perempuan itu pulang kerja jam berapa? A. Jam enam B. Jam tujuh C. Jam delapan D. Jam sepuluh","en":"M: What time do you get off work every day? W: Usually six, but this week is busy, so until eight. M: What about weekends? W: I don't work on weekends. Q: What time does the woman get off work this week? A. Six B. Seven C. Eight D. Ten","tl":"L: Anong oras ka umuuwi galing trabaho araw-araw? B: Karaniwan alas-sais, pero abala ngayong linggo, hanggang alas-otso. L: E tuwing weekend? B: Walang pasok tuwing weekend. T: Anong oras umuuwi ang babae ngayong linggo? A. Alas-sais B. Alas-siyete C. Alas-otso D. Alas-diyes","vi":"Nam: Mỗi ngày mấy giờ bạn tan làm? Nữ: Bình thường sáu giờ, nhưng tuần này bận, phải đến tám giờ. Nam: Còn cuối tuần? Nữ: Cuối tuần không phải đi làm. Hỏi: Tuần này mấy giờ người nữ tan làm? A. Sáu giờ B. Bảy giờ C. Tám giờ D. Mười giờ"},"exp":{"id":"Biasanya jam 6, tapi minggu ini 到八點.","en":"Usually six, but this week 到八點 (until eight).","tl":"Karaniwan alas-sais, pero ngayong linggo 到八點.","vi":"Bình thường sáu giờ, tuần này 到八點 (đến tám giờ)."}},{"dlg":[{"sp":"F","zh":"明天去海邊，小王會來嗎？","py":"Míng tiān qù hǎi biān, Xiǎo Wáng huì lái ma?"},{"sp":"M","zh":"他說要上班，不能來。","py":"Tā shuō yào shàng bān, bù néng lái."},{"sp":"F","zh":"那小李呢？","py":"Nà Xiǎo Lǐ ne?"},{"sp":"M","zh":"小李會來，他還要帶他的女朋友。","py":"Xiǎo Lǐ huì lái, tā hái yào dài tā de nǚ péng you."}],"q":{"zh":"明天誰不去海邊？","py":"Míng tiān shéi bú qù hǎi biān?"},"opts":[{"zh":"小李","py":"Xiǎo Lǐ"},{"zh":"男的","py":"Nán de"},{"zh":"小李的女朋友","py":"Xiǎo Lǐ de nǚ péng you"},{"zh":"小王","py":"Xiǎo Wáng"}],"a":3,"tr":{"id":"P: Besok ke pantai, Xiao Wang datang? L: Dia bilang harus kerja, tidak bisa datang. P: Kalau Xiao Li? L: Xiao Li datang, dia juga mau ajak pacarnya. Pertanyaan: Besok siapa yang tidak ke pantai? A. Xiao Li B. Laki-laki itu C. Pacar Xiao Li D. Xiao Wang","en":"W: We're going to the beach tomorrow. Is Xiao Wang coming? M: He says he has to work and can't come. W: What about Xiao Li? M: Xiao Li is coming, and he's bringing his girlfriend. Q: Who is NOT going to the beach tomorrow? A. Xiao Li B. The man C. Xiao Li's girlfriend D. Xiao Wang","tl":"B: Pupunta tayo sa beach bukas; sasama ba si Xiao Wang? L: Sabi niya may trabaho siya, hindi siya makakasama. B: E si Xiao Li? L: Sasama si Xiao Li, at isasama pa niya ang girlfriend niya. T: Sino ang HINDI pupunta sa beach bukas? A. Xiao Li B. Ang lalaki C. Girlfriend ni Xiao Li D. Xiao Wang","vi":"Nữ: Mai đi biển, Tiểu Vương có đến không? Nam: Cậu ấy nói phải đi làm, không đến được. Nữ: Còn Tiểu Lý? Nam: Tiểu Lý sẽ đến, còn dẫn theo bạn gái. Hỏi: Ngày mai ai KHÔNG đi biển? A. Tiểu Lý B. Người nam C. Bạn gái Tiểu Lý D. Tiểu Vương"},"exp":{"id":"小王要上班，不能來.","en":"小王 has to work and can't come.","tl":"Si 小王 ay may trabaho, hindi makakasama.","vi":"小王 phải đi làm nên không đến được."}},{"dlg":[{"sp":"M","zh":"你看過這部電影嗎？","py":"Nǐ kàn guò zhè bù diàn yǐng ma?"},{"sp":"F","zh":"看過了，上個月跟我哥哥一起看的。","py":"Kàn guò le, shàng ge yuè gēn wǒ gē ge yì qǐ kàn de."},{"sp":"M","zh":"好看嗎？","py":"Hǎo kàn ma?"},{"sp":"F","zh":"還不錯，可是有一點長，三個小時。","py":"Hái bú cuò, kě shì yǒu yì diǎn cháng, sān ge xiǎo shí."}],"q":{"zh":"女的覺得這部電影怎麼樣？","py":"Nǚ de jué de zhè bù diàn yǐng zěn me yàng?"},"opts":[{"zh":"很難看","py":"Hěn nán kàn"},{"zh":"不錯，可是有點長","py":"Bú cuò, kě shì yǒu diǎn cháng"},{"zh":"太短了","py":"Tài duǎn le"},{"zh":"她還沒看","py":"Tā hái méi kàn"}],"a":1,"tr":{"id":"L: Kamu sudah nonton film ini? P: Sudah, bulan lalu nonton bersama kakakku. L: Bagus? P: Lumayan, tapi agak panjang, tiga jam. Pertanyaan: Menurut perempuan itu film ini bagaimana? A. Jelek sekali B. Lumayan, tapi agak panjang C. Terlalu pendek D. Dia belum menonton","en":"M: Have you seen this movie? W: Yes, I saw it last month with my older brother. M: Was it good? W: Not bad, but a bit long — three hours. Q: What does the woman think of the movie? A. Very bad B. Not bad, but a bit long C. Too short D. She hasn't seen it","tl":"L: Napanood mo na ba ang pelikulang ito? B: Oo, noong isang buwan kasama ang kuya ko. L: Maganda ba? B: Hindi masama, pero medyo mahaba, tatlong oras. T: Ano ang tingin ng babae sa pelikula? A. Pangit na pangit B. Hindi masama, pero medyo mahaba C. Masyadong maikli D. Hindi pa niya napapanood","vi":"Nam: Bạn xem phim này chưa? Nữ: Xem rồi, tháng trước xem cùng anh trai. Nam: Hay không? Nữ: Cũng được, nhưng hơi dài, ba tiếng. Hỏi: Người nữ thấy bộ phim thế nào? A. Rất dở B. Cũng được nhưng hơi dài C. Ngắn quá D. Cô ấy chưa xem"},"exp":{"id":"還不錯，可是有一點長.","en":"She says 還不錯，可是有一點長 (not bad, but a bit long).","tl":"Sabi niya 還不錯，可是有一點長.","vi":"Cô ấy nói 還不錯，可是有一點長."}},{"dlg":[{"sp":"F","zh":"你學鋼琴學多久了？","py":"Nǐ xué gāng qín xué duō jiǔ le?"},{"sp":"M","zh":"兩年了。我妹妹也在學，她學了五年。","py":"Liǎng nián le. Wǒ mèi mei yě zài xué, tā xué le wǔ nián."},{"sp":"F","zh":"你們一個星期上幾次課？","py":"Nǐ men yí ge xīng qí shàng jǐ cì kè?"},{"sp":"M","zh":"我一次，我妹妹三次。","py":"Wǒ yí cì, wǒ mèi mei sān cì."}],"q":{"zh":"男的學鋼琴學了多久？","py":"Nán de xué gāng qín xué le duō jiǔ?"},"opts":[{"zh":"三年","py":"Sān nián"},{"zh":"五年","py":"Wǔ nián"},{"zh":"一年","py":"Yì nián"},{"zh":"兩年","py":"Liǎng nián"}],"a":3,"tr":{"id":"P: Sudah berapa lama kamu belajar piano? L: Dua tahun. Adikku juga belajar, dia sudah lima tahun. P: Seminggu kalian les berapa kali? L: Aku sekali, adikku tiga kali. Pertanyaan: Sudah berapa lama laki-laki itu belajar piano? A. Tiga tahun B. Lima tahun C. Satu tahun D. Dua tahun","en":"W: How long have you been learning piano? M: Two years. My younger sister is learning too; she's been at it five years. W: How many lessons a week do you have? M: I have one, my sister has three. Q: How long has the man been learning piano? A. Three years B. Five years C. One year D. Two years","tl":"B: Gaano ka na katagal nag-aaral ng piano? L: Dalawang taon na. Nag-aaral din ang kapatid kong babae, limang taon na siya. B: Ilang beses kayong may klase sa isang linggo? L: Ako isang beses, ang kapatid ko tatlong beses. T: Gaano na katagal nag-aaral ng piano ang lalaki? A. Tatlong taon B. Limang taon C. Isang taon D. Dalawang taon","vi":"Nữ: Bạn học piano bao lâu rồi? Nam: Hai năm rồi. Em gái tôi cũng học, em ấy học năm năm rồi. Nữ: Một tuần các bạn học mấy buổi? Nam: Tôi một buổi, em gái tôi ba buổi. Hỏi: Người nam học piano bao lâu rồi? A. Ba năm B. Năm năm C. Một năm D. Hai năm"},"exp":{"id":"Dia 兩年; lima tahun itu adiknya.","en":"He has learned 兩年 (two years); five years is his sister.","tl":"兩年 siya; ang limang taon ay sa kapatid niya.","vi":"Anh ấy học 兩年 (hai năm); năm năm là em gái."}},{"dlg":[{"sp":"M","zh":"這個週末要打掃家裡，你想做什麼？","py":"Zhè ge zhōu mò yào dǎ sǎo jiā lǐ, nǐ xiǎng zuò shén me?"},{"sp":"F","zh":"我洗衣服，你打掃房間。","py":"Wǒ xǐ yī fu, nǐ dǎ sǎo fáng jiān."},{"sp":"M","zh":"好。那誰去倒垃圾？","py":"Hǎo. Nà shéi qù dào lè sè?"},{"sp":"F","zh":"讓弟弟去吧。","py":"Ràng dì di qù ba."}],"q":{"zh":"誰要打掃房間？","py":"Shéi yào dǎ sǎo fáng jiān?"},"opts":[{"zh":"男的","py":"Nán de"},{"zh":"女的","py":"Nǚ de"},{"zh":"弟弟","py":"Dì di"},{"zh":"媽媽","py":"Mā ma"}],"a":0,"tr":{"id":"L: Akhir pekan ini kita bersih-bersih rumah, kamu mau mengerjakan apa? P: Aku cuci baju, kamu bersihkan kamar. L: Oke. Lalu siapa yang buang sampah? P: Suruh adik saja. Pertanyaan: Siapa yang akan membersihkan kamar? A. Laki-laki itu B. Perempuan itu C. Adik laki-laki D. Ibu","en":"M: We're cleaning the house this weekend. What do you want to do? W: I'll do the laundry, and you clean the rooms. M: Okay. Then who takes out the trash? W: Let our little brother do it. Q: Who will clean the rooms? A. The man B. The woman C. The younger brother D. Mom","tl":"L: Maglilinis tayo ng bahay ngayong weekend; ano ang gusto mong gawin? B: Ako ang maglalaba, ikaw ang maglinis ng kuwarto. L: Sige. E sino ang magtatapon ng basura? B: Ang bunso na lang. T: Sino ang maglilinis ng kuwarto? A. Ang lalaki B. Ang babae C. Ang nakababatang kapatid na lalaki D. Si Nanay","vi":"Nam: Cuối tuần này dọn dẹp nhà, em muốn làm gì? Nữ: Em giặt quần áo, anh dọn phòng. Nam: Được. Vậy ai đi đổ rác? Nữ: Để em trai đi. Hỏi: Ai sẽ dọn phòng? A. Người nam B. Người nữ C. Em trai D. Mẹ"},"exp":{"id":"你打掃房間 — perempuan itu menyuruh laki-laki.","en":"你打掃房間 — she tells the man to clean the rooms.","tl":"你打掃房間 — ang lalaki ang sinabihang maglinis.","vi":"你打掃房間 — cô ấy bảo người nam dọn phòng."}},{"dlg":[{"sp":"F","zh":"你的生日是幾月幾號？","py":"Nǐ de shēng rì shì jǐ yuè jǐ hào?"},{"sp":"M","zh":"十月二十號。你呢？","py":"Shí yuè èr shí hào. Nǐ ne?"},{"sp":"F","zh":"我的是十二月十號。","py":"Wǒ de shì shí èr yuè shí hào."},{"sp":"M","zh":"我會記得送你禮物。","py":"Wǒ huì jì de sòng nǐ lǐ wù."}],"q":{"zh":"女的生日是幾月幾號？","py":"Nǚ de shēng rì shì jǐ yuè jǐ hào?"},"opts":[{"zh":"十二月十號","py":"Shí èr yuè shí hào"},{"zh":"十月二十號","py":"Shí yuè èr shí hào"},{"zh":"十月十號","py":"Shí yuè shí hào"},{"zh":"十二月二十號","py":"Shí èr yuè èr shí hào"}],"a":0,"tr":{"id":"P: Ulang tahunmu tanggal berapa bulan apa? L: Tanggal 20 Oktober. Kamu? P: Punyaku 10 Desember. L: Aku akan ingat memberimu hadiah. Pertanyaan: Ulang tahun perempuan itu tanggal berapa? A. 10 Desember B. 20 Oktober C. 10 Oktober D. 20 Desember","en":"W: What's the date of your birthday? M: October 20th. And yours? W: Mine is December 10th. M: I'll remember to give you a present. Q: When is the woman's birthday? A. December 10 B. October 20 C. October 10 D. December 20","tl":"B: Kailan ang kaarawan mo? L: Oktubre 20. Ikaw? B: Disyembre 10 ang akin. L: Tatandaan kong bigyan ka ng regalo. T: Kailan ang kaarawan ng babae? A. Disyembre 10 B. Oktubre 20 C. Oktubre 10 D. Disyembre 20","vi":"Nữ: Sinh nhật bạn ngày mấy tháng mấy? Nam: Ngày 20 tháng 10. Còn bạn? Nữ: Của tôi là ngày 10 tháng 12. Nam: Tôi sẽ nhớ tặng quà bạn. Hỏi: Sinh nhật người nữ ngày nào? A. 10 tháng 12 B. 20 tháng 10 C. 10 tháng 10 D. 20 tháng 12"},"exp":{"id":"Perempuan: 十二月十號; 10/20 milik laki-laki.","en":"Hers is 十二月十號; October 20 is the man's.","tl":"Kaniya ang 十二月十號; sa lalaki ang Oktubre 20.","vi":"Của cô ấy là 十二月十號; 20/10 là của người nam."}},{"dlg":[{"sp":"M","zh":"你昨天晚上看棒球比賽了嗎？","py":"Nǐ zuó tiān wǎn shàng kàn bàng qiú bǐ sài le ma?"},{"sp":"F","zh":"沒有，我在公司加班。誰贏了？","py":"Méi yǒu, wǒ zài gōng sī jiā bān. Shéi yíng le?"},{"sp":"M","zh":"台北贏了，五比三。","py":"Tái běi yíng le, wǔ bǐ sān."},{"sp":"F","zh":"太好了！","py":"Tài hǎo le!"}],"q":{"zh":"女的昨天晚上做什麼？","py":"Nǚ de zuó tiān wǎn shàng zuò shén me?"},"opts":[{"zh":"看棒球比賽","py":"Kàn bàng qiú bǐ sài"},{"zh":"打棒球","py":"Dǎ bàng qiú"},{"zh":"在公司工作","py":"Zài gōng sī gōng zuò"},{"zh":"在家睡覺","py":"Zài jiā shuì jiào"}],"a":2,"tr":{"id":"L: Tadi malam kamu nonton pertandingan bisbol? P: Tidak, aku lembur di kantor. Siapa yang menang? L: Taipei menang, lima-tiga. P: Bagus sekali! Pertanyaan: Tadi malam perempuan itu melakukan apa? A. Menonton pertandingan bisbol B. Main bisbol C. Bekerja di kantor D. Tidur di rumah","en":"M: Did you watch the baseball game last night? W: No, I was working overtime at the office. Who won? M: Taipei won, five to three. W: Great! Q: What did the woman do last night? A. Watched the baseball game B. Played baseball C. Worked at the office D. Slept at home","tl":"L: Napanood mo ba ang baseball game kagabi? B: Hindi, nag-overtime ako sa opisina. Sino ang nanalo? L: Nanalo ang Taipei, lima laban sa tatlo. B: Ang galing! T: Ano ang ginawa ng babae kagabi? A. Nanood ng baseball game B. Naglaro ng baseball C. Nagtrabaho sa opisina D. Natulog sa bahay","vi":"Nam: Tối qua bạn có xem trận bóng chày không? Nữ: Không, tôi tăng ca ở công ty. Ai thắng? Nam: Đài Bắc thắng, năm-ba. Nữ: Tuyệt quá! Hỏi: Tối qua người nữ làm gì? A. Xem trận bóng chày B. Chơi bóng chày C. Làm việc ở công ty D. Ngủ ở nhà"},"exp":{"id":"在公司加班 = bekerja di kantor.","en":"在公司加班 means she was working at the office.","tl":"Ang 在公司加班 ay nagtatrabaho sa opisina.","vi":"在公司加班 là làm việc ở công ty."}},{"dlg":[{"sp":"F","zh":"中秋節你要回南部嗎？","py":"Zhōng qiū jié nǐ yào huí nán bù ma?"},{"sp":"M","zh":"不回去了，火車票買不到。","py":"Bù huí qù le, huǒ chē piào mǎi bú dào."},{"sp":"F","zh":"那你跟我們一起烤肉吧！","py":"Nà nǐ gēn wǒ men yì qǐ kǎo ròu ba!"},{"sp":"M","zh":"好啊，謝謝你。","py":"Hǎo a, xiè xie nǐ."}],"q":{"zh":"男的中秋節為什麼不回南部？","py":"Nán de zhōng qiū jié wèi shén me bù huí nán bù?"},"opts":[{"zh":"他要上班","py":"Tā yào shàng bān"},{"zh":"他買不到票","py":"Tā mǎi bú dào piào"},{"zh":"他生病了","py":"Tā shēng bìng le"},{"zh":"他想去烤肉","py":"Tā xiǎng qù kǎo ròu"}],"a":1,"tr":{"id":"P: Festival Kue Bulan kamu pulang ke selatan? L: Tidak pulang, tiket kereta tidak dapat. P: Kalau begitu ikut barbekyu bersama kami! L: Oke, terima kasih. Pertanyaan: Kenapa laki-laki itu tidak pulang ke selatan? A. Dia harus kerja B. Dia tidak dapat tiket C. Dia sakit D. Dia ingin barbekyu","en":"W: Are you going back to the south for the Mid-Autumn Festival? M: No, I couldn't get a train ticket. W: Then come barbecue with us! M: Sure, thank you. Q: Why isn't the man going back south? A. He has to work B. He couldn't get a ticket C. He is sick D. He wants to barbecue","tl":"B: Uuwi ka ba sa timog sa Mid-Autumn Festival? L: Hindi na, wala akong nabiling tiket sa tren. B: Kung gayon, sumama ka sa ihawan namin! L: Sige, salamat. T: Bakit hindi uuwi sa timog ang lalaki? A. May trabaho siya B. Hindi siya nakabili ng tiket C. May sakit siya D. Gusto niyang mag-ihaw","vi":"Nữ: Trung thu bạn có về miền Nam không? Nam: Không về nữa, không mua được vé tàu. Nữ: Vậy bạn đi nướng thịt với chúng tôi nhé! Nam: Được, cảm ơn bạn. Hỏi: Vì sao Trung thu người nam không về miền Nam? A. Phải đi làm B. Không mua được vé C. Bị ốm D. Muốn đi nướng thịt"},"exp":{"id":"火車票買不到 — tidak dapat tiket.","en":"火車票買不到 — he couldn't get a train ticket.","tl":"火車票買不到 — walang nabiling tiket.","vi":"火車票買不到 — không mua được vé tàu."}},{"dlg":[{"sp":"F","zh":"這件運動衣多少錢？","py":"Zhè jiàn yùn dòng yī duō shǎo qián?"},{"sp":"M","zh":"一件四百塊，兩件七百塊。","py":"Yí jiàn sì bǎi kuài, liǎng jiàn qī bǎi kuài."},{"sp":"F","zh":"那我買兩件。","py":"Nà wǒ mǎi liǎng jiàn."},{"sp":"M","zh":"好的，一共七百塊。","py":"Hǎo de, yí gòng qī bǎi kuài."}],"q":{"zh":"女的要付多少錢？","py":"Nǚ de yào fù duō shǎo qián?"},"opts":[{"zh":"七百塊","py":"Qī bǎi kuài"},{"zh":"四百塊","py":"Sì bǎi kuài"},{"zh":"八百塊","py":"Bā bǎi kuài"},{"zh":"一千一百塊","py":"Yì qiān yì bǎi kuài"}],"a":0,"tr":{"id":"P: Baju olahraga ini berapa? L: Satu 400, dua 700. P: Kalau begitu saya beli dua. L: Baik, totalnya 700. Pertanyaan: Perempuan itu harus membayar berapa? A. 700 B. 400 C. 800 D. 1100","en":"W: How much is this sports shirt? M: 400 for one, 700 for two. W: Then I'll buy two. M: Okay, 700 in total. Q: How much does the woman pay? A. 700 B. 400 C. 800 D. 1,100","tl":"B: Magkano ang damit pang-isport na ito? L: 400 ang isa, 700 ang dalawa. B: Kung gayon, dalawa ang bibilhin ko. L: Sige, 700 lahat. T: Magkano ang babayaran ng babae? A. 700 B. 400 C. 800 D. 1,100","vi":"Nữ: Áo thể thao này bao nhiêu tiền? Nam: Một chiếc 400, hai chiếc 700. Nữ: Vậy tôi mua hai chiếc. Nam: Vâng, tổng cộng 700. Hỏi: Người nữ phải trả bao nhiêu? A. 700 B. 400 C. 800 D. 1.100"},"exp":{"id":"Dua potong harganya 七百塊, bukan 800.","en":"Two cost 七百塊 (700), not 800.","tl":"七百塊 ang dalawa, hindi 800.","vi":"Hai chiếc giá 七百塊 (700), không phải 800."}}]}],"R":[{"p":1,"items":[{"zh":"我哥哥每天早上去公園跑步。","py":"Wǒ gē ge měi tiān zǎo shang qù gōng yuán pǎo bù.","opts":[{"i":["man","swim"],"bg":"sea"},{"i":["man","run"],"bg":"park"},{"i":["man","basketball"],"bg":"school"}],"a":1,"tr":{"id":"Kakak laki-laki saya pergi lari di taman setiap pagi.","en":"My older brother goes running in the park every morning.","tl":"Tumatakbo sa parke ang kuya ko tuwing umaga.","vi":"Anh trai tôi mỗi sáng đều ra công viên chạy bộ."},"exp":{"id":"跑步 = lari; 公園 = taman.","en":"跑步 = running; 公園 = park.","tl":"跑步 = pagtakbo; 公園 = parke.","vi":"跑步 = chạy bộ; 公園 = công viên."}},{"zh":"她發燒了，要去醫院看醫生。","py":"Tā fā shāo le, yào qù yī yuàn kàn yī shēng.","opts":[{"i":["woman","sun"],"bg":"park"},{"i":["woman","cook"],"bg":"home"},{"i":["woman","fever"],"bg":"hospital"}],"a":2,"tr":{"id":"Dia demam, harus pergi ke rumah sakit menemui dokter.","en":"She has a fever and needs to go to the hospital to see a doctor.","tl":"May lagnat siya at kailangang pumunta sa ospital para magpatingin sa doktor.","vi":"Cô ấy bị sốt, phải đến bệnh viện khám bác sĩ."},"exp":{"id":"發燒 = demam; 醫院 = rumah sakit.","en":"發燒 = fever; 醫院 = hospital.","tl":"發燒 = lagnat; 醫院 = ospital.","vi":"發燒 = sốt; 醫院 = bệnh viện."}},{"zh":"今天是妹妹的生日，我送她一本書。","py":"Jīn tiān shì mèi mei de shēng rì, wǒ sòng tā yì běn shū.","opts":[{"i":["girl","birthday","book"],"bg":"home"},{"i":["girl","birthday","watch"],"bg":"home"},{"i":["girl","birthday","shoes"],"bg":"home"}],"a":0,"tr":{"id":"Hari ini ulang tahun adik perempuan saya, saya memberinya sebuah buku.","en":"Today is my younger sister's birthday; I'm giving her a book.","tl":"Kaarawan ngayon ng nakababata kong kapatid na babae; binigyan ko siya ng isang libro.","vi":"Hôm nay là sinh nhật em gái, tôi tặng em ấy một quyển sách."},"exp":{"id":"Hadiahnya 一本書 (sebuah buku).","en":"The gift is 一本書, a book.","tl":"Ang regalo ay 一本書, isang libro.","vi":"Quà là 一本書, một quyển sách."}},{"zh":"下午三點我們在電影院門口見。","py":"Xià wǔ sān diǎn wǒ men zài diàn yǐng yuàn mén kǒu jiàn.","opts":[{"i":["restaurant","clock"],"b":"15:00"},{"i":["cinema","clock"],"b":"13:00"},{"i":["cinema","clock"],"b":"15:00"}],"a":2,"tr":{"id":"Jam tiga sore kita bertemu di depan bioskop.","en":"Let's meet at the cinema entrance at 3 p.m.","tl":"Magkita tayo sa harap ng sinehan nang alas-tres ng hapon.","vi":"Ba giờ chiều chúng ta gặp nhau ở cửa rạp chiếu phim."},"exp":{"id":"下午三點 = 15:00; 電影院 = bioskop.","en":"下午三點 = 15:00; 電影院 = cinema.","tl":"下午三點 = 15:00; 電影院 = sinehan.","vi":"下午三點 = 15:00; 電影院 = rạp chiếu phim."}},{"zh":"弟弟頭很痛，所以今天沒去上課。","py":"Dì di tóu hěn tòng, suǒ yǐ jīn tiān méi qù shàng kè.","opts":[{"i":["boy","school","study"],"bg":"school"},{"i":["boy","headache","bed"],"bg":"home"},{"i":["boy","play_ball"],"bg":"park"}],"a":1,"tr":{"id":"Adik laki-laki sakit kepala, jadi hari ini tidak masuk sekolah.","en":"My younger brother has a bad headache, so he didn't go to class today.","tl":"Masakit ang ulo ng nakababata kong kapatid, kaya hindi siya pumasok ngayon.","vi":"Em trai bị đau đầu nên hôm nay không đi học."},"exp":{"id":"頭很痛 = sakit kepala; 沒去上課 = tetap di rumah.","en":"頭很痛 = headache; 沒去上課 = stayed home.","tl":"頭很痛 = masakit ang ulo; 沒去上課 = nasa bahay.","vi":"頭很痛 = đau đầu; 沒去上課 = ở nhà."}},{"zh":"我的工作是開計程車。","py":"Wǒ de gōng zuò shì kāi jì chéng chē.","opts":[{"i":["driver","bus"],"bg":"street"},{"i":["driver","taxi"],"bg":"street"},{"i":["waiter","restaurant"]}],"a":1,"tr":{"id":"Pekerjaan saya adalah menyetir taksi.","en":"My job is driving a taxi.","tl":"Ang trabaho ko ay magmaneho ng taxi.","vi":"Công việc của tôi là lái taxi."},"exp":{"id":"計程車 = taksi, bukan bus.","en":"計程車 = taxi, not a bus.","tl":"計程車 = taxi, hindi bus.","vi":"計程車 = taxi, không phải xe buýt."}},{"zh":"星期六我想跟朋友去海邊游泳。","py":"Xīng qí liù wǒ xiǎng gēn péng yǒu qù hǎi biān yóu yǒng.","opts":[{"i":["friends","mountain","walk"]},{"i":["friends","park","play_ball"],"bg":"park"},{"i":["friends","beach","swim"],"bg":"sea"}],"a":2,"tr":{"id":"Hari Sabtu saya ingin pergi berenang di pantai bersama teman.","en":"On Saturday I want to go swimming at the beach with friends.","tl":"Sa Sabado, gusto kong lumangoy sa dagat kasama ang mga kaibigan.","vi":"Thứ Bảy tôi muốn cùng bạn bè đi bơi ở biển."},"exp":{"id":"海邊 = pantai; 游泳 = berenang.","en":"海邊 = beach; 游泳 = swim.","tl":"海邊 = dalampasigan; 游泳 = lumangoy.","vi":"海邊 = bờ biển; 游泳 = bơi."}},{"zh":"外面下大雨，我們在家看電影吧。","py":"Wài miàn xià dà yǔ, wǒ men zài jiā kàn diàn yǐng ba.","opts":[{"i":["friends","movie","rain"],"bg":"home"},{"i":["friends","cinema","sun"]},{"i":["friends","rain","umbrella"],"bg":"street"}],"a":0,"tr":{"id":"Di luar hujan deras, ayo kita nonton film di rumah saja.","en":"It's raining hard outside, let's watch a movie at home.","tl":"Malakas ang ulan sa labas, manood na lang tayo ng pelikula sa bahay.","vi":"Bên ngoài mưa to, chúng ta ở nhà xem phim nhé."},"exp":{"id":"Hujan, dan mereka menonton film 在家 (di rumah).","en":"It's raining and they watch a movie 在家, at home.","tl":"Umuulan at nanonood sila ng pelikula 在家, sa bahay.","vi":"Trời mưa, họ xem phim 在家, ở nhà."}},{"zh":"我每個星期打兩次籃球。","py":"Wǒ měi ge xīng qí dǎ liǎng cì lán qiú.","opts":[{"i":["baseball","calendar"],"b":"x2"},{"i":["basketball","calendar"],"b":"x2"},{"i":["basketball","calendar"],"b":"x3"}],"a":1,"tr":{"id":"Saya main basket dua kali seminggu.","en":"I play basketball twice a week.","tl":"Naglalaro ako ng basketball dalawang beses bawat linggo.","vi":"Mỗi tuần tôi chơi bóng rổ hai lần."},"exp":{"id":"籃球 = basket; 兩次 = dua kali.","en":"籃球 = basketball; 兩次 = twice.","tl":"籃球 = basketball; 兩次 = dalawang beses.","vi":"籃球 = bóng rổ; 兩次 = hai lần."}},{"zh":"姐姐正在聽音樂，沒有在寫功課。","py":"Jiě jie zhèng zài tīng yīn yuè, méi yǒu zài xiě gōng kè.","opts":[{"i":["girl","write","notebook"],"bg":"home"},{"i":["girl","sing"],"bg":"home"},{"i":["girl","listen_music"],"bg":"home"}],"a":2,"tr":{"id":"Kakak perempuan sedang mendengarkan musik, tidak sedang mengerjakan PR.","en":"My older sister is listening to music, not doing homework.","tl":"Nakikinig ng musika ang ate ko, hindi siya gumagawa ng takdang-aralin.","vi":"Chị gái đang nghe nhạc, không phải đang làm bài tập."},"exp":{"id":"聽音樂 = mendengarkan musik, bukan menyanyi atau menulis.","en":"聽音樂 = listening to music, not singing or writing.","tl":"聽音樂 = nakikinig ng musika, hindi kumakanta o sumusulat.","vi":"聽音樂 = nghe nhạc, không phải hát hay viết."}}]},{"p":2,"items":[{"pic":{"i":["man","swim"],"bg":"sea"},"zh":"他很喜歡在海裡＿＿＿。","py":"Tā hěn xǐ huān zài hǎi lǐ yóu yǒng.","opts":["跑步","游泳","唱歌","睡覺"],"a":1,"tr":{"id":"Dia sangat suka berenang di laut.","en":"He really likes swimming in the sea.","tl":"Gustong-gusto niyang lumangoy sa dagat.","vi":"Anh ấy rất thích bơi ở biển."},"exp":{"id":"Gambar: pria berenang di laut → 游泳.","en":"The picture shows a man swimming in the sea → 游泳.","tl":"Nasa larawan ang lalaking lumalangoy sa dagat → 游泳.","vi":"Hình là người đàn ông bơi ở biển → 游泳."}},{"pic":{"i":["doctor","girl","medicine"],"bg":"hospital"},"zh":"醫生給了她一些＿＿＿。","py":"Yī shēng gěi le tā yì xiē yào.","opts":["藥","錢","書","花"],"a":0,"tr":{"id":"Dokter memberinya beberapa obat.","en":"The doctor gave her some medicine.","tl":"Binigyan siya ng doktor ng ilang gamot.","vi":"Bác sĩ đưa cho cô bé một ít thuốc."},"exp":{"id":"Gambar menunjukkan obat → 藥.","en":"The picture shows medicine → 藥.","tl":"Gamot ang nasa larawan → 藥.","vi":"Hình có thuốc → 藥."}},{"pic":{"i":["woman","computer"],"b":"09:00","bg":"office"},"zh":"她早上九點就到公司＿＿＿了。","py":"Tā zǎo shang jiǔ diǎn jiù dào gōng sī shàng bān le.","opts":["下課","吃飯","上班","睡覺"],"a":2,"tr":{"id":"Dia sudah sampai di kantor untuk bekerja jam sembilan pagi.","en":"She was already at the office working at nine in the morning.","tl":"Alas-nuwebe pa lang ng umaga ay nasa opisina na siya para magtrabaho.","vi":"Chín giờ sáng cô ấy đã đến công ty làm việc rồi."},"exp":{"id":"Kantor + komputer jam 09:00 → 上班 (bekerja).","en":"Office and computer at 09:00 → 上班, going to work.","tl":"Opisina at computer nang 09:00 → 上班, pagtatrabaho.","vi":"Văn phòng, máy tính lúc 09:00 → 上班, đi làm."}},{"pic":{"i":["birthday","cake"],"b":"20","bg":"home"},"zh":"今天是我二十歲的＿＿＿。","py":"Jīn tiān shì wǒ èr shí suì de shēng rì.","opts":["新年","週末","中秋節","生日"],"a":3,"tr":{"id":"Hari ini adalah ulang tahun saya yang ke-20.","en":"Today is my 20th birthday.","tl":"Ngayon ang ika-20 kong kaarawan.","vi":"Hôm nay là sinh nhật hai mươi tuổi của tôi."},"exp":{"id":"Kue ulang tahun dengan angka 20 → 生日.","en":"A birthday cake with 20 → 生日.","tl":"Birthday cake na may 20 → 生日.","vi":"Bánh sinh nhật số 20 → 生日."}},{"pic":{"i":["friends","cinema"],"b":"19:30","bg":"night"},"zh":"我們晚上七點半一起去看＿＿＿。","py":"Wǒ men wǎn shang qī diǎn bàn yì qǐ qù kàn diàn yǐng.","opts":["書","電影","醫生","球賽"],"a":1,"tr":{"id":"Kami pergi menonton film bersama jam setengah delapan malam.","en":"We're going to see a movie together at 7:30 p.m.","tl":"Sabay kaming manonood ng sine nang alas-siyete y medya ng gabi.","vi":"Bảy giờ rưỡi tối chúng tôi cùng đi xem phim."},"exp":{"id":"Gambar bioskop → 看電影.","en":"The picture shows a cinema → 看電影.","tl":"Sinehan ang nasa larawan → 看電影.","vi":"Hình là rạp chiếu phim → 看電影."}},{"pic":{"i":["man","cook"],"bg":"home"},"zh":"爸爸在廚房＿＿＿。","py":"Bà ba zài chú fáng zuò fàn.","opts":["做飯","洗澡","看書","打球"],"a":0,"tr":{"id":"Ayah sedang memasak di dapur.","en":"Dad is cooking in the kitchen.","tl":"Nagluluto si Tatay sa kusina.","vi":"Bố đang nấu cơm trong bếp."},"exp":{"id":"Pria sedang memasak → 做飯.","en":"The man is cooking → 做飯.","tl":"Nagluluto ang lalaki → 做飯.","vi":"Người đàn ông đang nấu ăn → 做飯."}},{"pic":{"i":["boy","fever","bed"],"bg":"home"},"zh":"弟弟＿＿＿了，在床上休息。","py":"Dì di shēng bìng le, zài chuáng shàng xiū xi.","opts":["生氣","吃飽","生病","畢業"],"a":2,"tr":{"id":"Adik laki-laki sakit, sedang istirahat di tempat tidur.","en":"My younger brother is sick and resting in bed.","tl":"May sakit ang nakababata kong kapatid at nagpapahinga sa kama.","vi":"Em trai bị ốm, đang nằm nghỉ trên giường."},"exp":{"id":"Demam di tempat tidur → 生病 (sakit).","en":"Fever and in bed → 生病, sick.","tl":"May lagnat at nasa kama → 生病, may sakit.","vi":"Sốt, nằm giường → 生病, bị ốm."}},{"pic":{"i":["girl","tennis"],"bg":"park"},"zh":"她常常跟朋友打＿＿＿。","py":"Tā cháng cháng gēn péng yǒu dǎ wǎng qiú.","opts":["籃球","網球","電話","棒球"],"a":1,"tr":{"id":"Dia sering main tenis dengan teman.","en":"She often plays tennis with friends.","tl":"Madalas siyang maglaro ng tennis kasama ang mga kaibigan.","vi":"Cô ấy thường chơi quần vợt với bạn."},"exp":{"id":"Gambar raket tenis → 網球.","en":"The picture shows tennis → 網球.","tl":"Tennis ang nasa larawan → 網球.","vi":"Hình là quần vợt → 網球."}},{"pic":{"i":["waiter","restaurant"]},"zh":"我哥哥在餐廳當＿＿＿。","py":"Wǒ gē ge zài cān tīng dāng fú wù shēng.","opts":["老師","司機","醫生","服務生"],"a":3,"tr":{"id":"Kakak laki-laki saya bekerja sebagai pelayan di restoran.","en":"My older brother works as a waiter in a restaurant.","tl":"Weyter ang kuya ko sa isang restawran.","vi":"Anh trai tôi làm phục vụ ở nhà hàng."},"exp":{"id":"Pelayan di restoran → 服務生.","en":"A waiter in a restaurant → 服務生.","tl":"Weyter sa restawran → 服務生.","vi":"Người phục vụ ở nhà hàng → 服務生."}},{"pic":{"i":["friends","sing","dance"]},"zh":"大家一邊唱歌一邊＿＿＿。","py":"Dà jiā yì biān chàng gē yì biān tiào wǔ.","opts":["跳舞","游泳","開車","寫字"],"a":0,"tr":{"id":"Semua orang bernyanyi sambil menari.","en":"Everyone is singing and dancing at the same time.","tl":"Kumakanta at sumasayaw nang sabay ang lahat.","vi":"Mọi người vừa hát vừa nhảy."},"exp":{"id":"Gambar menyanyi dan menari → 跳舞.","en":"The picture shows singing and dancing → 跳舞.","tl":"Kumakanta at sumasayaw sa larawan → 跳舞.","vi":"Hình vừa hát vừa nhảy → 跳舞."}}]},{"p":3,"items":[{"zh":"我從來沒看＿＿＿這部電影。","py":"Wǒ cóng lái méi kàn guò zhè bù diàn yǐng.","opts":["了","過","著","在"],"a":1,"tr":{"id":"Saya belum pernah menonton film ini.","en":"I have never seen this movie.","tl":"Hindi ko pa kailanman napanood ang pelikulang ito.","vi":"Tôi chưa từng xem bộ phim này."},"exp":{"id":"從來沒…過 = belum pernah (pengalaman).","en":"從來沒…過 expresses 'never have' (experience).","tl":"從來沒…過 = hindi pa kailanman (karanasan).","vi":"從來沒…過 = chưa từng (kinh nghiệm)."}},{"zh":"你想喝咖啡＿＿＿茶？——茶，謝謝。","py":"Nǐ xiǎng hē kā fēi hái shì chá? Chá, xiè xie.","opts":["還是","或是","和","也"],"a":0,"tr":{"id":"Kamu mau minum kopi atau teh? — Teh, terima kasih.","en":"Would you like coffee or tea? — Tea, thanks.","tl":"Gusto mo ba ng kape o tsaa? — Tsaa, salamat.","vi":"Bạn muốn uống cà phê hay trà? — Trà, cảm ơn."},"exp":{"id":"Dalam pertanyaan pilihan dipakai 還是, bukan 或是.","en":"Choice questions use 還是, not 或是.","tl":"Sa tanong na may pagpipilian, 還是 ang gamit, hindi 或是.","vi":"Câu hỏi lựa chọn dùng 還是, không dùng 或是."}},{"zh":"他跑＿＿＿很快，每次比賽都是第一名。","py":"Tā pǎo de hěn kuài, měi cì bǐ sài dōu shì dì yī míng.","opts":["的","地","得","了"],"a":2,"tr":{"id":"Dia berlari sangat cepat, setiap lomba selalu juara satu.","en":"He runs very fast and wins first place in every race.","tl":"Napakabilis niyang tumakbo; lagi siyang nangunguna sa bawat paligsahan.","vi":"Anh ấy chạy rất nhanh, lần thi nào cũng đứng nhất."},"exp":{"id":"Kata kerja + 得 + keterangan: 跑得很快.","en":"Verb + 得 + complement: 跑得很快.","tl":"Pandiwa + 得 + komplemento: 跑得很快.","vi":"Động từ + 得 + bổ ngữ: 跑得很快."}},{"zh":"今天比昨天＿＿＿熱。","py":"Jīn tiān bǐ zuó tiān gèng rè.","opts":["很","非常","太","更"],"a":3,"tr":{"id":"Hari ini lebih panas daripada kemarin.","en":"Today is even hotter than yesterday.","tl":"Mas mainit pa ngayon kaysa kahapon.","vi":"Hôm nay còn nóng hơn hôm qua."},"exp":{"id":"Kalimat 比 tidak memakai 很/非常/太; pakai 更.","en":"比 sentences can't use 很/非常/太; use 更.","tl":"Hindi ginagamit ang 很/非常/太 sa 比; 更 ang tama.","vi":"Câu 比 không dùng 很/非常/太; dùng 更."}},{"zh":"我弟弟才三歲，還不＿＿＿騎腳踏車。","py":"Wǒ dì di cái sān suì, hái bú huì qí jiǎo tà chē.","opts":["要","會","對","得"],"a":1,"tr":{"id":"Adik laki-laki saya baru tiga tahun, belum bisa naik sepeda.","en":"My little brother is only three; he can't ride a bike yet.","tl":"Tatlong taon pa lang ang kapatid ko; hindi pa siya marunong magbisikleta.","vi":"Em trai tôi mới ba tuổi, chưa biết đi xe đạp."},"exp":{"id":"會 = bisa karena sudah belajar (keterampilan).","en":"會 = know how to (a learned skill).","tl":"會 = marunong (natutunang kakayahan).","vi":"會 = biết (kỹ năng học được)."}},{"zh":"媽媽給我買了一＿＿＿新鞋子。","py":"Mā ma gěi wǒ mǎi le yì shuāng xīn xié zi.","opts":["雙","件","條","張"],"a":0,"tr":{"id":"Ibu membelikan saya sepasang sepatu baru.","en":"Mom bought me a new pair of shoes.","tl":"Binilhan ako ni Nanay ng isang pares ng bagong sapatos.","vi":"Mẹ mua cho tôi một đôi giày mới."},"exp":{"id":"Kata bantu bilangan untuk sepatu: 雙.","en":"The measure word for shoes is 雙 (pair).","tl":"Ang measure word ng sapatos ay 雙 (pares).","vi":"Lượng từ của giày là 雙 (đôi)."}},{"zh":"電影七點開始，他七點半＿＿＿到。","py":"Diàn yǐng qī diǎn kāi shǐ, tā qī diǎn bàn cái dào.","opts":["就","才","再","又"],"a":1,"tr":{"id":"Film mulai jam tujuh, dia baru datang jam setengah delapan.","en":"The movie started at seven; he didn't arrive until 7:30.","tl":"Alas-siyete nagsimula ang pelikula; alas-siyete y medya na siya dumating.","vi":"Phim bắt đầu lúc bảy giờ, bảy rưỡi anh ấy mới đến."},"exp":{"id":"Terlambat → 才 (baru).","en":"He was late → 才 (not until).","tl":"Huli siya → 才.","vi":"Đến muộn → 才 (mới)."}},{"zh":"吃完飯以後，請你＿＿＿碗洗乾淨。","py":"Chī wán fàn yǐ hòu, qǐng nǐ bǎ wǎn xǐ gān jìng.","opts":["給","對","被","把"],"a":3,"tr":{"id":"Setelah makan, tolong cuci mangkuk sampai bersih.","en":"After eating, please wash the bowls clean.","tl":"Pagkatapos kumain, pakihugasan nang malinis ang mga mangkok.","vi":"Ăn xong, bạn hãy rửa sạch bát nhé."},"exp":{"id":"Pola 把 + objek + kata kerja + hasil: 把碗洗乾淨.","en":"把 + object + verb + result: 把碗洗乾淨.","tl":"把 + layon + pandiwa + resulta: 把碗洗乾淨.","vi":"把 + tân ngữ + động từ + kết quả: 把碗洗乾淨."}},{"zh":"你打電話給我的時候，我正＿＿＿洗澡。","py":"Nǐ dǎ diàn huà gěi wǒ de shí hou, wǒ zhèng zài xǐ zǎo.","opts":["在","了","過","著"],"a":0,"tr":{"id":"Waktu kamu menelepon saya, saya sedang mandi.","en":"When you called me, I was taking a shower.","tl":"Noong tumawag ka, naliligo ako.","vi":"Lúc bạn gọi cho tôi, tôi đang tắm."},"exp":{"id":"正在 + kata kerja = sedang.","en":"正在 + verb = in the middle of doing.","tl":"正在 + pandiwa = kasalukuyang ginagawa.","vi":"正在 + động từ = đang làm."}},{"zh":"我家＿＿＿公司不遠，走路十分鐘就到了。","py":"Wǒ jiā lí gōng sī bù yuǎn, zǒu lù shí fēn zhōng jiù dào le.","opts":["從","往","離","在"],"a":2,"tr":{"id":"Rumah saya tidak jauh dari kantor, jalan kaki sepuluh menit sudah sampai.","en":"My home isn't far from the office; it's a ten-minute walk.","tl":"Hindi malayo ang bahay ko sa opisina; sampung minutong lakad lang.","vi":"Nhà tôi cách công ty không xa, đi bộ mười phút là tới."},"exp":{"id":"Jarak dinyatakan dengan A 離 B 遠/近.","en":"Distance uses A 離 B 遠/近.","tl":"Ang layo ay ipinapahayag ng A 離 B 遠/近.","vi":"Khoảng cách dùng A 離 B 遠/近."}}]},{"p":4,"items":[{"zh":"上個星期六我（1）了，頭很痛，也有一點發燒。媽媽帶我去醫院看醫生。醫生說我是感冒，要多喝水，多（2）。他還給了我三天的（3）。我在家睡了兩天，現在已經好多了。醫生說我應該常常（4），所以我打算以後每天早上跟爸爸去公園跑步。下個星期我（5）可以去學校上課了。","py":"Shàng ge xīng qí liù wǒ shēng bìng le, tóu hěn tòng, yě yǒu yì diǎn fā shāo. Mā ma dài wǒ qù yī yuàn kàn yī shēng. Yī shēng shuō wǒ shì gǎn mào, yào duō hē shuǐ, duō xiū xi. Tā hái gěi le wǒ sān tiān de yào. Wǒ zài jiā shuì le liǎng tiān, xiàn zài yǐ jīng hǎo duō le. Yī shēng shuō wǒ yīng gāi cháng cháng yùn dòng, suǒ yǐ wǒ dǎ suàn yǐ hòu měi tiān zǎo shang gēn bà ba qù gōng yuán pǎo bù. Xià ge xīng qí wǒ jiù kě yǐ qù xué xiào shàng kè le.","bank":["藥","就","生病","上班","運動","休息"],"ans":[2,5,0,4,1],"tr":{"id":"Sabtu lalu saya sakit, kepala sangat sakit dan sedikit demam. Ibu membawa saya ke rumah sakit menemui dokter. Dokter bilang saya flu, harus banyak minum air dan banyak istirahat. Dia juga memberi saya obat untuk tiga hari. Saya tidur di rumah dua hari, sekarang sudah jauh lebih baik. Dokter bilang saya sebaiknya sering berolahraga, jadi saya berencana setiap pagi lari di taman bersama ayah. Minggu depan saya sudah bisa masuk sekolah.","en":"Last Saturday I got sick; I had a bad headache and a slight fever. Mom took me to the hospital to see a doctor. The doctor said I had a cold and should drink lots of water and rest a lot. He also gave me three days of medicine. I slept at home for two days and now I'm much better. The doctor said I should exercise often, so I plan to go running in the park with Dad every morning. Next week I can go back to school.","tl":"Noong nakaraang Sabado nagkasakit ako; masakit ang ulo ko at may kaunting lagnat. Dinala ako ni Nanay sa ospital para magpatingin sa doktor. Sabi ng doktor, sipon lang, kailangan kong uminom ng maraming tubig at magpahinga nang husto. Binigyan din niya ako ng gamot para sa tatlong araw. Dalawang araw akong natulog sa bahay at ngayon mas magaling na ako. Sabi ng doktor dapat madalas akong mag-ehersisyo, kaya balak kong tumakbo sa parke kasama si Tatay tuwing umaga. Sa susunod na linggo, makakapasok na ako sa paaralan.","vi":"Thứ Bảy tuần trước tôi bị ốm, đau đầu lắm và hơi sốt. Mẹ đưa tôi đến bệnh viện khám bác sĩ. Bác sĩ nói tôi bị cảm, phải uống nhiều nước, nghỉ ngơi nhiều. Ông ấy còn cho tôi thuốc ba ngày. Tôi ngủ ở nhà hai ngày, bây giờ đã khỏe hơn nhiều. Bác sĩ nói tôi nên thường xuyên tập thể dục, nên tôi định sau này mỗi sáng cùng bố ra công viên chạy bộ. Tuần sau tôi đã có thể đi học rồi."},"exp":{"id":"(1) 生病 sakit; (2) 多休息; (3) 三天的藥; (4) 運動 → lari; (5) 就 = sudah bisa. 上班 pengecoh.","en":"(1) 生病 sick; (2) 多休息 rest; (3) 三天的藥 medicine; (4) 運動 → running; (5) 就 'then'. 上班 is the distractor.","tl":"(1) 生病; (2) 多休息; (3) 三天的藥; (4) 運動 → takbo; (5) 就. Pang-abala ang 上班.","vi":"(1) 生病 ốm; (2) 多休息; (3) 三天的藥 thuốc; (4) 運動 → chạy bộ; (5) 就. 上班 là đáp án nhiễu."}}]},{"p":5,"items":[{"kind":"notice","title":"游泳池公告","zh":"各位會員：\n下星期一到星期三游泳池要打掃，不開放，星期四早上再開。\n開放時間：星期二到星期日 6:00-21:00\n星期一休息。\n小孩一定要跟大人一起來游泳。\n游泳以前請先洗澡。","py":"Gè wèi huì yuán:\nXià xīng qí yī dào xīng qí sān yóu yǒng chí yào dǎ sǎo, bù kāi fàng, xīng qí sì zǎo shang zài kāi.\nKāi fàng shí jiān: xīng qí èr dào xīng qí rì 6:00-21:00\nXīng qí yī xiū xi.\nXiǎo hái yí dìng yào gēn dà rén yì qǐ lái yóu yǒng.\nYóu yǒng yǐ qián qǐng xiān xǐ zǎo.","qs":[{"zh":"游泳池下星期哪天再開放？","py":"Yóu yǒng chí xià xīng qí nǎ tiān zài kāi fàng?","opts":["星期一","星期三","星期四","星期日"],"a":2,"exp":{"id":"Senin–Rabu dibersihkan, 星期四早上再開.","en":"Closed Mon–Wed for cleaning; reopens Thursday morning (星期四早上再開).","tl":"Sarado Lunes–Miyerkoles; magbubukas muli sa Huwebes ng umaga.","vi":"Đóng cửa thứ Hai–thứ Tư; sáng thứ Năm mở lại."}},{"zh":"平常游泳池星期幾休息？","py":"Píng cháng yóu yǒng chí xīng qí jǐ xiū xi?","opts":["星期一","星期二","星期六","星期日"],"a":0,"exp":{"id":"Tertulis 星期一休息.","en":"The notice says 星期一休息, closed Mondays.","tl":"Nakasulat ang 星期一休息, sarado tuwing Lunes.","vi":"Ghi 星期一休息, nghỉ thứ Hai."}},{"zh":"下面哪一個是對的？","py":"Xià miàn nǎ yí ge shì duì de?","opts":["小孩可以自己來游泳","晚上十點還可以游泳","小孩要跟大人一起來","下星期二可以去游泳"],"a":2,"exp":{"id":"小孩一定要跟大人一起來. Tutup jam 21:00 dan Selasa depan masih tutup.","en":"Children must come with an adult; it closes at 21:00 and next Tuesday is closed.","tl":"Kailangang may kasamang matanda ang bata; sarado pagkalipas ng 21:00 at sa susunod na Martes.","vi":"Trẻ em phải đi cùng người lớn; đóng cửa lúc 21:00, thứ Ba tuần sau cũng đóng."}}],"tr":{"id":"Para anggota: Senin sampai Rabu minggu depan kolam renang akan dibersihkan dan tidak buka; buka lagi Kamis pagi. Jam buka: Selasa sampai Minggu 6:00-21:00. Senin tutup. Anak-anak harus datang berenang bersama orang dewasa. Mandi dulu sebelum berenang.","en":"Dear members: Next Monday to Wednesday the pool will be cleaned and closed; it reopens Thursday morning. Opening hours: Tuesday to Sunday 6:00-21:00. Closed on Mondays. Children must come swimming with an adult. Please shower before swimming.","tl":"Sa lahat ng miyembro: Mula Lunes hanggang Miyerkoles sa susunod na linggo, lilinisin ang swimming pool at sarado ito; bubuksan muli sa Huwebes ng umaga. Oras: Martes hanggang Linggo 6:00-21:00. Sarado tuwing Lunes. Kailangang may kasamang matanda ang mga bata. Maligo muna bago lumangoy.","vi":"Kính gửi hội viên: Từ thứ Hai đến thứ Tư tuần sau hồ bơi sẽ dọn dẹp, không mở cửa; sáng thứ Năm mở lại. Giờ mở cửa: thứ Ba đến Chủ nhật 6:00-21:00. Thứ Hai nghỉ. Trẻ em phải đi bơi cùng người lớn. Trước khi bơi xin tắm trước."}},{"kind":"menu","title":"阿美麵店","zh":"牛肉麵 150元\n雞肉飯 60元\n水餃（十個） 70元\n燙青菜 40元\n紅茶 25元\n＊買兩碗牛肉麵，送一杯紅茶。\n＊每星期一休息。\n營業時間：11:00-20:00\n＊雞肉飯和水餃可以外帶。","py":"Niú ròu miàn 150 yuán\nJī ròu fàn 60 yuán\nShuǐ jiǎo (shí ge) 70 yuán\nTàng qīng cài 40 yuán\nHóng chá 25 yuán\nMǎi liǎng wǎn niú ròu miàn, sòng yì bēi hóng chá.\nMěi xīng qí yī xiū xi.\nYíng yè shí jiān: 11:00-20:00\nJī ròu fàn hé shuǐ jiǎo kě yǐ wài dài.","qs":[{"zh":"一碗牛肉麵和一盤燙青菜一共多少錢？","py":"Yì wǎn niú ròu miàn hé yì pán tàng qīng cài yí gòng duō shǎo qián?","opts":["一百六十五元","一百九十元","兩百一十元","一百七十五元"],"a":1,"exp":{"id":"150 + 40 = 190 元.","en":"150 + 40 = 190 dollars.","tl":"150 + 40 = 190.","vi":"150 + 40 = 190 đồng."}},{"zh":"買兩碗牛肉麵，可以拿到什麼？","py":"Mǎi liǎng wǎn niú ròu miàn, kě yǐ ná dào shén me?","opts":["一杯紅茶","十個水餃","一盤燙青菜","一碗雞肉飯"],"a":0,"exp":{"id":"買兩碗牛肉麵，送一杯紅茶.","en":"Buy two beef noodles, get a free black tea.","tl":"Bumili ng dalawang beef noodles, libre ang isang black tea.","vi":"Mua hai bát mì bò, tặng một ly hồng trà."}},{"zh":"哪一天不能去這家店吃飯？","py":"Nǎ yì tiān bù néng qù zhè jiā diàn chī fàn?","opts":["星期日","星期六","星期三","星期一"],"a":3,"exp":{"id":"每星期一休息 = tutup setiap Senin.","en":"每星期一休息: closed every Monday.","tl":"每星期一休息: sarado tuwing Lunes.","vi":"每星期一休息: nghỉ mỗi thứ Hai."}}],"tr":{"id":"Mi daging sapi 150 dolar; nasi ayam 60; pangsit (sepuluh) 70; sayur rebus 40; teh hitam 25. *Beli dua mangkuk mi sapi, gratis segelas teh hitam. *Tutup setiap Senin. Jam buka: 11:00-20:00. *Nasi ayam dan pangsit bisa dibawa pulang.","en":"Beef noodles NT$150; chicken rice 60; dumplings (ten) 70; blanched vegetables 40; black tea 25. *Buy two bowls of beef noodles, get a black tea free. *Closed every Monday. Hours: 11:00-20:00. *Chicken rice and dumplings available for takeout.","tl":"Beef noodles 150; chicken rice 60; dumplings (sampu) 70; nilagang gulay 40; black tea 25. *Bumili ng dalawang mangkok ng beef noodles, libre ang isang black tea. *Sarado tuwing Lunes. Oras: 11:00-20:00. *Puwedeng i-take out ang chicken rice at dumplings.","vi":"Mì bò 150 đồng; cơm gà 60; sủi cảo (mười cái) 70; rau luộc 40; hồng trà 25. *Mua hai bát mì bò tặng một ly hồng trà. *Nghỉ mỗi thứ Hai. Giờ mở cửa: 11:00-20:00. *Cơm gà và sủi cảo có thể mua mang về."}},{"kind":"message","title":"小文和大中的訊息","zh":"小文：大中，這個星期六晚上要不要一起去看電影？\n大中：星期六我要上班，星期日可以嗎？\n小文：好啊！那星期日下午兩點在捷運站見面。\n大中：好，看完電影我們去夜市吃東西吧！\n小文：沒問題，我請你喝珍珠奶茶。","py":"Xiǎo Wén: Dà Zhōng, zhè ge xīng qí liù wǎn shang yào bú yào yì qǐ qù kàn diàn yǐng?\nDà Zhōng: Xīng qí liù wǒ yào shàng bān, xīng qí rì kě yǐ ma?\nXiǎo Wén: Hǎo a! Nà xīng qí rì xià wǔ liǎng diǎn zài jié yùn zhàn jiàn miàn.\nDà Zhōng: Hǎo, kàn wán diàn yǐng wǒ men qù yè shì chī dōng xi ba!\nXiǎo Wén: Méi wèn tí, wǒ qǐng nǐ hē zhēn zhū nǎi chá.","qs":[{"zh":"他們哪天去看電影？","py":"Tā men nǎ tiān qù kàn diàn yǐng?","opts":["星期五晚上","星期六晚上","星期日下午","星期日晚上"],"a":2,"exp":{"id":"Rencana diganti ke 星期日下午兩點.","en":"The plan changed to Sunday at 2 p.m.","tl":"Inilipat ang plano sa Linggo, alas-dos ng hapon.","vi":"Kế hoạch đổi sang 2 giờ chiều Chủ nhật."}},{"zh":"大中星期六為什麼不能去？","py":"Dà Zhōng xīng qí liù wèi shén me bù néng qù?","opts":["他要上課","他要上班","他生病了","他要去夜市"],"a":1,"exp":{"id":"大中: 星期六我要上班.","en":"Dazhong says he has to work on Saturday.","tl":"Sabi ni Dazhong, may trabaho siya sa Sabado.","vi":"Đại Trung nói thứ Bảy phải đi làm."}},{"zh":"看完電影以後，他們要做什麼？","py":"Kàn wán diàn yǐng yǐ hòu, tā men yào zuò shén me?","opts":["去夜市吃東西","回家休息","去公司上班","去捷運站見面"],"a":0,"exp":{"id":"看完電影我們去夜市吃東西.","en":"After the movie they'll eat at the night market.","tl":"Pagkatapos ng sine, kakain sila sa night market.","vi":"Xem phim xong họ đi chợ đêm ăn uống."}}],"tr":{"id":"Xiaowen: Dazhong, Sabtu malam ini mau nonton film bareng? Dazhong: Sabtu aku kerja, Minggu bisa? Xiaowen: Oke! Kalau begitu Minggu jam dua siang ketemu di stasiun MRT. Dazhong: Oke, habis nonton kita ke pasar malam makan ya! Xiaowen: Boleh, aku traktir kamu bubble tea.","en":"Xiaowen: Dazhong, want to see a movie together this Saturday evening? Dazhong: I work on Saturday, is Sunday OK? Xiaowen: Sure! Then let's meet at the MRT station at 2 p.m. on Sunday. Dazhong: OK, after the movie let's go eat at the night market! Xiaowen: No problem, I'll buy you bubble tea.","tl":"Xiaowen: Dazhong, gusto mo bang manood ng sine sa Sabado ng gabi? Dazhong: May trabaho ako sa Sabado, puwede ba sa Linggo? Xiaowen: Sige! Magkita tayo sa MRT station sa Linggo nang alas-dos ng hapon. Dazhong: Sige, pagkatapos ng sine kain tayo sa night market! Xiaowen: Walang problema, ililibre kita ng bubble tea.","vi":"Tiểu Văn: Đại Trung, tối thứ Bảy này đi xem phim cùng không? Đại Trung: Thứ Bảy tớ phải đi làm, Chủ nhật được không? Tiểu Văn: Được! Vậy 2 giờ chiều Chủ nhật gặp ở ga tàu điện ngầm. Đại Trung: Ừ, xem phim xong mình đi chợ đêm ăn nhé! Tiểu Văn: Không vấn đề, tớ mời cậu trà sữa trân châu."}},{"kind":"schedule","title":"王醫生診所看診時間","zh":"星期一到星期五\n上午 9:00-12:00\n下午 3:00-6:00\n晚上 7:00-9:00\n星期六：只有上午看診\n星期日：休息\n看病請帶健保卡。\n如果發燒或頭痛，可以先打電話問護士。\n下午五點以後人比較多，請早一點來。","py":"Xīng qí yī dào xīng qí wǔ\nShàng wǔ 9:00-12:00\nXià wǔ 3:00-6:00\nWǎn shang 7:00-9:00\nXīng qí liù: zhǐ yǒu shàng wǔ kàn zhěn\nXīng qí rì: xiū xi\nKàn bìng qǐng dài jiàn bǎo kǎ.\nRú guǒ fā shāo huò tóu tòng, kě yǐ xiān dǎ diàn huà wèn hù shì.\nXià wǔ wǔ diǎn yǐ hòu rén bǐ jiào duō, qǐng zǎo yì diǎn lái.","qs":[{"zh":"星期六下午可以去看醫生嗎？","py":"Xīng qí liù xià wǔ kě yǐ qù kàn yī shēng ma?","opts":["可以，三點以後","不可以，星期六只有上午看診","可以，晚上七點以後","不可以，星期六休息"],"a":1,"exp":{"id":"星期六只有上午看診; siang tidak ada.","en":"On Saturday there are only morning hours.","tl":"Tuwing Sabado, umaga lang may konsulta.","vi":"Thứ Bảy chỉ khám buổi sáng."}},{"zh":"李先生星期三下班以後才有時間，他幾點可以去看病？","py":"Lǐ xiān sheng xīng qí sān xià bān yǐ hòu cái yǒu shí jiān, tā jǐ diǎn kě yǐ qù kàn bìng?","opts":["上午十點","中午十二點半","晚上八點","晚上十點"],"a":2,"exp":{"id":"Setelah kerja → malam; buka 7:00-9:00, jadi jam delapan.","en":"After work → evening hours 7:00-9:00, so 8 p.m.","tl":"Pagkatapos ng trabaho → gabi, 7:00-9:00, kaya alas-otso.","vi":"Sau giờ làm → buổi tối 7:00-9:00, nên 8 giờ tối."}},{"zh":"去看病的時候要帶什麼？","py":"Qù kàn bìng de shí hou yào dài shén me?","opts":["手機","照片","錢包","健保卡"],"a":3,"exp":{"id":"看病請帶健保卡.","en":"Bring your health insurance card (健保卡).","tl":"Dalhin ang health insurance card (健保卡).","vi":"Mang thẻ bảo hiểm y tế (健保卡)."}}],"tr":{"id":"Jam praktik Klinik Dokter Wang. Senin–Jumat: pagi 9:00-12:00, sore 3:00-6:00, malam 7:00-9:00. Sabtu: hanya pagi. Minggu: tutup. Bawa kartu asuransi kesehatan. Jika demam atau sakit kepala, bisa telepon dulu tanya perawat. Setelah jam lima sore lebih ramai, silakan datang lebih awal.","en":"Dr. Wang's Clinic hours. Mon–Fri: morning 9:00-12:00, afternoon 3:00-6:00, evening 7:00-9:00. Saturday: mornings only. Sunday: closed. Please bring your health insurance card. If you have a fever or headache, you can call and ask the nurse first. After 5 p.m. it's busier, please come early.","tl":"Oras ng Klinika ni Dr. Wang. Lunes–Biyernes: umaga 9:00-12:00, hapon 3:00-6:00, gabi 7:00-9:00. Sabado: umaga lang. Linggo: sarado. Dalhin ang health insurance card. Kung may lagnat o sakit ng ulo, puwedeng tumawag muna at magtanong sa nars. Mas maraming tao pagkalipas ng alas-singko, kaya pumunta nang maaga.","vi":"Giờ khám Phòng khám bác sĩ Vương. Thứ Hai–thứ Sáu: sáng 9:00-12:00, chiều 3:00-6:00, tối 7:00-9:00. Thứ Bảy: chỉ khám sáng. Chủ nhật: nghỉ. Khi khám bệnh xin mang thẻ bảo hiểm y tế. Nếu sốt hoặc đau đầu, có thể gọi điện hỏi y tá trước. Sau 5 giờ chiều đông người, xin đến sớm."}},{"kind":"diary","title":"我的日記","zh":"十月五日　星期日　晴\n今天是媽媽的生日。早上我和姐姐把家裡打掃得很乾淨，爸爸去市場買菜。中午我們做了很多菜，姐姐還做了一個蛋糕。晚上奶奶也來了，大家一起唱生日快樂歌。媽媽說這是她最快樂的一個生日。","py":"Shí yuè wǔ rì xīng qí rì qíng\nJīn tiān shì mā ma de shēng rì. Zǎo shang wǒ hé jiě jie bǎ jiā lǐ dǎ sǎo de hěn gān jìng, bà ba qù shì chǎng mǎi cài. Zhōng wǔ wǒ men zuò le hěn duō cài, jiě jie hái zuò le yí ge dàn gāo. Wǎn shang nǎi nai yě lái le, dà jiā yì qǐ chàng shēng rì kuài lè gē. Mā ma shuō zhè shì tā zuì kuài lè de yí ge shēng rì.","qs":[{"zh":"今天早上誰去買菜？","py":"Jīn tiān zǎo shang shéi qù mǎi cài?","opts":["媽媽","姐姐","爸爸","奶奶"],"a":2,"exp":{"id":"爸爸去市場買菜.","en":"Dad went to the market to buy food.","tl":"Si Tatay ang namalengke.","vi":"Bố đi chợ mua thức ăn."}},{"zh":"蛋糕是誰做的？","py":"Dàn gāo shì shéi zuò de?","opts":["姐姐","媽媽","我","奶奶"],"a":0,"exp":{"id":"姐姐還做了一個蛋糕.","en":"The older sister made a cake.","tl":"Si Ate ang gumawa ng cake.","vi":"Chị gái làm bánh kem."}},{"zh":"下面哪一個是對的？","py":"Xià miàn nǎ yí ge shì duì de?","opts":["今天下雨了","奶奶晚上來了","他們在餐廳吃飯","媽媽早上打掃家裡"],"a":1,"exp":{"id":"晚上奶奶也來了. Cuaca 晴; makan di rumah; yang bersih-bersih aku dan kakak.","en":"Grandma came in the evening. It was sunny, they ate at home, and the kids cleaned.","tl":"Dumating si Lola sa gabi. Maaraw, sa bahay kumain, at ang magkapatid ang naglinis.","vi":"Bà đến buổi tối. Trời nắng, ăn ở nhà, hai chị em dọn nhà."}}],"tr":{"id":"5 Oktober, Minggu, cerah. Hari ini ulang tahun ibu. Pagi aku dan kakak membersihkan rumah sampai bersih, ayah pergi ke pasar belanja sayur. Siang kami memasak banyak makanan, kakak juga membuat kue. Malam nenek juga datang, semua menyanyikan lagu selamat ulang tahun. Ibu bilang ini ulang tahun paling bahagianya.","en":"October 5, Sunday, sunny. Today is Mom's birthday. In the morning my older sister and I cleaned the house, and Dad went to the market to buy groceries. At noon we cooked lots of dishes, and my sister also made a cake. In the evening Grandma came too, and everyone sang Happy Birthday together. Mom said this was her happiest birthday.","tl":"Oktubre 5, Linggo, maaraw. Kaarawan ngayon ni Nanay. Sa umaga, nilinis namin ni Ate ang bahay, at namalengke si Tatay. Sa tanghali nagluto kami ng maraming ulam, at gumawa rin si Ate ng cake. Sa gabi dumating din si Lola, at sabay-sabay naming kinanta ang Happy Birthday. Sabi ni Nanay, ito ang pinakamasaya niyang kaarawan.","vi":"Ngày 5 tháng 10, Chủ nhật, nắng. Hôm nay là sinh nhật mẹ. Buổi sáng tôi và chị dọn nhà sạch sẽ, bố đi chợ mua thức ăn. Buổi trưa chúng tôi nấu nhiều món, chị còn làm một chiếc bánh kem. Buổi tối bà cũng đến, mọi người cùng hát bài chúc mừng sinh nhật. Mẹ nói đây là sinh nhật vui nhất của mẹ."}}]}]}];
